window.RARE_FLASHCARDS = [{"id": "fc_001_01", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **Physical examination** defined and characterized?", "a": "Physical examination then provides important phenotypic information; both the presence and absence of key findings inform the list of diagnoses under consideration (i.", "img": null}, {"id": "fc_001_02", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **team-based approach** defined and characterized?", "a": "team-based approach to diagnosis incorporates diverse points of view and expands the collective knowledge base, often outperforming the diagnostic accuracy of individual experienced diagnosticians.", "img": null}, {"id": "fc_001_03", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **Diagnostic error** defined and characterized?", "a": "Diagnostic error is _the failure to (a) establish an accurate and timely explanation of the patient’s health problem(s) or (b) communicate that explanation to the patient.", "img": null}, {"id": "fc_001_04", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **system 2 process** defined and characterized?", "a": "system 2 process that is based in hypothesis generation and counterfactual reasoning.", "img": null}, {"id": "fc_001_05", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **dual process theory** defined and characterized?", "a": "dual process theory suggests that most clinicians, under most circumstances, employ a system 1 process with relatively high diagnostic accuracy for most common medical concerns.", "img": null}, {"id": "fc_001_06", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **heuristic failure** defined and characterized?", "a": "heuristic failure , the same rules of thumb and quick pattern recognition that clinicians employ to arrive at a diagnosis fail to account for the entire scope of patient information or fail to adapt to new information as it becomes available and instead bias the clarity of medical reasoning.", "img": null}, {"id": "fc_001_07", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **Anchoring** defined and characterized?", "a": "Anchoring occurs when a clinician locks into a diagnosis based on the initial presenting features, failing to adjust diagnostic impressions when new clinical information presents itself.", "img": null}, {"id": "fc_001_08", "ch": 1, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Diagnostic Error**, how is **Confirmation bias** defined and characterized?", "a": "Confirmation bias occurs when clinicians seek out or respond only to evidence that affirms diagnostic impressions, to the neglect of contradictory evidence.", "img": null}, {"id": "fc_001_09", "ch": 1, "part": "I", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 1.1):", "a": "The diagnostic process as it occurs within the larger sociotechnical healthcare work system. The patient and diagnosing clinician exist as part of a larger system containing other members of the diagnostic team, all interacting with various technologies and tools in a dynamically changing environment working toward completion of the common task of diagnosis. Changes in any of these variables can positively or negatively impact the outcome. (Balogh, E.P., Miller, B.T., Ball, J.R., 2015. Improving Diagnosis in Health Care . National Academies Press, Washington, DC.)", "img": "fig_p0029_01.jpg"}, {"id": "fc_001_10", "ch": 1, "part": "I", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 1.2):", "a": "The diagnostic odyssey, from first appearance of symptoms to confirmed diagnosis. (Adapted from Soomers V, Husson O, Young R, Desar I, Van der Graaf W. The sarcoma diagnostic interval: a systematic review on length, contributing factors and patient outcomes. ESMO Open . 2020 Feb;5[1]:e000592.", "img": "vfig_p0029_01.jpg"}, {"id": "fc_001_11", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Cognitive Bias es Related to Heuristic Failure**, what are the distinguishing features of **Anchoring**?", "a": "**Definition**: Locking into a diagnosis based on initial presenting features, failing to adjust diagnostic impressions when new information becomes available.", "img": null}, {"id": "fc_001_12", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Cognitive Bias es Related to Heuristic Failure**, what are the distinguishing features of **Confirmation bias**?", "a": "**Definition**: Looking for and accepting only evidence that confirms a diagnostic impression, rejecting or not seeking contradictory evidence.", "img": null}, {"id": "fc_001_13", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Cognitive Bias es Related to Heuristic Failure**, what are the distinguishing features of **Diagnostic momentum**?", "a": "**Definition**: Perpetuating a diagnostic label over time, usually by multiple providers both within and across health care systems, despite the label being incomplete or inaccurate.", "img": null}, {"id": "fc_001_14", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Cognitive Bia ses Related to Errors of Attribution**, what are the distinguishing features of **Appeal to authority**?", "a": "**Definition**: Deferring to authoritative recommendations from senior, supervising, or “expert” clinicians, independent of the evidentiary support for such recommendations.", "img": null}, {"id": "fc_001_15", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Cognitive Bia ses Related to Errors of Attribution**, what are the distinguishing features of **Countertransference**?", "a": "**Definition**: Being influenced by positive or negative subjective feelings toward a specific patient.", "img": null}, {"id": "fc_001_16", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Cognitive Bia ses Related to Errors of Attribution**, what are the distinguishing features of **Normalcy bias**?", "a": "**Definition**: Minimizing or overemphasizing the significance of a finding or result, often based on subjective feelings about a patient or a desired outcome; the use of “slightly” to describe abnormal results.", "img": null}, {"id": "fc_001_17", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Bias Definition**, what are the distinguishing features of **Availability bias**?", "a": "**Definition**: Basing decisions on the most recent patient with similar symptoms, preferentially recalling recent and more common diseases.", "img": null}, {"id": "fc_001_18", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Bias Definition**, what are the distinguishing features of **Base-rate neglect**?", "a": "**Definition**: Over-or underestimating the prevalence of a disease, typically overestimating the prevalence of common diseases and underestimating the prevalence of rare diseases.", "img": null}, {"id": "fc_001_19", "ch": 1, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Bias Definition**, what are the distinguishing features of **Framing effect**?", "a": "**Definition**: Being influenced by how or by whom a problem is described, or by the setting in which the evaluation takes place.", "img": null}, {"id": "fc_001_20", "ch": 1, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Diagnosis and Diagnostic Error** (Finding the Rare Among the Common: Diagnosis, Diagnostic Error, and When to Suspect a Rare Disease)?", "a": "This dual process theory suggests that most clinicians, under most circumstances, employ a system 1 process with relatively high diagnostic accuracy for most common medical concerns.", "img": null}, {"id": "fc_001_21", "ch": 1, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Rare Diseases and the Diagnostic Odyssey** (Finding the Rare Among the Common: Diagnosis, Diagnostic Error, and When to Suspect a Rare Disease)?", "a": "Certain rare disease phenotypes are well characterized and are rapidly recognized when presenting with typical manifestations; others are readily diagnosed based on newborn screening results or an established family history.", "img": null}, {"id": "fc_001_22", "ch": 1, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **When to Suspect a Rare Disease** (Finding the Rare Among the Common: Diagnosis, Diagnostic Error, and When to Suspect a Rare Disease)?", "a": "Some rare disorders do present with pathognomonic historical, physical, laboratory, or imaging findings that allow for rapid diagnosis.", "img": null}, {"id": "fc_001_23", "ch": 1, "part": "I", "cat": "Pathophysiology & Synthesis", "q": "What core pathophysiologic or diagnostic principle governs **Finding the Rare Among the Common Diagnosis, Diagnostic Error, and When to Suspect a Rare Disease**?", "a": "The field of rare disorders is relatively nascent, having only formally organized and evolved over the last several decades, yet literary descriptions of rare disorders can be found across the globe dating back thousands of years.", "img": null}, {"id": "fc_001_24", "ch": 1, "part": "I", "cat": "Pathophysiology & Synthesis", "q": "What core pathophysiologic or diagnostic principle governs **Diagnosis and Diagnostic Error**?", "a": "Fundamental to the practice of medicine is diagnosis, the process of uncovering the cause of a patient’s health-related concerns.", "img": null}, {"id": "fc_002_01", "ch": 2, "part": "I", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Metabolomics**?", "a": "**Causative Gene(s):** `NSD1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Inactivating NSD1 variants causing Sotos syndrome have been associated with a specific genome-wide DNA methylation (DNAm) pattern.", "img": null}, {"id": "fc_002_02", "ch": 2, "part": "I", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NSD1`** are associated with which clinical phenotype and molecular mechanism in **Metabolomics**?", "a": "Inactivating NSD1 variants causing Sotos syndrome have been associated with a specific genome-wide DNA methylation (DNAm) pattern.", "img": null}, {"id": "fc_002_03", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic and Genomic Tests, Genetic Variants Detected, and Resolution Level**, how is **Locus-specific molecular probes** defined and characterized?", "a": "Locus-specific molecular probes are a diagnostic tool for recognizing microdeletions, such as 22q11.", "img": null}, {"id": "fc_002_04", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic and Genomic Tests, Genetic Variants Detected, and Resolution Level**, how is **Optical genome mapping** defined and characterized?", "a": "Optical genome mapping has advanced ways to analyze SVs, labeling DNA molecules with fluorochromes and subsequently linearizing them into nanochannel arrays to detect submicroscopic rearrangements.", "img": null}, {"id": "fc_002_05", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Testing for Moderateto Small-Scale Gene Variants**, how is **Intragenic deletions and duplications** defined and characterized?", "a": "Intragenic deletions and duplications are typically analyzed by multiplex ligation-dependent probe amplification (MLPA), which allows exons to be amplified quantitatively.", "img": null}, {"id": "fc_002_06", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Testing for Moderateto Small-Scale Gene Variants**, how is **Unstable repeat expansions** defined and characterized?", "a": "Unstable repeat expansions , also known as dynamic variants, represent genetic variants of a single trinucleotide repeat sequence or, less frequently, other small repeats that are the cause of several monogenic disorders, most of them related to the nervous system (Fig.", "img": null}, {"id": "fc_002_07", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Bioinformatics and Data Analysis**, how is **integrative genomic viewer (IGV)** defined and characterized?", "a": "integrative genomic viewer (IGV) are not variant callers, and specific software has been developed to determine when a variant is reliable and worth reporting.", "img": null}, {"id": "fc_002_08", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Beyond the Exome and the Genome in the Diagnostic Testing of Undiagnosed Rare Diseases**, how is **human phenotype ontology (HPO)** defined and characterized?", "a": "human phenotype ontology (HPO) , are crucial to enhancing this interaction.", "img": null}, {"id": "fc_002_09", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Beyond the Exome and the Genome in the Diagnostic Testing of Undiagnosed Rare Diseases**, how is **FAIR data principles** defined and characterized?", "a": "FAIR data principles , are designed to enhance the usability and value of data across various disciplines.", "img": null}, {"id": "fc_002_10", "ch": 2, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Transcriptomics**, how is **Uniparental disomy** defined and characterized?", "a": "Uniparental disomy can be due to abnormal genomic imprinting, which leads to recessive variant effects.", "img": null}, {"id": "fc_002_11", "ch": 2, "part": "I", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 2.1):", "a": "Genetic and genomic tests. Diagnostic rates (green) and resolution levels (red) are indicated for each test. bp, Base pair; CMA, chromosomal microarray; Kb, kilobases; LRS, long read sequencing; Mb, megabases; MLPA, multiplex ligation probe amplification; SRS, short read sequencing; SNV, single nucleotide variant.", "img": "fig_p0036_04.jpg"}, {"id": "fc_002_12", "ch": 2, "part": "I", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 2.2):", "a": "Cytogenetic analysis of a syndromic patient with a chromosomal anomaly that affects chromosomes 4 and 11. The patient has a duplication at 4p14 and deletion at 11q25 due to meiotic abnormal segregation of the paternal reciprocal translocation between chromosome 4p and 11q. (A) G-banding karyotype of the patient with 46 chromosomes is observed, a derivative chromosome 11 (arrow) that contains duplicated material from paternal chromosome 4p and is missing chromosomal 11q material. (B) Paternal G-banding karyotype, 46 chromosomes, and a reciprocal translocation between chromosomes 4p14 and 11q25. (C) The patient’s CMA shows partial 4p14 duplication (left panel) and 11q25 deletion (right panel). (D) FISH study on a patient with 22q11.2 deletion syndrome: single locus probe TUPLE1 is absent in one of the chromosomes 22 (green); chromosome 22 is labeled with a specific probe (red). (Images courtesy of C. Hernando and E. Cuatrecasas, Sant Joan de Déu Children’s Hospital.)", "img": "fig_p0038_01.jpg"}, {"id": "fc_002_13", "ch": 2, "part": "I", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 2.3):", "a": "Chromosomal microarray analysis of genomic rearrangements or contiguous gene syndromes. Both panels show, from left to right, the ideogram of the chromosome, the genomic alteration in low resolution and the alteration in higher resolution, with an indication of the genes involved. (A) Microdeletion of approximately 593 kb on chromosome 16p11.2, associated with 16p11.2 deletion syndrome (MIM #611913), and (B) microduplication of 1.4 Mb causing the CMT1A form of Charcot-Marie-Tooth neuropathy (MIM #118220), which affects the expression of the myelin gene PMP22 . (Images courtesy of C. Hernando and A. Alcalá, Sant Joan de Déu Children’s Hospital.)", "img": "fig_p0039_03.jpg"}, {"id": "fc_002_14", "ch": 2, "part": "I", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 2.4):", "a": "Analysis of exon deletions and duplications by MLPA of the DMD gene. (A) The mother’s study shows that she has a 50% amplification of exons 46 to 50, which confirms who is a carrier of the deletion. (B) The son affected by Duchenne muscular dystrophy showing the outframe deletion of exons 46 to 50. (Images courtesy of L. Martorell, Sant Joan de Déu Children’s Hospital.)", "img": "fig_p0040_01.jpg"}, {"id": "fc_002_15", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### 2.1 Types of Genomic and Genetic Variants**, what are the distinguishing features of **Resolution Level**?", "a": "Genetic Variants; Definition", "img": null}, {"id": "fc_002_16", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### 2.1 Types of Genomic and Genetic Variants**, what are the distinguishing features of **Chromosome**?", "a": "Deletion; Loss of a sequence of DNA and chromatin from a chromosome observed in the karyotype", "img": null}, {"id": "fc_002_17", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gen etic Variants**, what are the distinguishing features of **Genetic Test**?", "a": "**etic Variants**: Chromosomal Abnormalities and Rearrangements; Genome Structural Variants (SV) and Copy Number Variants (CNV); Single Nucleotide Variants (SNV); Dynamic Variants (STRs); Resolution Level", "img": null}, {"id": "fc_002_18", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gen etic Variants**, what are the distinguishing features of **Karyotype (G-banding)**?", "a": "**etic Variants**: +; +/−; −; −; Chromosomes (5–10 Mb)", "img": null}, {"id": "fc_002_19", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gen etic Variants**, what are the distinguishing features of **FISH**?", "a": "**etic Variants**: +; +; −; −; Locus-specific on chromosomes", "img": null}, {"id": "fc_002_20", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Nomenclature f or the Si i ngle Nucleotide Variants Position to the Reference Molecule Sequence**, what are the distinguishing features of **Genomic DNA**?", "a": "**Prefix**: g.; **Numbering System**: Genomic reference sequence nucleotide numbering is g.1, g.2, g.3, …, etc., from the first to the last nucleotide of the reference sequence", "img": null}, {"id": "fc_002_21", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Nomenclature f or the Si i ngle Nucleotide Variants Position to the Reference Molecule Sequence**, what are the distinguishing features of **Circular DNA**?", "a": "**Prefix**: o.; **Numbering System**: Circular reference sequence nucleotide numbering is o.1, o.2, o.3, …, etc., from the first to the last nucleotide of the reference sequence", "img": null}, {"id": "fc_002_22", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Nomenclature f or the Si i ngle Nucleotide Variants Position to the Reference Molecule Sequence**, what are the distinguishing features of **Mitochondrial DNA**?", "a": "**Prefix**: m.; **Numbering System**: Mitochondrial reference sequence nucleotide numbering is m.1, m.2, m.3, …, etc., from the first to the last nucleotide of the reference sequence (special case of a circular genomic reference sequence)", "img": null}, {"id": "fc_002_23", "ch": 2, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Nomenclature an Type of Variant d Characteristics of SNVs and Gene SVs Gene and Protein Nomenclature* [Disease Example] I a —cont’d nterpret**, what are the distinguishing features of **Large gene deletions, duplications, inversions, and fusions**?", "a": "**Rare**: Intragenic complex mechanisms and variable variant nomenclature: e.g., intron 22 inversion of theF8gene [hemophilia A]; Involving one or several exons and/ or introns; Rare", "img": null}, {"id": "fc_002_24", "ch": 2, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Genetic and Genomic Testing for DNA Single Nucleotide Variants** (Diagnostic Methods: Genomics, Omics, Biomarkers, Imaging, and Other Technologies)?", "a": "WES is considered the gold standard approach in clinical practice because it allows the reanalysis of novel genes compared to CES, generates a smaller amount of data, and is more affordable than WGS.", "img": null}, {"id": "fc_002_25", "ch": 2, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Transcriptomics** (Diagnostic Methods: Genomics, Omics, Biomarkers, Imaging, and Other Technologies)?", "a": "Uniparental disomy can be due to abnormal genomic imprinting, which leads to recessive variant effects.", "img": null}, {"id": "fc_002_26", "ch": 2, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **The Epigenome: Beyond the Structure of the Gene** (Diagnostic Methods: Genomics, Omics, Biomarkers, Imaging, and Other Technologies)?", "a": "In the clinical setting, genomic imprinting disorders can be diagnosed by specific MLPA tests determining the methylation profiling to determine the genes preferentially expressed from only one of the two parental chromosomes (i.e., Prader-Willi syndrome vs.", "img": null}, {"id": "fc_003_01", "ch": 3, "part": "I", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Treatment Opportunities and Therapy Development**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** This incentivization is the objective of orphan drug policies that provide dedicated resource support when a drug, gene therapy, or cell therapy is specifically intended for the treatment of a RD.", "img": null}, {"id": "fc_003_02", "ch": 3, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **An Overview of Rare Diseases**, how is **ultra-rare** defined and characterized?", "a": "ultra-rare , affecting fewer than 1 in 50,000 individuals.", "img": null}, {"id": "fc_003_03", "ch": 3, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **An Overview of Rare Diseases**, how is **rarity paradox** defined and characterized?", "a": "rarity paradox : each individual disease is infrequent but the collective group of people living with a rare disease (PLWRD) is large.", "img": null}, {"id": "fc_003_04", "ch": 3, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Geographical Dispersion**, how is **founder effect** defined and characterized?", "a": "founder effect of disease-causing pathogenic variants, with a consequent increase in the carrier rate in that population, or the presence of a population cluster due to environmental problems (e.", "img": null}, {"id": "fc_003_05", "ch": 3, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Rare Disease Diagnostics**, how is **Stigma** defined and characterized?", "a": "Stigma , as seminally defined in the work of 20th century sociologist Erving Goffman, is a discrediting attribute that distinguishes an individual from others by reducing them “from a whole and usual person to a tainted, discounted one.", "img": null}, {"id": "fc_003_06", "ch": 3, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Rare Disease Landscape in Canada and the United States**, how is **Orphan Drug Act** defined and characterized?", "a": "Orphan Drug Act in 1983, creating incentives for RD pharmacologic therapy development.", "img": null}, {"id": "fc_003_07", "ch": 3, "part": "I", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Rare Disease Landscape in Canada and the United States**, how is **Rare Disease Act of 2002** defined and characterized?", "a": "Rare Disease Act of 2002 established a definition of rarity (<200,000 cases in the United States), established a RD office at the National Institutes of Health, and provided funding for a research network for selected rare diseases (Rare Diseases Clinical Research Network or RDCRN).", "img": null}, {"id": "fc_003_08", "ch": 3, "part": "I", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 3.1):", "a": "Rare disease prevalence per 100,000 across countries and jurisdictions. The size of the circles corresponds to the average prevalence threshold (number of cases per 100,000 people). Black and white circles correspond to jurisdictions in which the average prevalence in definitions of rare disease is lower or higher, respectively, than the average across all jurisdictions of 40 cases/100,000 people. Map lines delineate study areas and do not necessarily depict accepted national boundaries.", "img": "fig_p0064_01.jpg"}, {"id": "fc_003_09", "ch": 3, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Global and M f ultinational Coordinated Efforts for Rare Diseases**, what are the distinguishing features of **Rare Diseases International (RDI)**?", "a": "**Concept**: RDI promotes international initiatives such as the Global Network for Rare Disease, supporting the rare disease community in developing a person-centered global network of care and expertise for all people living with a rare disease, and the adoption of 12 main recommendations to be addressed at international level as a matter of priority.; **URL**: https://www.rarediseasesinternational. org/collaborative-global-network/. https://www. rarediseasesinternational.org/jointdeclaration/ https://www.rarediseasesinternational. org/description-for-rd/", "img": null}, {"id": "fc_003_10", "ch": 3, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Global and M f ultinational Coordinated Efforts for Rare Diseases**, what are the distinguishing features of **The United Nations**?", "a": "**Concept**: The NGO Committee for Rare Diseases is a substantive committee established under the umbrella of the Conference of NGOs (nongovernmental organizations) in Consultative Relationship with the United Nations (CoNGO). The goal is to promote rare diseases as a priority in global health, research, and social and medical care as part of the UN 2030 Agenda: the Sustainable Development Goals (SDGs).; **URL**: http://download2.eurordis.org. s3.amazonaws.com/ ngocommittee/ngocommittee_ report.pdf", "img": null}, {"id": "fc_003_11", "ch": 3, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **European a f nd Eastern Mediterranean Coordinated Efforts for Rare Dise f ases**, what are the distinguishing features of **Committee for Orphan Medicinal Products (COMP)**?", "a": "**Concept**: Established in 2000, COMP is the European Medicines Agency committee responsible for recommending orphan designation of medicines for rare diseases.; **URL**: https://www.ema.europa.eu/en/ committees/committee-orphanmedicinal-products-comp https://www.ema.europa.eu/en/ human-regulatory/overview/ orphan-designation-overview", "img": null}, {"id": "fc_003_12", "ch": 3, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **European a f nd Eastern Mediterranean Coordinated Efforts for Rare Dise f ases**, what are the distinguishing features of **European Union (EU) National Plans & Strategies**?", "a": "**Concept**: A European Council recommendation to EU member states to implement strategic plans for rare diseases to ensure that patients have access to high-quality care, including diagnostics, treatments, rehabilitation for those living with a rare disease, and, if possible, effective orphan drugs.; **URL**: https://health.ec.europa.eu/latestupdates/national-plans-or- strategies-rare-diseases-pageupdated-1970-01-01_en", "img": null}, {"id": "fc_003_13", "ch": 3, "part": "I", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **European a f nd Eastern Mediterranean Coordinated Efforts for Rare Dise f ases**, what are the distinguishing features of **EURORDIS**?", "a": "**Concept**: Rare Diseases Europe is a nonprofit alliance of over 1,000 rare disease patient organizations from 74 countries that work together to improve the lives of people living with a rare disease, strengthen the patient voice, and shape research, policies, and patient services.; **URL**: https://www.eurordis.org/", "img": null}, {"id": "fc_003_14", "ch": 3, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Genetics, Inheritance, and Risk of Recurrence** (The Approach to Rare Diseases: From Local to Global)?", "a": "Up to 80% of rare diseases are genetic, and most follow either Mendelian or mitochondrial monogenic inheritance, meaning that the underlying cause is a pathogenic variant in autosomal dominant, X-linked, or mitochondrial cases and biallelic pathogenic variants in autosomal recessive cases.", "img": null}, {"id": "fc_003_15", "ch": 3, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Treatment Opportunities and Therapy Development** (The Approach to Rare Diseases: From Local to Global)?", "a": "This incentivization is the objective of orphan drug policies that provide dedicated resource support when a drug, gene therapy, or cell therapy is specifically intended for the treatment of a RD.", "img": null}, {"id": "fc_003_16", "ch": 3, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Newborn Screening for Rare Diseases** (The Approach to Rare Diseases: From Local to Global)?", "a": "Both the United States and Canada have ceded decisions about newborn screening (NBS) to individual states and provinces, respectively.", "img": null}, {"id": "fc_003_17", "ch": 3, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **The Rare Disease Landscape in Europe** (The Approach to Rare Diseases: From Local to Global)?", "a": "EURORDIS also supports relevant public health and clinical actions, such as newborn screening, favoring the incorporation of genome sequencing to expand the early detection of more actionable genetic RDs.", "img": null}, {"id": "fc_003_18", "ch": 3, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Rare Disease Landscape in Southeast Asia** (The Approach to Rare Diseases: From Local to Global)?", "a": "In addition, the policy has also provided for the inclusion of 40 rare diseases in its expanded newborn screening program starting in 2022.", "img": null}, {"id": "fc_003_19", "ch": 3, "part": "I", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **The Rare Disease Landscape in the Western Pacific Region** (The Approach to Rare Diseases: From Local to Global)?", "a": "The Philippines established a central laboratory in 1997 for a nationwide newborn screening system.", "img": null}, {"id": "fc_003_20", "ch": 3, "part": "I", "cat": "Pathophysiology & Synthesis", "q": "What core pathophysiologic or diagnostic principle governs **The Approach to Rare Diseases From Local to Global**?", "a": "DAVID ADAMS, GARETH BAYNAM, MARIELA LARRANDABURU, HELEN MALHERBE, CARMENCITA D.", "img": null}, {"id": "fc_003_21", "ch": 3, "part": "I", "cat": "Pathophysiology & Synthesis", "q": "What core pathophysiologic or diagnostic principle governs **An Overview of Rare Diseases**?", "a": "Rare diseases (RDs) are a global healthcare priority and a challenge for health professionals, scientific researchers, affected individuals, and their families.", "img": null}, {"id": "fc_003_22", "ch": 3, "part": "I", "cat": "Pathophysiology & Synthesis", "q": "What core pathophysiologic or diagnostic principle governs **Public Health**?", "a": "Labeling an individual disorder or group of disorders (e.g., Friedreich ataxia or inherited cerebellar ataxias) as rare collectively elevates them to a public health priority.", "img": null}, {"id": "fc_003_23", "ch": 3, "part": "I", "cat": "Pathophysiology & Synthesis", "q": "What core pathophysiologic or diagnostic principle governs **Natural History: Diversity and Heterogeneity**?", "a": "The nature of the pathological processes varies from diseases that affect a single organ system to multisystem diseases; in the case of retinitis pigmentosa and the group of retinal dystrophies, the affected organ is the eye and individuals suffer from a sensory disorder.", "img": null}, {"id": "fc_003_24", "ch": 3, "part": "I", "cat": "Pathophysiology & Synthesis", "q": "What core pathophysiologic or diagnostic principle governs **Comprehensive and Multidisciplinary Care**?", "a": "In many cases, affected individuals require care that goes beyond that offered by a single specialized healthcare provider.", "img": null}, {"id": "fc_004_01", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Diabetes mellitus, transient neonatal,1** (#601410)?", "a": "**Causative Gene(s):** `PLAGL1` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 6q24/PLAGL1,HYMAI — Molecular Defect: UPD (chr6) pat, paternal duplications, methylation defects onPLAGL1 TSS (caused by pathogenic variants in ZFP57gene at chr6p22) — Key Clinical Features: Intrauterine growth restriction, neonatal diabetes mellitus, hyperglycemia, macroglossia — Current Treatment: Insulin", "img": null}, {"id": "fc_004_02", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Silver-Russell syndrome** (#180860, #618905, #616489)?", "a": "**Causative Gene(s):** `H19, IGF2` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 11p15.5/H19, IGF2 7p13-q32/C7ORF10 11p15.5/IGF2 — Molecular Defect: UPD (chr11p15) mat chr11p15 CNVs UPD (chr7) mat methylation defects on H19andIGF2genes — Key Clinical Features: Pre-and postnatal growth deficiency, asymmetry, broad forehead, facial dysmorphism, macrocephaly, gastrointestinal symptoms — Curren", "img": null}, {"id": "fc_004_03", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Birk–Barel syndrome** (#612292)?", "a": "**Causative Gene(s):** `KCNK9` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 8q24.3/KCNK9 — Molecular Defect: KCNK9missense pathogenic variants on maternal gene — Key Clinical Features: Developmental delay, central hypotonia, facial dysmorphism, intellectual disability — Current Treatment: Symptomatic care", "img": null}, {"id": "fc_004_04", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Beckwith–Wiedemann syndrome** (#130650)?", "a": "**Causative Gene(s):** `H19, IGF2` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 11p15.5/H19, IGF2 — Molecular Defect: UPD (chr11p15) pat, hypermethylation on H19andIGF2genes imprinting control region (ICR1) — Key Clinical Features: Hypoglycemia, hyperinsulinism, macroglossia, overgrowth, visceromegaly — Current Treatment: Surgery to correct omphalocele or umbilical hernia, diazoxide", "img": null}, {"id": "fc_004_05", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Kagami–Ogata syndrome** (#608149)?", "a": "**Causative Gene(s):** `DLK1, MEG3, RTL1, MEG8, DIO3` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 14q32/DLK1,MEG3, RTL1, MEG8, miRNAs, SNORDs, DIO3, RTL1as — Molecular Defect: UPD (chr14) pat, 14q32 mat deletion, hypermethylation on MEG3–DLK1region — Key Clinical Features: Polyhydramnios, macrosomia, placentomegaly, hypotonia, developmental delay, abdominal wall defects, cardiac/thoracic abnormalities, coat", "img": null}, {"id": "fc_004_06", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Temple syndrome** (#616222)?", "a": "**Causative Gene(s):** `DLK1, MEG3, RTL1, MEG8, DIO3` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 14q32/DLK1,MEG3, RTL1, MEG8, miRNAs,SNORDs, DIO3, RTL1as — Molecular Defect: UPD (chr14) mat, 14q32 pat deletion, hypomethylation on MEG3–DLK1region — Key Clinical Features: Postnatal short stature, hypotonia, developmental delay, small hands and feet, intellectual disability — Current Treatment: Growth hormone", "img": null}, {"id": "fc_004_07", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Prader–Willi syndrome** (#176270)?", "a": "**Causative Gene(s):** `MRKN3, MAGEL2, NDN, PWRN4, PWRN3, SNRPN` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 15q11.2-q13/MRKN3, MAGEL2, NDN, PWRN4, PWRN3, SNURF-SNRPN, SNORDs IPW — Molecular Defect: chr15q11.2-q13 pat deletion, UPD (chr15) mat, imprinting defect, deletion of paternal SNORD116 — Key Clinical Features: Hypotonia, developmental delay, intellectual disability, hyperphagia, hypogonadism, diabetes type II —", "img": null}, {"id": "fc_004_08", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Angelman syndrome** (#105830)?", "a": "**Causative Gene(s):** `UBE3A` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 15q11.2-q13/UBE3A — Molecular Defect: chr15q11.2-q13 mat deletion, UPD (chr15) pat, imprinting defect, UBE3Apathogenic variants on the maternal allele — Key Clinical Features: Unmotivated laughing, ataxia, microcephaly, developmental delay, seizures, hyperreflexia — Current Treatment: Antiepileptic drug", "img": null}, {"id": "fc_004_09", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Schaaf–Yang syndrome** (#615547)?", "a": "**Causative Gene(s):** `MAGEL2` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 15q11.2/MAGEL2 — Molecular Defect: MAGEL2pathogenic variants in the paternal allele — Key Clinical Features: Psychomotor developmental delay, hypotonia, behavioral abnormalities, intellectual disability — Current Treatment: Growth hormone, antipsychotic medication, noninvasive ventilation", "img": null}, {"id": "fc_004_10", "ch": 4, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pseudohypoparathyroidism1A (PHP1A)/PHP1C** (#103580, #612462)?", "a": "**Causative Gene(s):** `GNAS` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** Chromosome/ Imprinted Gene: 20q13.32/GNAS — Molecular Defect: Inactivating pathogenic variants on the maternal allele ofGNAS — Key Clinical Features: Albright hereditary osteodystrophy, resistance to parathyroid/ other hormones, obesity, cognitive impairment — Current Treatment: Growth hormone, vitamin D", "img": null}, {"id": "fc_004_11", "ch": 4, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SNORD116`** are associated with which clinical phenotype and molecular mechanism in **Molecular Genetics**?", "a": "There are rare cases of PWS patients with typical features which only have a small microdeletion restricted to SNORD116 .", "img": null}, {"id": "fc_004_12", "ch": 4, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MAGEL2`** are associated with which clinical phenotype and molecular mechanism in **Molecular Genetics**?", "a": "Pathogenic variants of paternal origin in MAGEL2 have been found in patients with autism spectrum disorder (ASD) and some overlapping features with PWS—the Schaaf-Yang syndrome (SHFYNG) .", "img": null}, {"id": "fc_004_13", "ch": 4, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`UBE3A`** are associated with which clinical phenotype and molecular mechanism in **Molecular Genetics**?", "a": "UBE3A is the only gene that is solely expressed from the maternal chromosome.", "img": null}, {"id": "fc_004_14", "ch": 4, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IGF2`** are associated with which clinical phenotype and molecular mechanism in **Molecular Genetics**?", "a": "The IC1 region is a CpG island that is mapped to the intergenic region between H19 and IGF2 .", "img": null}, {"id": "fc_004_15", "ch": 4, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KCNQ1OT1`** are associated with which clinical phenotype and molecular mechanism in **Molecular Genetics**?", "a": "The IC2 region is associated with transcriptional start site of KCNQ1OT1 .", "img": null}, {"id": "fc_004_16", "ch": 4, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CDKN1C`** are associated with which clinical phenotype and molecular mechanism in **The Second-Tier Diagnostic Test**?", "a": "If DNA methylation of IC1 and IC2 and SNP chromosome microarray are negative, a single gene sequencing test of CDKN1C should be requested.", "img": null}, {"id": "fc_004_17", "ch": 4, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Diabetes mellitus, transient neonatal,1**?", "a": "**Therapy / Intervention:** Insulin\n\n**Clinical Context:** Chromosome/ Imprinted Gene: 6q24/PLAGL1,HYMAI — Molecular Defect: UPD (chr6) pat, paternal duplications, methylation defects onPLAGL1 TSS (caused by pathogenic variants in ZFP57gene at chr6p22) — Key Clinical Features: I", "img": null}, {"id": "fc_004_18", "ch": 4, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Silver-Russell syndrome**?", "a": "**Therapy / Intervention:** Growth hormone\n\n**Clinical Context:** Chromosome/ Imprinted Gene: 11p15.5/H19, IGF2 7p13-q32/C7ORF10 11p15.5/IGF2 — Molecular Defect: UPD (chr11p15) mat chr11p15 CNVs UPD (chr7) mat methylation defects on H19andIGF2genes — Key Clinical Features: Pre-and post", "img": null}, {"id": "fc_004_19", "ch": 4, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Birk–Barel syndrome**?", "a": "**Therapy / Intervention:** Symptomatic care\n\n**Clinical Context:** Chromosome/ Imprinted Gene: 8q24.3/KCNK9 — Molecular Defect: KCNK9missense pathogenic variants on maternal gene — Key Clinical Features: Developmental delay, central hypotonia, facial dysmorphism, intellectual disability", "img": null}, {"id": "fc_004_20", "ch": 4, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Beckwith–Wiedemann syndrome**?", "a": "**Therapy / Intervention:** Surgery to correct omphalocele or umbilical hernia, diazoxide\n\n**Clinical Context:** Chromosome/ Imprinted Gene: 11p15.5/H19, IGF2 — Molecular Defect: UPD (chr11p15) pat, hypermethylation on H19andIGF2genes imprinting control region (ICR1) — Key Clinical Features: Hypoglycemia, hyperinsulinism, macroglos", "img": null}, {"id": "fc_004_21", "ch": 4, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Terminology**, how is **Genomic imprinting** defined and characterized?", "a": "Genomic imprinting is a specific form of epigenetic modifications that involves the epigenetic marking of genes and results in a parent-of-origin specific expression pattern.", "img": null}, {"id": "fc_004_22", "ch": 4, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Motor delays** defined and characterized?", "a": "Motor delays and tremulous movements of limbs are common.", "img": null}, {"id": "fc_004_23", "ch": 4, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Abnormal EEG** defined and characterized?", "a": "Abnormal EEG with a characteristic pattern of largeamplitude slow-spike waves.", "img": null}, {"id": "fc_004_24", "ch": 4, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Developmental delay** defined and characterized?", "a": "Developmental delay and intellectual disability: Individuals with AS experience significant developmental delays in reaching motor and cognitive milestones.", "img": null}, {"id": "fc_004_25", "ch": 4, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Uniparental Disomy 14 (UPD 14) (OMIM #616222 and #608149)**, how is **Temple syndrome (TS)** defined and characterized?", "a": "Temple syndrome (TS) and UPD 14pat is the cause of a different imprinting disorder known as Kagami-Ogata syndrome (KOS) .", "img": null}, {"id": "fc_004_26", "ch": 4, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Diabetes mellitus** defined and characterized?", "a": "Diabetes mellitus may recur in adolescence or later in adulthood.", "img": null}, {"id": "fc_004_27", "ch": 4, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 4.1):", "a": "Schematic representation of epigenetic modifications at multiple levels of DNA packaging. (A) Nucleosomes consist of histone proteins (shown in blue) surrounded by two loops of DNA and when assembled as beads on a string form chromatin, the building block of a chromosome. Reversible and site-specific histone modifications occur at multiple sites through acetylation, methylation, and phosphorylation. DNA methylation occurs at 5 position of cytosine residues in a reaction catalyzed by DNA methyltransferases (DNMTs). Together, these modifications provide a unique epigenetic signature that regulates chromatin organization and gene expression. (B) Schematic of the reversible changes in chromatin organization that influence gene expression: genes are expressed (switched on) when the chromatin is open (active) in the form of euchromatin, and they are inactivated (switched off) when the chromatin is condensed (silent) in the form of heterochromatin. White circles = unmethylated cytosines; red circles = methylated cytosines.", "img": "fig_p0080_01.jpg"}, {"id": "fc_004_28", "ch": 4, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 4.3):", "a": "Molecular basis of Prader-Willi syndrome (PWS). UPD, Uniparental disomy.", "img": "fig_p0083_02.jpg"}, {"id": "fc_005_01", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Dysmorphology and Phenotyping**, how is **dysmorphology** defined and characterized?", "a": "dysmorphology was created to describe the study of human congenital malformations.", "img": null}, {"id": "fc_005_02", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Dysmorphology and Phenotyping**, how is **Phenotypes** defined and characterized?", "a": "Phenotypes are used to guide the interpretation of genetic and genomic results.", "img": null}, {"id": "fc_005_03", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Causes**, how is **Chromosomal** defined and characterized?", "a": "Chromosomal disorders such as Down syndrome result from the chromosomal imbalance caused by the presence of a third copy of chromosome 21 (trisomy 21).", "img": null}, {"id": "fc_005_04", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Causes**, how is **Copy number variations** defined and characterized?", "a": "Copy number variations , microduplications and microdeletions , are often implicated because their effect on gene dosage can disrupt normal developmental pathways.", "img": null}, {"id": "fc_005_05", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Embryology**, how is **embryonic period** defined and characterized?", "a": "embryonic period (gestational week 3–8) is the period of maximum risk for major malformations because tissue differentiation and organogenesis are taking place.", "img": null}, {"id": "fc_005_06", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Pathways and Heterogeneity**, how is **phenotype** defined and characterized?", "a": "phenotype , to see which genetic variants they also had in common.", "img": null}, {"id": "fc_005_07", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Pathways and Heterogeneity**, how is **Cornelia de Lange syndrome (CdLS)** defined and characterized?", "a": "Cornelia de Lange syndrome (CdLS) , which is characterized by distinctive facial dysmorphic features, growth restriction, and upper limb abnormalities.", "img": null}, {"id": "fc_005_08", "ch": 5, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Pregnancy History**, how is **fetal akinesia** defined and characterized?", "a": "fetal akinesia ) sets the scene for possible associated features: breech presentation, limb malformations and contractures at birth, and a possible underlying neuromuscular disorder (Fig.", "img": null}, {"id": "fc_005_09", "ch": 5, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 5.1):", "a": "Frequency of major malformations in relation to the number of minor anomalies detected in a given newborn baby.", "img": "fig_p0097_02.jpg"}, {"id": "fc_005_10", "ch": 5, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 5.2):", "a": "Critical periods in human embryological and fetal development.", "img": "fig_p0098_01.jpg"}, {"id": "fc_005_11", "ch": 5, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 5.3):", "a": "Mechanisms of abnormal morphogenesis.", "img": "fig_p0100_01.jpg"}, {"id": "fc_005_12", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Accutane (isotretinoin) Facial-ear anomalies, heart disease, CNS anomalies**, what are the distinguishing features of **Alcohol**?", "a": "**Facial-ear anomalies, heart disease, CNS anomalies**: Congenital cardiac, CNS, limb anomalies; IUGR; developmental delay; attention deficits; autism", "img": null}, {"id": "fc_005_13", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Accutane (isotretinoin) Facial-ear anomalies, heart disease, CNS anomalies**, what are the distinguishing features of **ACE inhibitors, angiotensin receptor antagonists**?", "a": "**Facial-ear anomalies, heart disease, CNS anomalies**: Oligohydramnios, IUGR, renal failure, Potter sequence", "img": null}, {"id": "fc_005_14", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Accutane (isotretinoin) Facial-ear anomalies, heart disease, CNS anomalies**, what are the distinguishing features of **Carbamazepine**?", "a": "**Facial-ear anomalies, heart disease, CNS anomalies**: Neural tube defects, possible neurodevelopmental delay", "img": null}, {"id": "fc_005_15", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Thalidomide Phocomelia, deafness, other malformations**, what are the distinguishing features of **Toluene (solvent abuse)**?", "a": "**Phocomelia, deafness, other malformations**: Craniofacial abnormalities, prematurity, hypertonia", "img": null}, {"id": "fc_005_16", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Thalidomide Phocomelia, deafness, other malformations**, what are the distinguishing features of **Topiramate**?", "a": "**Phocomelia, deafness, other malformations**: Cleft lip", "img": null}, {"id": "fc_005_17", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Thalidomide Phocomelia, deafness, other malformations**, what are the distinguishing features of **Trimethadione and paramethadione**?", "a": "**Phocomelia, deafness, other malformations**: Spontaneous abortion, multiple malformations, cognitive impairment", "img": null}, {"id": "fc_005_18", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Maternal Infections f Affecting the Fetus or Newborn**, what are the distinguishing features of **Virus Rubella**?", "a": "**Mode(s) of Transmission**: Transplacental; **Neonatal Outcome**: Congenital rubella", "img": null}, {"id": "fc_005_19", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Maternal Infections f Affecting the Fetus or Newborn**, what are the distinguishing features of **Cytomegalovirus**?", "a": "**Mode(s) of Transmission**: Transplacental, breast milk (rare); **Neonatal Outcome**: Congenital cytomegalovirus or asymptomatic", "img": null}, {"id": "fc_005_20", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Inheritance Pattern Cardinal Features**, what are the distinguishing features of **Autosomal dominant**?", "a": "**Cardinal Features**: Affected individuals have one normal allele and one altered/variant allele on one of the autosomes Males and females equally affected Vertical transmission with affected individuals in each generation 50% recurrence risk for future pregnancies De novooccurrence possible", "img": null}, {"id": "fc_005_21", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Inheritance Pattern Cardinal Features**, what are the distinguishing features of **Autosomal recessive**?", "a": "**Cardinal Features**: Affected individuals have two altered/variant alleles (biallelic) Parents of affected individuals are heterozygous carriers and healthy Consanguinity may be present 25% recurrence risk", "img": null}, {"id": "fc_005_22", "ch": 5, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Inheritance Pattern Cardinal Features**, what are the distinguishing features of **X-linked**?", "a": "**Cardinal Features**: Affected individuals have an altered/variant allele on their X chromosome Males are hemizygous Males typically more severely affected than females Skewed X-inactivation plays a role in affected females Affected males will pass the altered/variant allele to all daughters", "img": null}, {"id": "fc_005_23", "ch": 5, "part": "II", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Dysmorphology and Phenotyping** (Dysmorphology and Phenotyping)?", "a": "Dysmorphic features are combined with results from other investigations, such as biochemistry, imaging, and psychosocial or behavioral assessments, to delineate the patient’s phenotype.", "img": null}, {"id": "fc_005_24", "ch": 5, "part": "II", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Pathways and Heterogeneity** (Dysmorphology and Phenotyping)?", "a": "Another example is Cornelia de Lange syndrome (CdLS) , which is characterized by distinctive facial dysmorphic features, growth restriction, and upper limb abnormalities.", "img": null}, {"id": "fc_005_25", "ch": 5, "part": "II", "cat": "High-Yield Clinical Pearl", "q": "What is a critical clinical or diagnostic hallmark regarding **Beyond Descriptive Terminology** (Dysmorphology and Phenotyping)?", "a": "The RASopathies are patterns of anomalies caused by pathogenic variants in genes that encode components or regulators of the RAS/MAPK pathway (indicated by dashed lines ).", "img": null}, {"id": "fc_006_01", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Primary ciliary dyskinesia**?", "a": "**Causative Gene(s):** `DNAI1, DNAH5, DNAH11, DNAI2, TXNDC3, LRRC50` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: Chronic bronchitis, rhinosinusitis, otitis media, laterality defects, infertility, CHD — Selected Gene(s): DNAI1, DNAH5, DNAH11, DNAI2, KTU, TXNDC3, LRRC50, RSPH9, RSPH4A, CCDC40, CCDC39", "img": null}, {"id": "fc_006_02", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal recessive polycystic kidney disease**?", "a": "**Causative Gene(s):** `PKHD1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Clinical Manifestations: RFD, CHF", "img": null}, {"id": "fc_006_03", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Nephronophthisis**?", "a": "**Causative Gene(s):** `ALMS1, CEP290` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: RFD, interstitial nephritis, CHF, RP — Selected Gene(s): NPHP1-8, ALMS1, CEP290", "img": null}, {"id": "fc_006_04", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Bardet-Biedl syndrome**?", "a": "**Causative Gene(s):** `MKS1, MKS3, CEP290` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: Obesity, polydactyly, ID, RP, renal anomalies, anosmia, CHD — Selected Gene(s): BBS1-12, MKS1, MKS3, CEP290", "img": null}, {"id": "fc_006_05", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Meckel-Gruber syndrome**?", "a": "**Causative Gene(s):** `CC2D2A, CEP290, TMEM216` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: RFD, polydactyly, ID, CNS anomalies, CHD, cleft lip, cleft palate — Selected Gene(s): MKS1-6, CC2D2A, CEP290, TMEM216", "img": null}, {"id": "fc_006_06", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Joubert syndrome**?", "a": "**Causative Gene(s):** `NPHP1, AHI1, CEP290, TMEM216` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: CNS anomalies, ID, ataxia, RP, polydactyly, cleft lip, cleft palate — Selected Gene(s): NPHP1, JBTS1, JBTS3, JBTS4, CORS2, AHI1, CEP290, TMEM216", "img": null}, {"id": "fc_006_07", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Alström syndrome**?", "a": "**Causative Gene(s):** `ALMS1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: Obesity, RP, DM, hypothyroidism, hypogonadism, skeletal dysplasia, cardiomyopathy, pulmonary fibrosis", "img": null}, {"id": "fc_006_08", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Orofaciodigital syndrome type I**?", "a": "**Causative Gene(s):** `OFD1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: Polydactyly, syndactyly, cleft lip, cleft palate, CNS anomalies, ID, RFD", "img": null}, {"id": "fc_006_09", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ellis–van Creveld syndrome**?", "a": "**Causative Gene(s):** `EVC, EVC2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: Chondrodystrophy, polydactyly, ectodermal dysplasia, CHD — Selected Gene(s): EVC, EVC2", "img": null}, {"id": "fc_006_10", "ch": 6, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Jeune asphyxiating thoracic dystrophy**?", "a": "**Causative Gene(s):** `IFT80` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: Narrow thorax, RFD, RP, dwarfism, polydactyly", "img": null}, {"id": "fc_006_11", "ch": 6, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GLI3`** are associated with which clinical phenotype and molecular mechanism in **Ciliary Signaling and Dysmorphology**?", "a": "In the absence of SHH, GPR161 activates cAMPdependent kinase (PKA), which phosphorylates GLI2/ GLI3 transcription factors, leading to their proteolytic cleavage into the inactive form GLI-R.", "img": null}, {"id": "fc_006_12", "ch": 6, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CEP290`** are associated with which clinical phenotype and molecular mechanism in **Genotype-Phenotype Correlation in Ciliopathies**?", "a": "TZ is enriched in MKS, NPHP, and CEP290 complexes/modules that are abnormal in severe forms of ciliopathies such as Meckel-Gruber syndrome (MKS) .", "img": null}, {"id": "fc_006_13", "ch": 6, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RPGRIP1`** are associated with which clinical phenotype and molecular mechanism in **Genotype-Phenotype Correlation in Ciliopathies**?", "a": "However, RPGRIP1L and RPGRIP1, while both necessary for TZ assembly, are linked to very distinct clinical phenotypes: RPGRIP1L -related MKS and Joubert syndrome (JS) vs.", "img": null}, {"id": "fc_006_14", "ch": 6, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CSPP1`** are associated with which clinical phenotype and molecular mechanism in **Genotype-Phenotype Correlation in Ciliopathies**?", "a": "Truncating variants affecting both long and short isoforms of CSPP1 have been found to cause stillbirths with major ciliopathy features consistent with MKS, whereas variants that only truncate the long isoform cause a much milder form of Joubert syndrome.", "img": null}, {"id": "fc_006_15", "ch": 6, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ARL6`** are associated with which clinical phenotype and molecular mechanism in **Genotype-Phenotype Correlation in Ciliopathies**?", "a": "Similarly, variants that only affect a long retinaspecific ARL6 isoform cause nonsyndromic adult-onset RP unlike the classic Bardet-Biedl syndrome (BBS)-related ARL6 variants.", "img": null}, {"id": "fc_006_16", "ch": 6, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCLT1`** are associated with which clinical phenotype and molecular mechanism in **Genotype-Phenotype Correlation in Ciliopathies**?", "a": "The same SCLT1 founder variant that was initially identified in severe oral-facial-digital syndrome IX with lethality in the first year of life was also found to cause a milder form of BBS in teenage sisters.", "img": null}, {"id": "fc_006_17", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ciliary Signaling and Dysmorphology**, how is **Meckel-Gruber syndrome (MKS)** defined and characterized?", "a": "Meckel-Gruber syndrome (MKS) (comprising MKS1, TMEM67, TMEM216, B9D1, B9D2, CEP290, and TCTN1-3) and nephronophthisis (NPHP) (comprising NPHP1, NPHP4, NPHP8, and NPHP2), disruption of which leads to major ciliary defects characterized by misrouting of non-ciliary proteins to the cilia.", "img": null}, {"id": "fc_006_18", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ciliary Signaling and Dysmorphology**, how is **intraflagellar transport (IFT)** defined and characterized?", "a": "intraflagellar transport (IFT) , a bidirectional “train” that moves cargo along the axoneme from the base to the tip of the cilia (anterograde transport, mediated by IFT-B complex) and in the reverse direction (retrograde transport, mediated by IFT-A complex).", "img": null}, {"id": "fc_006_19", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ciliary Signaling and Dysmorphology**, how is **Ectosomes** defined and characterized?", "a": "Ectosomes are vesicles shed off by the plasma membrane without being preassembled by endocytic membranes like exosomes.", "img": null}, {"id": "fc_006_20", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ciliary Signaling and Dysmorphology**, how is **primary ciliary dyskinesia (PCD)** defined and characterized?", "a": "primary ciliary dyskinesia (PCD) for the latter and restrict the term ciliopathies to disorders of the primary (immotile) cilium.", "img": null}, {"id": "fc_006_21", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genotype-Phenotype Correlation in Ciliopathies**, how is **oral-facial-digital syndrome IX** defined and characterized?", "a": "oral-facial-digital syndrome IX with lethality in the first year of life was also found to cause a milder form of BBS in teenage sisters.", "img": null}, {"id": "fc_006_22", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Skeletal Defects**, how is **Jeune syndrome (JeS)** defined and characterized?", "a": "Jeune syndrome (JeS) , Ellis–van Creveld syndrome (EVC) , oral-facialdigital syndrome (OFD) , and short-rib thoracic dysplasia (SRTD) .", "img": null}, {"id": "fc_006_23", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Neurodevelopmental Disorders**, how is **acrocallosal syndrome** defined and characterized?", "a": "acrocallosal syndrome , which is commonly caused by KIF7 biallelic variants.", "img": null}, {"id": "fc_006_24", "ch": 6, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Neurodevelopmental Disorders**, how is **microcephalic primordial dwarfism** defined and characterized?", "a": "microcephalic primordial dwarfism and the gene is essential for ciliogenesis, and yet the Pcnt −/− mouse lacks any of the classical features of ciliopathies.", "img": null}, {"id": "fc_006_25", "ch": 6, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 6.1):", "a": "Cilia classification and location.", "img": "fig_p0114_01.jpg"}, {"id": "fc_006_26", "ch": 6, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 6.2):", "a": "Hedgehog (Hh) signal transduction in the primary cilium. The primary cilium has several spatially distinct regions that promote normal Hh signal transduction. Entry into the cilium is gated at the transition zone; the EVC zone facilitates pathway activation in some cell types; the cilia tip compartment, defined by KIF7, is the site of enrichment and activation of the GLI/SUFU complex; and proteolytic processing to make GLI repressors that may occur at the base where protein kinase A (PKA) is localized and leads to formation of Gli3R. In the absence of Hh signal, PTCH1 and Gpr161, both negative regulators of the pathway, are present in the cilia membrane. Gpr161 trafficking into the cilium depends on TULP3 and intraflagellar transport (IFT)-A; GPR161 appears to activate Gas, which activates adenylyl cyclase, which increases the levels of cAMP, thereby activating PKA. Activated PKA phosphorylates sites on GLI3 that promote partial proteolysis by βTrCP/Cul1 and the proteasome, generating Gli3 repressor (Gli3R), which moves to the nucleus and represses expression of Hh target genes. GLI2 and GLI3 are trafficked to the tip of the cilium in the absence of ligand in a complex with SuFu, and processing of GLI3 depends on it having transited the cilium. Binding of Hh to PTCH1 triggers its removal from the cilium, allowing Smoothened (SMO) to translocate into the cilium where it can activate downstream signaling. Gpr161 also exits the cilium after exposure to ligand.", "img": "fig_p0115_02.jpg"}, {"id": "fc_006_27", "ch": 6, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 6.3):", "a": "Ciliopathies of motile and/or non-motile cilia encompass most human organ systems. Different organ systems or tissues are affected in diverse ciliopathies, with the most common phenotypic manifestations for each organ highlighted in the corresponding box. Ciliopathies caused primarily by defects in motile cilia are in orange, those in non-motile (primary) cilia are in blue and those associated with defects in nodal cilia are in green. (Source: Fig. 101.4 in Nelson Textbook of Pediatrics 22/e.)", "img": "fig_p0116_01.jpg"}, {"id": "fc_006_28", "ch": 6, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Pediatric Ciliopathy Clinical Manifestations Selected Gene(s)**, what are the distinguishing features of **Primary ciliary dyskinesia**?", "a": "**Clinical Manifestations**: Chronic bronchitis, rhinosinusitis, otitis media, laterality defects, infertility, CHD; **Selected Gene(s)**: DNAI1, DNAH5, DNAH11, DNAI2, KTU, TXNDC3, LRRC50, RSPH9, RSPH4A, CCDC40, CCDC39", "img": null}, {"id": "fc_007_01", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal recessive polycystic kidney disease (ARPKD)**?", "a": "**Causative Gene(s):** `PKHD1, DZIP1L` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Gene(s): PKHD1, DZIP1L — Prevalence: 1:20,000 — Rarely, ARPKD can also be caused by pathogenic variants in DZIP1L .", "img": null}, {"id": "fc_007_02", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Meckel-Gruber-syndrome**?", "a": "**Causative Gene(s):** `MKS1, TMEM67, CEP290, RPGRIP1L, CC2D2A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Gene(s): MKS1, TMEM67, CEP290, RPGRIP1L, CC2D2A — Prevalence: 1:140,000", "img": null}, {"id": "fc_007_03", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Joubert syndrome and related disorders, including COACH syndrome**?", "a": "**Causative Gene(s):** `AHI1, NPHP1, CEP290, TMEM67, RPGRIP1L, ARL13B` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Gene(s): AHI1, NPHP1, CEP290, TMEM67, RPGRIP1L, ARL13B, CC2D2A — Prevalence: 1:100,000", "img": null}, {"id": "fc_007_04", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Bardet-Biedl syndrome (BBS)**?", "a": "**Causative Gene(s):** `BBS1, BBS2, ARL6, BBS4, BBS5, BBS7` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Gene(s): BBS1, BBS2, ARL6, BBS4, BBS5, MKKS, BBS7, TTC8, BBS9, BBS10, TRIM32, BBS12, MKS1, CEP290 — Prevalence: 1:100,000", "img": null}, {"id": "fc_007_05", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Renal-hepatic-pancreatic dysplasia**?", "a": "**Causative Gene(s):** `NPHP3` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Prevalence: Rare", "img": null}, {"id": "fc_007_06", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Oral-facial-digital syndrome (OFD)**?", "a": "**Causative Gene(s):** `OFD1` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Mode of Inheritance: X-linked — Prevalence: 1:100,000 — Oral-facial-digital syndrome, type 1 (OFD1) is an X-linked dominant disease, with male embryonic lethality.", "img": null}, {"id": "fc_007_07", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Skeletal ciliopathies (CED, SRTD)**?", "a": "**Causative Gene(s):** `IFT80, IFT122, WDR19, WDR35, IFT43, EVC` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Gene(s): IFT80, IFT122,WDR19,WDR35,IFT43,EVC, EVC2, IFT40,IFT172 — Prevalence: Rare", "img": null}, {"id": "fc_007_08", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal dominant polycystic kidney disease (ADPKD)**?", "a": "**Causative Gene(s):** `PKD1, PKD2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AD — Gene(s): PKD1, PKD2 — Prevalence: 1:1,000 — Autosomal dominant polycystic kidney disease (ADPKD) is the most common of all autosomal dominant monogenic diseases in humans (~1:1,000 live births).", "img": null}, {"id": "fc_007_09", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Nephronophthisis**?", "a": "**Causative Gene(s):** `NPHP1, NPHP3, NPHP4, IQCB1, CEP290, LIS2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Gene(s): NPHP1, INVS, NPHP3, NPHP4, IQCB1, CEP290, LIS2, RPGRIP1L, NEK8 — Prevalence: 1:100,000", "img": null}, {"id": "fc_007_10", "ch": 7, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ellis–van Creveld syndrome (EVC)**?", "a": "**Causative Gene(s):** `EVC` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Skeletal Phenotype: Short ribs and long bones, abnormal pelvis configuration, polydactyly of the hands — Renal Phenotype: – — Retinopathy: – — Liver Phenotype: –", "img": null}, {"id": "fc_007_11", "ch": 7, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ARL6`** are associated with which clinical phenotype and molecular mechanism in **Ciliopathies Clinical Presentations and Syndromes**?", "a": "The protein ARL6/BBS3 has been identified as a cause for Bardet-Biedl syndrome; however, a longer isoform is known in mice and zebrafish to specifically be required for photoreceptor maintenance and therefore causes an ocular phenotype, if altered.", "img": null}, {"id": "fc_007_12", "ch": 7, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NPHP1`** are associated with which clinical phenotype and molecular mechanism in **Nephronophthisis**?", "a": "Pathogenic variants in NPHP1 are by far the most common genetic cause for NPHP.", "img": null}, {"id": "fc_007_13", "ch": 7, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CPLANE1`** are associated with which clinical phenotype and molecular mechanism in **Joubert Syndrome**?", "a": "The most common genes associated with JS, accounting for approximately 6–9% each, are CPLANE1 , CC2D2A , CEP290 , AHI1 , and TMEM67 .", "img": null}, {"id": "fc_007_14", "ch": 7, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TMEM67`** are associated with which clinical phenotype and molecular mechanism in **Joubert Syndrome**?", "a": "A syndromic form of JS called COACH , which stands for colobomas, cognitive impairment, ataxia, cerebellar vermis hypoplasia, and hepatic fibrosis, is most frequently caused by pathogenic variants in TMEM67 .", "img": null}, {"id": "fc_007_15", "ch": 7, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ALMS1`** are associated with which clinical phenotype and molecular mechanism in **Alström Syndrome**?", "a": "Alström syndrome is caused by pathogenic variants in the gene ALMS1 .", "img": null}, {"id": "fc_007_16", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ciliopathies Clinical Presentations and Syndromes**, how is **Meckel-Gruber syndrome complex (MKS)** defined and characterized?", "a": "Meckel-Gruber syndrome complex (MKS) , the nephronophthisis complex (NPHP) , and the “BBSome” (Bardet-Biedl syndrome) , implying an association between subcellular localization of proteins and certain disease group clusters (Fig.", "img": null}, {"id": "fc_007_17", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Kidney Involvement**, how is **Autosomal dominant polycystic kidney disease (ADPKD)** defined and characterized?", "a": "Autosomal dominant polycystic kidney disease (ADPKD) is the most common of all autosomal dominant monogenic diseases in humans (~1:1,000 live births).", "img": null}, {"id": "fc_007_18", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Kidney Involvement**, how is **autosomal recessive polycystic kidney disease (ARPKD)** defined and characterized?", "a": "autosomal recessive polycystic kidney disease (ARPKD) and the NPHP-like related ciliopathies (RCs) .", "img": null}, {"id": "fc_007_19", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Autosomal Recessive Polycystic Kidney Disease (ARPKD)**, how is **pulmonary hypoplasia** defined and characterized?", "a": "pulmonary hypoplasia results from mechanical pressure on the fetal lungs due to oligohydramnios and the massively enlarged kidneys, leading to an estimated mortality of 30–50% shortly after birth.", "img": null}, {"id": "fc_007_20", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Autosomal Recessive Polycystic Kidney Disease (ARPKD)**, how is **congenital hepatic fibrosis** defined and characterized?", "a": "congenital hepatic fibrosis and/or Caroli disease (a dilation of the intrahepatic bile ducts), caused by ductal plate malformation of the developing biliary system.", "img": null}, {"id": "fc_007_21", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Nephronophthisis**, how is **infantile** defined and characterized?", "a": "infantile , juvenile , and adolescent NPHP, with manifestation of ESKD at median ages of 1 year, 13 years, and 19 years, respectively.", "img": null}, {"id": "fc_007_22", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ocular Involvement**, how is **Leber congenital amaurosis** defined and characterized?", "a": "Leber congenital amaurosis , the most severe form of inherited retinal dystrophies.", "img": null}, {"id": "fc_007_23", "ch": 7, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ocular Involvement**, how is **coloboma** defined and characterized?", "a": "coloboma resulting from abnormal closure of the optic cup during eye development.", "img": null}, {"id": "fc_007_24", "ch": 7, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 7.1):", "a": "The key structural components of the primary cilium. The cilium is a hair-like structure, protruding from the cell surface, and consists of a microtubule-based axoneme and a surrounding specialized ciliary membrane. This nonmotile cilium has nine outer microtubule doublets, but no central doublet, in contrast to motile cilia. The axoneme is assembled from the basal body, also called the mother centriole. Ciliary components, receptors, and signaling proteins are trafficked in anterograde and retrograde directions on the axoneme by intraflagellar transport (IFT) complexes (IFTA and IFTB), which engage dynein II and kinesins (blue box), respectively. The BBSome complex assists traffic at the base of the cilium and then cooperates with IFTs. The base of the cilium is segregated from the cytoplasm by the transition zone, defined by the presence of Y-linkers. The primary cilium is erected in quiescent cells and disassembled before cell division. BBS, Bardet-Biedl syndrome; KIF, kinesin family members.", "img": "fig_p0124_01.jpg"}, {"id": "fc_007_25", "ch": 7, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 7.2):", "a": "Subcellular localization of proteins encoded by known monogenic disease-causing genes of nephronophthisis-related ciliopathies (NPHP-RC). Proteins are color-coded based on their respective disease group (red/orange/pink: nephronophthisis [NPHP], Senior–Løken syndrome [SLS], Joubert syndrome [JBTS], Meckel–Gruber syndrome [MKS]; yellow: Bardet–Biedl syndrome [BBS]; green: skeletal ciliopathies). It becomes apparent that disease groups cluster to distinct subcellular localizations. IFT, Intraflagellar transport.", "img": "fig_p0125_02.jpg"}, {"id": "fc_007_26", "ch": 7, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 7.3):", "a": "Monogenic genes of nephronophthisis-related ciliopathies (NPHP-RC) cause distinct but widely overlapping phenotypes. Monogenic genes of NPHP-RC are categorized into four major phenotypes, namely, JBTS (blue, Joubert syndrome [JBTS]: congenital brain malformations, cerebellar vermis hypoplasia, and intellectual disability), NPHP/SLS (red, nephronophthisis/Senior–Loken syndrome [SLS]: nephronophthisis [NPHP], retinal degeneration, coloboma), BBS (yellow, Bardet–Biedl syndrome [BBS]: obesity, intellectual disability, retinal degeneration, cystic kidney disease, polydactyly, hypogonadisms), and skeletal ciliopathies (green, oral-facial-digital syndrome [OFD], cranioectodermal dysplasia (CED), short-rib thoracic dysplasia [SRTD]). As shown in a Venn diagram, numerous genes can give rise to overlapping phenotypes if they become pathogenic variants. Meckel–Gruber syndrome (MKS), the most severe clinical manifestation of NPHP-RC, is caused by variants in monogenic genes of nephronophthisis, Joubert syndrome, and Bardet–Biedl syndrome on an allelic basis. White text indicates genes in which liver involvement has been reported. Recently discovered genes include: SUFU (De Mori 2017, Serpieri 2022), IFT74 (Lindstrand 2016, Luo 2021), PIBF1 (Wheway 2015, Hebbar 2018), TOGARAM1 (Latour 2020, Morbidoni 2021), ARL3 (Alkanderi 2018, Powell 2019), KIAA0753 (Hammarsjoe 2017, Stephen 2017), TMEM218 (Van de Weghe 2021, Epting 20", "img": "fig_p0126_01.jpg"}, {"id": "fc_007_27", "ch": 7, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **TABLE 7.1 Clinical Summary**, what are the distinguishing features of **Age of onset**?", "a": "**Autosomal Recessive Polycystic Kidney Disease (ARPKD)**: Infancy to adolescence; **Autosomal Dominant Polycystic Kidney Disease (ADPKD)**: Mostly infancy; Typically adult onset", "img": null}, {"id": "fc_007_28", "ch": 7, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **TABLE 7.1 Clinical Summary**, what are the distinguishing features of **Clinical findings**?", "a": "**Autosomal Recessive Polycystic Kidney Disease (ARPKD)**: • Polyuria • Polydipsia (with frequent night-time fluid intake) • Secondary enuresis • Growth retardation • At later stages: pallor, weakness, pruritus • Typically: Absence of edema, hypertension and urinary tract infections • Rarely: sudden death from fluid and electrolyte imbalance; **Autosomal Dominant Polycystic Kidney Disease (ADPKD)**: • Often: “Potter” oligohydramnios phenotype at birth: • Enlarged kidneys • Pulmonary hypoplasia • Characteristic facies • Contracted limbs • Treatment-resistant arterial hypertension (~80%), often starting in infancy • ESKD in 60% of patients by 20 years of age • Kidneys decrease in size as fibrosis advances • Liver complications, e.g., portal hypertension, cholangitis; • (Gross) Hematuria • Urinary tract infections • Urinary concentration defect • Abdominal fullness/pain • Nephrolithiasis (20–35%) • Hypertension in 20–40% of children/ adolescents (before glomerular filtration rate (GFR) decline), in most adults • End stage kidney disease (ESKD) in 50% at age of 60 years • Intracranial aneurysms in~8% of patients (increased in patients with a positive family history) • Heart valve abnormalities • Aortic root dilation • Diverticulosis", "img": null}, {"id": "fc_008_01", "ch": 8, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PIK3CA**?", "a": "**Causative Gene(s):** `PIK3CA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Overgrowth Syndromes: PIK3CA-related overgrowth spectrum (Table 8.2) — PIK3CA -related overgrowth spectrum is the most common mosaic overgrowth disorder and is up to 1,000 times more common than the next most prevalent mosaic overgrowth disorder, Proteus syndrome.", "img": null}, {"id": "fc_008_02", "ch": 8, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AKT(PKB)**?", "a": "**Causative Gene(s):** `AKT1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Overgrowth Syndromes: AKT1 (PKBA): Proteus syndrome — Clinical Manifestations: Overgrowth, often affecting the lower limbs", "img": null}, {"id": "fc_008_03", "ch": 8, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PTEN hamartoma tumor syndrome (Cowden syndrome, Bannayan- Riley-Ruvalcaba syndrome, and PTEN-related Proteus s**?", "a": "**Causative Gene(s):** `PTEN` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Manifestations: Benign and malignant neoplasms; brain overgrowth and neurodevelopmental anomalies, asymmetrical bones and soft-tissue overgrowth", "img": null}, {"id": "fc_008_04", "ch": 8, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TSC1/2**?", "a": "**Causative Gene(s):** `TSC1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Overgrowth Syndromes: Tuberous sclerosis complex — Clinical Manifestations: Hypopigmented macules, facial angiofibromas, ash leaf spots, nail fibromas, cortical tubercles, subependymal nodules, and subependymal giant cell astrocytomas, seizures, and intellectual disability/developmental delay", "img": null}, {"id": "fc_008_05", "ch": 8, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Mosaic Overgrowth Syndromes**?", "a": "**Causative Gene(s):** `PIK3CA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Lymphatic and other vascular malformative/overgrowth disorders are caused by somatic pathogenic variants in PIK3CA.", "img": null}, {"id": "fc_008_06", "ch": 8, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Diagnosis of Mosaic Overgrowth Disorders**?", "a": "**Causative Gene(s):** `PIK3R1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** There are no consistent clinical features that distinguish PIK3CA -related overgrowth spectrum (PROS) from PIK3R1 -related overgrowth spectrum , although clinical criteria have been suggested for PROS (Tables 8.1, 8.2).", "img": null}, {"id": "fc_008_07", "ch": 8, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PIK3CA -Related Overgrowth Spectrum (PROS)**?", "a": "**Causative Gene(s):** `PIK3CA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** PIK3CA -related overgrowth spectrum is the most common mosaic overgrowth disorder and is up to 1,000 times more common than the next most prevalent mosaic overgrowth disorder, Proteus syndrome.", "img": null}, {"id": "fc_008_08", "ch": 8, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PIK3CA`** are associated with which clinical phenotype and molecular mechanism in **Mosaic Overgrowth Syndromes**?", "a": "Lymphatic and other vascular malformative/overgrowth disorders are caused by somatic pathogenic variants in PIK3CA.", "img": null}, {"id": "fc_008_09", "ch": 8, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PIK3R1`** are associated with which clinical phenotype and molecular mechanism in **Diagnosis of Mosaic Overgrowth Disorders**?", "a": "There are no consistent clinical features that distinguish PIK3CA -related overgrowth spectrum (PROS) from PIK3R1 -related overgrowth spectrum , although clinical criteria have been suggested for PROS (Tables 8.1, 8.2).", "img": null}, {"id": "fc_008_10", "ch": 8, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PTEN`** are associated with which clinical phenotype and molecular mechanism in **Diagnosis of Mosaic Overgrowth Disorders**?", "a": "AKT1 -related Proteus syndrome, PIK3R1 -related overgrowth spectrum, and PTEN -related SOLAMEN syndrome are rare; knowledge of the range and specificity of phenotypic features that would allow for clinical diagnosis is limited.", "img": null}, {"id": "fc_008_11", "ch": 8, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`AKT1`** are associated with which clinical phenotype and molecular mechanism in **Diagnosis of Mosaic Overgrowth Disorders**?", "a": "For example, the strongly activating PIK3CA variants and both AKT1 variants that cause these disorders are absent in peripheral blood.", "img": null}, {"id": "fc_008_12", "ch": 8, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`AKT3`** are associated with which clinical phenotype and molecular mechanism in **Molecular Mechanism and Pathogenesis**?", "a": "It is sometimes referred to as protein kinase B (PKB), or by both names as “Akt/PKB.” There are three paralogs in humans, AKT1 , AKT2 , and AKT3 .", "img": null}, {"id": "fc_008_13", "ch": 8, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATK1`** are associated with which clinical phenotype and molecular mechanism in **Management**?", "a": "The risk of deep vein thrombosis and pulmonary embolism is not precisely established but is higher in ATK1 -related Proteus syndrome than it is in PIK3CA -relted overgrowth spectrum.", "img": null}, {"id": "fc_008_14", "ch": 8, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Diagnosis**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** However, molecular diagnosis remains important, increasingly so because of the availability of the targeted therapeutic agent alpelisib.", "img": null}, {"id": "fc_008_15", "ch": 8, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Management**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Targeted therapy with a PIK3CA inhibitor (alpelisib) should be considered and can be effective in reducing lesion size in some patients, especially those with large vascular malformations.", "img": null}, {"id": "fc_008_16", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Mosaic Overgrowth Syndromes**, how is **Mosaicism** defined and characterized?", "a": "Mosaicism is the state of an organism having cells of two distinct genotypes despite all cells being derived from a single fertilized gamete (Fig.", "img": null}, {"id": "fc_008_17", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Mosaic Overgrowth Syndromes**, how is **lines of Blaschko** defined and characterized?", "a": "lines of Blaschko are a key diagnostic feature of mosaicism (Fig.", "img": null}, {"id": "fc_008_18", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Mosaic Overgrowth Syndromes**, how is **constitutional variant** defined and characterized?", "a": "constitutional variant ) is another feature that suggests mosaicism: if a particular variant is incompatible with life as a constitutional variant, then the only possible presentation is as a mosaic disorder.", "img": null}, {"id": "fc_008_19", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis of Mosaic Overgrowth Disorders**, how is **Proteus syndrome** defined and characterized?", "a": "Proteus syndrome has a highly distinct phenotype, findings early in disease progression are often indistinct.", "img": null}, {"id": "fc_008_20", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis of Mosaic Overgrowth Disorders**, how is **Critically** defined and characterized?", "a": "Critically , sampling must be from an affected area of the body .", "img": null}, {"id": "fc_008_21", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis of Mosaic Overgrowth Disorders**, how is **second critical factor** defined and characterized?", "a": "second critical factor is selecting a testing laboratory that accepts the type of tissue sampled and that uses an assay platform that is sensitive to low variant allele fractions.", "img": null}, {"id": "fc_008_22", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis of Mosaic Overgrowth Disorders**, how is **Variant allele fraction** defined and characterized?", "a": "Variant allele fraction is the proportion of all copies of the gene in the specimen that harbor the variant under investigation.", "img": null}, {"id": "fc_008_23", "ch": 8, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis of Mosaic Overgrowth Disorders**, how is **third critical factor** defined and characterized?", "a": "third critical factor is determining which variants and genes will be tested.", "img": null}, {"id": "fc_008_24", "ch": 8, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 8.1):", "a": "Photographs and MRIs of participants with isolated LM, CLOVES, KTS, and FAVA. (A) An 8-month-old male (LM1) with isolated LM. Note swelling in deltoid region without cutaneous vascular signs. Coronal and sagittal fat-saturated T2-weighted MRI demonstrates macrocystic LM (a multilocular cystic mass) involving the anterolateral aspects of the right shoulder without muscular infiltration (arrows) ; humeral head (asterisk) . (B) A 19-month-old female (CL12) with CLOVES syndrome. Note asymmetric distribution of truncal lipomatous masses and bilateral lower extremity involvement. Coronal fat-saturated T1-weighted MRI after contrast administration demonstrates moderate heterogeneous enhancement of the bilateral truncal masses (arrows) . Axial T1-weighted MRI without contrast depicts truncal lipomatous overgrowth (arrows) ; segment VI of the liver (asterisk) . (C) A 3-year-old male (KT4) with KTS. Note capillary LM and overgrowth involving the right lower extremity. Coronal and axial fat-saturated T2-weighted MRI shows the persistent marginal vein system (bent arrows) and marked enlargement of the subcutaneous tissues due to a combination of lymphatic fluid and fat (straight arrow) . There are also intramuscular venous malformations. (D) A 9-year-old male (F8) with FAVA of the left gastrocnemius muscle; note absence of overgrowth and cutaneous vascular anomalies. Sagittal fat-saturated T1-weighted MRI after contrast administration demonstrates the longit", "img": "fig_p0144_01.jpg"}, {"id": "fc_008_25", "ch": 8, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 8.2):", "a": "Overview of the most common clinical presentations, features, and PIK3CA (activating variants of the p110α subunit of phosphatidylinositol 3-kinases)-related overgrowth spectrum (PROS).", "img": "fig_p0145_03.jpg"}, {"id": "fc_008_26", "ch": 8, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 8.3):", "a": "Simplified PI3K-AKT-mTOR pathway and associated clinical overgrowth disorders. PDK,", "img": "fig_p0146_01.jpg"}, {"id": "fc_008_27", "ch": 8, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 8.4):", "a": "Diagram showing how pathogenic variants occurring at different moments of embryonic", "img": "fig_p0146_03.jpg"}, {"id": "fc_008_28", "ch": 8, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **PROS Clinical Manifestations**, what are the distinguishing features of **Syndromic Forms**?", "a": "**Clinical Manifestations**: l", "img": null}, {"id": "fc_009_01", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ectodermal dysplasia 1, hypohidrotic, X-linked (Christ–Siemens–Touraine syndrome, XLHED)**?", "a": "**Causative Gene(s):** `EDA` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Pathway: EDA-NFκB pathway — Hypodontia:  — Hair Abnormalities:  — s Glandula:  — The most common HED, X-linked hypohidrotic ectod ermal dysplasia (XLHED) , is caused by pathogenic variants in EDA , located on the X chromosome.", "img": null}, {"id": "fc_009_02", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ectodermal dysplasia 10A and 10B, AD and AR (ECTD10A, B)**?", "a": "**Causative Gene(s):** `EDAR, ECTD10A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Hypodontia:  — Hair Abnormalities:  — Nail Feature:  — s Glandula: ", "img": null}, {"id": "fc_009_03", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ectodermal dysplasia 11A and 11B, AD and AR (ECTD11A, B)**?", "a": "**Causative Gene(s):** `EDARADD, ECTD11A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Hypodontia:  — Hair Abnormalities:  — Nail Feature:  — s Glandula: ", "img": null}, {"id": "fc_009_04", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Incontinentia pigmenti (IP)**?", "a": "**Causative Gene(s):** `IKBKG` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Hypodontia:  — Hair Abnormalities:  — Nail Feature:  — The salient clinical features, genetics, diagnosis, and management of EDs will be explored through several of the most common and prototypical EDs: hypohidrotic ectodermal dysplasias, TP63 -related disorders, incontinentia pigmenti, and PORCN -related developmental disorders.", "img": null}, {"id": "fc_009_05", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ectodermal dysplasia and immunodeficiency 1, AD and AR (EDAID1)**?", "a": "**Causative Gene(s):** `IKBKG, EDAID1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Hypodontia:  — Hair Abnormalities:  — s Glandula: ", "img": null}, {"id": "fc_009_06", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ectodermal dysplasia and immunodeficiency 2 (EDAID2)**?", "a": "**Causative Gene(s):** `EDAID2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Affected Gene(s): NFKBIA — Hypodontia:  — Hair Abnormalities:  — s Glandula: ", "img": null}, {"id": "fc_009_07", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Congenital heart defects and ectodermal dysplasia (CHDED)**?", "a": "**Causative Gene(s):** `PRKD1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Hypodontia:  — Hair Abnormalities:  — Nail Feature:  — r Additional Symptoms: ", "img": null}, {"id": "fc_009_08", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hidrotic form of ectodermal dysplasia, not yet OMIM-listed**?", "a": "**Causative Gene(s):** `TRAF6` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Hypodontia:  — Hair Abnormalities:  — Nail Feature: ", "img": null}, {"id": "fc_009_09", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Focal facial dermal dysplasia 3/Ablepharonmacrostomia syndrome (AMS)**?", "a": "**Causative Gene(s):** `TWIST2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Hair Abnormalities:  — s Glandula:  — r Additional Symptoms: ", "img": null}, {"id": "fc_009_10", "ch": 9, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Odonto–onycho–dermal dysplasia (OODD)/ Schöpf–Schulz–Passarge syndrome (SSPS)**?", "a": "**Causative Gene(s):** `WNT10A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Hypodontia:  — Hair Abnormalities:  — Nail Feature:  — s Glandula:  — Carriers of AR HEDs, such as patients with heterozygous pathogenic variants in WNT10A , may have mild findings, further confounding diagnosis of homozygous offspring, as well as recurrence risk estimates for future pregnancies.", "img": null}, {"id": "fc_009_11", "ch": 9, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TP63`** are associated with which clinical phenotype and molecular mechanism in **Ectodermal Dysplasia**?", "a": "The salient clinical features, genetics, diagnosis, and management of EDs will be explored through several of the most common and prototypical EDs: hypohidrotic ectodermal dysplasias, TP63 -related disorders, incontinentia pigmenti, and PORCN -related developmental disorders.", "img": null}, {"id": "fc_009_12", "ch": 9, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`WNT10A`** are associated with which clinical phenotype and molecular mechanism in **Genetics**?", "a": "Carriers of AR HEDs, such as patients with heterozygous pathogenic variants in WNT10A , may have mild findings, further confounding diagnosis of homozygous offspring, as well as recurrence risk estimates for future pregnancies.", "img": null}, {"id": "fc_009_13", "ch": 9, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ectodermal Dysplasia**, how is **Ectodermal dysplasias (EDs)** defined and characterized?", "a": "Ectodermal dysplasias (EDs) are genetically and phenotypically diverse disorders affecting two or more structures derived from the ectoderm, including teeth, skin, and ectodermal appendages such as hair, nails, eccrine sweat glands, and sebaceous glands.", "img": null}, {"id": "fc_009_14", "ch": 9, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hypohidrotic Ectodermal Dysplasias**, how is **Hypohidrotic ectodermal dysplasias (HEDs)** defined and characterized?", "a": "Hypohidrotic ectodermal dysplasias (HEDs) are phenotypically similar but genetically heterogeneous.", "img": null}, {"id": "fc_009_15", "ch": 9, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetics**, how is **X-linked hypohidrotic ectod ermal dysplasia (XLHED)** defined and characterized?", "a": "X-linked hypohidrotic ectod ermal dysplasia (XLHED) , is caused by pathogenic variants in EDA , located on the X chromosome.", "img": null}, {"id": "fc_009_16", "ch": 9, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other**, how is **AEC syndrome** defined and characterized?", "a": "AEC syndrome is caused by pathogenic variants affecting the SAM or the N-terminal domains of the ΔNp63α isoform.", "img": null}, {"id": "fc_009_17", "ch": 9, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Disorders Associated With Collodion or Collodion-like Membrane in the Newborn**, how is **ADULT syndrome** defined and characterized?", "a": "ADULT syndrome is typically caused by pathogenic variants affecting the DNA-B domain.", "img": null}, {"id": "fc_009_18", "ch": 9, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Disorders Associated With Collodion or Collodion-like Membrane in the Newborn**, how is **EEC3 syndrome** defined and characterized?", "a": "EEC3 syndrome is caused by pathogenic missense variants affecting the DNA-B domain.", "img": null}, {"id": "fc_009_19", "ch": 9, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Disorders Associated With Collodion or Collodion-like Membrane in the Newborn**, how is **Limb-mammary syndrome** defined and characterized?", "a": "Limb-mammary syndrome is caused by pathogenic missense variants located between the TA and DNA-B domains or by truncating variants in the SAM domain.", "img": null}, {"id": "fc_009_20", "ch": 9, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 9.1):", "a": "The multiple interactions between the EDA/NF-κB, Wnt and p63 pathways (in orange, purple, and blue, respectively). Arrows indicate stimulatory protein–protein or protein–gene regulatory interactions, bars are used for inhibitory interactions.", "img": "fig_p0164_01.jpg"}, {"id": "fc_009_21", "ch": 9, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 9.2):", "a": "Hypohidrotic ectodermal dysplasia (HED). (A) This male shows the short, sparse hair; large conspicuous nostrils; wide cheekbones with flat malar ridges; periorbital wrinkling; a thick everted lower lip; prominent chin; and low-lying, anteriorly placed, pointed ears. (B) Conical incisors in a toddler with HED. Note the periorbital wrinkling, flat malar ridges, and prominent ears. (C) This female is a carrier for a variant in ectodysplasin but shows all of the characteristic facies features. Females with HED may also have a pathogenic variant in a gene encoding the receptor for ectodysplasin, inherited as an autosomal disorder.", "img": "fig_p0164_03.jpg"}, {"id": "fc_009_22", "ch": 9, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 9.3):", "a": "Collodion membrane in a neonate.", "img": "fig_p0165_18.jpg"}, {"id": "fc_009_23", "ch": 9, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Pathway Affected Gene(s) Disease(s)/Syndrome(s)— Previously Suggested Nomenclature OMIM No. Hypodontia Hair Abnormalitie**, what are the distinguishing features of **EDA-NFκB pathway**?", "a": "**Affected Gene(s)**: EDA; **Disease(s)/Syndrome(s)— Previously Suggested Nomenclature**: Ectodermal dysplasia 1, hypohidrotic, X-linked (Christ–Siemens–Touraine syndrome, XLHED); **OMIM No.**: 305100; **Hypodontia**: ; **Hair Abnormalities**: ; **s Glandula**: ", "img": null}, {"id": "fc_009_24", "ch": 9, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Affected Gene(s) Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere OMIM No. Hypodo**, what are the distinguishing features of **CDHI,CTNND1**?", "a": "**Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere**: Blepharocheilodontic syndrome 1/Blepharocheilodontic syndrome 2 (BCDS1/BCDS2; **OMIM No.**: 119580, 617681; **Hypodontia**: ; **Hair**: ; **Additional Symptoms**: ", "img": null}, {"id": "fc_009_25", "ch": 9, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Affected Gene(s) Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere OMIM No. Hypodo**, what are the distinguishing features of **IFT43, -52. -122, -140 WDR19, -35**?", "a": "**Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere**: Cranioectodermal dysplasia, types 1–4 (CED) or Sensenbrenner syndrome; **OMIM No.**: 218330; **Hypodontia**: ; **Hair**: ; **Nail Phenotypic Features**: ; **Additional Symptoms**: ", "img": null}, {"id": "fc_009_26", "ch": 9, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Affected Gene(s) Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere OMIM No. Hypodo**, what are the distinguishing features of **EVC, EVC2**?", "a": "**Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere**: Ellis-van Creveld syndrome (EVC); **OMIM No.**: 22550000; **Hypodontia**: ; **Hair**: ; **Nail Phenotypic Features**: ; **Additional Symptoms**: ", "img": null}, {"id": "fc_009_27", "ch": 9, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Affected Gene(s) Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere OMIM No. Hypodo**, what are the distinguishing features of **SREBFI**?", "a": "**Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere**: Mucoepithelial dysplasia, hereditary (HMD); **OMIM No.**: 158310; **Hair**: ; **Nail Phenotypic Features**: ", "img": null}, {"id": "fc_009_28", "ch": 9, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Affected Gene(s) Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere OMIM No. Hypodo**, what are the distinguishing features of **HEPHLI**?", "a": "**Syndrome(s) With a Partial Ectodermal Dysplasia-like Phenotype But Classified Elsewhere**: Pili torti and developmental delay (HJDD); **OMIM No.**: 261990; **Hair**: ; **Nail Phenotypic Features**: ; **Additional Symptoms**: ", "img": null}, {"id": "fc_010_01", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ehlers-Danlos syndrome (EDS)** (#130000, #130010, #130060, #617821, #225320)?", "a": "**Causative Gene(s):** `COL5A1, COL1, COL3, COL5` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Collagen Type: COL1 COL3 COL5 — Genetic Alteration: Variants in 20 genes have been found to cause EDS (#130000). Classical EDS (#130010) results from variants in either the COL5A1(120215) orCOL5A2(120190) gene. Variants inCOL1A1(120150) orCOL1A2(120160) that lead to skipping of exon 6 of the mRNA coding the pro α1 or pro α2-chain result i", "img": null}, {"id": "fc_010_02", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Osteogenesis Imperfecta (OI)** (#166200, #166210, #259420, #166220)?", "a": "**Causative Gene(s):** `COL1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Collagen Type: COL1 — Genetic Alteration: Variants in theCOL1A1(120150) andCOL1A2(120160) genes are responsible for more than 90% of all cases of OI (#166200). Most of the variants causative of OI type I affectCOL1A1gene and result in reduced levels of COL1, whereas those responsible for most of OI types II (#166210), III (#259420) and IV", "img": null}, {"id": "fc_010_03", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Caffey disease, also called infantile cortical hyperostosis** (#120150, #114000)?", "a": "**Causative Gene(s):** `COL1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Type: COL1 — Genetic Alteration: Two missense variants inCOL1A1(*120150) (variant c.3040C>T, p.[Arg836Cys] and variant c. c.2752C>T, p.[Arg918Cys]) have been identified in individuals with Caffey disease (#114000). Inheritance is autosomal dominant but not all people who inherit the variant develop signs and symptoms. The amino acid chang", "img": null}, {"id": "fc_010_04", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Spondyloepiphysea l dysplasia congenita (SED)** (#183900, #120140)?", "a": "**Causative Gene(s):** `COL2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Type: COL2 — Genetic Alteration: SED congenita (#183900) is caused by heterozygous variant inCOL2A1gene (*120140) on chromosome 12q13. The inheritance is autosomal dominant. — Major Clinical Features: SED congenita is a chondrodysplasia characterized by short spine, barrel-shaped chest, abnormal epiphyses, and flattened vertebral bodies.", "img": null}, {"id": "fc_010_05", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Stanescu type of spondyloepiphyseal dysplasia (SEDSTN)** (#616583, #120140)?", "a": "**Causative Gene(s):** `COL2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Type: COL2 — Genetic Alteration: SEDSTN (#616583) is caused by heterozygous variant in COL2A1gene (*120140) on chromosome 12q13. The inheritance is autosomal dominant. — Major Clinical Features: Spondyloepiphyseal dysplasia with accumulation of glycoprotein in chondrocytes has been designated the “Stanescu type.” Clinical hallmarks includ", "img": null}, {"id": "fc_010_06", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Multiple epiphyseal dysplasia with myopia and conductive deafness (EDMMD)** (#132450, #120140)?", "a": "**Causative Gene(s):** `COL2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Collagen Type: COL2 — Genetic Alteration: EDMMD (#132450) is caused by heterozygous variant in COL2A1gene (*120140) on chromosome 12q13. The inheritance is autosomal dominant. — Major Clinical Features: EDMMD is characterized by epiphyseal dysplasia associated with progressive myopia, retinal thinning, crenated cataracts, conductive deafn", "img": null}, {"id": "fc_010_07", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Achondrogenesis type II (ACG2)** (#200610, #120140)?", "a": "**Causative Gene(s):** `ACG2, COL2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Collagen Type: COL2 — Genetic Alteration: ACG2 (#200610) is caused by variants inCOL2A1gene (*120140) on chromosome 12q13. The inheritance is autosomal dominant but somatic and germline mosaicism have also been reported. — Major Clinical Features: ACG2 is characterized by severe micromelic dwarfism with small chest and prominent abdomen.", "img": null}, {"id": "fc_010_08", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Czech dysplasia** (#609162, #120140)?", "a": "**Causative Gene(s):** `COL2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Collagen Type: COL2 — Genetic Alteration: Czech dysplasia (#609162) is caused by heterozygous variants inCOL2A1gene (*120140) on chromosome 12q13. The inheritance is autosomal dominant. — Major Clinical Features: Czech dysplasia is a skeletal dysplasia characterized by early and progressive onset, shortening of the third and fourth toes c", "img": null}, {"id": "fc_010_09", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Legg-Calve-Perthes disease (LCPD)** (#150600, #120140, #608805)?", "a": "**Causative Gene(s):** `COL2A1, COL2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Collagen Type: COL2 — Genetic Alteration: LCPD (#150600) is caused by heterozygous variant in the COL2A1(*120140) gene on chromosome 12q13. The inheritance is autosomal dominant. — Major Clinical Features: LCPD is a form of avascular necrosis of the femoral head (ANFH; #608805) that affects hip development in growing children. It is due t", "img": null}, {"id": "fc_010_10", "ch": 10, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Osteoarthritis with mild chondrodysplasia (OSCDP)** (#604864, #120140)?", "a": "**Causative Gene(s):** `COL2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Collagen Type: COL2 — Genetic Alteration: OSCDP (#604864) is caused by heterozygous variant in COL2A1gene (*120140) on chromosome 12q13. The inheritance is autosomal dominant. — Major Clinical Features: OSCDP is a common disease that produces joint pain and stiffness together with radiologic evidence of progressive degeneration of joint c", "img": null}, {"id": "fc_010_11", "ch": 10, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`P3H1`** are associated with which clinical phenotype and molecular mechanism in **Collagen Biosynthesis**?", "a": "The exact role of 3-hydroxyproline residues is unknown, though their presence confers specific biomechanical properties and influences collagen fiber assembly; a severe autosomal recessive form of osteogenesis imperfecta is related to pathogenic variants in P3H1 .", "img": null}, {"id": "fc_010_12", "ch": 10, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`COL5A1`** are associated with which clinical phenotype and molecular mechanism in **Molecular Basis**?", "a": "Classical EDS is caused by heterozygous pathogenic variants in the genes coding for type V collagen ( COL5A1 and COL5A2 ), while vascular EDS is caused by heterozygous pathogenic variants in the gene coding for type III collagen (COL3A1) .", "img": null}, {"id": "fc_010_13", "ch": 10, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SLC39A13`** are associated with which clinical phenotype and molecular mechanism in **Molecular Basis**?", "a": "A rare type of spondylodysplastic EDS is caused by biallelic pathogenic variants in SLC39A13 , encoding the intracellular zinc transporter ZIP13.", "img": null}, {"id": "fc_010_14", "ch": 10, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TGFBR1`** are associated with which clinical phenotype and molecular mechanism in **Related Disorders**?", "a": "Loeys-Dietz syndrome is caused by pathogenic variants in genes encoding components of the TGFβ signaling pathway, including the cytokines TGFβ2 and TGFβ3, the cytokine receptors TGFBR1 and TGFBR2, and the downstream effectors SMAD2, SMAD3.", "img": null}, {"id": "fc_010_15", "ch": 10, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FBN2`** are associated with which clinical phenotype and molecular mechanism in **Related Disorders**?", "a": "CCA is caused by heterozygous pathogenic variants in FBN2 , the gene encoding fibrillin-2, and is characterized by tall stature, arachnodactyly, progressive scoliosis, contractures, and crumpled ears.", "img": null}, {"id": "fc_010_16", "ch": 10, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATP7A`** are associated with which clinical phenotype and molecular mechanism in **Molecular Basis**?", "a": "Occipital horn syndrome , previously referred to as X-linked cutis laxa , is caused by pathogenic variants in ATP7A , the same gene that causes Menkes disease and ATP7A -related distal motor neuropathy (also known as distal spinal muscular atrophy-3 ).", "img": null}, {"id": "fc_010_17", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **FRANSISKA LIEVE MALFAIT**, how is **collagens** defined and characterized?", "a": "collagens , proteoglycans , and glycoproteins .", "img": null}, {"id": "fc_010_18", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Collagen Structure and Classification**, how is **Fibril-forming** defined and characterized?", "a": "Fibril-forming or fibrillar collagens make up approximately 70% of all collagen in the human body.", "img": null}, {"id": "fc_010_19", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **10.1 Hereditary Disorders Resulting From Collagen Structural Alterations—cont’d**, how is **Network-forming collagens** defined and characterized?", "a": "Network-forming collagens (types IV, VI, VIII, and X) associate in multiple dimensions and form open networks rather than fibers.", "img": null}, {"id": "fc_010_20", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Collagen Biosynthesis**, how is **matrix metalloproteinases (MMPs)** defined and characterized?", "a": "matrix metalloproteinases (MMPs) termed collagenases that cause partial unfolding of the triple helices into gelatin-like structures that are further degraded by less specific proteinases.", "img": null}, {"id": "fc_010_21", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microfibrils and Elastic Fibers**, how is **microfibrils** defined and characterized?", "a": "microfibrils and elastic fibers , insoluble ECM assemblies that permit long-range deformability and recoil.", "img": null}, {"id": "fc_010_22", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microfibrils and Elastic Fibers**, how is **multiple growth factors** defined and characterized?", "a": "multiple growth factors including TGFβ and bone morphogenic protein either via direct binding or through interaction with latent TGFβ-binding proteins.", "img": null}, {"id": "fc_010_23", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microfibrils and Elastic Fibers**, how is **elastic fibers** defined and characterized?", "a": "elastic fibers with a hydrophobic elastin core and a surrounding microfibrillar coat (Fig.", "img": null}, {"id": "fc_010_24", "ch": 10, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microfibrils and Elastic Fibers**, how is **congenital contractural arachnodactyly** defined and characterized?", "a": "congenital contractural arachnodactyly , or more rarely in acromelic dysplasia, while defects in elastin lead to a form of cutis laxa .", "img": null}, {"id": "fc_010_25", "ch": 10, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 10.1):", "a": "Biosynthesis of a “prototype” collagen. The procollagen α-chains are synthesized by ribosomes in the rough endoplasmic reticulum (ER). Already during the synthesis of the nascent polypeptide, certain prolyl and lysyl residues are hydroxylated and modified by glycosylation. Three α-chains associate to form a trimer and fold into a triple helix. This process is facilitated by heat shock protein (HSP) 47, a collagen-specific molecular chaperone in the ER. The transport and Golgi organization (TANGO) protein 1 mediates secretion of the newly formed triple helical procollagen into the extracellular space, where the N- and C-terminal propeptides are cleaved by specific proteases. The mature collagen molecules assemble to form mixed fibrils with other collagens and non-collagenous molecules. The suprastructures are stabilized by covalent crosslinks. Small leucine-rich proteoglycans (SLRPs) and other proteoglycans have roles in the regulation of collagen fibrillogenesis and crosslinking. EDS, Ehlers–Danlos syndrome.", "img": "fig_p0196_01.jpg"}, {"id": "fc_010_26", "ch": 10, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 10.3):", "a": "Clinical features of Ehlers–Danlos syndrome (EDS). Patients with classical EDS demonstrating hyperextensible skin (A), joint hypermobility at the wrist (B), atrophic horseshoe-shaped scars on the shin (C), piezogenic papules on the heel (D), and the Gorlin sign (E). (F) Translucent skin with visible veins on the chest in a patient with vascular EDS.", "img": "fig_p0200_06.jpg"}, {"id": "fc_010_27", "ch": 10, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 10.4):", "a": "Atrophic scarring in an individual with classical EhlersDanlos syndrome.", "img": "fig_p0206_11.jpg"}, {"id": "fc_010_28", "ch": 10, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 10.5):", "a": "Beighton score. The range of motion of several key small and large joints is measured to provide an overview of joint hypermobility. Instability is not assessed. Scoring: 2 points for each bilateral measure in Nos. 1 to 4 and 1 point for No. 5, equaling a total possible score of 9. Hypermobility is considered significant with a score of ≥6 between the ages of 6 and 35. (Modified from Smits-Engelsman B, Klerks M, Kirby A. Beighton score: a valid measure for generalized hypermobility in children. J Pediatr . 2011;158:119-123.e4.)", "img": "fig_p0207_06.jpg"}, {"id": "fc_011_01", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Group 1**?", "a": "**Causative Gene(s):** `FGFR3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** FGFR3 Chondrodysplasias", "img": null}, {"id": "fc_011_02", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 01-0010**?", "a": "**Causative Gene(s):** `FGFR3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Thanatophoric dysplasia (type 1), FGFR3-related — Inheritance: AD — us Notes: Includes previous “platyspondylyic dysplasia type San Diego”", "img": null}, {"id": "fc_011_03", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 01-0020**?", "a": "**Causative Gene(s):** `FGFR3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Thanatophoric dysplasia (type 2), FGFR3-related — Inheritance: AD — us Notes: Radiographic differences between types 1 and 2 are correlated to specificFGFR3variants", "img": null}, {"id": "fc_011_04", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 01-0030**?", "a": "**Causative Gene(s):** `FGFR3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Severe achondroplasia with developmental delay and acanthosis nigricans (SADDAN), FGFR3-related — Inheritance: AD", "img": null}, {"id": "fc_011_05", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 01-0040**?", "a": "**Causative Gene(s):** `FGFR3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Achondroplasia, FGFR3-related — Inheritance: AD", "img": null}, {"id": "fc_011_06", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 01-0050**?", "a": "**Causative Gene(s):** `FGFR3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Hypochondroplasia, FGFR3-related — Inheritance: AD", "img": null}, {"id": "fc_011_07", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 02-0010**?", "a": "**Causative Gene(s):** `COL2A1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Achondrogenesis, COL2A1-related (formerly type 2, type Langer-Saldino) — Inheritance: AD — us Notes: Achondrogenesis type 2 and hypochondrogenesis form one phenotypic continuum", "img": null}, {"id": "fc_011_08", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 02-0020**?", "a": "**Causative Gene(s):** `COL2A1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Hypochondrogenesis, COL2A1-related — Inheritance: AD — us Notes: Achondrogenesis type 2 and hypochondrogenesis form one phenotypic continuum", "img": null}, {"id": "fc_011_09", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 02-0030**?", "a": "**Causative Gene(s):** `COL2A1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Platyspondylic dysplasia, type Torrance, COL2A1- related — Inheritance: AD — us Notes: Often variants in the C-propeptide of collagen 2", "img": null}, {"id": "fc_011_10", "ch": 11, "part": "II", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NOS 02-0040**?", "a": "**Causative Gene(s):** `COL2A1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Spondyloepiphyseal dysplasia congenita (SEDC), COL2A1-related — Inheritance: AD, AR* — us Notes: Includes mild SED with premature onset arthrosis, also known as osteoarthrosis with mild chondrodysplasia; includes Namaqualand type hip dysplasia. Mild SED cases may resemble MED (see note). AR*: very rare SED cases with biallelicCOL2A1varian", "img": null}, {"id": "fc_011_11", "ch": 11, "part": "II", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FAM46A`** are associated with which clinical phenotype and molecular mechanism in **Pharmaceutical Approaches to OI and Bone Fragility**?", "a": "Also affecting collagen expression and bone mineralization in osteoblasts is FAM46A, encoded by TENTA , which is involved in the polyadenylation of collagen transcripts and other proteins involved in bone mineralization.", "img": null}, {"id": "fc_011_12", "ch": 11, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Achondroplasia (group 1)**?", "a": "**Therapy / Intervention:** Vosoritide (Voxzogo)\n\n**Clinical Context:** Therapy: Vosoritide (Voxzogo) — Mechanism: CNP analog — Phase of Development: Approved — Representative References: PMID 34341520", "img": null}, {"id": "fc_011_13", "ch": 11, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Hypochondroplasia (group 1)**?", "a": "**Therapy / Intervention:** Vosoritide\n\n**Clinical Context:** Therapy: Vosoritide — Mechanism: CNP analog — Phase of Development: Phase 3 — Representative References: NCT06455059", "img": null}, {"id": "fc_011_14", "ch": 11, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Type 2 collagen disorders (group 2)**?", "a": "**Therapy / Intervention:** INS-101\n\n**Clinical Context:** Therapy: INS-101 — Mechanism: Gene therapy — Phase of Development: Preclinical — Representative References: https://innoskel.com/pipeline/", "img": null}, {"id": "fc_011_15", "ch": 11, "part": "II", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Diastrophic dysplasia (group 4)**?", "a": "**Therapy / Intervention:** N-acetylcysteine\n\n**Clinical Context:** Therapy: N-acetylcysteine — Mechanism: Sulfate supplementation — Phase of Development: Preclinical — Representative References: PMID 26206888, PMID 33545117", "img": null}, {"id": "fc_011_16", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Dysplasias vs. Dysostoses**, how is **Dysplasias** defined and characterized?", "a": "Dysplasias are disorders of skeletal growth; they tend to affect all skeletal elements, and are progressive, because they continue to evolve throughout childhood and adolescence.", "img": null}, {"id": "fc_011_17", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Dysplasias vs. Dysostoses**, how is **collagen type 1** defined and characterized?", "a": "collagen type 1 (the main collagen of bone ) and collagen type 2 (the main collagen of cartilage ).", "img": null}, {"id": "fc_011_18", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Therapeutic Approaches**, how is **Kniest dysplasia** defined and characterized?", "a": "Kniest dysplasia is essentially a severe SEDC variant with hyperplastic (but unossified) epiphyses; it is often associated with type II collagen exon-skipping variants or small deletions.", "img": null}, {"id": "fc_011_19", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Therapeutic Approaches**, how is **Stickler syndrome** defined and characterized?", "a": "Stickler syndrome that combines hearing loss, myopia of variable degree, cleft palate or uvula, and normal or even tall stature.", "img": null}, {"id": "fc_011_20", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **TRPV4 Group**, how is **Kozlowski-type spondylometaphyseal dysplasia** defined and characterized?", "a": "Kozlowski-type spondylometaphyseal dysplasia , brachyolmia , and familial digital arthropathy but also of peripheral neuropathies.", "img": null}, {"id": "fc_011_21", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Lysosomal Storage Disorders and the Dysostosis Multiplex Phenotype (See Chapter 46)**, how is **mucopolysaccharidoses** defined and characterized?", "a": "mucopolysaccharidoses are systemic metabolic disorders; in their full-blown forms, they affect connective tissues (skin, joints, eyes, heart valves, and more), the skeleton (with dysostosis multiplex), the airways, the inner ear, the liver and spleen, and the brain with intellectual disability.", "img": null}, {"id": "fc_011_22", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Lysosomal Storage Disorders and the Dysostosis Multiplex Phenotype (See Chapter 46)**, how is **mucolipidosis 2** defined and characterized?", "a": "mucolipidosis 2 and mucolipidosis 3 ; they are allelic conditions related to GNPTAB and GNPTG , necessary for the targeting of lysosomal enzymes to the lysosome.", "img": null}, {"id": "fc_011_23", "ch": 11, "part": "II", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Lysosomal Storage Disorders and the Dysostosis Multiplex Phenotype (See Chapter 46)**, how is **Achondrogenesis 1b** defined and characterized?", "a": "Achondrogenesis 1b has extreme shortening of limbs and fingers and a very hypoplastic thorax and is incompatible with life.", "img": null}, {"id": "fc_011_24", "ch": 11, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 11.1):", "a": "Diagnostic algorithm for the major skeletal dysplasias. TRPV4, Transient receptor potential vanilloid 4.", "img": "fig_p0274_07.jpg"}, {"id": "fc_011_25", "ch": 11, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 11.2):", "a": "Achondroplasia. Features of achondroplasia at birth (A), at the age of 2 months (B and C) showing the lordosis, at the age of 4 months (D) showing the basilar impression (arrow) , and at the age of 1 year (E and F). Radiographs show narrowed vertebrae, kyphosis, typical trident image of the iliac bone, and femoral heads looking like an ice-cream cone. (From Linglart A, Merzoug V, Lambert AS, Adamsbaum C. Bone dysplasia. Ann Endocrinol (Paris). 2017;78:114-122 [Fig. 1, p. 115].)", "img": "fig_p0275_07.jpg"}, {"id": "fc_011_26", "ch": 11, "part": "II", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 11.3):", "a": "Hypochondroplasia. Pelvic features at the age of 5, 10, and 16 years (A, B, and C). Stocky pattern of the bones (D and F) and specific long fibula (D). Narrowed lumbar spine (E) and hypertrophic extremity of the ulna (F). (From Linglart A, Merzoug V, Lambert AS, Adamsbaum C. Bone dysplasia. Ann Endocrinol (Paris). 2017;78:114-122 [Fig. 2, p. 116].)", "img": "fig_p0276_01.jpg"}, {"id": "fc_011_27", "ch": 11, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Group Number/ Number of Disorder Name of Group/Name of Disorder Inheritance Gene or Loc us Notes**, what are the distinguishing features of **Group 1**?", "a": "**Name of Group/Name of Disorder**: FGFR3 Chondrodysplasias", "img": null}, {"id": "fc_011_28", "ch": 11, "part": "II", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Group Number/ Number of Disorder Name of Group/Name of Disorder Inheritance Gene or Loc us Notes**, what are the distinguishing features of **NOS 01-0010**?", "a": "**Name of Group/Name of Disorder**: Thanatophoric dysplasia (type 1), FGFR3-related; **Inheritance**: AD; **Gene or Loc**: FGFR3; **us Notes**: Includes previous “platyspondylyic dysplasia type San Diego”", "img": null}, {"id": "fc_012_01", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Down syndrome (Trisomy 21)**?", "a": "**Causative Gene(s):** `DYRK1A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** % With Autism as a Feature: 20–40% — ID, ADHD — Phenotype: Distinctive facies, speech delay, hypotonia, hypothyroidism, recurrent infections, cardiac defects, leukemia, myeloproliferative disorders", "img": null}, {"id": "fc_012_02", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **XXYY**?", "a": "**Causative Gene(s):** `NLGN4Y` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** % With Autism as a Feature: 25–50% — ID, ADHD, tics, epilepsy — Phenotype: Distinctive facies, skeletal anomalies, congenital heart defects, tremor, diabetes, tall stature, cryptorchidism", "img": null}, {"id": "fc_012_03", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2p16.3 deletion/duplication syndromes**?", "a": "**Causative Gene(s):** `NRXN1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 40–45%; duplication associated with schizophrenia — ID, schizophrenia, epilepsy — Phenotype: Distinctive facies, speech delay, behavior problems, skeletal issues, heart and eye abnormalities", "img": null}, {"id": "fc_012_04", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2p15-p16.1 microdeletion syndrome**?", "a": "**Causative Gene(s):** `BCL11A, USP34` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Up to 60%; duplication associated with ID, ADHD, OCD, atypical physical features — ID, epilepsy — Phenotype: Microcephaly, distinctive facies, renal and eye anomalies — Gene(s) Implicated in ASD: BCL11A, REL, USP34, XP01", "img": null}, {"id": "fc_012_05", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2q13 deletion/duplication syndromes**?", "a": "**Causative Gene(s):** `NPHP1, RGPD6, BUB1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 30–35% deletion; 15–20% duplication — ID, ADHD — Phenotype: Congenital heart disease, behavioral problems, liver disease — Gene(s) Implicated in ASD: MALL, NPHP1, RGPD6, BUB1", "img": null}, {"id": "fc_012_06", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2q23.1 deletion/duplication syndromes**?", "a": "**Causative Gene(s):** `MBD5` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Up to 98% in both deletion and duplication — ID, epilepsy — Phenotype: Microcephaly, distinctive facies, speech delay, ataxia, short stature, mild skeletal anomalies, eye anomalies", "img": null}, {"id": "fc_012_07", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2q33.1 deletion/duplication (including 2q32-q33) syndromes**?", "a": "**Causative Gene(s):** `SATB2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Rare in deletion; 15% in duplication — ID, epilepsy — Phenotype: Atypical physical features, dental and palatal anomalies, behavioral problems, speech delay, hypotonia, skeletal anomalies", "img": null}, {"id": "fc_012_08", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2q33-q34 deletion syndrome**?", "a": "**Causative Gene(s):** `NRP2, ADAM23, KLF7, CREB1, MAP2, UNC80` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Up to 50%; duplication rare and associated with ID, hypotonia, atypical physical features — ID, epilepsy — Phenotype: Growth delay, distinctive facies, orofacial clefts, skeletal anomalies, hypotonia — Gene(s) Implicated in ASD: NRP2, ADAM23, KLF7, CREB1, MAP2, UNC80,andLANCL1", "img": null}, {"id": "fc_012_09", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2q37 deletion syndrome**?", "a": "**Causative Gene(s):** `HDAC4, TWIST2, KIF1A, FARP2, ATG4B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 60–70%; phenotype of duplication unknown — ID, epilepsy — Phenotype: Distinctive facies, Type E brachydactyly, short stature, obesity, dystonic movements, self-injurious and aggressive behaviors, hypotonia — Gene(s) Implicated in ASD: HDAC4, TWIST2, KIF1A, PASK, HDLBP, FARP2, ATG4B", "img": null}, {"id": "fc_012_10", "ch": 12, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **3p26 deletion/duplication syndromes**?", "a": "**Causative Gene(s):** `CNTN4, CNTN6` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 30% deletion; 15% duplication — ID, ADHD, epilepsy, schizophrenia, OCD — Phenotype: Microcephaly, distinctive facies, growth delay — Gene(s) Implicated in ASD: CNTN4, CNTN6", "img": null}, {"id": "fc_012_11", "ch": 12, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SHANK3`** are associated with which clinical phenotype and molecular mechanism in **22q13.3 Deletion**?", "a": "SHANK3 in the region affected by this CNV is thought to mediate many of these effects, although in some individuals with 22q13.3 deletion, SHANK3 is not disrupted although cognition and language development are impaired.", "img": null}, {"id": "fc_012_12", "ch": 12, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TSC1`** are associated with which clinical phenotype and molecular mechanism in **TSC1 and TSC2**?", "a": "Disruption of TSC1 or TSC2 , known tumor suppressor genes, produces the tuberous sclerosis complex (TSC) , a genetic disorder characterized by excessive growth or malformation of tissue throughout the body.", "img": null}, {"id": "fc_012_13", "ch": 12, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SETD2`** are associated with which clinical phenotype and molecular mechanism in **SETD2**?", "a": "Disruption of SETD2 can produce a neurodevelopmental disorder that includes macrocephaly (with or without associated ventriculomegaly), obesity, overgrowth, ASD, intellectual disability, developmental delay, and recurrent ear infections.", "img": null}, {"id": "fc_012_14", "ch": 12, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`DYRK1A`** are associated with which clinical phenotype and molecular mechanism in **DYRK1A**?", "a": "DYRK1A variants produce a syndrome characterized by microcephaly, intellectual impairment, and in ~85% of affected individuals, ASD.", "img": null}, {"id": "fc_012_15", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Autism Spectrum Disorders: Challenge of Heterogeneity and Rare Genetic Variation**, how is **polygenic risk score** defined and characterized?", "a": "polygenic risk score that represents the additive risk for ASD across common variants throughout the genome.", "img": null}, {"id": "fc_012_16", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Types of Rare Genetic Variation in Autism Spectrum Disorder**, how is **haploinsufficiency** defined and characterized?", "a": "haploinsufficiency (in the case of losses) or triplosensitivity (in the case of copy number gains).", "img": null}, {"id": "fc_012_17", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Maternal 15q11.2-q13 Duplication**, how is **imprinting** defined and characterized?", "a": "imprinting , a process by which only either the maternal or paternal copy of a gene is expressed, whereas the copy inherited from the other parent is imprinted or silenced.", "img": null}, {"id": "fc_012_18", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Maternal 15q11.2-q13 Duplication**, how is **Prader-Willi** defined and characterized?", "a": "Prader-Willi and Angelman syndrome are also neurodevelopmental syndromes that involve the disruption of genes in the 15q11.", "img": null}, {"id": "fc_012_19", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **22q11.2 Deletion**, how is **DiGeorge syndrome** defined and characterized?", "a": "DiGeorge syndrome or velocardiofacial syndrome ) phenotype involves multiple organ systems, including but not limited to congenital heart disease, velopharyngeal insufficiency, malformations of the palate, trachea or larynx, micrognathia, and anomalies of the thyroid and thymus.", "img": null}, {"id": "fc_012_20", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **7q11.23 Duplication**, how is **deletion** defined and characterized?", "a": "deletion (Williams syndrome) who meet criteria for ASD bear some resemblance to an active but odd presentation of ASD, described as a drive for social engagement that can be intrusive and difficulty reading social cues.", "img": null}, {"id": "fc_012_21", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **7q11.23 Duplication**, how is **duplication** defined and characterized?", "a": "duplication who meet criteria for ASD resemble the classic aloof presentation of ASD, with decreased social engagement coupled with difficulty in verbal communication.", "img": null}, {"id": "fc_012_22", "ch": 12, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **17p11.2 Deletion and Duplication**, how is **Smith-Magenis syndrome** defined and characterized?", "a": "Smith-Magenis syndrome , which is characterized by moderate intellectual impairment, self-injurious behavior, and a degree of impairment in social communication that can overlap with ASD.", "img": null}, {"id": "fc_012_23", "ch": 12, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### Severity Levels for Autism Spectrum Disorder (Examples of Level of Support Needs)**, what are the distinguishing features of **Level 3**?", "a": "**Social Communication**: Severe deficits in verbal and nonverbal social; **Restricted, Repetitive Behaviors**: Inflexibility of behavior, extreme difficulty coping", "img": null}, {"id": "fc_012_24", "ch": 12, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### Severity Levels for Autism Spectrum Disorder (Examples of Level of Support Needs)**, what are the distinguishing features of **“Requiring very substantial support”**?", "a": "**Social Communication**: communication skills cause severe impairments in functioning, very limited initiation of social interactions, and minimal response to social overtures from others. For example, a person with few words of intelligible speech who rarely initiates interaction and, when he or she does, makes unusual approaches to meet needs only and responds to only very direct social approaches.; **Restricted, Repetitive Behaviors**: with change, or other restricted/repetitive behaviors markedly interfere with functioning in all spheres. Great distress/difficulty changing focus or action.", "img": null}, {"id": "fc_012_25", "ch": 12, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### Severity Levels for Autism Spectrum Disorder (Examples of Level of Support Needs)—cont’d**, what are the distinguishing features of **Severity Level**?", "a": "**p p**: Social Communication; **pp**: Restricted, Repetitive Behaviors", "img": null}, {"id": "fc_012_26", "ch": 12, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### Severity Levels for Autism Spectrum Disorder (Examples of Level of Support Needs)—cont’d**, what are the distinguishing features of **Level 2 “Requiring substantial support”**?", "a": "**p p**: Marked deficits in verbal and nonverbal social communication skills; social impairments apparent even with supports in place; limited initiation of social interactions; and reduced or abnormal responses to social overtures from others. For example, a person who speaks simple sentences, whose interaction is limited to narrow special interests, and who has markedly odd nonverbal communication.; **pp**: Inflexibility of behavior, difficulty coping with change, or other restricted/repetitive behaviors appear frequently enough to be obvious to the casual observer and interfere with functioning in a variety of contexts. Distress and/or difficulty changing focus or action.", "img": null}, {"id": "fc_012_27", "ch": 12, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### Severity Levels for Autism Spectrum Disorder (Examples of Level of Support Needs)—cont’d**, what are the distinguishing features of **Level 1 “Requiring support”**?", "a": "**p p**: Without supports in place, deficits in social communication cause noticeable impairments. Difficulty initiating social interactions, and clear examples of atypical or unsuccessful responses to social overtures of others. May appear to have decreased interest in social interactions. For example, a person who is able to speak in full sentences and engages in communication but whose to-and-fro conversation with others fails, and whose attempts to make friends are odd and typically unsuccessful.; **pp**: Inflexibility of behavior causes significant interference with functioning in one or more contexts. Difficulty switching between activities. Problems of organization and planning hamper independence.", "img": null}, {"id": "fc_012_28", "ch": 12, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### Genetic Testing in Autism ###### 12.4**, what are the distinguishing features of **Chromosomal microarray**?", "a": "**Recommended for**: All children with ASD (first line)", "img": null}, {"id": "fc_013_01", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PLA2G6-associated neurodegeneration (PLAN)** (#256600)?", "a": "**Causative Gene(s):** `PLA2G6` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Function: Lipid metabolism — The globus pallidus shows preservation of signal in the medial medullary lamina in MPAN, which is absent in betapropeller protein-associated neurodegeneration and PLA2G6 -associated neurodegeneration, and may be mistaken for an eye of the tiger sign found in pantothenate kinase-associated neurodegeneration (PK", "img": null}, {"id": "fc_013_02", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pantothenate kinase-associated neurodegeneration (PKAN)** (#234200)?", "a": "**Causative Gene(s):** `PANK2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Function: Coenzyme A biosynthesis — Pantothenate kinase-associated neurodegeneration (PKAN) is an autosomal recessive disease characterized by progressive dystonia, dysarthria, and retinal degeneration.", "img": null}, {"id": "fc_013_03", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **COASY protein-associated neurodegeneration (CoPAN)** (#615643)?", "a": "**Causative Gene(s):** `COASY` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Function: Coenzyme A biosynthesis — COASY protein-associated neurodegeneration (CoPAN) has childhood-onset dystonia and spasticity with cognitive impairment.", "img": null}, {"id": "fc_013_04", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Kufor-Rakeb syndrome (KRS)** (#606693)?", "a": "**Causative Gene(s):** `ATP13A2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Function: Autophagy — Kufor-Rakeb syndrome may also be referred to as Parkinson disease 9 or PARK9.", "img": null}, {"id": "fc_013_05", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Aceruloplasminemia (ACP)** (#604290)?", "a": "**Causative Gene(s):** `CP` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Function: Iron homeostasis", "img": null}, {"id": "fc_013_06", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Fatty acid hydroxylase-associated neurodegeneration (FAHN)** (#612319)?", "a": "**Causative Gene(s):** `FA2H` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Function: Lipid metabolism", "img": null}, {"id": "fc_013_07", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Mitochondrial membrane protein-associated neurodegeneration (MPAN)** (#614298)?", "a": "**Causative Gene(s):** `C19ORF12` · **Inheritance:** mtDNA\n\n**Clinical & Molecular Profile:** C19ORF12*** — Function: Lipid metabolism — MPAN typically occurs as an autosomal recessive condition, though heterozygous pathogenic variants in the last exon of C19orf12 may cause dominant disease.", "img": null}, {"id": "fc_013_08", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Woodhouse-Sakati syndrome (WSS)** (#241080)?", "a": "**Causative Gene(s):** `DCAF17` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Function: Unknown", "img": null}, {"id": "fc_013_09", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Beta-propeller protein-associated neurodegeneration (BPAN)** (#300894)?", "a": "**Causative Gene(s):** `WDR45` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** WDR45* — Function: Autophagy — There are generally two key time periods in which BPAN is diagnosed: (1) early childhood, usually characterized by global development delay, seizures, or both, and (2) adulthood, during a period of regression in an individual who had been relatively stable.", "img": null}, {"id": "fc_013_10", "ch": 13, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FTL-associated neuroferritinopathy (NFT)** (#606159)?", "a": "**Causative Gene(s):** `FTL` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** FTL** — Function: Iron homeostasis — Neuroferritinopathy is caused by variants in FTL or FTH1 , which encode the ferritin light and ferritin heavy chains, respectively.", "img": null}, {"id": "fc_013_11", "ch": 13, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`WDR45`** are associated with which clinical phenotype and molecular mechanism in **Beta-Propeller Protein-Associated Neurodegeneration (BPAN)**?", "a": "The gene that causes beta-propeller protein-associated neurodegeneration (BPAN), WDR45 , was identified in a cohort of adults with a very similar phenotype that consisted of childhood seizures and intellectual disability followed by a period of parkinsonian regression in adulthood.", "img": null}, {"id": "fc_013_12", "ch": 13, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PLA2G6`** are associated with which clinical phenotype and molecular mechanism in **Molecular Genetic Testing and Common Diagnostic Challenges**?", "a": "The globus pallidus shows preservation of signal in the medial medullary lamina in MPAN, which is absent in betapropeller protein-associated neurodegeneration and PLA2G6 -associated neurodegeneration, and may be mistaken for an eye of the tiger sign found in pantothenate kinase-associated neurodegeneration (PKAN), (bottom left).", "img": null}, {"id": "fc_013_13", "ch": 13, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PANK2`** are associated with which clinical phenotype and molecular mechanism in **Neurodegeneration**?", "a": "The causative gene, PANK2 , was the first NBIA gene to be identified, and the development of therapeutics is most advanced for PKAN relative to other NBIA disorders.", "img": null}, {"id": "fc_013_14", "ch": 13, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`COASY`** are associated with which clinical phenotype and molecular mechanism in **Clinical Features and Brain Imaging**?", "a": "COASY protein-associated neurodegeneration (CoPAN) has childhood-onset dystonia and spasticity with cognitive impairment.", "img": null}, {"id": "fc_013_15", "ch": 13, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FTH1`** are associated with which clinical phenotype and molecular mechanism in **Clinical Features and Brain Imaging**?", "a": "Neuroferritinopathy is caused by variants in FTL or FTH1 , which encode the ferritin light and ferritin heavy chains, respectively.", "img": null}, {"id": "fc_013_16", "ch": 13, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FTL`** are associated with which clinical phenotype and molecular mechanism in **Clinical Features and Brain Imaging**?", "a": "FTL -associated neuroferritinopathy has adult onset and may present similarly to Huntington disease with chorea or dystonia and cognitive changes.", "img": null}, {"id": "fc_013_17", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Lennox-Gastaut syndrome** defined and characterized?", "a": "Lennox-Gastaut syndrome , developing an epileptic encephalopathy that compounds cognitive delays related to their BPAN.", "img": null}, {"id": "fc_013_18", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Brain Imaging**, how is **eye-of-the-tiger** defined and characterized?", "a": "eye-of-the-tiger sign seen in pantothenate kinase-associated neurodegeneration (PKAN), a more common NBIA disorder.", "img": null}, {"id": "fc_013_19", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Classic PKAN** defined and characterized?", "a": "Classic PKAN presents in early childhood by about 3 years of age; it can be diagnosed quickly by exome sequencing or gene panel testing.", "img": null}, {"id": "fc_013_20", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Brain Imaging**, how is **eye-of-the-tiger sign** defined and characterized?", "a": "eye-of-the-tiger sign on T2-weighted brain MRI is virtually pathognomonic for PKAN (Fig.", "img": null}, {"id": "fc_013_21", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **PLA2G6 -Associated Neurodegeneration**, how is **infantile neuroaxonal dystrophy** defined and characterized?", "a": "infantile neuroaxonal dystrophy , or INAD), juvenile PLAN, and adult PLAN.", "img": null}, {"id": "fc_013_22", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Children with INAD** defined and characterized?", "a": "Children with INAD may have normal early development or only mild delays.", "img": null}, {"id": "fc_013_23", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Juvenile-onset** defined and characterized?", "a": "Juvenile-onset cases account for only a small portion of all PLAN, making them ultra-rare.", "img": null}, {"id": "fc_013_24", "ch": 13, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Adult PLAN** defined and characterized?", "a": "Adult PLAN usually presents in young adulthood (late teens to 20s) with rare exceptions.", "img": null}, {"id": "fc_013_25", "ch": 13, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 13.1):", "a": "Frequencies of NBIA. Frequencies are based on approximately 1,000 families worldwide collected over 30 years in an international repository of NBIA. Some countries and regions are not represented because of limitations in making a diagnosis or making contact with the repository.", "img": "fig_p0326_03.jpg"}, {"id": "fc_013_26", "ch": 13, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 13.3):", "a": "Axial T2-weighted imaging of globus pallidus (left) and substantia nigra (right) in beta-propeller protein-associated neurodegeneration, with inset showing T1-weighted imaging “halo” in the cerebral peduncles.", "img": "fig_p0328_01.jpg"}, {"id": "fc_013_27", "ch": 13, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 13.4):", "a": "Axial T2-weighted imaging of globus pallidus (top left) and substantia nigra (right) in mitochondrial membrane protein-associated neurodegeneration (MPAN). The globus pallidus shows preservation of signal in the medial medullary lamina in MPAN, which is absent in betapropeller protein-associated neurodegeneration and PLA2G6 -associated neurodegeneration, and may be mistaken for an eye of the tiger sign found in pantothenate kinase-associated neurodegeneration (PKAN), (bottom left). The degree of signal hypointensity in the substantia nigra in MPAN is greater than is typically seen in PKAN, another distinguishing feature.", "img": "fig_p0329_08.jpg"}, {"id": "fc_013_28", "ch": 13, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **List o f NBIA Genes, Their Expected Function, and Corresponding Disorders**, what are the distinguishing features of **PLA2G6**?", "a": "**Function**: Lipid metabolism; **Corresponding Disorder**: PLA2G6-associated neurodegeneration; **Acronym**: PLAN; **MIM-ID**: # 256600", "img": null}, {"id": "fc_014_01", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ataxia telangiectasia and variants**?", "a": "**Causative Gene(s):** `ATLD1, MRE11, ATLD2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Cerebellar ataxia, oculomotor apraxia, extrapyramidal features, large fiber sensory neuropathy; Wheelchair confined by age 10 — Telangiectases present 2–4 years after onset of ataxia; Humoral and cellular immunodeficiency Leukemia, lymphoma, other neoplasms (38%); Hypogonadism; Glucose intolerance — Laboratory Features: High serum α-fetop", "img": null}, {"id": "fc_014_02", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Episodic ataxias**?", "a": "**Causative Gene(s):** `EA8, EA9, FGF14, DYT9, SLC2A1, GLUT1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Ataxia attacks lasting minutes to hours to days; occasionally associated with seizures; may respond to clonazepam or acetazolamide — Imaging Features: Brain MRI may be normal — AD EA8 1p36.13-p34.3 EA9 FGF14 DYT9 SLC2A1(GLUT1) 1p34.2 SCN2A: Nav1.2", "img": null}, {"id": "fc_014_03", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AOA1**?", "a": "**Causative Gene(s):** `AOA1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Diagnosis: High serum cholesterol, low albumin", "img": null}, {"id": "fc_014_04", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AOA2**?", "a": "**Causative Gene(s):** `AOA2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Diagnosis: High α-fetoprotein", "img": null}, {"id": "fc_014_05", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Celiac disease**?", "a": "**Causative Gene(s):** `DQ8` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Diagnosis: Antitissue transglutaminase antibody, duodenal biopsy, HLA-DQ2.5 or DQ8 molecules", "img": null}, {"id": "fc_014_06", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Friedreich ataxia**?", "a": "**Causative Gene(s):** `GAA` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Caudal to rostral ataxia progression, posterior column sensory loss, absent deep tendon reflexes, bilateral Babinski sign, ocular fixation instability; later stage vision and hearing loss. — Hypertrophic cardiomyopathy (75%); Scoliosis, pes cavus (60– 80%); Diabetes or glucose intolerance (20%) — Laboratory Features: ECG—non-specific ST-T", "img": null}, {"id": "fc_014_07", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TITF1 (also known as NKX 2.1) (AD)**?", "a": "**Causative Gene(s):** `TITF1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Chorea: ++ — Other Movement Disorders: 1,2,3 — Ataxia: + — Clinical Features: Thyroid and lung dysfunction", "img": null}, {"id": "fc_014_08", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ADCY5 (AD/De novo)**?", "a": "**Causative Gene(s):** `ADCY5` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Chorea: ++ — Other Movement Disorders: 1,2,3 — Ataxia: ++ — Cognitive Impairment: + — Clinical Features: Hypotonia, sleep dyskinesias", "img": null}, {"id": "fc_014_09", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PDE10A (AR/De novo)**?", "a": "**Causative Gene(s):** `PDE10A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Chorea: ++ — Other Movement Disorders: 1,2,3 — Ataxia: ++ — Autosomal recessive PDE10A -related chorea is similar to ADCY5 -related chorea.", "img": null}, {"id": "fc_014_10", "ch": 14, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Isolated, Complex**?", "a": "**Causative Gene(s):** `KMT2B` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Nuclear gene expression, nuclear envelope — Function: Regulates histone methylation and gene expression — Inheritance (Penetrance): AD (reduced penetrance) — NDD, facial dysmorphism, short stature, spasticity — Neuroradiological Findings: Iron accumulation in globus pallidus", "img": null}, {"id": "fc_014_11", "ch": 14, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`VPS13A`** are associated with which clinical phenotype and molecular mechanism in **Neuroacanthocytosis**?", "a": "It is an autosomal recessive entity caused by variants of the VPS13A gene coding for chorein, a large protein implicated in intracellular protein sorting.", "img": null}, {"id": "fc_014_12", "ch": 14, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATN1`** are associated with which clinical phenotype and molecular mechanism in **Ataxic Conditions**?", "a": "DRPLA is also an autosomal dominant disease due to a CAG-repeat expansion in the ATN1 gene, encoding for atrophin-1.", "img": null}, {"id": "fc_014_13", "ch": 14, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TITF1`** are associated with which clinical phenotype and molecular mechanism in **Benign Hereditary Chorea**?", "a": "Variants in the TITF1 gene (also known as NKX2-1 ), encoding a transcription factor essential for striatal development were the first identified genetic cause of BHC.", "img": null}, {"id": "fc_014_14", "ch": 14, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TOR1A`** are associated with which clinical phenotype and molecular mechanism in **BELÉN PÉREZ-DUEÑAS, ANNA MARCÉ-GRAU, ROSER PONS**?", "a": "Lower limb dystonia is common in TOR1A and KMT2B genetic disorders, while cervical dystonia is frequently described in ANO3 and GNAL -related disorders.", "img": null}, {"id": "fc_014_15", "ch": 14, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MECP2`** are associated with which clinical phenotype and molecular mechanism in **Nuclear Gene Expression, Nuclear Envelope Dysfunction, and Stress Response**?", "a": "MECP2 genes, which regulate other transcription activities, cause severe developmental disorders, epileptic encephalopathies, and complex dystonia phenotypes.", "img": null}, {"id": "fc_014_16", "ch": 14, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NUP62`** are associated with which clinical phenotype and molecular mechanism in **Nuclear Gene Expression, Nuclear Envelope Dysfunction, and Stress Response**?", "a": "NUP54 and NUP62 variants are linked to autosomal recessive infantile striatal necrosis and generalized dystonia with prominent oromandibular involvement.", "img": null}, {"id": "fc_014_17", "ch": 14, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Abetalipoproteinemia**?", "a": "**Therapy / Intervention:** Vitamin E and reduced fat diet (can prevent/reduce symptoms)\n\n**Clinical Context:** Age of Onset: Childhood to early adulthood — Clinical Manifestations: Progressive ataxia, chorea, dystonia, seizures, acanthocytosis, retinitis pigmentosa, fat malabsorption syndrome — Diagnostic Tests: Plasma lipids and", "img": null}, {"id": "fc_014_18", "ch": 14, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Aromatic L-amino acid decarboxylase deficiency**?", "a": "**Therapy / Intervention:** Dopamine agonists, monoamine oxidase inhibitors, gene therapy\n\n**Clinical Context:** AADC — Age of Onset: Infancy — Clinical Manifestations: Global developmental delay, hypotonia, dystonia, oculogyric crisis, autonomic dysfunction — Diagnostic Tests: CSF neurotransmitters AADC activity in the plasma AADC", "img": null}, {"id": "fc_014_19", "ch": 14, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Ataxia with vitamin E deficiency**?", "a": "**Therapy / Intervention:** Oral vitamin E\n\n**Clinical Context:** TTPA — Age of Onset: Late childhood — Clinical Manifestations: Ataxia, dystonia, dysarthria, areflexia, vision loss, loss of proprioception, and sensory disturbance — Diagnostic Tests: Plasma vitamin E level Brain MRI TT", "img": null}, {"id": "fc_014_20", "ch": 14, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Biotin and thiamine responsive basal ganglia disease**?", "a": "**Therapy / Intervention:** Biotin and thiamine\n\n**Clinical Context:** Age of Onset: Abrupt onset in early childhood — Clinical Manifestations: Dystonia, parkinsonism, ataxia, subacute encephalopathy, dysarthria, dysphagia, external ophthalmoplegia, seizures — Diagnostic Tests: Brain MRI SL", "img": null}, {"id": "fc_014_21", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **SUSAN L. PERLMAN**, how is **genetic anticipation** defined and characterized?", "a": "genetic anticipation sometimes before the affected parent shows symptoms.", "img": null}, {"id": "fc_014_22", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Characteristic Symptoms and Signs**, how is **Friedreich ataxia** defined and characterized?", "a": "Friedreich ataxia (1/20,000 to 1/50,000 in Caucasians; carrier status 1/60–110).", "img": null}, {"id": "fc_014_23", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Characteristic Symptoms and Signs**, how is **GAA trinucleotide** defined and characterized?", "a": "GAA trinucleotide expansion in the first intron of the FXN gene (9q21.", "img": null}, {"id": "fc_014_24", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **CARLOS ESTEVEZ-FRAGA, JUAN CARLOS MARTINEZ-CASTRILLO, PEDRO J. GARCIA-RUIZ**, how is **Huntington disease (HD)** defined and characterized?", "a": "Huntington disease (HD) should always be the first step in the diagnostic workup.", "img": null}, {"id": "fc_014_25", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Symptoms of Juvenile Huntington Disease**, how is **pediatric HD** defined and characterized?", "a": "pediatric HD is used for patients who exhibit clinical signs before turning 18 years old.", "img": null}, {"id": "fc_014_26", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Symptoms of Juvenile Huntington Disease**, how is **childhood** defined and characterized?", "a": "childhood (under 10 years) and adolescent onset (10–18 years).", "img": null}, {"id": "fc_014_27", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Symptoms of Juvenile Huntington Disease**, how is **Parkinsonism** defined and characterized?", "a": "Parkinsonism appears in virtually every patient with JHD during disease progression, but it is present in only 16% of patients at onset.", "img": null}, {"id": "fc_014_28", "ch": 14, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Management of Juvenile Huntington Disease**, how is **Psychiatric manifestations** defined and characterized?", "a": "Psychiatric manifestations such as depression or anxiety can be treated with selective serotonin reuptake inhibitors (SSRIs).", "img": null}, {"id": "fc_015_01", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB1**?", "a": "**Causative Gene(s):** `FEB1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 8q13-q21 (PL) — Phenotype MIM no. (#): 121210", "img": null}, {"id": "fc_015_02", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB2**?", "a": "**Causative Gene(s):** `HCN2, FEB2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 19p13.3 — Phenotype MIM no. (#): 602477 — Novel HCN2 mutation contributes to febrile seizures by shifting the channel’s kinetics in a temperature-dependent manner.", "img": null}, {"id": "fc_015_03", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB3A**?", "a": "**Causative Gene(s):** `SCN1A, FEB3A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 2q24.3 — Phenotype MIM no. (#): 604403 — Typical DS is caused by autosomal dominant pathogenic variants in SCN1A , located at chromosomal locus 2q24.3.", "img": null}, {"id": "fc_015_04", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB3B**?", "a": "**Causative Gene(s):** `FEB3B` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 2q23-q24 (PL) — Phenotype MIM no. (#): 613863", "img": null}, {"id": "fc_015_05", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB4**?", "a": "**Causative Gene(s):** `ADGRV1, FEB4` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 5q14.3 — Phenotype MIM no. (#): 604352", "img": null}, {"id": "fc_015_06", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB5**?", "a": "**Causative Gene(s):** `FEB5` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 6q22-q24 (PL) — Phenotype MIM no. (#): 609255", "img": null}, {"id": "fc_015_07", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB6**?", "a": "**Causative Gene(s):** `IMPA2, FEB6` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 18p11.2 (PL) — Phenotype MIM no. (#): 609253", "img": null}, {"id": "fc_015_08", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB7**?", "a": "**Causative Gene(s):** `FEB7` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Cytogenetic Location: 21q22 (PL) — Phenotype MIM no. (#): 611515", "img": null}, {"id": "fc_015_09", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB8**?", "a": "**Causative Gene(s):** `GABRG2, FEB8` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 5q34 — Phenotype MIM no. (#): 137164 — De novo GABRG2 mutations associated with epileptic encephalopathies.", "img": null}, {"id": "fc_015_10", "ch": 15, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FEB9**?", "a": "**Causative Gene(s):** `FEB9` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Cytogenetic Location: 3p24.2-p23 (PL) — Phenotype MIM no. (#): 611634", "img": null}, {"id": "fc_015_11", "ch": 15, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CACNA1A`** are associated with which clinical phenotype and molecular mechanism in **Electroencephalogram (EEG) Findings**?", "a": "Several genetic variants have emerged as potentially predisposing to HHE, including Ser218Leu and Tyr62Cys variants in CACNA1A .", "img": null}, {"id": "fc_015_12", "ch": 15, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCN1A`** are associated with which clinical phenotype and molecular mechanism in **Dravet Syndrome**?", "a": "The genetic etiology of DS was first reported in 2001: approximately 80% is caused by haploinsufficiency due to loss-of-function variants in SCN1A (Fig. 15.1).", "img": null}, {"id": "fc_015_13", "ch": 15, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PCDH19`** are associated with which clinical phenotype and molecular mechanism in **Prognosis**?", "a": "Genes associated with refractory status epilepticus include RANBP2 , CACNA1A , PCDH19 , and KCNA2 (Fig. 15.5).", "img": null}, {"id": "fc_015_14", "ch": 15, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`HCN2`** are associated with which clinical phenotype and molecular mechanism in **Genetic Epilepsies Associated With Fever-Induced Seizures**?", "a": "Novel HCN2 mutation contributes to febrile seizures by shifting the channel’s kinetics in a temperature-dependent manner.", "img": null}, {"id": "fc_015_15", "ch": 15, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`HCN1`** are associated with which clinical phenotype and molecular mechanism in **Genetic Epilepsies Associated With Fever-Induced Seizures**?", "a": "De novo mutations in HCN1 cause early infantile epileptic encephalopathy.", "img": null}, {"id": "fc_015_16", "ch": 15, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GABRG2`** are associated with which clinical phenotype and molecular mechanism in **Genetic Epilepsies Associated With Fever-Induced Seizures**?", "a": "De novo GABRG2 mutations associated with epileptic encephalopathies.", "img": null}, {"id": "fc_015_17", "ch": 15, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Treatment**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Use of first-line immunotherapy (e.g., corticosteroids, immunoglobulins, plasma exchange) and second-line immunotherapy (e.g., tacrolimus, rituximab, cyclophosphamide, anakinra) has been associated with improved outcomes in adults, while these interventions seem less effective in", "img": null}, {"id": "fc_015_18", "ch": 15, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Genetic Epilepsies Associated With Fever-Induced Seizures**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Centromedian thalamic nuclei deep brain stimulation and Anakinra treatment for FIRES—Two different outcomes.", "img": null}, {"id": "fc_015_19", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Fever-Associated Seizures and Epilepsies**, how is **Epileptic seizures** defined and characterized?", "a": "Epileptic seizures are the transient occurrence of signs or symptoms due to abnormal excessive or synchronous neuronal activity in the brain.", "img": null}, {"id": "fc_015_20", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Fever-Associated Seizures and Epilepsies**, how is **Acute symptomatic seizures** defined and characterized?", "a": "Acute symptomatic seizures can occur in the setting of direct chemical or inflammatory excitation caused by a central nervous system (CNS) or systemic infection.", "img": null}, {"id": "fc_015_21", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Fever-Associated Seizures or Epilepsy (FASE)**, how is **New-onset refractory status epilepticus (NORSE)** defined and characterized?", "a": "New-onset refractory status epilepticus (NORSE) and febrile infection-related epilepsy syndrome (FIRES) .", "img": null}, {"id": "fc_015_22", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Febrile Seizures (FS)**, how is **complex FS** defined and characterized?", "a": "complex FS is a focal seizure, a generalized seizure lasting longer than 15 minutes, the recurrence of seizures more than once in 24 hours, or a seizure associated with postictal neurologic abnormalities, most frequently a postictal (Todd) paralysis, occurring in the context of a fever.", "img": null}, {"id": "fc_015_23", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Febrile Seizures (FS)**, how is **prolonged febrile seizure** defined and characterized?", "a": "prolonged febrile seizure or febrile status epilepticus (FSE) is defined as a seizure occurring in the context of a fever and lasting longer than 30 minutes.", "img": null}, {"id": "fc_015_24", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetics**, how is **familial febrile seizures** defined and characterized?", "a": "familial febrile seizures , with many genes and putative loci potentially associated with FS (Table 15.", "img": null}, {"id": "fc_015_25", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Atypical DS/Developmental Epileptic Encephalopathy**, how is **developmental epileptic encephalopathy (DEE)** defined and characterized?", "a": "developmental epileptic encephalopathy (DEE) followed by a number corresponding to the particular variant (Table 15.", "img": null}, {"id": "fc_015_26", "ch": 15, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Prognosis**, how is **Sudden unexpected death in epilepsy (SUDEP)** defined and characterized?", "a": "Sudden unexpected death in epilepsy (SUDEP) is the most common cause of mortality, followed by status epilepticus, infections, and seizure-related injuries and accidents.", "img": null}, {"id": "fc_015_27", "ch": 15, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 15.1):", "a": "Genes associated with a Dravet syndrome phenotype. Red, sodium channels; green, potassium channels; purple, chloride channels; blue, nonchannels.", "img": "fig_p0380_01.jpg"}, {"id": "fc_015_28", "ch": 15, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 15.2):", "a": "Schematic representation of clinical manifestations of Dravet syndrome and their relative incidence according to age. Moderate fever for 60%; mostly clonic generalized and unilateral motor seizures. *Difficult distinction between atypical absences and complex partial seizures without ictal EEG recording, so their precise incidence is unknown. °Including generalized tonic-clonic and unilateral seizures. However, unilateral seizures are less frequent after the age of 7 years, whereas sleep seizures increase after 6–7 years and become predominant after the age of 9–10 years. AA, Atypical absences; AE, acute encephalopathy; CG, crouching gait; CPS, complex partial seizures; DD, developmental delay; FSz, complex febrile seizures; GMS, generalized motor seizures; HS, hyperthermia sensitivity; MSz, myoclonic seizures; OS, obtundation status; SE, convulsive status epilepticus; SUDEP, sudden unexpected death in epilepsy.", "img": "fig_p0382_01.jpg"}, {"id": "fc_016_01", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Dravet syndrome and GEFS+**?", "a": "**Causative Gene(s):** `SCN1A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Voltage-gated sodium channel Nav1.1 — Protein Function: Initiates action potential firing in GABAergic inhibitory interneurons — Type of Pathogenic Variant: Haploinsufficiency and LOF — Main Clinical Features: Fever sensitivity, seizure onset <6 months of age, ataxia, mild-to-severe intellectual disability, and autism — T", "img": null}, {"id": "fc_016_02", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **EIDEE and bitemporal focal epilepsy**?", "a": "**Causative Gene(s):** `SCN1A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Voltage-gated sodium channel Nav1.1 — Protein Function: Initiates action potential firing in GABAergic inhibitory interneurons — Type of Pathogenic Variant: GOF — Main Clinical Features: Neonatal-onset seizures, movement disorder, congenital arthrogryposis, severe-to-profound intellectual disability — Targeted Treatments:", "img": null}, {"id": "fc_016_03", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Epilepsy with or without intellectual disability and autism**?", "a": "**Causative Gene(s):** `SCN2A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Voltage-gated sodium channel Nav1.2 — Protein Function: Regulating the flow of sodium ions across neuronal membranes — Type of Pathogenic Variant: Haploinsufficiency and LOF — Main Clinical Features: Infantile onset, mainly generalized seizures and myoclonic seizures, intellectual disability, and autism — Targeted Treatme", "img": null}, {"id": "fc_016_04", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SeLNE, SeLFNE, and EIDEE**?", "a": "**Causative Gene(s):** `SCN2A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Voltage-gated sodium channel Nav1.2 — Protein Function: Regulating the flow of sodium ions across neuronal membranes — Type of Pathogenic Variant: GOF — Main Clinical Features: Epilepsy onset<3 months of age, often neonatal, with mainly focal seizures; severeto-profound intellectual disability in EIDEE — Targeted Treatmen", "img": null}, {"id": "fc_016_05", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Infantile onset epilepsy with or without intellectual disability and autism**?", "a": "**Causative Gene(s):** `SCN8A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Voltage-gated sodium channel Nav1.6 — Protein Function: Regulating the membrane excitability of neurons — Type of Pathogenic Variant: Haploinsufficiency and LOF — Main Clinical Features: Infantile onset, mainly generalized seizures and myoclonic seizures, intellectual disability, and autism — Targeted Treatments: Avoidanc", "img": null}, {"id": "fc_016_06", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SeLFIE, SeLIE, and EIDEE**?", "a": "**Causative Gene(s):** `SCN8A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Voltage-gated sodium channel Nav1.6 — Protein Function: Regulating the membrane excitability of neurons — Type of Pathogenic Variant: GOF — Main Clinical Features: Epilepsy onset<3 months of age, often neonatal, with focal seizures and generalized seizures; severeto-profound intellectual disability in EIDEE — Targeted Tre", "img": null}, {"id": "fc_016_07", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PCDH19-clustering epilepsy**?", "a": "**Causative Gene(s):** `PCDH19` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Protocadherin-19 — Protein Function: Regulates synaptic transmission — Type of Pathogenic Variant: Cellular interference — Main Clinical Features: Mainly female subjects; seizure clusters, fever sensitivity, mild-to-moderate intellectual disability, and autism — Targeted Treatments: Ganaxolone under exploration", "img": null}, {"id": "fc_016_08", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **IESS and EIDEE**?", "a": "**Causative Gene(s):** `STXBP1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Syntaxin-binding protein 1* — Protein Function: Key organizer of the neuronal SNARE complex, the molecular machine driving synaptic vesicle fusion — Type of Pathogenic Variant: Haploinsufficiency and LOF — Main Clinical Features: Seizure onset<1 year (90%), moderate-to-severe intellectual disability, and movement disorder", "img": null}, {"id": "fc_016_09", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **EIDEE**?", "a": "**Causative Gene(s):** `CDKL5` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: CDKL5 — Protein Function: CDKL5 is localized at excitatory synapses and contributes to correct dendritic spine structure and synapse activity — Type of Pathogenic Variant: Haploinsufficiency and LOF — Main Clinical Features: Infantile-onset refractory epilepsy, movement disorders, hypotonia, moderate-to-severe intellectua", "img": null}, {"id": "fc_016_10", "ch": 16, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **EIDEE, SeLFIE, and SeLIE**?", "a": "**Causative Gene(s):** `KCNQ2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Encoded Protein: Voltage-gated potassium channel subunit Kv7.2 — Protein Function: Regulating the membrane excitability of neurons — Type of Pathogenic Variant: Haploinsufficiency and LOF — Main Clinical Features: Neonatal onset epilepsy with focal seizures and severe-to- profound intellectual disability — Targeted Treatments: Sodium chan", "img": null}, {"id": "fc_016_11", "ch": 16, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`UBE3A`** are associated with which clinical phenotype and molecular mechanism in **Angelman Syndrome**?", "a": "If the maternal genes (mainly UBE3A ) are not well expressed, either due to deletion of the maternal copy, dysfunction of the imprinting mechanism or intragenic pathogenic variant of UBE3A , Angelman syndrome will appear.", "img": null}, {"id": "fc_016_12", "ch": 16, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GABRA5`** are associated with which clinical phenotype and molecular mechanism in **Dup15q Syndrome (Maternal Origin)**?", "a": "It has been postulated that its mechanism of action may be useful in Dup15q because GABRA5 encoding this GABAA-α5 subunit is in the affected region.", "img": null}, {"id": "fc_016_13", "ch": 16, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCN1A`** are associated with which clinical phenotype and molecular mechanism in **Monogenic Syndromes**?", "a": "For example, in Dravet syndrome , pathogenic variants in the Nav1.1 sodium channel, encoded by SCN1A have a loss-of-function effect (LoF) in GABAergic inhibitory interneurons, resulting in a loss of inhibitory tone of these neurons on pyramidal excitatory neurons, which promotes hyperexcitability.", "img": null}, {"id": "fc_016_14", "ch": 16, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCN8A`** are associated with which clinical phenotype and molecular mechanism in **Monogenic Syndromes**?", "a": "In contrast, variants in SCN8A , which encodes the Nav1.6 channel that is expressed in excitatory neurons, will cause epilepsy and neurodevelopmental disorders in the case of a gain-offunction (GoF) variant effect.", "img": null}, {"id": "fc_016_15", "ch": 16, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCN2A`** are associated with which clinical phenotype and molecular mechanism in **SCN2A-Related Disorder**?", "a": "Early-onset (<3 months of age) DEE due to pathogenic variants in SCN2A is very severe and causes clinical phenotypes such as Ohtahara syndrome or focal migratory epilepsy of infancy .", "img": null}, {"id": "fc_016_16", "ch": 16, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KCNQ3`** are associated with which clinical phenotype and molecular mechanism in **KCNQ2- DEE**?", "a": "One study suggests that the administration of donepezil through compassionate use in patients with pathogenic gain-of-function variants in KCNQ2 or KCNQ3 may improve their cognitive outcomes.", "img": null}, {"id": "fc_016_17", "ch": 16, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **mTORopathies**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Everolimus is an mTOR inhibitor similar to sirolimus but with better bioavailability and is an approved therapy for use in epilepsy associated with TSC.", "img": null}, {"id": "fc_016_18", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Angelman Syndrome**, how is **nonconvulsive status epilepticus** defined and characterized?", "a": "nonconvulsive status epilepticus in these patients, which will require rescue with benzodiazepines.", "img": null}, {"id": "fc_016_19", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **SCN2A-Related Disorder**, how is **Ohtahara syndrome** defined and characterized?", "a": "Ohtahara syndrome or focal migratory epilepsy of infancy .", "img": null}, {"id": "fc_016_20", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **SCN2A-Related Disorder**, how is **West syndrome** defined and characterized?", "a": "West syndrome , myoclonic-atonic epilepsy to Lennox-Gastaut syndrome .", "img": null}, {"id": "fc_016_21", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Benign Neonatal Epilepsy**, how is **Benign neonatal epilepsy** defined and characterized?", "a": "Benign neonatal epilepsy , which presents with selflimiting seizures in the neonatal period and normal neurodevelopment (due to loss-of-function variants) .", "img": null}, {"id": "fc_016_22", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **KCNT1-Related Disorder**, how is **Severe sleep-related hypermotor epilepsy** defined and characterized?", "a": "Severe sleep-related hypermotor epilepsy , due to inherited or de novo variants.", "img": null}, {"id": "fc_016_23", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **KCNB1-Related Disorder**, how is **status epilepticus during sleep** defined and characterized?", "a": "status epilepticus during sleep , which may benefit from targeted treatment.", "img": null}, {"id": "fc_016_24", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **SLC6A1-Related Disorders**, how is **myoclonic-atonic epilepsy** defined and characterized?", "a": "myoclonic-atonic epilepsy , although other epileptic phenotypes or even neurodevelopmental disorders without epilepsy may occur.", "img": null}, {"id": "fc_016_25", "ch": 16, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **GNAO1-Related Disorder**, how is **movement disorders** defined and characterized?", "a": "movement disorders (dystonia, ataxia, chorea, dyskinesia) and epilepsy in 65%, which is usually refractory.", "img": null}, {"id": "fc_016_26", "ch": 16, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 16.1):", "a": "Concept of genetic generalized epilepsy (GGE) versus idiopathic generalized epilepsy (IGE). The IGEs are a subgroup of GGEs, comprised of the following four syndromes: childhood absence epilepsy, juvenile absence epilepsy, juvenile myoclonic epilepsy, and epilepsy with generalized tonic-clonic seizures alone. These four syndromes may show some degree of overlap. In addition to the IGEs, GGEs include (1) individuals with generalized seizure types who do not meet criteria for a specific syndrome, and (2) less common generalized epilepsy syndromes. These latter syndromes also have a genetic basis and may occur in the setting of normal intellect or intellectual disability. Some present with an epileptic encephalopathy such as epilepsy with myoclonic–atonic seizures, whereas other syndromes, such as epilepsy with myoclonic absences and epilepsy with eyelid myoclonia, may be associated with a developmental and epileptic encephalopathy, an epileptic encephalopathy, or a developmental encephalopathy. Other syndromes such as myoclonic epilepsy in infancy may present as a generalized epilepsy in a child with a developmental encephalopathy (i.e., intellectual disability) or normal intellect.", "img": "fig_p0396_01.jpg"}, {"id": "fc_016_27", "ch": 16, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 16.2):", "a": "Relationship between different genes and their associated epilepsy phenotypes. The plot illustrates the connections between gene variants (blue, right) and their respective abnormal functions (green, left), highlighting the genetic complexity of epilepsy; the colors used for the connections correspond to the nature of the genetic abnormality. CAE, Childhood absence epilepsy; CI, complex inheritance; DEE 1 dys, developmental and epileptic encephalopathy and late-onset dystonia; DR, drugresponsive or self-limited focal or generalized epilepsy; E±ID-autism, epilepsy with or without intellectual disability and autism; EIDEE, early infantile developmental and epileptic encephalopathy; EIMFS, epilepsy of infancy with migrating focal seizures; EMAtS, epilepsy with myoclonic-atonic seizures; GEFS1 , genetic epilepsy with febrile seizures plus; GGE, genetic generalized epilepsy; GOF, gain of function; IDEE, infantile developmental and epileptic encephalopathy; IE, infantile onset epilepsy with both focal and generalized seizures; IESS, infantile epileptic spasms syndrome; LOF, loss of function; MD1E, early-onset hyperkinetic movement disorder associated with epilepsy; NEDCAS, neurodevelopmental disorder with cerebellar atrophy, with or without seizures; PCDH19-CE, PCDH19-clustering epilepsy; RMFSL, lethal neonatal rigidity and multifocal seizure syndrome; SelFIE, self-limited familial infantile epilepsy; SelFNE, self-limited f", "img": "fig_p0401_02.jpg"}, {"id": "fc_016_28", "ch": 16, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 16.3):", "a": "Classification of epilepsy syndromes, based on age at presentation. Shown are the typical ages of presentation, with ranges indicated by arrows . Focal epilepsy syndromes are indicated in blue, generalized epilepsy syndromes in green, focal, and generalized syndromes in yellow, and syndromes with developmental and/or epileptic encephalopathy or with progressive neurological deterioration in red.", "img": "fig_p0402_01.jpg"}, {"id": "fc_017_01", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CMT1**?", "a": "**Causative Gene(s):** `CMT1, CMT4, CMT2` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** yelinatingC AR: CMT4 — MT X-Linked: CMT — Int AD: DI-CMT — ermediate C AR: RI-CMT — MT X-Linked: CMTX — A — Axona: D CMT2 — l CMT AR: CMT2 — X-Linked — d: AD — HMN AR: (X-Linked) — HS: AD — AN: AR", "img": null}, {"id": "fc_017_02", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PMP22**?", "a": "**Causative Gene(s):** `PMP22, GDAP1, GJB1, GBF1, MFN2, AIFM1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** yelinatingC AR: GDAP1 — MT X-Linked: GJB1 — Int AD: GBF1 — ermediate C AR: GDAP1 — MT X-Linked: GJB1 — MFN2 — Axona: NEFH — l CMT AR: GDAP1 — AIFM1 — d: UBE3C — HMN AR: IGHMBP2 — HS: SPTCL1 — AN: WNK1", "img": null}, {"id": "fc_017_03", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LITAF**?", "a": "**Causative Gene(s):** `MTMR13, PLEKHG5, DRP2, TRPV4, TUBB3, MFN2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** yelinatingC AR: MTMR13 — Int AD: YARS — ermediate C AR: PLEKHG5 — MT X-Linked: (DRP2) — TRPV4 — Axona: TUBB3 — l CMT AR: MFN2 — PDK3 — d: HSPB1 — HMN AR: PLEKHG5 — HS: ATL1 — AN: KIF1A", "img": null}, {"id": "fc_017_04", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **EGR2**?", "a": "**Causative Gene(s):** `EGR2, MTMR5, INF2, COX6A1, DGAT2, HINT1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** yelinatingC AR: MTMR5 — Int AD: INF2 — ermediate C AR: COX6A1 — GARS — Axona: DGAT2 — l CMT AR: HINT1 — d: HSPB3 — HMN AR: DNAJB2 — HS: DNMT1 — AN: SCN9A", "img": null}, {"id": "fc_017_05", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NEFL**?", "a": "**Causative Gene(s):** `SH3TC2, GNB4, ATP1A1, TRIM2, FBXO38, HINT1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** yelinatingC AR: SH3TC2 — Int AD: GNB4 — Axona: ATP1A1 — l CMT AR: TRIM2 — d: FBXO38 — HMN AR: HINT1 — HS: ATL3 — AN: IKBKAP", "img": null}, {"id": "fc_017_06", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PMP2**?", "a": "**Causative Gene(s):** `PMP2, NDRG1, HSPB1, KIF5A, IGHMBP2, BSCL2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** yelinatingC AR: NDRG1 — Int AD: NEFL — HSPB1 — Axona: KIF5A — l CMT AR: IGHMBP2 — d: BSCL2 — HMN AR: VRK1 — AN: NTRK1", "img": null}, {"id": "fc_017_07", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FBLN5**?", "a": "**Causative Gene(s):** `FBLN5, EGR2, MPZ, DCAF8, HSJ1, DNAJB2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** yelinatingC AR: EGR2 — Int AD: MPZ — MPZ — Axona: DCAF8 — l CMT AR: HSJ1/ DNAJB2 — d: GARS — HMN AR: LAS1L — HS: SCN11A — AN: NGF-B", "img": null}, {"id": "fc_017_08", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ITP3**?", "a": "**Causative Gene(s):** `ITP3, GDAP1, TUBB3, SPG11, REEP1, RAB7` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** yelinatingC AR: PRX — Int AD: C1orf194 — GDAP1 — Axona: TUBB3 — l CMT AR: SPG11 — d: REEP1 — HMN AR: SORD — HS: RAB7 — AN: DST", "img": null}, {"id": "fc_017_09", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Congenital hypomyelinating neuropathy (CHN)**?", "a": "**Causative Gene(s):** `PMP22, MPZ, EGR2, CNTNAP1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Congenital onset, global hypotonia, possible respiratory distress; severe course. No or poor myelin formation, very low NCV — PMP22, MPZ, EGR2, PRX CNTNAP1", "img": null}, {"id": "fc_017_10", "ch": 17, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Dejerine-Sottas disease (DSD or CMT3/HMSN III)**?", "a": "**Causative Gene(s):** `CMT3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Onset age<2 years, early foot deformities, motor global developmental delay, frequent cranial nerve involvement, relatively milder course, hypo-dysmyelination, very low NCV (≤12 m/s)", "img": null}, {"id": "fc_017_11", "ch": 17, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CMT3`** are associated with which clinical phenotype and molecular mechanism in **The Main CMT/HMSN Types**?", "a": "DejerineSottas disease (DSD) , (CMT3/HMSN III) includes the most severe forms of CMT1/CMT4, with onset before age 2, very low NCVs (<12 m/s), and nerve biopsy evidence of hypomyelination-dysmyelination.", "img": null}, {"id": "fc_017_12", "ch": 17, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FDG4`** are associated with which clinical phenotype and molecular mechanism in **CMT4**?", "a": "Peculiar abnormal myelin figures (myelin outfoldings) formed by redundant loop of excessive myelin are very typical of CMT4B1-2 and also of another demyelinating autosomal recessive subtype, CMT4H associated with variants in the FDG4 gene encoding Frabin.", "img": null}, {"id": "fc_017_13", "ch": 17, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CMTX1`** are associated with which clinical phenotype and molecular mechanism in **CMTX1**?", "a": "Pathogenic variants in the GJB1 gene on chromosome Xq13.1 encoding connexin-32 (Cx32) are associated with an X-linked form of CMT, CMTX1, which accounts for ~10–12% of all patients with CMT and is therefore the second most common type of CMT.", "img": null}, {"id": "fc_017_14", "ch": 17, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`BICD2`** are associated with which clinical phenotype and molecular mechanism in **Phenotypes and Main Associated Genes**?", "a": "If the clinical presentation is consistent with AMC and the EMG examination suggests a neurogenic origin, the molecular investigations should include the following genes: DYNC1H1, BICD2, TRPV4 (mainly dominant de novo variants).", "img": null}, {"id": "fc_017_15", "ch": 17, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATP7A`** are associated with which clinical phenotype and molecular mechanism in **Phenotypes and Main Associated Genes**?", "a": "Genes are listed in alphabetical order and according to mode of inheritance: autosomal dominant (AD) pattern, bold font and red; autosomal recessive (AR), regular font and blue; X-linked in black (LAS1L and ATP7A).", "img": null}, {"id": "fc_017_16", "ch": 17, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MPZ`** are associated with which clinical phenotype and molecular mechanism in **Childhood**?", "a": "Sensory symptoms like pain or paresthesias are unusual in children, especially at an early age; however, sensory ataxia is seen in some demyelinating CMT forms with onset in infancy and variable severity, such as those associated with dominant MPZ and the very rare PRX recessive variants (CMT4F).", "img": null}, {"id": "fc_017_17", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Motor-Sensory Neuropathies or Charcot-Marie-Tooth Disease and Related Neuropathies**, how is **hereditary** defined and characterized?", "a": "hereditary forms represent a significant proportion of such cases.", "img": null}, {"id": "fc_017_18", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Motor-Sensory Neuropathies or Charcot-Marie-Tooth Disease and Related Neuropathies**, how is **CharcotMarie-Tooth neuropathy (CMT)** defined and characterized?", "a": "CharcotMarie-Tooth neuropathy (CMT) , also named hereditary motor and sensory neuropathy (HMSN), is by far the most frequent hereditary neuropathy, with a pooled prevalence across different populations of about 17:100,000.", "img": null}, {"id": "fc_017_19", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Main CMT/HMSN Types**, how is **CMT4** defined and characterized?", "a": "CMT4 in case of autosomal recessive (AR) inheritance.", "img": null}, {"id": "fc_017_20", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Main CMT/HMSN Types**, how is **CMT2** defined and characterized?", "a": "CMT2 (HMSN II) indicates the primary axonal CMT subtypes , with either AD or AR inheritance, with preserved or only mildly slowed NCVs, above the limit of 38 m/s for median and ulnar motor nerves.", "img": null}, {"id": "fc_017_21", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Main CMT/HMSN Types**, how is **intermediate CMT** defined and characterized?", "a": "intermediate CMT , DI-CMT for autosomal dominant and RI-CMT for autosomal recessive inheritance; the X-linked CMTX1 variety frequently demonstrates intermediate NCV values.", "img": null}, {"id": "fc_017_22", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Main CMT/HMSN Types**, how is **DejerineSottas disease (DSD)** defined and characterized?", "a": "DejerineSottas disease (DSD) , (CMT3/HMSN III) includes the most severe forms of CMT1/CMT4, with onset before age 2, very low NCVs (<12 m/s), and nerve biopsy evidence of hypomyelination-dysmyelination.", "img": null}, {"id": "fc_017_23", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **CMT4**, how is **Vocal cord palsy** defined and characterized?", "a": "Vocal cord palsy may be seen in CMT4B1 and CMT4B2 associated with MTMR2 and MTMR13 gene variants, respectively; in the latter form glaucoma, either congenital or with later onset, is evident in ~25% of patients.", "img": null}, {"id": "fc_017_24", "ch": 17, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **CMT2**, how is **vocal cord palsy** defined and characterized?", "a": "vocal cord palsy causing hoarse voice is a frequent finding.", "img": null}, {"id": "fc_017_25", "ch": 17, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 17.1):", "a": "Representation of the different CMT and related neuropathy types and the overlap with other neurogenetic disorders to be considered in the differential diagnosis.", "img": "fig_p0416_02.jpg"}, {"id": "fc_017_26", "ch": 17, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 17.2):", "a": "VENN diagram showing the distribution of pathogenic variants among clinical and electrophysiological groups of hereditary neuropathies. CMT, Charcot-Marie-Tooth; dHMN, distal hereditary motor neuropathy; HSAN, hereditary sensory autonomic neuropathy. (From Korinthenberg R, Trollmann R, Plecko B, et al. Differential diagnosis of acquired and hereditary neuropathies in children and adolescents: consensus-based practice guidelines. Children (Basel). 2021;8:687 [Fig. 1].)", "img": "fig_p0419_02.jpg"}, {"id": "fc_017_27", "ch": 17, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Diagnostic Approach**, what are the distinguishing features of **Personal history**?", "a": "**Investigate carefully See at risk family members if possible Determine inheritance pattern: • Autosomal dominant • Autosomal recessive • X-linked (dominant or recessive) • Sporadic • Matrilineal (mitochondrial) Difficulties for sporadic cases:de novooccurrence or possible recessive inheritance Consider X-linked for males Consider also false paternity or maternity**: Onset and course; motor milestones, walking and running, trips and falls Muscle wasting and weakness, cramps and fasciculations, positive and negative sensory symptoms; fatigability Other known comorbidities", "img": null}, {"id": "fc_017_28", "ch": 17, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Diagnostic Approach**, what are the distinguishing features of **Neurological examination**?", "a": "**Investigate carefully See at risk family members if possible Determine inheritance pattern: • Autosomal dominant • Autosomal recessive • X-linked (dominant or recessive) • Sporadic • Matrilineal (mitochondrial) Difficulties for sporadic cases:de novooccurrence or possible recessive inheritance Consider X-linked for males Consider also false paternity or maternity**: Presence, site and degree of muscle wasting and weakness and sensory loss; muscle tone, deep tendon reflexes; skeletal deformities; cranial nerves’ function; hearing; presence of cerebellar signs", "img": null}, {"id": "fc_018_01", "ch": 18, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Early adulthood**?", "a": "**Causative Gene(s):** `HSAN1A, SPTLC1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** HSAN1 Subtype (Gene): HSAN1A (SPTLC1) — Sensory Involvement: +++ — Autonomic Disturbances: −/+(Horner syndrome) — Ulcerative- Mutilating: ++ — Distinguishing Features: Sensorineural deafness in some", "img": null}, {"id": "fc_018_02", "ch": 18, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Adulthood**?", "a": "**Causative Gene(s):** `HSAN1C, SPTLC2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** HSAN1 Subtype (Gene): HSAN1C (SPTLC2) — Sensory Involvement: +++ — Autonomic Disturbances: − — Ulcerative- Mutilating: −(except for one patient) — Distinguishing Features: UMN involvement in a family", "img": null}, {"id": "fc_018_03", "ch": 18, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HSAN2A(HSN2/WNK1)**?", "a": "**Causative Gene(s):** `HSAN2A, HSN2, WNK1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Early childhood — Sensory: +++ — Autonomic: +(sweating) — Ulcerative-: +++ — Distinguishing: Intellectual disability", "img": null}, {"id": "fc_018_04", "ch": 18, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HSAN2B(RETREG1)**?", "a": "**Causative Gene(s):** `HSAN2B, RETREG1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Early childhood — Sensory: ++ — Autonomic: ++ — Ulcerative-: +++ — Distinguishing: Spasticity", "img": null}, {"id": "fc_018_05", "ch": 18, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HSAN2C(KIF1A)**?", "a": "**Causative Gene(s):** `HSAN2C, KIF1A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Congenital — Sensory: +++ — Autonomic: − — Ulcerative-: +++ — Distinguishing: Intellectual disability in some", "img": null}, {"id": "fc_018_06", "ch": 18, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SPTLC1`** are associated with which clinical phenotype and molecular mechanism in **HSAN Caused by Variants in SPTLC1 (HSAN1A)**?", "a": "SPTLC1 encodes the first subunit of serine palmitoyltransferase (SPTLC1), which is involved in the synthesis of sphingolipids.", "img": null}, {"id": "fc_018_07", "ch": 18, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`HSAN1A`** are associated with which clinical phenotype and molecular mechanism in **Key Features of HSAN1**?", "a": "A clinical trial in adults with HSAN1A demonstrated that oral L-serine supplementation may be an effective therapy to slow disease progression.", "img": null}, {"id": "fc_018_08", "ch": 18, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SPTLC2`** are associated with which clinical phenotype and molecular mechanism in **HSAN Caused by Variants in SPTLC2 (HSAN1C)**?", "a": "A few families with pathogenic variants in SPTLC2 have been described.", "img": null}, {"id": "fc_018_09", "ch": 18, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`HSAN1D`** are associated with which clinical phenotype and molecular mechanism in **HSAN Caused by Variants in ATL1 and ATL3 (HSAN1D and HSAN1F)**?", "a": "HSAN1D is caused by a pathogenic variant in ATL1 , a gene that has been associated with spastic paraplegia 3 (SPG3) .", "img": null}, {"id": "fc_018_10", "ch": 18, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RAB7`** are associated with which clinical phenotype and molecular mechanism in **HSAN Caused by Variants in RAB7 (HSAN1 and CMT2B)**?", "a": "The first family reported with a RAB7 pathogenic variant had high arches, symmetrical distal wasting and weakness, reduced distal reflexes, pan-modal sensory impairment, and complications such as ulcers and amputations.", "img": null}, {"id": "fc_018_11", "ch": 18, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CMT2B`** are associated with which clinical phenotype and molecular mechanism in **HSAN Caused by Variants in RAB7 (HSAN1 and CMT2B)**?", "a": "This family was subcategorized among the hereditary motor and sensory neuropathies (CMT2B) because of the prominent motor involvement.", "img": null}, {"id": "fc_018_12", "ch": 18, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Cutaneous wounds**?", "a": "**Therapy / Intervention:** Wounds require cleaning and protection along with antiseptic treatment for osteomyelitis prevention. Surgical amputations or curettage may be necessary.\n\n**Clinical Context:** Treatment/Considerations: Wounds require cleaning and protection along with antiseptic treatment for osteomyelitis prevention. Surgical amputations or curettage may be necessary.", "img": null}, {"id": "fc_018_13", "ch": 18, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Callous formation prevention**?", "a": "**Therapy / Intervention:** Skin of neuropathic limbs requires hydration and lipid-based unguents. Appropriate shoes and socks are recommended.\n\n**Clinical Context:** Treatment/Considerations: Skin of neuropathic limbs requires hydration and lipid-based unguents. Appropriate shoes and socks are recommended.", "img": null}, {"id": "fc_018_14", "ch": 18, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Spine deformities**?", "a": "**Therapy / Intervention:** Bracing is not effective and may cause pressure ulcers; spinal fusion may be necessary.\n\n**Clinical Context:** Treatment/Considerations: Bracing is not effective and may cause pressure ulcers; spinal fusion may be necessary.", "img": null}, {"id": "fc_018_15", "ch": 18, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Ophthalmological complications**?", "a": "**Therapy / Intervention:** Prevention of corneal ulceration Antibiotics or antifungals if necessary. A corneal transplant may be required.\n\n**Clinical Context:** Treatment/Considerations: Prevention of corneal ulceration Antibiotics or antifungals if necessary. A corneal transplant may be required.", "img": null}, {"id": "fc_018_16", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN With Gastroesophageal Reflux and Cough Linked to 3p22-p24 (HSAN1B)**, how is **Neuropathic** defined and characterized?", "a": "Neuropathic symptoms consist of a sensation of hyperesthesia and numbness in the feet and fingertips.", "img": null}, {"id": "fc_018_17", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN2**, how is **Autonomic dysfunction** defined and characterized?", "a": "Autonomic dysfunction is variable and can include hyperhidrosis, slow pupillary reaction to light, and urinary incontinency in patients with more advanced disease.", "img": null}, {"id": "fc_018_18", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN2D/CIP Caused by Variants in SCN9A**, how is **paroxysmal extreme pain disorder** defined and characterized?", "a": "paroxysmal extreme pain disorder , primary erythromelalgia , and small fiber neuropathy (SFN) , whereas loss-of-function variants , which produce non-sodium currents, in both copies of SCN9A have been linked to channelopathy associated with congenital insensitivity to pain (CIP) .", "img": null}, {"id": "fc_018_19", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN2D/CIP Caused by Variants in SCN9A**, how is **familial erythromelalgia** defined and characterized?", "a": "familial erythromelalgia and paroxysmal extreme pain disorder are the opposite of the loss-of-function variants observed in CIP, and are characterized by localized extreme periodic pain and autonomic manifestations such as skin flushing and increased temperature because of vasodilation.", "img": null}, {"id": "fc_018_20", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN3 Caused by Variants in IKBKAP**, how is **familial dysautonomia (FD)** defined and characterized?", "a": "familial dysautonomia (FD) or the Riley-Day syndrome , is an autosomal recessive disorder which presents in infancy and mainly in Ashkenazi Jewish populations.", "img": null}, {"id": "fc_018_21", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN3 Caused by Variants in IKBKAP**, how is **dysautonomic crisis** defined and characterized?", "a": "dysautonomic crisis episodes, which are characterized by nausea and vomiting, agitation, tachycardia, and hypertension, that are often triggered by emotional or physical stress.", "img": null}, {"id": "fc_018_22", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN7 Caused by Variants in SCN11A**, how is **familiar episodic pain syndrome** defined and characterized?", "a": "familiar episodic pain syndrome consists of the appearance of painful episodes in the distal regions of the arms and legs during early infancy or childhood.", "img": null}, {"id": "fc_018_23", "ch": 18, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HSAN7 Caused by Variants in SCN11A**, how is **small fiber neuropathy** defined and characterized?", "a": "small fiber neuropathy , causing pain, tingling, and numbness in distal arms and legs, sometimes associated with gastroparesis.", "img": null}, {"id": "fc_018_24", "ch": 18, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 18.1):", "a": "(A) Patient with HSAN1 causing toe amputation, distal atrophy, and trophic changes. (B) Patient with HSAN1 that causes ulcerations in the sole of the foot.", "img": "fig_p0439_17.jpg"}, {"id": "fc_018_25", "ch": 18, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 18.2):", "a": "(A) Normal tongue with fungiform papillae present on the tip. (B) Dysautonomic tongue. Note the absence of the highly vascularized fungiform papillae from the tongue tip, which gives the appearance of a smooth tongue.", "img": "fig_p0443_06.jpg"}, {"id": "fc_018_26", "ch": 18, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 18.3):", "a": "Histamine test. Dysautonomic reaction (forearm on top) demonstrates a narrow areola surrounding the wheal. Normal reaction (lower forearm) displays diffuse axon flare around a central wheal.", "img": "fig_p0444_01.jpg"}, {"id": "fc_018_27", "ch": 18, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 18.4):", "a": "Digital shortening and nail deficiency in a patient with HSAN4.", "img": "fig_p0444_03.jpg"}, {"id": "fc_018_28", "ch": 18, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Function Autono al Outcomes of t mic Nervous Syste he Activation of the m**, what are the distinguishing features of **Heart Rate**?", "a": "**Parasympathetic**: Acceleration; Deceleration", "img": null}, {"id": "fc_019_01", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **V (McArdle) Myophosphorylase**?", "a": "**Causative Gene(s):** `PYGM` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Involved Tissues: Muscle — Main Clinical Symptoms: Exercise intolerance, rhabdomyolysis — Forearm Exercise Test: No lactate increase Excessive rise of ammonia — Muscle Biopsy: Vacuolar myopathy, increased PAS staining, phosphorylase stain deficiency — Gene/Inheritance: PYGM(AR)", "img": null}, {"id": "fc_019_02", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **IX Phosphorylase b kinase**?", "a": "**Causative Gene(s):** `PHKA1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Involved Tissues: Muscle Liver — Main Clinical Symptoms: Exercise intolerance, rhabdomyolysis — Forearm Exercise Test: Normal or blunted lactate increase — Muscle Biopsy: Inconstant vacuolar myopathy or increased PAS staining — Gene/Inheritance: PHKA1(XR)", "img": null}, {"id": "fc_019_03", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Phosphoglycerate kinase**?", "a": "**Causative Gene(s):** `PGK1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Involved Tissues: Muscle Erythrocytes Central nervous system — Main Clinical Symptoms: Exercise intolerance, rhabdomyolysis, muscle weakness Hemolytic anemia — Forearm Exercise Test: No lactate increase Excessive rise of ammonia — Muscle Biopsy: Inconstant increased PAS staining — Gene/Inheritance: PGK1(XR)", "img": null}, {"id": "fc_019_04", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **XIII β-enolase**?", "a": "**Causative Gene(s):** `ENO3` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Involved Tissues: Muscle — Main Clinical Symptoms: Exercise intolerance — Forearm Exercise Test: No lactate increase — Muscle Biopsy: Normal PAS staining Negative muscle β-enolase staining — Gene/Inheritance: ENO3(AR)", "img": null}, {"id": "fc_019_05", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **XIV Phosphoglucomutase**?", "a": "**Causative Gene(s):** `PGM1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Involved Tissues: Muscle — Main Clinical Symptoms: Exercise intolerance, rhabdomyolysis — Forearm Exercise Test: Normal lactate increase Excessive rise of ammonia — Muscle Biopsy: Vacuolar myopathy Increased PAS staining — Gene/Inheritance: PGM1(AR)", "img": null}, {"id": "fc_019_06", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Primary carnitine deficiency**?", "a": "**Causative Gene(s):** `SLC22A5` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Main Neuromuscular: Proximal muscle weakness, cardiomyopathy — Increase in Muscle: +++ — Very low plasma and muscle carnitine No acylcarnitines — SLC22A5", "img": null}, {"id": "fc_019_07", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Neutral lipid storage disease (NLSD)**?", "a": "**Causative Gene(s):** `ABHD5, PNPLA2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Main Neuromuscular: Proximal and distal muscle weakness, cardiomyopathy — Increase in Muscle: +++ — Normal plasma carnitine Normal acylcarnitine profile Lipid vacuoles in leucocytes — ABHD5 PNPLA2", "img": null}, {"id": "fc_019_08", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Carnitine palmitoyl transferase II (CPTII) deficiency**?", "a": "**Causative Gene(s):** `CPT2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Main Neuromuscular: Rhabdomyolysis episodes — Increase in Muscle: 0 to+ — Normal or moderately reduced plasma carnitine Increased long-chain acylcarnitines (C16, C18:1, C18) — CPT2(p.Ser113Leu prevalent variant)", "img": null}, {"id": "fc_019_09", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Very-long-chain acyl-CoA dehydrogenase (VLCAD) deficiency**?", "a": "**Causative Gene(s):** `ACADVL` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Main Neuromuscular: Rhabdomyolysis episodes Cardiomyopathy — Increase in Muscle: 0 to+ — Normal or moderately reduced plasma carnitine Increased long-chain acylcarnitines (C14:1as main species) Dicarboxylic aciduria — ACADVL", "img": null}, {"id": "fc_019_10", "ch": 19, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Mitochondrial trifunctional protein (MTP) deficiency**?", "a": "**Causative Gene(s):** `HADHA` · **Inheritance:** mtDNA\n\n**Clinical & Molecular Profile:** Main Neuromuscular: Rhabdomyolysis episodes Cardiomyopathy Axonal peripheral neuropathy — Increase in Muscle: 0 to+ — Increased long-chain 3-hydroxy-acylcarnitines Dicarboxylic and 3-hydroxydicarboxylic aciduria — HADHA HADHB", "img": null}, {"id": "fc_019_11", "ch": 19, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ANO5`** are associated with which clinical phenotype and molecular mechanism in **Metabolic Myopathies Revealed by Exercise Intolerance and Rhabdomyolysis**?", "a": "Muscular dystrophies can also mimic McArdle disease (pseudo-metabolic presentation of muscular dystrophies), and exercise intolerance associated with rhabdomyolysis episodes may be the initial disease manifestations in patients with dystrophin, calpain, FKRP , or ANO5 gene variants.", "img": null}, {"id": "fc_019_12", "ch": 19, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PYGM`** are associated with which clinical phenotype and molecular mechanism in **Myophosphorylase Deficiency (Glycogen Storage Disease Type V or McArdle Disease)**?", "a": "GSD V is caused by deficient activity of myophosphorylase, which is encoded by PYGM .", "img": null}, {"id": "fc_019_13", "ch": 19, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PHKA1`** are associated with which clinical phenotype and molecular mechanism in **Phosphorylase b Kinase Deficiency (Glycogen Storage Disease Type IX)**?", "a": "The myopathic form of PHK deficiency is caused by pathogenic variants in the X-chromosomal gene encoding the α-subunit of PHK (PHKA1) .", "img": null}, {"id": "fc_019_14", "ch": 19, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PGK1`** are associated with which clinical phenotype and molecular mechanism in **Other Disorders of Glycolysis**?", "a": "PGK is encoded by an X-linked gene (PGK1) , and approximately 10 patients have been reported with a myopathic form, with or without hemolytic anemia.", "img": null}, {"id": "fc_019_15", "ch": 19, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PGM1`** are associated with which clinical phenotype and molecular mechanism in **Other Disorders of Glycolysis**?", "a": "Pathogenic variants in the PGM1 gene were initially detected in patients with congenital disorders of glycosylation (CDG).", "img": null}, {"id": "fc_019_16", "ch": 19, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ENO3`** are associated with which clinical phenotype and molecular mechanism in **Other Disorders of Glycolysis**?", "a": "Deficiencies in aldolase A (ALDOA gene), b-enolase (ENO3 gene), and lactate dehydrogenase ( LDHM gene) have also been identified in patients with exercise intolerance.", "img": null}, {"id": "fc_019_17", "ch": 19, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Glycogen Storage Disease Type II (Pompe Disease)**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** The treatment of Pompe disease is the use of recombinant acid α-glucosidase (rhGAA, alglucosidase alfa).", "img": null}, {"id": "fc_019_18", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Muscle Metabolism During Exercise**, how is **anaerobic glycolysis** defined and characterized?", "a": "anaerobic glycolysis , especially when there is a burst of activity with rapid acceleration to maximal exercise.", "img": null}, {"id": "fc_019_19", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Muscle Glycogenosis**, how is **glycogen storage disease** defined and characterized?", "a": "glycogen storage disease (GSD) due to aberrant storage or utilization of glycogen (Fig.", "img": null}, {"id": "fc_019_20", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Disorders of Muscle Lipid Metabolism**, how is **lipid storage myopathies** defined and characterized?", "a": "lipid storage myopathies is often used when the accumulation of lipid droplets in muscle fibers is the predominant feature and is associated with a vacuolated appearance on routine histological stains such as hematoxylin and eosin or modified Gömöri trichrome.", "img": null}, {"id": "fc_019_21", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Muscle Biopsy**, how is **glycogenosis** defined and characterized?", "a": "glycogenosis , a vacuolar myopathy and increased glycogen content on periodic acid-Schiff (PAS) staining are the typical features.", "img": null}, {"id": "fc_019_22", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Muscle Biopsy**, how is **disorders of lipid metabolism** defined and characterized?", "a": "disorders of lipid metabolism , muscle biopsy may exhibit increased lipid droplet content as observed in neutral lipid storage diseases (NLSD), PCD, or MADD.", "img": null}, {"id": "fc_019_23", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Phosphorylase b Kinase Deficiency (Glycogen Storage Disease Type IX)**, how is **myopathic** defined and characterized?", "a": "myopathic variants of PHK deficiency present in a form that is clinically similar to McArdle disease with exercise intolerance, cramps, and rarely recurrent myoglobinuria in young adults.", "img": null}, {"id": "fc_019_24", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Disorders of Glycolysis**, how is **Phosphofructokinase deficiency or GSD VII** defined and characterized?", "a": "Phosphofructokinase deficiency or GSD VII is the most frequent glycolytic disorder.", "img": null}, {"id": "fc_019_25", "ch": 19, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Disorders of Glycolysis**, how is **Phosphoglycerate mutase (PGAM)** defined and characterized?", "a": "Phosphoglycerate mutase (PGAM) deficiency has been described in fewer than 20 patients.", "img": null}, {"id": "fc_019_26", "ch": 19, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 19.1):", "a": "Metabolic pathways and corresponding metabolic myopathies. See text for abbreviations.", "img": "fig_p0456_01.jpg"}, {"id": "fc_019_27", "ch": 19, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 19.2):", "a": "Clinical symptoms and/or signs highly suggestive of metabolic myopathies. Font size depends on the frequency of the element in the specific group. The highlighted features are found only in the group they belong to.", "img": "fig_p0456_04.jpg"}, {"id": "fc_019_28", "ch": 19, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 19.3):", "a": "(A) Muscle energy metabolism during maximal exercise. Contributions of PCr (light green), glycolysis (medium green), and oxidative phosphorylation (dark green) to ATP turnover during maximal exercise. Muscle samples were obtained before and during 30 s of all-out cycling exercise. Dw, Dry weight. (From Hargreaves M, Spriet LL. Skeletal muscle energy metabolism during exercise. Nat Metab. 2020;2:817-828 [Fig. 1, p. 818].) (B) Relative contributions of carbohydrate and fat fuel sources based on exercise intensity. Trained cyclists exercised at increasing intensities, and the relative contributions of fuels for contracting skeletal muscle were measured with indirect calorimetry and tracer methods. An increasing contribution of carbohydrate fuels, notably muscle glycogen, is observed at higher exercise intensities. cal, Calorie; FFA, free fatty acids.", "img": "fig_p0457_02.jpg"}, {"id": "fc_020_01", "ch": 20, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hyperkalemic periodic paralysis**?", "a": "**Causative Gene(s):** `SCN4A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Age of Onset: First decade — Muscles Most Affected: Limbs and trunk — Additional Features: Neonatal hypotonia Myotonia can be seen — Triggers: High serum potassium, may be due to potassium-rich foods Cold environment, intercurrent illness Rest after exertion Puberty, menses — Diagnostic Clue: Weakness can be any time of", "img": null}, {"id": "fc_020_02", "ch": 20, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hypokalemic periodic paralysis**?", "a": "**Causative Gene(s):** `CACNA1S, SCN4A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Causative Gene: CACNA1S SCN4A — Inheritance: AD — Age of Onset: Second decade typical — Muscles Most Affected: Limbs and trunk — Additional Features: In very severe attacks facial muscles can be weak— speech slurred, and respiratory muscles affected — Triggers: Low serum potassium, may be due to carbohydrate-rich food or fasting Intercurr", "img": null}, {"id": "fc_020_03", "ch": 20, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Andersen-Tawil syndrome**?", "a": "**Causative Gene(s):** `KCNJ2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Age of Onset: First and second decade — Muscles Most Affected: Limbs and trunk — Additional Features: Cardiac conduction abnormalities Ventricular tachyarrhythmia Dysmorphic features— commonly short stature, micrognathia, clinodactyly, syndactyly, low-set ears — Triggers: Low serum potassium, may be due to carbohydrate-r", "img": null}, {"id": "fc_020_04", "ch": 20, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Myotonia congenita**?", "a": "**Causative Gene(s):** `CLCN1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AD or AR — Age of Onset: Typically early teens Range first to fourth decade — Muscles Most Affected: Legs>face and hands — Additional Features: Warm-up phenomenon (myotonia improves with repetitive action) Transient weakness may be observed, also improves with repetitive action Muscle hypertrophy Contractures Scoliosis Toe wa", "img": null}, {"id": "fc_020_05", "ch": 20, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Paramyotonia congenita**?", "a": "**Causative Gene(s):** `SCN4A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Age of Onset: Typically first decade Often early— birth or within first few weeks — Muscles Most Affected: Eyelids, extraocular muscles, jaw, tongue, hands>legs — Additional Features: Paradoxical worsening with repetitive action Can have episodic weakness/paralysis (overlap with hyperPP) Muscle hypertrophy Contractures S", "img": null}, {"id": "fc_020_06", "ch": 20, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Sodium channel myotonia**?", "a": "**Causative Gene(s):** `SCN4A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Age of Onset: Typically first or second decade — Muscles Most Affected: Eyelids, extraocular muscles, jaw, tongue, hands, legs — Additional Features: Both warm-up phenomenon and paradoxical worsening can be seen Muscle hypertrophy — Myotonic Triggers: Extremes of temperature—cold or hot Sometimes high-potassium foods — D", "img": null}, {"id": "fc_020_07", "ch": 20, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SNEL**?", "a": "**Causative Gene(s):** `SCN4A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: Often de novo Can be AD — Age of Onset: Birth to 10 months — Muscles Most Affected: Generalized but prominent respiratory and laryngeal muscle involvement — Additional Features: Recurrent episodic apnea±stridor Bradycardia Loss of consciousness Massive muscle hypertrophy Dysmorphic features", "img": null}, {"id": "fc_020_08", "ch": 20, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCN4A`** are associated with which clinical phenotype and molecular mechanism in **Hyperkalemic Periodic Paralysis (HyperPP)**?", "a": "The genetic form is due to pathogenic variants in SCN4A .", "img": null}, {"id": "fc_020_09", "ch": 20, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CACNA1S`** are associated with which clinical phenotype and molecular mechanism in **Hypokalemic Periodic Paralysis (HypoPP)**?", "a": "It is due primarily to pathogenic variants in the CACNA1S gene, which codes for a voltage-gated calcium channel that interacts with the ryanodine receptor to prompt calcium release from the sarcoplasmic reticulum.", "img": null}, {"id": "fc_020_10", "ch": 20, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KCNJ2`** are associated with which clinical phenotype and molecular mechanism in **Andersen-Tawil Syndrome (ATS)**?", "a": "It is due to pathogenic variants in KCNJ2 expressed in both skeletal and cardiac muscle as well as having a role in bony development.", "img": null}, {"id": "fc_020_11", "ch": 20, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CLCN1`** are associated with which clinical phenotype and molecular mechanism in **Myotonia Congenita (MC)**?", "a": "It is due to pathogenic variants in CLCN1 which codes for the voltage-gated chloride channel ClC-1, which has an essential role in resetting the sarcolemma after depolarization and muscle contraction.", "img": null}, {"id": "fc_020_12", "ch": 20, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Nondystrophic myotonia (NMD)**?", "a": "**Therapy / Intervention:** Mexiletine\n\n**Clinical Context:** Medication: Mexiletine — Monitoring Requirements: ECG, FBC, LFTs, clotting before starting ECG after each dose increment and yearly on stable regime — Other Comments: Those with MC may need higher doses than those withSC", "img": null}, {"id": "fc_020_13", "ch": 20, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **SNEL**?", "a": "**Therapy / Intervention:** Mexiletine, carbamazepine, flecainide\n\n**Clinical Context:** Medication: Mexiletine, carbamazepine, flecainide — Monitoring Requirements: As above — Other Comments: Can result in almost complete cessation of apneic episodes and infants in ICU can be discharged Some in vitro eviden", "img": null}, {"id": "fc_020_14", "ch": 20, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Hypokalemic periodic paralysis**?", "a": "**Therapy / Intervention:** Acetazolamide\n\n**Clinical Context:** Medication: Acetazolamide — Monitoring Requirements: U+Es before starting and 7 to 10 days after Repeat U+Es after each dose increment Renal USS before starting and consider yearly thereafter", "img": null}, {"id": "fc_020_15", "ch": 20, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Hyperkalemic periodic paralysis**?", "a": "**Therapy / Intervention:** Acetazolamide\n\n**Clinical Context:** Medication: Acetazolamide — Monitoring Requirements: U+Es before starting and 7 to 10 days after Repeat U+Es after each dose increment Renal USS before starting and consider yearly thereafter", "img": null}, {"id": "fc_020_16", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Periodic Paralyses**, how is **hyperkalemic periodic paralysis** defined and characterized?", "a": "hyperkalemic periodic paralysis (HyperPP), hypokalemic periodic paralysis (HypoPP), and Andersen-Tawil syndrome (ATS) (Table 20.", "img": null}, {"id": "fc_020_17", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hypokalemic Periodic Paralysis (HypoPP)**, how is **AndersenTawil syndrome (ATS)** defined and characterized?", "a": "AndersenTawil syndrome (ATS) and look for dysmorphic features and the ECG changes of hypokalemia (Table 20.", "img": null}, {"id": "fc_020_18", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Andersen-Tawil Syndrome (ATS)**, how is **Dysmorphic features** defined and characterized?", "a": "Dysmorphic features can include short stature, syndactyly, clinodactyly, micrognathia, low-set ears, small hands and feet, scoliosis, cleft palate, and dental abnormalities; these features are not universal.", "img": null}, {"id": "fc_020_19", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Andersen-Tawil Syndrome (ATS)**, how is **Cardiac involvement** defined and characterized?", "a": "Cardiac involvement can range from an asymptomatic long QT syndrome to life-threatening ventricular tachyarrhythmia requiring an implantable defibrillator.", "img": null}, {"id": "fc_020_20", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Paramyotonia Congenita and Sodium Channel Myotonia**, how is **paramyotonia congenita** defined and characterized?", "a": "paramyotonia congenita (PMC) and sodium channel myotonia (SCM).", "img": null}, {"id": "fc_020_21", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Differential Diagnosis**, how is **Myotonic dystrophy type 2** defined and characterized?", "a": "Myotonic dystrophy type 2 is more readily confused with MC, but congenital or early childhood onset is not recognized.", "img": null}, {"id": "fc_020_22", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Differential Diagnosis**, how is **myotonic myopathy** defined and characterized?", "a": "myotonic myopathy and probably does represent an overlap of the SNEL phenotype with congenital myopathy.", "img": null}, {"id": "fc_020_23", "ch": 20, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Anesthetic Guidance**, how is **myotonic crisis** defined and characterized?", "a": "myotonic crisis can mimic a malignant hyperthermia type syndrome with generalized body stiffness.", "img": null}, {"id": "fc_020_24", "ch": 20, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 20.1):", "a": "Clinical spectrum of the nondystrophic myotonias and periodic paralyses. Myotonia predominates in disorders further to the left in this spectrum, whereas periodic paralysis is the major symptom for those further to the right (A). The underlying molecular genetic defects in each of these disorders are variants in voltage-gated ion channels (A, bottom row). An electromyographic recording of a myotonic burst (B), computer simulations of an action potential in normal muscle, and depolarization-induced loss of excitability during an attack of periodic paralysis (C) are also shown. (Cannon SC. Pathomechanisms in channelopathies of skeletal muscle and brain. Annu Rev Neurosci 2006;29:387–415.)", "img": "fig_p0480_01.jpg"}, {"id": "fc_020_25", "ch": 20, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 20.2):", "a": "Periodic paralysis.", "img": "vfig_p0480_01.jpg"}, {"id": "fc_020_26", "ch": 20, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 20.3):", "a": "Flow chart for the emergency management of a child presenting with hypokalemia and flaccid paralysis.", "img": "fig_p0484_10.jpg"}, {"id": "fc_020_27", "ch": 20, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Channelopathy Causative Gene Inheritance Age of Onset Muscles Most Affected Additional Features Triggers Diagnostic Clue**, what are the distinguishing features of **Hyperkalemic periodic paralysis**?", "a": "**Causative Gene**: SCN4A; **Inheritance**: AD; **Age of Onset**: First decade; **Muscles Most Affected**: Limbs and trunk; **Additional Features**: Neonatal hypotonia Myotonia can be seen; **Triggers**: High serum potassium, may be due to potassium-rich foods Cold environment, intercurrent illness Rest after exertion Puberty, menses; **Diagnostic Clue**: Weakness can be any time of day Can last minutes to hours May have additional myotonia and sometimes muscle hypertrophy", "img": null}, {"id": "fc_020_28", "ch": 20, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Channelopathy Causative Gene Inheritance Age of Onset Muscles Most Affected Additional Features Triggers Diagnostic Clue**, what are the distinguishing features of **Hypokalemic periodic paralysis**?", "a": "**Causative Gene**: CACNA1S SCN4A; **Inheritance**: AD; **Age of Onset**: Second decade typical; **Muscles Most Affected**: Limbs and trunk; **Additional Features**: In very severe attacks facial muscles can be weak— speech slurred, and respiratory muscles affected; **Triggers**: Low serum potassium, may be due to carbohydrate-rich food or fasting Intercurrent illness Rest after exertion Puberty, menses; **Diagnostic Clue**: Attacks common during night when wakes to use bathroom or first thing in morning Attacks are typically hours to days Plays football after school, has pizza for tea, wakes next morning unable to move", "img": null}, {"id": "fc_021_01", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CHARGE association**?", "a": "**Causative Gene(s):** `CHD7` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Bilateral or unilateral uveal colobomas — Heart defects, choanal atresia, growth delays, genitourinary defects, and ear anomalies/deafness", "img": null}, {"id": "fc_021_02", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Meckel-Gruber syndrome**?", "a": "**Causative Gene(s):** `MKS1, TMEM216, TMEM67, CEP290, RPGRIP1L, CC2D2A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Microphthalmos, anophthalmos, chorioretinal abnormalities, hypoplasia/ aplasia of iris, sclerocornea — Occipital encephalocele, microcephaly, multicystic kidney, polydactyly of fingers and toes, hepatic fibrosis, ambiguous genitalia — Causative Gene: MKS1,TMEM216, TMEM67,CEP290, RPGRIP1L,CC2D2A and others", "img": null}, {"id": "fc_021_03", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Renal coloboma syndrome**?", "a": "**Causative Gene(s):** `PAX2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Optic nerve or retinal coloboma, optic nerve dysplasia, myopia, strabismus — Renal hypoplasia with end-stage renal disease, multicystic kidneys, vesicoureteral reflux", "img": null}, {"id": "fc_021_04", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Rubinstein-Taybi syndrome**?", "a": "**Causative Gene(s):** `EP300` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Congenital or juvenile glaucoma, coloboma, nystagmus, strabismus — Broad thumbs and halluces, short stature, DD/ID, facial anomalies, risk of cancerous and noncancerous tumors — Causative Gene: CREBBP,EP300, microdeletions of chromosome 16p", "img": null}, {"id": "fc_021_05", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Warburg syndrome**?", "a": "**Causative Gene(s):** `POMT1, POMT2, LARGE1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Microphthalmos, anophthalmos, coloboma, cataract, optic nerve hypoplasia, aplasia or atrophy — Congenital muscular dystrophy, abnormal cerebellar vermis, lissencephaly and neural migration defects, hydrocephalus, DD/ID — Causative Gene: POMT1,POMT2,CRPPA, FKTN,FKRP,LARGE1", "img": null}, {"id": "fc_021_06", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Anophthalmiaesophageal–genital (AEG) syndrome**?", "a": "**Causative Gene(s):** `SOX2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Anophthalmos, microphthalmos — Tracheo-esophageal fistula and esophageal atresia, genital tract malformations in males, renal anomalies, DD/ID, seizures", "img": null}, {"id": "fc_021_07", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Joubert syndrome**?", "a": "**Causative Gene(s):** `AHI1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Nystagmus, oculomotor apraxia, retinitis pigmentosa, uveal coloboma, ptosis, strabismus — Absent or hypoplastic cerebellar vermis with ataxia, abnormal breathing patterns, hypotonia, molar tooth sign, cleft lip/palate, seizures, DD/ID — Causative Gene: AHI1,CEP290and other ciliopathy genes as for Meckel-Gruber syndrom", "img": null}, {"id": "fc_021_08", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **OTX2and pituitary abnormalities**?", "a": "**Causative Gene(s):** `OTX2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Anophthalmos, microphthalmos, anterior segment dysgenesis, optic nerve and optic chiasm aplasia — Pituitary hypoplasia, ectopic pituitary gland, growth hormone deficiency and combined pituitary hormone deficiency, DD/ID, Arnold Chiari malformation, agnathia–otocephaly complex", "img": null}, {"id": "fc_021_09", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Matthew-Wood syndrome/Pulmonary hypoplasia- Diaphragmatic hernia- Anophthalmia-Cardiac defect (PDAC) syndrome**?", "a": "**Causative Gene(s):** `STRA6` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Anophthalmos, severe microphthalmos — Pulmonary hypoplasia or aplasia, diaphragmatic hernia, cardiac defects, craniofacial anomalies, DD/ID", "img": null}, {"id": "fc_021_10", "ch": 21, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Waardenburg anophthalmia syndrome**?", "a": "**Causative Gene(s):** `SMOC1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Ocular Associations: Microphthalmos, anophthalmos — Limb abnormalities with absent or fused digits (oligosyndactyly), facial anomalies, DD/ID", "img": null}, {"id": "fc_021_11", "ch": 21, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TRIM44`** are associated with which clinical phenotype and molecular mechanism in **Congenital Aniridia**?", "a": "Variations in other genes such as FOXC1 , PITX2 , CYP1B1 , FOXD3 , and TRIM44 have been observed in less than 10% of the cases.", "img": null}, {"id": "fc_021_12", "ch": 21, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`COL4A1`** are associated with which clinical phenotype and molecular mechanism in **Developmental Anomalies**?", "a": "Some of the commonly affected genes are PAX6, PITX2, CYP1B1, LTBP2, JAG1, FOXC1, FOXC2, PITX3, FOXE3, BMP4, COL4A1, LAMB2, B3GALTL, SOX2 , and BCOR .", "img": null}, {"id": "fc_021_13", "ch": 21, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CRYBB1`** are associated with which clinical phenotype and molecular mechanism in **Syndromes and Congenital Cataract**?", "a": "Of these gene families, the crystallin proteins represent >90% of the total soluble protein in the lens; pathogenic variants in CRYAA , CRYAB , CRYBB1 , CRYBB2 , CRYBB3 , CRYGC , and CRYGD are frequent causes of nonsyndromic cataracts (Table 21.5).", "img": null}, {"id": "fc_021_14", "ch": 21, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATF6`** are associated with which clinical phenotype and molecular mechanism in **Achromatopsia**?", "a": "Achromatopsia demonstrates AR inheritance in most patients and pathogenic variants have been demonstrated in six genes: CNGA3 and CNGB3 which account for an estimated 80–90% of cases; PDE6C , GNAT2 , ATF6 , and PDE6H are less common.", "img": null}, {"id": "fc_021_15", "ch": 21, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FZD4`** are associated with which clinical phenotype and molecular mechanism in **Persistent Hyperplastic Primary Vitreous**?", "a": "TP53, VEGFA, SMAD2, CDKN2A, FOXC, FZD4, LRP5, KDR, FZD5, PAX6, MYCN, NDP, PITX2 , and PAX2 have been considered as candidate genes, but the genetic etiology is largely unknown.", "img": null}, {"id": "fc_021_16", "ch": 21, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ZN408`** are associated with which clinical phenotype and molecular mechanism in **Familial Exudative Vitreoretinopathy**?", "a": "Approximately 50% of patients with FEVR have pathogenic variants in the NDP , FZD4 , LRP5 , TSPAN12 , and ZN408 genes.", "img": null}, {"id": "fc_021_17", "ch": 21, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Achromatopsia**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Gene supplementation approaches, with injections of functional genes into the cone photoreceptors, are being evaluated and gene therapy trials are available for CNGA3 - and CNGB3 -related diseases.", "img": null}, {"id": "fc_021_18", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Blindness**, how is **blindness/severe visual impairment (BL/SVI)** defined and characterized?", "a": "blindness/severe visual impairment (BL/SVI) worldwide and that 500,000 children lose their vision each year.", "img": null}, {"id": "fc_021_19", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microphthalmos, Anophthalmos, and Coloboma (MAC) Disorders**, how is **Microphthalmos** defined and characterized?", "a": "Microphthalmos represents a small eye, defined as two standard deviations less than the normal for chronological age.", "img": null}, {"id": "fc_021_20", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microphthalmos, Anophthalmos, and Coloboma (MAC) Disorders**, how is **Anophthalmos** defined and characterized?", "a": "Anophthalmos is described as a complete absence of ocular tissues, which can be confirmed either by ultrasound or histological examination.", "img": null}, {"id": "fc_021_21", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microphthalmos, Anophthalmos, and Coloboma (MAC) Disorders**, how is **Coloboma** defined and characterized?", "a": "Coloboma refers to a congenital defect in the uveal tissue owing to the incomplete closure of the choroidal fissure during embryogenesis.", "img": null}, {"id": "fc_021_22", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microphthalmos, Anophthalmos, and Coloboma (MAC) Disorders**, how is **nanophthalmos** defined and characterized?", "a": "nanophthalmos , refers to a small eye with no structural abnormalities and is associated with better visual acuity.", "img": null}, {"id": "fc_021_23", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microphthalmos, Anophthalmos, and Coloboma (MAC) Disorders**, how is **retinal detachment** defined and characterized?", "a": "retinal detachment ; periodic retinal examinations are required.", "img": null}, {"id": "fc_021_24", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Microphthalmos, Anophthalmos, and Coloboma (MAC) Disorders**, how is **Extraocular anomalies** defined and characterized?", "a": "Extraocular anomalies have been reported in 33–95% of patients with MAC; 20–45% may have an underlying syndromic diagnosis.", "img": null}, {"id": "fc_021_25", "ch": 21, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Aniridia**, how is **Foveal hypoplasia** defined and characterized?", "a": "Foveal hypoplasia is an absence of the foveal pit and is seen in 80–90% of patients with aniridia.", "img": null}, {"id": "fc_021_26", "ch": 21, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 21.1):", "a": "Anterior segment photographs of MAC (microphthalmos, anophthalmos and coloboma) disorder. (A) shows a child with bilateral colobomatous microphthalmos with a right orbitopalpebral cyst (bluish cystic swelling). (B) shows the same child with the lower eyelid everted to reveal the cystic nature of the swelling. (C) shows the axial computed tomography scan of the same patient showing the orbital extension of the cyst (white arrow) and the coloboma (yellow arrow) . (D) shows appearance of bilateral clinical anophthalmos. (E) shows a child with left eye anophthalmos and cleft lip and palate. (F) shows a child with bilateral microphthalmos, telecanthus, and downslanting palpebral fissures. (G) shows a patient with bilateral complex microphthalmos. (H) shows a patient with unilateral simple microphthalmos affecting the right eye. (I) shows the co-occurrence of iridocorneal adhesions (green arrow) with coloboma, (J) shows a typical iris coloboma with iris remnants over the anterior capsule.", "img": "fig_p0496_08.jpg"}, {"id": "fc_021_27", "ch": 21, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 21.2):", "a": "Retinochoroidal coloboma. (A) shows a montage reconstruction of the fundus images showing the retinochoroidal coloboma involving the optic nerve (ON) and the macula (M). (B) shows a retinal detachment (white arrow) due to the coloboma. (C) shows intraoperative view of a retinochoroidal coloboma (CO) sparing the optic nerve (ON) and macula and thus associated with a better visual prognosis.", "img": "fig_p0497_02.jpg"}, {"id": "fc_021_28", "ch": 21, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 21.3):", "a": "Congenital aniridia. (A) shows near total absence of iris and visible margins of the clear lens (L) in both the eyes. (B) shows a superiorly subluxated, cataractous lens (L) and early aniridia associated keratopathy (white arrow) in both the eyes.", "img": "fig_p0499_02.jpg"}, {"id": "fc_022_01", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Stargardt disease; 248200**?", "a": "**Causative Gene(s):** `ABCA4` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal recessive — Stargardt disease is a genetic retinal disorder caused by variants in ABCA4 which is crucial for the transport of vitamin A derivatives in photoreceptor cells of the retina.", "img": null}, {"id": "fc_022_02", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Macular dystrophy with central cone involvement; 616170**?", "a": "**Causative Gene(s):** `MFSD8` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal recessive", "img": null}, {"id": "fc_022_03", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal recessive bestrophinopathy; 611809**?", "a": "**Causative Gene(s):** `BEST1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal recessive — It is caused by pathogenic variants in BEST1 , which leads to the accumulation of lipofuscin (a fatty pigment) in the retinal pigment epithelium.", "img": null}, {"id": "fc_022_04", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal recessive (atypical) vitelliform dystrophy; 616151**?", "a": "**Causative Gene(s):** `IMPG1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal recessive", "img": null}, {"id": "fc_022_05", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Stargardt-like macular dystrophy; 600110**?", "a": "**Causative Gene(s):** `ELOVL4` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal dominant", "img": null}, {"id": "fc_022_06", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Stargardt-like macular dystrophy; 603786**?", "a": "**Causative Gene(s):** `PROM1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal dominant", "img": null}, {"id": "fc_022_07", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal dominant bull’s-eye macular dystrophy; 608051**?", "a": "**Causative Gene(s):** `PROM1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal dominant", "img": null}, {"id": "fc_022_08", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal dominant (atypical) vitelliform dystrophy; 616151**?", "a": "**Causative Gene(s):** `IMPG1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal dominant", "img": null}, {"id": "fc_022_09", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Best macular dystrophy; 153700**?", "a": "**Causative Gene(s):** `BEST1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal dominant — It is caused by pathogenic variants in BEST1 , which leads to the accumulation of lipofuscin (a fatty pigment) in the retinal pigment epithelium.", "img": null}, {"id": "fc_022_10", "ch": 22, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pattern dystrophy; 169150**?", "a": "**Causative Gene(s):** `PRPH2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Mode of Inheritance: Autosomal dominant", "img": null}, {"id": "fc_022_11", "ch": 22, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ABCA4`** are associated with which clinical phenotype and molecular mechanism in **Stargardt Disease**?", "a": "Stargardt disease is a genetic retinal disorder caused by variants in ABCA4 which is crucial for the transport of vitamin A derivatives in photoreceptor cells of the retina.", "img": null}, {"id": "fc_022_12", "ch": 22, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CEP290`** are associated with which clinical phenotype and molecular mechanism in **Retinitis Pigmentosa**?", "a": "There are more than 50 ongoing clinical trials for different gene defects, including RPGR, CEP290, and EYS .", "img": null}, {"id": "fc_022_13", "ch": 22, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FZD4`** are associated with which clinical phenotype and molecular mechanism in **Genetics**?", "a": "FEVR has been associated with pathogenic variants in several genes, the most frequently described are: FZD4 , LRP5 , TSPAN12 , ZNF408 , and NDP .", "img": null}, {"id": "fc_022_14", "ch": 22, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RS1`** are associated with which clinical phenotype and molecular mechanism in **X-Linked Juvenile Retinoschisis**?", "a": "It is due to pathogenic gene variations in RS1 , which codes for retinoschisin, a protein involved in cell adhesion and neuroconduction primarily expressed in photoreceptors and bipolar cells.", "img": null}, {"id": "fc_022_15", "ch": 22, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Main Retinitis Pigmentosa Syndromes**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** While there is currently no cure for choroideremia, clinical trials are exploring gene therapy to replace the defective CHM gene responsible for choroideremia.", "img": null}, {"id": "fc_022_16", "ch": 22, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Management**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** In cases with neovascularization but without retinal detachment (stage 2), early laser photocoagulation is the treatment of choice.", "img": null}, {"id": "fc_022_17", "ch": 22, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Leber Hereditary Optic Neuropathy (LHON)**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** There are multiple phase 2 and 3 intraocular gene therapy protocols, some with 5 years follow-up ( MT-ND4 gene) demonstrating improvement in the best corrected visual acuity.", "img": null}, {"id": "fc_022_18", "ch": 22, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ocular Manifestations in Type 1 and Type 2 Stickler Syndrome**, how is **Cataract** defined and characterized?", "a": "Cataract is also common, typically bilateral lamellar cortical opacity.", "img": null}, {"id": "fc_022_19", "ch": 22, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ocular Manifestations in Type 1 and Type 2 Stickler Syndrome**, how is **glaucoma** defined and characterized?", "a": "glaucoma is also higher than in the general population.", "img": null}, {"id": "fc_022_20", "ch": 22, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Abetalipoproteinemia**, how is **Bassen-Kornzweig syndrome** defined and characterized?", "a": "Bassen-Kornzweig syndrome , is a rare genetic disorder that affects the body’s ability to absorb dietary fats, cholesterol, and liposoluble vitamins (A, D, E, K).", "img": null}, {"id": "fc_022_21", "ch": 22, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Atrofia Gyrata**, how is **gyrate atrophy** defined and characterized?", "a": "gyrate atrophy of the choroid and retina, is a rare genetic disorder characterized by progressive degeneration of the retina.", "img": null}, {"id": "fc_022_22", "ch": 22, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Refsum Disease**, how is **heredopathia atactica polyneuritiformis** defined and characterized?", "a": "heredopathia atactica polyneuritiformis , is a rare genetic disorder that affects the ability to break down phytanic acid, a type of fatty acid found in certain foods.", "img": null}, {"id": "fc_022_23", "ch": 22, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 22.1):", "a": "Cross-sectional images of the human eye (A) and the light-sensitive retina (B). Eye field specification starts at around 3 weeks gestation in the anterior neural plate, followed by the formation of optic vesicle, lens, cornea, and retina at various stages. GCL, Ganglion cell layer; INL, inner nuclear layer; IPL, inner plexiform layer; ONL, outer nuclear layer; OPL, outer plexiform layer. (Modified from Chen HY, Lehmann OJ, Swaroop A. Genetics and therapy for pediatric eye disease. EBioMedicine . 2021;67:103360 [Fig. 1A, B].)", "img": "fig_p0530_01.jpg"}, {"id": "fc_022_24", "ch": 22, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 22.2):", "a": "Venn diagram of currently identified genes associated with retinitis pigmentosa (RP) and their genetic overlap with other inherited retinal dystrophies. For example, variants in the RHO gene can manifest in either RP or congenital stationary night-blindness phenotypes. All genes included are registered in the Online Mendelian Inheritance in Man (OMIM) database and follow the up-to-date symbols of the HUGO Gene Nomenclature Committee (HGNC). Genes that are associated with syndromic forms of RP are marked with an asterisk (*). ACHM, Achromatopsia; CO(R)D, cone(-rod) dystrophy; CSNB, congenital stationary night blindness; LCA, Leber congenital amaurosis; MD, macular dystrophy.", "img": "fig_p0531_02.jpg"}, {"id": "fc_022_25", "ch": 22, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 22.3):", "a": "Retinography, fundus autofluorescence (FAF), and macular optic coherence tomography (OCT) of a patient with Stargardt disease. There is a marked macular atrophy expressed as a characteristic retinal aspect on the retinography, central hypofluorescence on FAF, and retinal external layers atrophy on OCT.", "img": "fig_p0531_04.jpg"}, {"id": "fc_022_26", "ch": 22, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Chromosomal Loci and Causative Genes in Inherited Macular Dystroph ies**, what are the distinguishing features of **Stargardt disease; 248200**?", "a": "**Mode of Inheritance**: Autosomal recessive; **Affected Gene**: ABCA4", "img": null}, {"id": "fc_022_27", "ch": 22, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Chromosomal Loci and Causative Genes in Inherited Macular Dystroph ies**, what are the distinguishing features of **Macular dystrophy with central cone involvement; 616170**?", "a": "**Mode of Inheritance**: Autosomal recessive; **Affected Gene**: MFSD8", "img": null}, {"id": "fc_022_28", "ch": 22, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Chromosomal Loci and Causative Genes in Inherited Macular Dystroph ies**, what are the distinguishing features of **Autosomal recessive bestrophinopathy; 611809**?", "a": "**Mode of Inheritance**: Autosomal recessive; **Affected Gene**: BEST1", "img": null}, {"id": "fc_023_01", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal recessive**?", "a": "**Causative Gene(s):** `ADCY1, BDP1, BSND, CABP2, CDC14A, CDH23` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Characteristics: Generally prelingual and range from mild-to- moderate to severe to profound — N Genes: 76 — Genes: ADCY1, BDP1, BSND, CABP2, CDC14A, CDH23, CEACAM16, CIB2, CLDN14, CLDN9, CLIC5, COL11A2, DCDC2, ELMOD3, EPS8, EPS8L2, ESPN, ESRP1, ESRRB, FAM65B, GAB1, GIPC3, GJB2, GJB6, GPSM2, GRAP, GRXCR1, GRXCR2, HGF, ILDR1, KARS, LHFPL5,", "img": null}, {"id": "fc_023_02", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal dominant**?", "a": "**Causative Gene(s):** `ACTG1, CCDC50, CD164, CEACAM16, COL11A1, COL11A2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Characteristics: Generally postlingual and progressive — N Genes: 48 — Genes: ACTG1, CCDC50, CD164, CEACAM16, COCH, COL11A1, COL11A2, CRYM, DIAPH1, DMXL2, EYA4, GJB2, GJB3, GJB6, GRHL2, DFNA5, HOMER2, IFNLR1, KCNQ4, KITLG, LMX1A, MCM2, MIRN96, MYH14, MYH9, MYO3A, MYO6, MYO7A, NLRP3, OSBPL2, P2RX2, PDE1C, PLS1, POU4F3, PTPRQ, REST, SCD5, S", "img": null}, {"id": "fc_023_03", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **X-linked**?", "a": "**Causative Gene(s):** `AIFM1, COL4A6, POU3F4, PRPS1` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Characteristics: Generally progressive — N Genes: 5 — Genes: AIFM1, COL4A6, POU3F4, PRPS1, SMPX", "img": null}, {"id": "fc_023_04", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Usher syndrome**?", "a": "**Causative Gene(s):** `CDH23, MYO7A, PCDH15, USH1C, ADGRV1, USH2A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Inher: Autos rec — itance: omal essive — Details: Type I:congenital, prelingual severe to profound hearing loss with vestibular deficit and visual impairment starting in first decade of life Type II:progressive hearing loss with normal vestibular function and visual impairment starting in second decade of life Type III:variable onset prog", "img": null}, {"id": "fc_023_05", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pendred syndrome**?", "a": "**Causative Gene(s):** `FOXI1, KCNJ10, SLC26A4` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Details: Temporal bone anomalies, hearing loss, and thyroid dysfunction/goiter — N Genes: 3 — Gene Names: FOXI1, KCNJ10, SLC26A4", "img": null}, {"id": "fc_023_06", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Jervell and Lange- Nielsen syndrome**?", "a": "**Causative Gene(s):** `KCNE1, KCNQ1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Details: Hearing loss and long QT syndrome — N Genes: 2 — Gene Names: KCNE1, KCNQ1", "img": null}, {"id": "fc_023_07", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Branchiootorenal syndrome (BOR)**?", "a": "**Causative Gene(s):** `EYA1, SIX1, SIX5` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: Autosomal dominant — Details: Branchial cleft anomalies, outer, middle and inner ear structural anomalies, conductive and/or sensorineural hearing loss, structural renal abnormalities — N Genes: 3 — Gene Names: EYA1, SIX1, SIX5", "img": null}, {"id": "fc_023_08", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Stickler syndrome**?", "a": "**Causative Gene(s):** `COL2A1, COL11A1, COL11A2, COL9A1, COL9A2, COL9A3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Details: Connective tissue disease characterized by Robin sequence, arthropathy, mild spondyloepiphyseal dysplasia, retinal detachment or cataracts, sensorineural or mixed hearing loss — N Genes: 6 — Gene Names: Dominant:COL2A1, COL11A1, COL11A2 Recessive:COL9A1, COL9A2, COL9A3", "img": null}, {"id": "fc_023_09", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Treacher-Collins syndrome**?", "a": "**Causative Gene(s):** `TCOF1, POLR1B, POLR1C, POLR1D` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Details: Mandibulofacial dysostosis, microtia, aural meatal atresia, and conductive hearing loss caused by ossicular chain malformations — N Genes: 4 — Gene Names: TCOF1, POLR1B, POLR1C, POLR1D", "img": null}, {"id": "fc_023_10", "ch": 23, "part": "III", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Waardenburg syndrome**?", "a": "**Causative Gene(s):** `PAX3, SNAI2, EDN3, SOX10` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Details: Unilateral or bilateral SNHL, pigmentary anomalies (e.g., white forelock, heterochromia iridis, premature graying, and vitiligo), and craniofacial features (e.g., dystopia canthorum, broad nasal root, and synophrys) — N Genes: 6 — Gene Names: PAX3, MITF, SNAI2, EDNRB, EDN3,and SOX10", "img": null}, {"id": "fc_023_11", "ch": 23, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MYO15A`** are associated with which clinical phenotype and molecular mechanism in **Nonsyndromic Pediatric Hearing Loss**?", "a": "Some forms of genetic hearing loss are rapidly progressive (e.g., MYO15A , ACTG1 ) while others are relatively stable, or progress very slowly, over time (STRC, OTOA) .", "img": null}, {"id": "fc_023_12", "ch": 23, "part": "III", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CHD7`** are associated with which clinical phenotype and molecular mechanism in **CHARGE Syndrome**?", "a": "CHARGE syndrome is now referred to as CHD7 Disorder to better reflect the underlying genetic cause and underscore the variability in phenotype.", "img": null}, {"id": "fc_023_13", "ch": 23, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Usher Syndrome**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Gene therapy for Usher syndrome is an active area of research.", "img": null}, {"id": "fc_023_14", "ch": 23, "part": "III", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Future Directions**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** A better understanding of the underlying pathophysiological mechanisms of childhood hearing loss has resulted in a new push towards gene therapy for hearing loss.", "img": null}, {"id": "fc_023_15", "ch": 23, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Imaging and Other Testing**, how is **congenital CMV** defined and characterized?", "a": "congenital CMV is indicated for any newborn that is diagnosed with permanent hearing loss.", "img": null}, {"id": "fc_023_16", "ch": 23, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Imaging and Other Testing**, how is **Usher syndrome** defined and characterized?", "a": "Usher syndrome , may initially be suspected on physical exam of the retina, especially in slightly older children.", "img": null}, {"id": "fc_023_17", "ch": 23, "part": "III", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **GJB2**, how is **Bart-Humphrey syndrome** defined and characterized?", "a": "Bart-Humphrey syndrome , KID (keratitis ichthyosis deafness) syndrome, and Vohwinkel syndrome .", "img": null}, {"id": "fc_023_18", "ch": 23, "part": "III", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 23.1):", "a": "Diagnostic algorithm for pediatric sensorineural hearing loss.", "img": "fig_p0553_02.jpg"}, {"id": "fc_023_19", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clai ssification of Hearing Loss**, what are the distinguishing features of **Onset**?", "a": "**• Conductive hearing loss, arising from abnormalities of the external ear and/or the ossicles of the middle ear (and rarely from structural abnormalities of the inner ear) • Sensorineural hearing loss, due to malfunction of the inner ear structures arising from abnormalities of the cochlea or auditory nerve • Mixed hearing loss, a combination of conductive and sensorineural hearing loss • Central auditory dysfunction or auditory neuropathy spectrum disorder, from damage or dysfunction at the level of the eighth cranial nerve (auditory nerve), auditory brain stem, or cerebral cortex.**: • Congenital • Prelingual • Postlingual • Adult onset and presbycusis (age-related hearing loss)", "img": null}, {"id": "fc_023_20", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clai ssification of Hearing Loss**, what are the distinguishing features of **Severity**?", "a": "**• Conductive hearing loss, arising from abnormalities of the external ear and/or the ossicles of the middle ear (and rarely from structural abnormalities of the inner ear) • Sensorineural hearing loss, due to malfunction of the inner ear structures arising from abnormalities of the cochlea or auditory nerve • Mixed hearing loss, a combination of conductive and sensorineural hearing loss • Central auditory dysfunction or auditory neuropathy spectrum disorder, from damage or dysfunction at the level of the eighth cranial nerve (auditory nerve), auditory brain stem, or cerebral cortex.**: • Slight: 15–25 dB hearing level (HL) • Mild: 26–40 dB HL • Moderate: 41–60 dB HL • Moderately severe: 61–70 dB HL • Severe: 71–90 dB HL • Profound:>90 dB HL", "img": null}, {"id": "fc_023_21", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clai ssification of Hearing Loss**, what are the distinguishing features of **Laterality**?", "a": "**• Conductive hearing loss, arising from abnormalities of the external ear and/or the ossicles of the middle ear (and rarely from structural abnormalities of the inner ear) • Sensorineural hearing loss, due to malfunction of the inner ear structures arising from abnormalities of the cochlea or auditory nerve • Mixed hearing loss, a combination of conductive and sensorineural hearing loss • Central auditory dysfunction or auditory neuropathy spectrum disorder, from damage or dysfunction at the level of the eighth cranial nerve (auditory nerve), auditory brain stem, or cerebral cortex.**: • Bilateral symmetric • Bilateral asymmetric • Unilateral", "img": null}, {"id": "fc_023_22", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic C auses of Genetic Nonsyn dromic Hea ring Loss**, what are the distinguishing features of **Autosomal recessive**?", "a": "**Characteristics**: Generally prelingual and range from mild-to- moderate to severe to profound; **N Genes**: 76; **Genes**: ADCY1, BDP1, BSND, CABP2, CDC14A, CDH23, CEACAM16, CIB2, CLDN14, CLDN9, CLIC5, COL11A2, DCDC2, ELMOD3, EPS8, EPS8L2, ESPN, ESRP1, ESRRB, FAM65B, GAB1, GIPC3, GJB2, GJB6, GPSM2, GRAP, GRXCR1, GRXCR2, HGF, ILDR1, KARS, LHFPL5, LOXHD1, LRTOMT, MARVELD2, MET, MPZL2, MSRB3, MYO15A, MYO3A, MYO6, MYO7A, NARS2, OTOA, OTOF, OTOG, OTOGL, PCDH15, PDZD7, PJVK, PNPT1, PPIP5K2, PTPRQ, RDX, ROR1, S1PR2, SERPINB6, SLC22A4, SLC26A4, SLC26A5, SPNS2, STRC, SYNE4, TBC1D24, TECTA, TMC1, TMEM132E, TMIE, TMPRSS3, TPRN, TRIOBP, TSPEAR, USH1C, WBP2, WHRN", "img": null}, {"id": "fc_023_23", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic C auses of Genetic Nonsyn dromic Hea ring Loss**, what are the distinguishing features of **Autosomal dominant**?", "a": "**Characteristics**: Generally postlingual and progressive; **N Genes**: 48; **Genes**: ACTG1, CCDC50, CD164, CEACAM16, COCH, COL11A1, COL11A2, CRYM, DIAPH1, DMXL2, EYA4, GJB2, GJB3, GJB6, GRHL2, DFNA5, HOMER2, IFNLR1, KCNQ4, KITLG, LMX1A, MCM2, MIRN96, MYH14, MYH9, MYO3A, MYO6, MYO7A, NLRP3, OSBPL2, P2RX2, PDE1C, PLS1, POU4F3, PTPRQ, REST, SCD5, SIX1, SLC17A8, DIABLO, TBC1D24, TECTA, TJP2, TMC1, TNC, TRRAP, WFS1", "img": null}, {"id": "fc_023_24", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic C auses of Genetic Nonsyn dromic Hea ring Loss**, what are the distinguishing features of **X-linked**?", "a": "**Characteristics**: Generally progressive; **N Genes**: 5; **Genes**: AIFM1, COL4A6, POU3F4, PRPS1, SMPX", "img": null}, {"id": "fc_023_25", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic Causes of Syndro mic Hearing Loss**, what are the distinguishing features of **Autos rec**?", "a": "**itance**: omal essive; **Syndrome**: Usher syndrome; **Details**: Type I:congenital, prelingual severe to profound hearing loss with vestibular deficit and visual impairment starting in first decade of life Type II:progressive hearing loss with normal vestibular function and visual impairment starting in second decade of life Type III:variable onset progressive hearing loss, variable onset visual impairment, with variable vestibular dysfunction; **N Genes**: 9; **Gene Names**: Type I:CDH23, MYO7A, PCDH15, USH1C, SANS Type II:ADGRV1, USH2A, WHRN Type III:CLRN1", "img": null}, {"id": "fc_023_26", "ch": 23, "part": "III", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic Causes of Syndrom ic Hearing Loss—cont’d**, what are the distinguishing features of **Autosomal dominant**?", "a": "**Syndrome**: Branchiootorenal syndrome (BOR); **Details**: Branchial cleft anomalies, outer, middle and inner ear structural anomalies, conductive and/or sensorineural hearing loss, structural renal abnormalities; **N Genes**: 3; **Gene Names**: EYA1, SIX1, SIX5", "img": null}, {"id": "fc_024_01", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pulmonary interstitial glycogenosis (infantile cellular interstitial pneumonia) Surfactant dysfunction disorde**?", "a": "**Causative Gene(s):** `CSF2RA, NKX2, ABCA3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Anti-GBM disease Granulomatosis with polyangiitis Microscopic polyangiitis Idiopathic pulmonary capillaritis Gaucher disease and other storage diseases Malignant infiltrates Hemophagocytic lymphohistiocytosis MAS Langerhans cell histiocytosis Sarcoidosis Systemic sclerosis", "img": null}, {"id": "fc_024_02", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SFTPB**?", "a": "**Causative Gene(s):** `SFTPB` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: Neonatal • Respiratory distress — Age and Onset: Neonate, acute — SP-B is a hydrophobic protein encoded by SFTPB , located on chromosome 2.", "img": null}, {"id": "fc_024_03", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ABCA3**?", "a": "**Causative Gene(s):** `ABCA3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: Neonatal — Age and Onset: Neonate, acute — ABCA3 deficiency is autosomal recessively inherited and is the most common cause of surfactant protein deficiency.", "img": null}, {"id": "fc_024_04", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SFTPC**?", "a": "**Causative Gene(s):** `SFTPC` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: Neonatal — Age and Onset: Neonate, acute — Surfactantrelated genes implicated in congenital PAP include SFTPB , SFTPC , ABCA3 , and NKX2-1 ; additional genes associated with congenital PAP include SLC7A7 , which is associated with lysinuric protein intolerance (see Chapters 26 and 43).", "img": null}, {"id": "fc_024_05", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NKX2.1**?", "a": "**Causative Gene(s):** `NKX2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: Respiratory — Age and Onset: Any age — NKX2-1 is located on chromosome 14 and encodes thyroid transcription factor 1, which plays a critical role in thyroid and lung development, and which is also expressed in the basal ganglia.", "img": null}, {"id": "fc_024_06", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Thyroxine, thyroid-stimulating hormone**?", "a": "**Causative Gene(s):** `NKX2-1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Surfactant disorder(NKX2-1) — NKX2-1 is located on chromosome 14 and encodes thyroid transcription factor 1, which plays a critical role in thyroid and lung development, and which is also expressed in the basal ganglia.", "img": null}, {"id": "fc_024_07", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Scleroderma, polymyositis, and myositis antibodies (KU, PM-Scl75, TIF1γ, MDA-5, PM-Scl100, Ml2, KJ; antisynthe**?", "a": "**Causative Gene(s):** `PL7, PL12, JO1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Indicates: Muscular, esophageal, and/or cutaneous involvement", "img": null}, {"id": "fc_024_08", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GR and AR**?", "a": "**Causative Gene(s):** `CSF2RA, CSF2RB` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** CSF2RA, CSF2RB — Phenotypes: PAP (infants, children, adults) — Genes encoding GM-CSF receptor subunits and implicated in congenital PAP include CSF2RA and CSF2RB .", "img": null}, {"id": "fc_024_09", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GA and GD**?", "a": "**Causative Gene(s):** `FLNA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Phenotypes: chILD with emphysema; cardiac abnormalities, neurologic impairment; girls>boys", "img": null}, {"id": "fc_024_10", "ch": 24, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AD and AR**?", "a": "**Causative Gene(s):** `TBX4, FGFR2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** TBX4, FGFR2 — Phenotypes: chILD with PH; acinar dysplasia — AcDys and CAD is more complex and includes pathogenic variants in TBX4 , FGF10 , and FGFR2 .", "img": null}, {"id": "fc_024_11", "ch": 24, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ABCA3`** are associated with which clinical phenotype and molecular mechanism in **The Pediatric Interstitial Lung Disease in Children Under 2 Years of Age**?", "a": "Chest wall deformities such as pectus excavatum are often present in individuals with pleuro-parenchymal pulmonary fibroelastosis (PPFE) , a rare form of pulmonary fibrosis that is mostly restricted to the upper lobes and disorders related to pathogenic variants in ABCA3 .", "img": null}, {"id": "fc_024_12", "ch": 24, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STRA6`** are associated with which clinical phenotype and molecular mechanism in **Diffuse Developmental Disorders**?", "a": "De novo or inherited autosomal dominant pathogenic variants in FOXF1 are responsible for ACDMPV; rare cases have been described associated with homozygous autosomal recessive pathogenic variants in STRA6 .", "img": null}, {"id": "fc_024_13", "ch": 24, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FGFR2`** are associated with which clinical phenotype and molecular mechanism in **Diffuse Developmental Disorders**?", "a": "AcDys and CAD is more complex and includes pathogenic variants in TBX4 , FGF10 , and FGFR2 .", "img": null}, {"id": "fc_024_14", "ch": 24, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SFTPB`** are associated with which clinical phenotype and molecular mechanism in **Surfactant Protein B Deficiency**?", "a": "SP-B is a hydrophobic protein encoded by SFTPB , located on chromosome 2.", "img": null}, {"id": "fc_024_15", "ch": 24, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SFTPA2`** are associated with which clinical phenotype and molecular mechanism in **Surfactant Protein A Deficiency**?", "a": "SP-A is encoded by 2 genes on chromosome 10 ( SFTPA1 and SFTPA2 ).", "img": null}, {"id": "fc_024_16", "ch": 24, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NKX2`** are associated with which clinical phenotype and molecular mechanism in **NKX2-1 Deficiency**?", "a": "NKX2-1 is located on chromosome 14 and encodes thyroid transcription factor 1, which plays a critical role in thyroid and lung development, and which is also expressed in the basal ganglia.", "img": null}, {"id": "fc_024_17", "ch": 24, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Treatment of Surfactant Protein Deficiencies**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Active areas of investigation include targeted gene therapy and stem cell therapy.", "img": null}, {"id": "fc_024_18", "ch": 24, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Additional Syndromes**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** SAVI syndrome, COPA syndrome, and STAT gain-offunction disease can be treated with JAK inhibitors; CTLA-4 pathway defects can be treated with the immunomodulator abatacept.", "img": null}, {"id": "fc_024_19", "ch": 24, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Pulmonary Alveolar Proteinosis**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** The treatment of choice is generally whole lung lavage, which eliminates the proteinaceous material through instillation of saline into the lung.", "img": null}, {"id": "fc_024_20", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Pediatric Interstitial Lung Disease in Children Under 2 Years of Age**, how is **pleuro-parenchymal pulmonary fibroelastosis (PPFE)** defined and characterized?", "a": "pleuro-parenchymal pulmonary fibroelastosis (PPFE) , a rare form of pulmonary fibrosis that is mostly restricted to the upper lobes and disorders related to pathogenic variants in ABCA3 .", "img": null}, {"id": "fc_024_21", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis**, how is **neuroendocrine cell hyperplasia of infancy (NEHI)** defined and characterized?", "a": "neuroendocrine cell hyperplasia of infancy (NEHI) , with ground-glass opacities restricted almost entirely to the middle lobes (Figs.", "img": null}, {"id": "fc_024_22", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis**, how is **pulmonary alveolar proteinosis** defined and characterized?", "a": "pulmonary alveolar proteinosis (ground-glass opacities with smooth thickening of interlobular and intralobular septal lines, termed the crazy-paving pattern and depicted in Figures 24.", "img": null}, {"id": "fc_024_23", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis**, how is **pulmonary alveolar microlithiasis** defined and characterized?", "a": "pulmonary alveolar microlithiasis (diffuse ground-glass attenuation and multiple subpleural linear calcifications as depicted in Fig.", "img": null}, {"id": "fc_024_24", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis**, how is **acute hypersensitivity pneumonitis** defined and characterized?", "a": "acute hypersensitivity pneumonitis (upper lung predominant pulmonary changes including groundglass opacities, poorly defined centrilobular nodules, and areas of decreased attenuation representing air trapping, depicted in Figs.", "img": null}, {"id": "fc_024_25", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diffuse Developmental Disorders**, how is **acinar dysplasia (AcDys)** defined and characterized?", "a": "acinar dysplasia (AcDys) , congenital alveolar dysplasia ( CAD ; Fig.", "img": null}, {"id": "fc_024_26", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Surfactant Protein C Deficiency**, how is **Surfactant protein C deficiency** defined and characterized?", "a": "Surfactant protein C deficiency is autosomal dominantly inherited or caused by a de novo pathogenic variant.", "img": null}, {"id": "fc_024_27", "ch": 24, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Surfactant Protein A Deficiency**, how is **surfactant protein A deficiency** defined and characterized?", "a": "surfactant protein A deficiency have been associated with pulmonary fibrosis and pulmonary adenocarcinoma in adults.", "img": null}, {"id": "fc_024_28", "ch": 24, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 24.1):", "a": "Investigations in childhood interstitial lung disease (chILD) diagnostic workup. (A) The investigations are performed one after the other to reach a chILD etiology. The first step is usually done by the general pediatrician (framed in red) , and includes family history, clinical evaluation, chest radiography, and routine laboratory tests. (B) Age at onset is crucial information that helps to consider some etiologies more than others. (C) Bronchoalveolar lavage (BAL) eliminates infectious causes of ILD and provides clues to the most likely diagnoses. (D) When thoracic computed tomography (CT) scan, specific blood tests, BAL, and genetic analyses could not assess a diagnosis, lung biopsy is the last step of the diagnostic process, allowing to assess the most likely diagnoses in most cases. AEC2, Type 2 alveolar epithelial cells; DAH, diffuse alveolar hemorrhage; HSP, hypersensitivity pneumonitis; LIP, lymphoid interstitial pneumonia; NEHI, neuroendocrine cell hyperplasia of infancy; NSIP, nonspecific interstitial pneumonia; OB, obliterans bronchiolitis; PAP, pulmonary alveolar proteinosis; PAS, Periodic acid–Schiff.", "img": "fig_p0564_02.jpg"}, {"id": "fc_025_01", "ch": 25, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TEM: Class 1 outer dynein arm defect HSVM: Mostly static IF: Absent or misallocated DNAH5 TEM: Normal HSVM: Re**?", "a": "**Causative Gene(s):** `DNAH5, DNAI1, DNAI2, DNAL1, NME8, CCDC114` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** DNAH5, DNAI1, DNAI2, DNAL1, NME8, CCDC114, ARMC4, CCDC151, TTC25 DNAH11 DNAH9* — In fact, more than 6% of patients with PCD have heterotaxy , which can be associated with complex cardiac defects, and in a large study, more than 50% of the patients with heterotaxy had pathogenic gene variants in DNAI1 and DNAH5 .", "img": null}, {"id": "fc_025_02", "ch": 25, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TEM: Outer and inner dynein arm defect HSVM: Immotile IF: Absent DNAH5 and DNALI1**?", "a": "**Causative Gene(s):** `DNAAF1, LRRC50, DNAAF2, DNAAF3, DNAAF4, DYX1C1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** DNAAF1 (LRRC50), DNAAF2 (KTU), DNAAF3 (C19ORF51), DNAAF4 (DYX1C1), DNAAF5 (HEATR2), LRRC6, ZMYND10, SPAG1, CFAP298 (C21ORF59), DNAAF6 (PIH1D3), CFAP300 (C11ORF70)", "img": null}, {"id": "fc_025_03", "ch": 25, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TEM: Class 2 central complex defect HSVM: Rotational IF: Absent RSPH9 IF: Absent SPEF2**?", "a": "**Causative Gene(s):** `RSPH9, RSPH4A, RSPH1, SPEF2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** RSPH9, RSPH4A, RSPH1 HYDIN, SPEF2 — Abnormalities in the RSPH1 gene seem to result in milder lung disease, while more severe respiratory outcomes are noted in individuals with genetic variants of genes CCDC39 or CCDC40 .", "img": null}, {"id": "fc_025_04", "ch": 25, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TEM: Class 1 microtubular disorganization and inner dynein arm defect HSVM: Reduced bending IF: Absent GAS8 an**?", "a": "**Causative Gene(s):** `CCDC39, CCDC40, CCDC65, DRC2, DRC1, CCDC164` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** CCDC39, CCDC40 CCDC65 (DRC2), DRC1 (CCDC164), GAS8 (DRC4) — Abnormalities in the RSPH1 gene seem to result in milder lung disease, while more severe respiratory outcomes are noted in individuals with genetic variants of genes CCDC39 or CCDC40 .", "img": null}, {"id": "fc_025_05", "ch": 25, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TEM: Class 2 reduction of multiple motile cilia and mislocalization of basal bodies HSVM & IF: Reduction of mu**?", "a": "**Causative Gene(s):** `FOXJ1, NEK10` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** CCNO, MCIDAS, FOXJ1,NEK10", "img": null}, {"id": "fc_025_06", "ch": 25, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pathophysiology**?", "a": "**Causative Gene(s):** `CCDC39` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormalities in the RSPH1 gene seem to result in milder lung disease, while more severe respiratory outcomes are noted in individuals with genetic variants of genes CCDC39 or CCDC40 .", "img": null}, {"id": "fc_025_07", "ch": 25, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Transmission Electron Microscopy**?", "a": "**Causative Gene(s):** `CP` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** This can lead to the diagnosis of defects in the ciliary ultrastructure, such as outer dynein arm (ODA) defects, inner dynein arm (IDA) defects, or defects within the central pairs (CP).", "img": null}, {"id": "fc_025_08", "ch": 25, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CCDC39`** are associated with which clinical phenotype and molecular mechanism in **Pathophysiology**?", "a": "Abnormalities in the RSPH1 gene seem to result in milder lung disease, while more severe respiratory outcomes are noted in individuals with genetic variants of genes CCDC39 or CCDC40 .", "img": null}, {"id": "fc_025_09", "ch": 25, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`DNAH5`** are associated with which clinical phenotype and molecular mechanism in **Pathophysiology**?", "a": "In fact, more than 6% of patients with PCD have heterotaxy , which can be associated with complex cardiac defects, and in a large study, more than 50% of the patients with heterotaxy had pathogenic gene variants in DNAI1 and DNAH5 .", "img": null}, {"id": "fc_025_10", "ch": 25, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CP`** are associated with which clinical phenotype and molecular mechanism in **Transmission Electron Microscopy**?", "a": "This can lead to the diagnosis of defects in the ciliary ultrastructure, such as outer dynein arm (ODA) defects, inner dynein arm (IDA) defects, or defects within the central pairs (CP).", "img": null}, {"id": "fc_025_11", "ch": 25, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Airway Clearance Therapy (ACT)**?", "a": "**Therapy / Intervention:** Airway Clearance Therapy (ACT)\n\n**Clinical Context:**", "img": null}, {"id": "fc_025_12", "ch": 25, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Chest Physiotherapy**?", "a": "**Therapy / Intervention:** Chest Physiotherapy\n\n**Clinical Context:**", "img": null}, {"id": "fc_025_13", "ch": 25, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Extrapulmonary percussion (CPT, VEST) • Intrapulmonary percussion (PEP, OPEP)**?", "a": "**Therapy / Intervention:** • Extrapulmonary percussion (CPT, VEST) • Intrapulmonary percussion (PEP, OPEP)\n\n**Clinical Context:** Standard of Care: √ √", "img": null}, {"id": "fc_025_14", "ch": 25, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Cough Augmentation ll**?", "a": "**Therapy / Intervention:** Cough Augmentation ll\n\n**Clinical Context:**", "img": null}, {"id": "fc_025_15", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Pathophysiology**, how is **Kartagener disease** defined and characterized?", "a": "Kartagener disease , it was long thought that congenital cardiac defects were uncommon in PCD.", "img": null}, {"id": "fc_025_16", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Pathophysiology**, how is **heterotaxy** defined and characterized?", "a": "heterotaxy , which can be associated with complex cardiac defects, and in a large study, more than 50% of the patients with heterotaxy had pathogenic gene variants in DNAI1 and DNAH5 .", "img": null}, {"id": "fc_025_17", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Pathophysiology**, how is **male infertility** defined and characterized?", "a": "male infertility , which is common in PCD, may be a result of more than just poorly motile sperm.", "img": null}, {"id": "fc_025_18", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **four hallmark clinical criteria** defined and characterized?", "a": "four hallmark clinical criteria for PCD are (1) unexplained neonatal respiratory distress in term infants, (2) early-onset moist cough which is present year-round, (3) early-onset chronic nasal congestion, and (4) laterality defects.", "img": null}, {"id": "fc_025_19", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Unexplained neonatal respiratory distress** defined and characterized?", "a": "Unexplained neonatal respiratory distress , especially in term infants or lasting longer than 5 days, is a common manifestation of PCD, and is present in 80% of children with PCD.", "img": null}, {"id": "fc_025_20", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Nasal symptoms** defined and characterized?", "a": "Nasal symptoms may also be present from birth or arise within the first 6 months of life.", "img": null}, {"id": "fc_025_21", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Chronic wet cough** defined and characterized?", "a": "Chronic wet cough and history of frequent lower respiratory tract infections (LRTI) are classically present.", "img": null}, {"id": "fc_025_22", "ch": 25, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **bronchiectasis** defined and characterized?", "a": "bronchiectasis , which is best visualized on chest computed tomography (CT).", "img": null}, {"id": "fc_025_23", "ch": 25, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 25.2):", "a": "Mechanisms of respiratory disease in primary ciliary dyskinesia (PCD). The figure depicts", "img": "fig_p0587_02.jpg"}, {"id": "fc_025_24", "ch": 25, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 25.3):", "a": "Diagnostic algorithm for evaluating patients with suspected primary ciliary dyskinesia. CF,", "img": "fig_p0588_01.jpg"}, {"id": "fc_025_25", "ch": 25, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Primary Ciliary Dyskinesia Genes and Associatio n With Diagnostic Phenotype**, what are the distinguishing features of **Genes Coding for Structural Proteins in the Outer Dynei**?", "a": "**Diagnostic Test Results**: n Arm", "img": null}, {"id": "fc_025_26", "ch": 25, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Primary Ciliary Dyskinesia Genes and Associatio n With Diagnostic Phenotype**, what are the distinguishing features of **DNAH5, DNAI1, DNAI2, DNAL1, NME8, CCDC114, ARMC4, CCDC151, TTC25 DNAH11 DNAH9**?", "a": "**Diagnostic Test Results**: TEM: Class 1 outer dynein arm defect HSVM: Mostly static IF: Absent or misallocated DNAH5 TEM: Normal HSVM: Reduced amplitude and hyperfrequent IF: Absent DNAH11 TEM: Partial outer dynein arm defect HSVM: Subtle beat pattern defect IF: DNAH9 absent", "img": null}, {"id": "fc_025_27", "ch": 25, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Maintenance Tre Schedule atment and Prophylaxis**, what are the distinguishing features of **ACT combination of: • Chest physiotherapy**?", "a": "• Everyday asymptomatic baseline×2/day", "img": null}, {"id": "fc_025_28", "ch": 25, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Maintenance Tre Schedule atment and Prophylaxis**, what are the distinguishing features of **Mucociliary clearance agents**?", "a": "• Symptomatic respiratory exacerbations×4/day", "img": null}, {"id": "fc_026_01", "ch": 26, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Gene**?", "a": "**Causative Gene(s):** `SFTPB, ABCA3, SFTPC, NKX2, CSF2RA, CSF2RB` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** SP-B Deficiency SMDP1: SFTPB — ABCA3 Deficiency SMDP3: ABCA3 — SP-C Dysfunction SMDP2: SFTPC — NKX2–1 — Hereditary PAP SMDP4: CSF2RA — Hereditary PAP SMDP5: CSF2RB", "img": null}, {"id": "fc_026_02", "ch": 26, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pathology features**?", "a": "**Causative Gene(s):** `AEC2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** SP-B Deficiency SMDP1: AEC2 hyperplasia Mesenchymal thickening Proteinaceous material and macrophages in distal air spaces — ABCA3 Deficiency SMDP3: AEC2 hyperplasia Mesenchymal thickening Proteinaceous material and macrophages in distal air spaces — SP-C Dysfunction SMDP2: AEC2 hyperplasia Mesenchymal thickening Proteinaceous material an", "img": null}, {"id": "fc_026_03", "ch": 26, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pathogenesis**?", "a": "**Causative Gene(s):** `AEC2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** SP-B Deficiency SMDP1: Loss-of-function Impaired processing of proSP-C Abnormal lamellar bodies — ABCA3 Deficiency SMDP3: Loss-of-function Surfactant deficiency AEC2 injury Abnormal lamellar bodies — SP-C Dysfunction SMDP2: Toxic gain-of-function Dominant negative ER stress and activation of UPR Impaired autophagy — Haploinsufficiency Alt", "img": null}, {"id": "fc_026_04", "ch": 26, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **OAS1**?", "a": "**Causative Gene(s):** `SLC7A7, MARS1, OAS1, GATA2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** SLC7A7 — MARS1 — FARSA — FARSB — GATA2 — A well-described association with PAP includes pathogenic variants in GATA2 .", "img": null}, {"id": "fc_026_05", "ch": 26, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Proteinaceous material in alveolar space Small and nonfoamy alveolar macrophages**?", "a": "**Causative Gene(s):** `AEC2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** AEC2 hyperplasia, proteinaceous material in distal air spaces Septal thickening Chronic inflammation Cholesterol granulomas Enlarged foamy, lipid-laden alveolar macrophages Fibrosis — Proteinaceous material Cholesterol clefts Giant cell granulomas Interstitial fibrosis and inflammation — Emphysematous foci Chronic inflammation with lympho", "img": null}, {"id": "fc_026_06", "ch": 26, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Interferon-induced hyperinflammatory response of macrophages and B cells Macrophage dysfunction**?", "a": "**Causative Gene(s):** `GATA2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormal arginine transport Alveolar macrophage dysfunction — Abnormal ligation of methionine to transfer RNA Abnormal protein biosynthesis — Unknown, likely related to tissue specific impaired protein synthesis — Unknown, likely related to tissue specific impaired protein synthesis — GATA2 regulates the phagocytosis of alveolar macrophag", "img": null}, {"id": "fc_026_07", "ch": 26, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ABCA3`** are associated with which clinical phenotype and molecular mechanism in **Primary PAP—Autoimmune**?", "a": "SPB and SP-C are trafficked from the endoplasmic reticulum (ER) to lamellar bodies via the Golgi complex and multivesicular body (MVB); in contrast, surfactant phospholipids are likely directly transported from the ER to specific lipid importers (ABCA3) in the lamellar body–limiting membrane.", "img": null}, {"id": "fc_026_08", "ch": 26, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NKX2`** are associated with which clinical phenotype and molecular mechanism in **Primary PAP—Autoimmune**?", "a": "NKX2-1, FOXA2, SREBP, and CEBPα are transcription factors regulating surfactant protein and lipid synthesis.", "img": null}, {"id": "fc_026_09", "ch": 26, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CSFR2B`** are associated with which clinical phenotype and molecular mechanism in **Primary PAP—Hereditary**?", "a": "CSFR2B , which result in a similar phenotype of impaired GM-CSF function (Tables 26.1 and 26.2).", "img": null}, {"id": "fc_026_10", "ch": 26, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GATA2`** are associated with which clinical phenotype and molecular mechanism in **Secondary PAP**?", "a": "A well-described association with PAP includes pathogenic variants in GATA2 .", "img": null}, {"id": "fc_026_11", "ch": 26, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CSF2RA`** are associated with which clinical phenotype and molecular mechanism in **Disorders Associated With Secondary PAP**?", "a": "In a review of CSF2RA cases, there was a female predominance; high rates of consanguinity are noted in term children with hereditary PAP.", "img": null}, {"id": "fc_026_12", "ch": 26, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CSF2RB`** are associated with which clinical phenotype and molecular mechanism in **Laboratory Markers**?", "a": "If an underlying causative condition cannot be found, patients should undergo a blood-based GM-CSF signaling test and serum GM-CSF levels test; high concentrations of serum GM-CSF and no or reduced GM-CSF signaling should prompt further tests for CSF2RA and CSF2RB, pathogenic variants to identify hereditary PAP.", "img": null}, {"id": "fc_026_13", "ch": 26, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Management**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Gene therapy approaches for treatment of hereditary PAP are currently being investigated.", "img": null}, {"id": "fc_026_14", "ch": 26, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Presentation**, how is **Primary autoimmune PAP** defined and characterized?", "a": "Primary autoimmune PAP is more commonly described in older adolescents and adults; it has been reported in children as young as 3 years of age.", "img": null}, {"id": "fc_026_15", "ch": 26, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Presentation**, how is **primary hereditary PAP** defined and characterized?", "a": "primary hereditary PAP are not well established, given its rarity.", "img": null}, {"id": "fc_026_16", "ch": 26, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 26.1):", "a": "Biosynthesis of surfactant involves distinct pathways for surfactant proteins and lipids. SPB and SP-C are trafficked from the endoplasmic reticulum (ER) to lamellar bodies via the Golgi complex and multivesicular body (MVB); in contrast, surfactant phospholipids are likely directly transported from the ER to specific lipid importers (ABCA3) in the lamellar body–limiting membrane. Surfactant proteins and lipids are assembled into bilayer membranes that are secreted into the alveolar airspace, where they form a surface film at the air–liquid interface. Cyclical expansion and compression of the bioactive film results in the incorporation and loss of lipids and proteins from the multilayered surface film. Surfactant components removed from the film are degraded in alveolar macrophages or are taken up by type II epithelial cells for recycling or degradation in the lysosome. The MVB plays a key part in the integration of pathways for surfactant synthesis, recycling, and degradation. NKX2-1, FOXA2, SREBP, and CEBPα are transcription factors regulating surfactant protein and lipid synthesis. SLC34a2 is a phosphate transporter. Gpr116 is a membrane receptor regulating surfactant secretion. ABCA3, ATP-binding cassette transporter A3; GM-CSF, granulocyte-macrophage colony-stimulating factor; PC, phosphatidylcholine; PG, phosphatidylglycerol; SP, surfactant proteins. (From Polin RA, Abman SH, Rowitch DH, Benits WE, eds. Fetal and Neonatal Physiology . 6th ed", "img": "fig_p0600_01.jpg"}, {"id": "fc_026_17", "ch": 26, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 26.2):", "a": "PAP pathogenesis. In normal surfactant homeostasis (bottom right), surfactant is synthesized by type II alveolar epithelial cells and secreted into the alveolar space to generate a thin layer. GM-CSF is a cytokine produced by type II alveolar epithelial cells that binds specific receptors on macrophages; GM-CSF induces the terminal differentiation of alveolar macrophages, allowing an effective surfactant catabolism. In primary PAP (bottom left), altered macrophage activation, due to a dysfunction in GM-CSF signaling, leads to impaired surfactant clearance and to the consequent accumulation of surfactant. In autoimmune PAP, GM-CSF signaling is inhibited by the presence of neutralizing GM-CSF autoantibodies; the hereditary form is the result of pathogenic variants involving the GM-CSF receptor. In secondary PAP (top left), various underlying conditions can affect the number and/or the function of the alveolar macrophages, causing reduced surfactant clearance and surfactant accumulation within the alveoli. In congenital PAP (top right), pathogenic variants in SFTPB, SFTPC, ABCA3, and TTF1 interfere with the production of surfactant which, in turn, is ineffective and prone to accumulation. (From Salvaterra E, Campo I. Pulmonary alveolar proteinosis: from classification to therapy. Breathe (Sheff). 2020;16[2]:200018. [Fig.1].)", "img": "fig_p0601_02.jpg"}, {"id": "fc_026_18", "ch": 26, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 26.3):", "a": "Algorithm for the differential diagnosis of PAP. The presence of pulmonary alveolar proteinosis (PAP) is suspected on the basis of a compatible history, typical radiological findings, and bronchoalveolar lavage cytology findings. A granulocyte-macrophage colony-stimulating factor (GM-CSF) autoantibody test should be performed first: a positive test confirms the diagnosis of autoimmune PAP. Patients with a negative GM-CSF autoantibody test who have a disease known to cause PAP are diagnosed with secondary PAP. If an underlying causative condition cannot be found, patients should undergo a blood-based GM-CSF signaling test and serum GM-CSF levels test; high concentrations of serum GM-CSF and no or reduced GM-CSF signaling should prompt further tests for CSF2RA and CSF2RB, pathogenic variants to identify hereditary PAP. Patients with physiological levels of serum GM-CSF and GM-CSF signaling should undergo further tests for other gene pathogenic variants to diagnose congenital PAP. If no PAP-causing variant can be found, the patient is diagnosed with unclassified PAP and a transbronchial or surgical lung biopsy for lung parenchymal histopathological examination may be needed to confirm diagnosis. This diagnostic algorithm reflects an ideal setting in which physicians have unrestricted access to the appropriate diagnostic tools and tests. (From Trapnell BC, Nakata K, Bonella F, et al. Pulmonary alveolar proteinosis. _Nat Rev", "img": "fig_p0607_02.jpg"}, {"id": "fc_026_19", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Feature s of Hereditary Disorders of Surfactant Prod uction and Clearance i**, what are the distinguishing features of **Epidemiology**?", "a": "**SP-B Deficiency SMDP1**: Extremely rare, 1 in 5–10 million; **ABCA3 Deficiency SMDP3**: Rare; incidence estimate 1 in 90,000; **SP-C Dysfunction SMDP2**: Rare; incidence and prevalence unknown; **TTF-1 Haplo-Insufficiency Brain-Thyroid-Lung**: Rare; incidence and prevalence unknown; **Hereditary PAP SMDP4**: Very rare; incidence and prevalence unknown; **Hereditary PAP SMDP5**: Very rare; incidence and prevalence unknown", "img": null}, {"id": "fc_026_20", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Feature s of Hereditary Disorders of Surfactant Prod uction and Clearance i**, what are the distinguishing features of **Gene**?", "a": "**SP-B Deficiency SMDP1**: SFTPB; **ABCA3 Deficiency SMDP3**: ABCA3; **SP-C Dysfunction SMDP2**: SFTPC; **TTF-1 Haplo-Insufficiency Brain-Thyroid-Lung**: NKX2–1; **Hereditary PAP SMDP4**: CSF2RA; **Hereditary PAP SMDP5**: CSF2RB", "img": null}, {"id": "fc_026_21", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Feature s of Hereditary Disorders of Surfactant Prod uction and Clearance i**, what are the distinguishing features of **Chromosomal location**?", "a": "**SP-B Deficiency SMDP1**: 2p11.2; **ABCA3 Deficiency SMDP3**: 16p13.3; **SP-C Dysfunction SMDP2**: 8p21.3; **TTF-1 Haplo-Insufficiency Brain-Thyroid-Lung**: 14q13.3; **Hereditary PAP SMDP4**: Xp22.33; Yp11.2; **Hereditary PAP SMDP5**: 22q12.3", "img": null}, {"id": "fc_026_22", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **##### 26.1 #### Features of Hereditary Disorders of Surfactant Production and Clearance—cont’d**, what are the distinguishing features of **Diagnosis**?", "a": "**SP-B Deficiency SMDP1**: Genetic testing (NGS) panel most efficient; **ABCA3 Deficiency SMDP3**: Genetic testing (NGS) panel most efficient; **SP-C Dysfunction SMDP2**: Genetic testing (NGS) panel most efficient; **TTF-1 Haplo-Insufficiency Brain-Thyroid-Lung**: Genetic testing (NGS) panel most efficient; **Hereditary PAP SMDP4**: Genetic testing Serum GM-CSF level elevated; **Hereditary PAP SMDP5**: Genetic testing Serum GM-CSF level elevated", "img": null}, {"id": "fc_026_23", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### 26.2 Features of Hereditary Disorders of Surfactant Productions and Clearance**, what are the distinguishing features of **Epidemiology**?", "a": "**Lysinuric Protein Intolerance**: Very rare;~1/60,000 live births in Japan and Finland due to founder effect; **Methionyl-tRNA Synthetase Deficiency**: Very rare; incidence and prevalence unknown; **Phenylalanine t-RNA Synthetase, Alpha Subunit Deficiency**: Very rare; incidence and prevalence unknown; **Phenylalanine t-RNA Synthetase, Beta Subunit Deficiency**: Very rare; incidence and prevalence unknown; **2′-5′-Oligoadenylate Synthetase 1 Associated Lung Disease**: Very rare; incidence and prevalence unknown; **GATA Binding Protein 2 Associated Lung Disease**: Very rare; incidence and prevalence unknown", "img": null}, {"id": "fc_026_24", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### 26.2 Features of Hereditary Disorders of Surfactant Productions and Clearance**, what are the distinguishing features of **Gene**?", "a": "**Lysinuric Protein Intolerance**: SLC7A7; **Methionyl-tRNA Synthetase Deficiency**: MARS1; **Phenylalanine t-RNA Synthetase, Alpha Subunit Deficiency**: FARSA; **Phenylalanine t-RNA Synthetase, Beta Subunit Deficiency**: FARSB; **2′-5′-Oligoadenylate Synthetase 1 Associated Lung Disease**: OAS1; **GATA Binding Protein 2 Associated Lung Disease**: GATA2", "img": null}, {"id": "fc_026_25", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### 26.2 Features of Hereditary Disorders of Surfactant Productions and Clearance**, what are the distinguishing features of **Chromosomal location**?", "a": "**Lysinuric Protein Intolerance**: 14q11.2; **Methionyl-tRNA Synthetase Deficiency**: 12q13.3; **Phenylalanine t-RNA Synthetase, Alpha Subunit Deficiency**: 19p13.13; **Phenylalanine t-RNA Synthetase, Beta Subunit Deficiency**: 2p36.1; **2′-5′-Oligoadenylate Synthetase 1 Associated Lung Disease**: 12q24.13; **GATA Binding Protein 2 Associated Lung Disease**: 3q21.3", "img": null}, {"id": "fc_026_26", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **##### 26.2 #### Features of Hereditary Disorders of Surfactant Productions and Clearance —cont’d**, what are the distinguishing features of **Clinical features**?", "a": "**Lysinuric Protein Intolerance**: Pulmonary alveolar proteinosis Developmental delay Hepatosplenomegaly Osteoporosis Anemia Glomerulonephritis Protein aversion Hemophagocytic lymphohistiocytosis; **Methionyl-tRNA Synthetase Deficiency**: Pulmonary alveolar proteinosis Liver dysfunction Anemia Failure to thrive; **Phenylalanine t-RNA Synthetase, Alpha Subunit Deficiency**: chILD Growth failure Liver dysfunction Brain calcifications Hypotonia; **Phenylalanine t-RNA Synthetase, Beta Subunit Deficiency**: Pulmonary alveolar proteinosis child Growth failure Liver dysfunction Intracranial aneurysms Brain calcifications Hypotonia; **2′-5′-Oligoadenylate Synthetase 1 Associated Lung Disease**: Pulmonary alveolar proteinosis Hypogammaglobulinemia Frequent respiratory infections Failure to thrive Recurrent fevers Ulcerative dermatitis Inflammatory bowel disease; **GATA Binding Protein 2 Associated Lung Disease**: Pulmonary alveolar proteinosis Hematological disorders (chronic myeloid leukemia) Anemia Myelodysplastic syndrome", "img": null}, {"id": "fc_026_27", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **##### 26.2 #### Features of Hereditary Disorders of Surfactant Productions and Clearance —cont’d**, what are the distinguishing features of **Diagnosis**?", "a": "**Lysinuric Protein Intolerance**: Genetic testing (NGS) panel most efficient, plasma amino acids, 24-h urine excretion of cationic amino acids; **Methionyl-tRNA Synthetase Deficiency**: Genetic testing (NGS) panel, ES, GS; **Phenylalanine t-RNA Synthetase, Alpha Subunit Deficiency**: Genetic testing (NGS) panel, ES, GS; **Phenylalanine t-RNA Synthetase, Beta Subunit Deficiency**: Genetic testing (NGS) panel, ES, GS; **2′-5′-Oligoadenylate Synthetase 1 Associated Lung Disease**: Genetic testing (NGS) panel, ES, GS; **GATA Binding Protein 2 Associated Lung Disease**: Genetic testing, ES, GS", "img": null}, {"id": "fc_026_28", "ch": 26, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Disorders Associated With Secondary PAP**, what are the distinguishing features of **Pneumocystis jirovecii i**?", "a": "**Hematological Malignancies and Myelodysplastic Syndromes**: Leukemia/Lymphoma", "img": null}, {"id": "fc_027_01", "ch": 27, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Neural crest tumors**?", "a": "**Causative Gene(s):** `PHOX2B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** ROHHAD: Yes (in 40–50% of cases) — CCHS: Yes (in 40–50% of patients with PHOX2B NPARMs and <5% of patients with longest PARMs) — LO-CCHS: No — PWS: No", "img": null}, {"id": "fc_027_02", "ch": 27, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Comprehensive metabolic profile, urine osmolarity, serum or plasma prolactin, FT4, TSH, IGF factor binding pro**?", "a": "**Causative Gene(s):** `FT4` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** TestingF CCHS: Once, then as needed — requency ROHHAD: At first consideration of ROHHAD diagnosis*, then every 2–3 months during the first 3 years, then every 4–6 months for next 3 years, then every 6 months", "img": null}, {"id": "fc_027_03", "ch": 27, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PHOX2B: The Disease Defining Gene for CCHS**?", "a": "**Causative Gene(s):** `PHOX2B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Heterozygous variants of the coding region of the PHOX2B gene are responsible for CCHS.", "img": null}, {"id": "fc_027_04", "ch": 27, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Inheritance of CCHS, PHOX2B Variants, and PHOX2B Mosaicism**?", "a": "**Causative Gene(s):** `PHOX2B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** For 5–25% of known patients, the variant has been inherited from an unaffected parent, who is typically mosaic or a full carrier with incomplete penetrance of a PHOX2B variant.", "img": null}, {"id": "fc_027_05", "ch": 27, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Molecular Genetic PHOX2B Testing Approach**?", "a": "**Causative Gene(s):** `PHOX2B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Molecular genetic testing is the standard approach to identify variants in PHOX2B for CCHS diagnosis (Fig. 27.6A).", "img": null}, {"id": "fc_027_06", "ch": 27, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CCHS**?", "a": "**Causative Gene(s):** `PHOX2B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Because of small cohorts and varied methods of data collected, the association between CCHS PHOX2B genotypes and cognitive outcomes in school-aged children is inconsistent.", "img": null}, {"id": "fc_027_07", "ch": 27, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PHOX2B`** are associated with which clinical phenotype and molecular mechanism in **PHOX2B: The Disease Defining Gene for CCHS**?", "a": "Heterozygous variants of the coding region of the PHOX2B gene are responsible for CCHS.", "img": null}, {"id": "fc_027_08", "ch": 27, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Findings Suggestive of ROHHAD**, how is **Neural crest tumors** defined and characterized?", "a": "Neural crest tumors (ganglioneuroma, ganglioneuroblastoma, neuroblastoma) in the chest or adrenals may provide an early clue of ROHHAD in 40–50% of patients; in most cases, the tumor is discovered with serial imaging after the diagnosis of ROHHAD is made (Fig.", "img": null}, {"id": "fc_027_09", "ch": 27, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Later-Onset-CCHS (LO-CCHS; .1 Month Old Into Adulthood)**, how is **sudden infant death syndrome (SIDS)** defined and characterized?", "a": "sudden infant death syndrome (SIDS) and sudden unexplained death of childhood (SUDC) , especially with a family history of sudden death or CCHS.", "img": null}, {"id": "fc_027_10", "ch": 27, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Molecular Genetic PHOX2B Testing Approach**, how is **Step 1** defined and characterized?", "a": "Step 1 is the PHOX2B Fragment Analysis or Screening Test done by gel electrophoresis that targets the polyalanine repeat region.", "img": null}, {"id": "fc_027_11", "ch": 27, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Molecular Genetic PHOX2B Testing Approach**, how is **Step 3** defined and characterized?", "a": "Step 3 , PHOX2B multiplex ligation-dependent probe amplification (MLPA), detects exon 3 and whole-gene deletions, and potentially neighboring genes.", "img": null}, {"id": "fc_027_12", "ch": 27, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Autoimmune Theory**, how is **paraneoplastic autoimmune theory** defined and characterized?", "a": "paraneoplastic autoimmune theory of etiology, similar to the neuroblastoma associated opsoclonus-myoclonus syndrome , in which the cause is thought to be a tumor that activates the immune system to affect the nervous system.", "img": null}, {"id": "fc_027_13", "ch": 27, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **ROHHAD**, how is **Hyperprolactinemia** defined and characterized?", "a": "Hyperprolactinemia is consistently noted early in ROHHAD development.", "img": null}, {"id": "fc_027_14", "ch": 27, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **ROHHAD**, how is **neuropsychiatric dysfunction** defined and characterized?", "a": "neuropsychiatric dysfunction (including severe behavioral disturbances and developmental delay) has been noted and described as a key feature of ROHHAD, it may be more telling of poor management and compliance as opposed to a characteristic feature.", "img": null}, {"id": "fc_027_15", "ch": 27, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 27.1):", "a": "Ventilatory response to hypoxic hypercapnia (14% O2/7% CO2) combined gas challenges in CCHS (A) and ROHHAD (B). Percent change from baseline is shown during gas exposure and recovery (left and right panels of each figure, respectively). Reported values are for weight-normalized minute ventilation (VE, row i), respiratory frequency (f, row ii), and weight-normalized tidal volume (VT, row iii). Measurements in CCHS/ROHHAD cases are indicated as teal squares with crossbars as mean ± SEM; controls are shown as fuchsia circles with crossbars. Significant changes from baseline are indicated with filled markers above each data panel ( teal squares for CCHS/ROHHAD, fuchsia circles for controls). Significant differences between CCHS/ROHHAD and controls for each time point are indicated by yellow diamonds . Transparent background lines illustrate per-subject raw data. (Reproduced with permission from Carroll MS, et al. Residual chemosensitivity to ventilatory challenges in genotyped congenital central hypoventilation syndrome. J Appl Physiol [1985] . 2014;116[4]:443; Carroll MS, et al. Rapid-onset obesity with hypothalamic dysfunction, hypoventilation, and autonomic dysregulation [ROHHAD]: response to ventilatory challenges. Pediatr Pulmonol . 2015;50[12]:1341.)", "img": "fig_p0612_01.jpg"}, {"id": "fc_027_16", "ch": 27, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 27.2):", "a": "(A) Height, (B) weight, and (C) BMI with advancing age beginning before ROHHAD diagnosis to age 14.3 years. Height, weight, and BMI percentiles were calculated using published CDC growth charts and methods (Centers for Disease Control and Prevention, access date: March 18, 2024; Gulati et al., 2012). Dots are individual measurements for the case report. Bold solid lines represent 3rd, 50th, and 97th percentile. Nonbold solid lines represent 10th and 90th percentiles. The two dotted lines in the graphs of weight and BMI indicate the 125th and 150th of 95th percentiles. (Reproduced with permission from Khaytin I, et al. Evolution of physiologic and autonomic phenotype in rapid-onset obesity with hypothalamic dysfunction, hypoventilation, and autonomic dysregulation over a decade from age at diagnosis. J Clin Sleep Med . 2022;18[3]:940.)", "img": "fig_p0613_02.jpg"}, {"id": "fc_027_17", "ch": 27, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 27.3):", "a": "Rapid-onset obesity with hypoventilation, hypothalamic dysfunction, and autonomic dysregulation syndrome (neural crest tumor) (ROHHAD[NET]) general timeline. Age of outcome for each specific term of the ROHHAD(NET) acronym. Box plots show the median values and the first and third quartiles for each group. T-bars represent the rest of the data. Outlier data were not removed. (Modified from Harvengt J, Gernay C, Mastouri M, et al. ROHHAD[NET] syndrome: systematic review of the clinical timeline and recommendations for diagnosis and prognosis. J Clin Endocrinol Metab . 2020;105[7]:2119-2131 [Fig. 3, p. 2123].)", "img": "fig_p0614_01.jpg"}, {"id": "fc_027_18", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clinical Findings Percentage of Patients (%) Clinical Findings Percentage of Patients (%)**, what are the distinguishing features of **Hypothalamic Dysfunction**?", "a": "**Clinical Findings**: Autonomic Dysregulation—cont’d", "img": null}, {"id": "fc_027_19", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clinical Findings Percentage of Patients (%) Clinical Findings Percentage of Patients (%)**, what are the distinguishing features of **Rapid-onset obesity**?", "a": "**Percentage of Patients (%)**: 100; **Clinical Findings**: Altered sweating; **Percentage of Patients (%)**: 53", "img": null}, {"id": "fc_027_20", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clinical Findings Percentage of Patients (%) Clinical Findings Percentage of Patients (%)**, what are the distinguishing features of **Failed growth hormone stimulation test**?", "a": "**Percentage of Patients (%)**: 60; **Clinical Findings**: Cold hands and feet; **Percentage of Patients (%)**: 40", "img": null}, {"id": "fc_027_21", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Phenotypic Overlap Between ROHHAD, CCH S, LO-CCHS, and PWS**, what are the distinguishing features of **Age at presentation**?", "a": "**ROHHAD**: 1.5–7 years old; **CCHS LO-CCHS**: ≤1 month old >1 month old into adulthood; **PWS**: Symptoms first present in neonates and continue to unfold into childhood.", "img": null}, {"id": "fc_027_22", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Phenotypic Overlap Between ROHHAD, CCH S, LO-CCHS, and PWS**, what are the distinguishing features of **Genetic etiology**?", "a": "**ROHHAD**: Unknown; **CCHS LO-CCHS**: Yes (PHOX2Bvariant); **PWS**: Yes (PWCR at 15q11.2-q13)", "img": null}, {"id": "fc_027_23", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Phenotypic Overlap Between ROHHAD, CCH S, LO-CCHS, and PWS**, what are the distinguishing features of **Obesity**?", "a": "**ROHHAD**: Yes (over 3–12 months); **CCHS LO-CCHS**: No; **PWS**: Yes (less steep and not rapid onset trajectory)", "img": null}, {"id": "fc_027_24", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Phenotypic Overlap Between ROHHAD, CCH S, LO-CCHS, and P WS—cont’d**, what are the distinguishing features of **Neural crest tumors**?", "a": "**ROHHAD**: Yes (in 40–50% of cases); **CCHS**: Yes (in 40–50% of patients with PHOX2B NPARMs and <5% of patients with longest PARMs); **LO-CCHS**: No; **PWS**: No", "img": null}, {"id": "fc_027_25", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Phenotypic Overlap Between ROHHAD, CCH S, LO-CCHS, and P WS—cont’d**, what are the distinguishing features of **Altered pain perception and thermal dysregulation**?", "a": "**ROHHAD**: Yes; **CCHS**: Yes; **PWS**: Yes", "img": null}, {"id": "fc_027_26", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Phenotypic Overlap Between ROHHAD, CCH S, LO-CCHS, and P WS—cont’d**, what are the distinguishing features of **Neonatal hypotonia**?", "a": "**ROHHAD**: No; **CCHS**: Sometimes; **LO-CCHS**: No; **PWS**: Yes", "img": null}, {"id": "fc_027_27", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Nonrespirator Syndrome y Clinical Findings, Considerations, and Sur veillance in Congenital Hypoventilation**, what are the distinguishing features of **Cardiac**?", "a": "**Clinical Findings**: • Bradycardia • Sinus pauses≥3 s, may present as syncope • Exercise intolerance • Blood pressure dysregulation; **Considerations and Surveillance**: • Annual echocardiogram after age 3 yrs; every 6 mo before age 3 yr • Annual 24–72 h Holter or implantable cardiac monitor • Pacemaker as clinically indicated • Cardiopulmonary exercise testing • 24 h blood pressure", "img": null}, {"id": "fc_027_28", "ch": 27, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Nonrespirator Syndrome y Clinical Findings, Considerations, and Sur veillance in Congenital Hypoventilation**, what are the distinguishing features of **Ophthalmologic**?", "a": "**Clinical Findings**: • Strabismus • Pupillary response abnormalities • Ptosis • Convergence abnormalities; **Considerations and Surveillance**: • Annual surveillance as directed by ophthalmology • Refractive correction as needed • Strabismus/ptosis surgery as needed", "img": null}, {"id": "fc_028_01", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Duchenne muscular dystrophy (DMD)**?", "a": "**Causative Gene(s):** `DMD` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene Product: Dystrophin — Cardiomyopathy: Dilated — ECG: Short PR interval, prolonged QT interval, increased QT:PT ratio, right ventricular hypertrophy, deep Q waves II, III, aVF, V5, V6 — Arrhythmia: Increased baseline HR, decreased rate variability, premature ventricular beats", "img": null}, {"id": "fc_028_02", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **DMD—female carrier**?", "a": "**Causative Gene(s):** `DMD` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Gene Product: Dystrophin — Cardiomyopathy: Dilated — Arrhythmia: Uncommon — Duchenne muscular dystrophy is an X-linked condition resulting from pathogenic variants in the DMD gene.", "img": null}, {"id": "fc_028_03", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Becker muscular dystrophy**?", "a": "**Causative Gene(s):** `DMD` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene Product: Dystrophin — Cardiomyopathy: Dilated — ECG: Conduction system disease — Arrhythmia: Similar to DMD", "img": null}, {"id": "fc_028_04", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Complex I deficiency**?", "a": "**Causative Gene(s):** `ACAD9, FOXRED1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Genetic Defect: Multiple complex I subunit genes, ACAD9, FOXRED1 — Heart Findings: HCM, DCM, LVNC, WPW — Other Clinical Features: Leigh syndrome, FILA. MELAS, leukoencephalopathy, seizures, hypotonia, pigmentary retinopathy, optic atrophy, hearing loss, liver dysfunction", "img": null}, {"id": "fc_028_05", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Complex III deficiency**?", "a": "**Causative Gene(s):** `BCS1L` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Heart Findings: HCM — Other Clinical Features: Developmental delay, psychosis, hearing loss", "img": null}, {"id": "fc_028_06", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Complex IV deficiency**?", "a": "**Causative Gene(s):** `SCO2, SURF1, COA5, COX14, COX6B1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Genetic Defect: SCO2, SURF1, COA5, COX14, COX6B1 — Heart Findings: HCM, DCM — Other Clinical Features: Leigh syndrome, encephalopathy, ataxia, liver dysfunction, kidney dysfunction", "img": null}, {"id": "fc_028_07", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GTP-binding protein-3 deficiency**?", "a": "**Causative Gene(s):** `GTPBP3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Heart Findings: HCM, DCM, heart block, WPW — Other Clinical Features: Leigh syndrome, encephalopathy", "img": null}, {"id": "fc_028_08", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Alanyl-tRNA synthetase deficiency**?", "a": "**Causative Gene(s):** `AARS2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Heart Findings: HCM — Other Clinical Features: Leukoencephalopathy, myopathy", "img": null}, {"id": "fc_028_09", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Tyrosyl-tRNA synthetase deficiency**?", "a": "**Causative Gene(s):** `YARS2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Heart Findings: HCM — Other Clinical Features: MLASA syndrome", "img": null}, {"id": "fc_028_10", "ch": 28, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **tRNA methyltransferase-5 deficiency**?", "a": "**Causative Gene(s):** `TRMT5` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Heart Findings: HCM — Other Clinical Features: Developmental delay, hypotonia, peripheral neuropathy, renal tubulopathy", "img": null}, {"id": "fc_028_11", "ch": 28, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MYH7`** are associated with which clinical phenotype and molecular mechanism in **Hypertrophic Cardiomyopathy**?", "a": "MYH7 , the gene that encodes β myosin heavy chain, a component of the thick filament of the sarcomere and the structural protein containing the ATPase activity necessary for contraction, was the first gene identified as causative in families with HCM.", "img": null}, {"id": "fc_028_12", "ch": 28, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TPM1`** are associated with which clinical phenotype and molecular mechanism in **Hypertrophic Cardiomyopathy**?", "a": "Subsequently, pathogenic variants in MYBPC3 , TNNT2 , ACTC , MYL2 , TPM1 , and other components of the thick and thin filaments of the sarcomere, their interacting proteins, or contiguous Z-disc were identified as causative in individuals with HCM.", "img": null}, {"id": "fc_028_13", "ch": 28, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`LMNA`** are associated with which clinical phenotype and molecular mechanism in **Dilated Cardiomyopathy**?", "a": "Individuals with LMNA pathogenic variants are more likely to require transplantation due to arrhythmogenic disease.", "img": null}, {"id": "fc_028_14", "ch": 28, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TNNI3`** are associated with which clinical phenotype and molecular mechanism in **Restrictive Cardiomyopathy**?", "a": "Because of its rarity, genetic diagnostic yield is uncertain but pathogenic variants in TNNI3 followed by MYH7 genes are the most frequently identified causes.", "img": null}, {"id": "fc_028_15", "ch": 28, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PRKAG2`** are associated with which clinical phenotype and molecular mechanism in **LEFT VENTRICULAR NONCOMPACTION (LVNC)**?", "a": "CoA, Coenzyme A; GSD, glycogen storage disease; HCM, hypertrophic cardiomyopathy; PRKAG2, γ-2 subunit of AMP-activated protein kinase.-2 subunit of AMP-activated protein kinase.", "img": null}, {"id": "fc_028_16", "ch": 28, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PTPN11`** are associated with which clinical phenotype and molecular mechanism in **RASopathies**?", "a": "It is thought that mTOR inhibitors are helpful in patients with PTPN11 related Noonan syndrome with multiple lentigines because these inhibitors may inactivate the phosphatase activity.", "img": null}, {"id": "fc_028_17", "ch": 28, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **RASopathies**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Using the mTOR inhibitors sirolimus and everolimus for HCM in RASopathies is another option to improve outcomes.", "img": null}, {"id": "fc_028_18", "ch": 28, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Muscular Dystrophies**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Antisense oligonucleotide (ASO) therapy is a therapeutic that induces exon skipping for specific classes of pathogenic variants.", "img": null}, {"id": "fc_028_19", "ch": 28, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **(see Chapter 46)**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Enzyme replacement therapy with alglucosidase alfa is approved by the FDA for Pompe disease.", "img": null}, {"id": "fc_028_20", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Pediatric Cardiomyopathies**, how is **secondary cardiomyopathies** defined and characterized?", "a": "secondary cardiomyopathies which result from systemic disorders and include genetic conditions with cardiomyopathy as part of multiple malformation syndromes, inborn errors of metabolism, and neuromuscular diseases (Table 28.", "img": null}, {"id": "fc_028_21", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **RASopathies**, how is **cardiofaciocutaneous syndrome** defined and characterized?", "a": "cardiofaciocutaneous syndrome , Costello syndrome , Noonan syndrome , Noonan syndrome with loose anagen hair , and Noonan syndrome with multiple lentigines .", "img": null}, {"id": "fc_028_22", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Muscular Dystrophies**, how is **Duchenne muscular dystrophy** defined and characterized?", "a": "Duchenne muscular dystrophy is an X-linked condition resulting from pathogenic variants in the DMD gene.", "img": null}, {"id": "fc_028_23", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Muscular Dystrophies**, how is **Becker muscular dystrophy** defined and characterized?", "a": "Becker muscular dystrophy is characterized by higher levels of residual protein.", "img": null}, {"id": "fc_028_24", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Muscular Dystrophies**, how is **Emery-Dreifuss muscular dystrophy** defined and characterized?", "a": "Emery-Dreifuss muscular dystrophy results from pathogenic variants in EMD , an X-linked gene, FHL1 , an X-linked gene, or LMNA with autosomal dominant inheritance (Table 28.", "img": null}, {"id": "fc_028_25", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Muscular Dystrophies**, how is **Limb-girdle muscular dystrophies** defined and characterized?", "a": "Limb-girdle muscular dystrophies are a group of autosomal recessive and autosomal dominant conditions that together are the fourth most common type of muscular dystrophy (Table 28.", "img": null}, {"id": "fc_028_26", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **(see Chapter 45)**, how is **Barth syndrome** defined and characterized?", "a": "Barth syndrome , sometimes referred to as 3-methylglutaconic acidemia type II, is an X-linked cause of cardiomyopathy due to abnormal remodeling of cardiolipin, a complex lipid only found in the inner mitochondrial membrane.", "img": null}, {"id": "fc_028_27", "ch": 28, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **(see Chapter 46)**, how is **Pompe disease** defined and characterized?", "a": "Pompe disease is a result of glycogen accumulation within the lysosome presenting with profound hypotonia, cardiomyopathy and cardiorespiratory failure in the first year of life.", "img": null}, {"id": "fc_028_28", "ch": 28, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 28.1):", "a": "Relationships of genes implicated in causing cardiovascular and related phenotypes. The gene relationships for several cardiovascular phenotypes are shown, with the principal focus on dilated cardiomyopathy (DCM) genetics. Common cardiac phenotypes are shown in the purple ovals , and lines connect each phenotype to the gene or genes (shown in a box) of which rare variants have been implicated in causing the phenotype. The gene boxes are color-coded according to the number of phenotypes with which they are associated: blue indicates one phenotype, red indicates two phenotypes, and yellow indicates three phenotypes (as shown in the lower left corner of the figure). For a gene causing 3% or more of familial DCM cases, the frequency is included with its name. Hypertrophic cardiomyopathy (HCM) gene associations are indicated by dotted lines . Well-established HCM genes include two sarcomere genes ( MYH7 and MYBPC3 ) that together account for 80% of HCM cases for which a genetic cause can be identified. Three other sarcomere genes ( TNNT2 , TNNI3 , and TPM1 ) account for an additional 15% of such cases. The other numerous genes implicated have caused only one or a few reported cases. The evidence in support of rare variants in the genes shown and their relevance for the specified cardiomyopathy varies considerably. (From Hershberger RE: The dilated, restrictive, and infiltrative cardiomyopathies in Libby P, Bonow RO, Mann DL, et al., eds. _Bra", "img": "fig_p0634_01.jpg"}, {"id": "fc_029_01", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LQT1**?", "a": "**Causative Gene(s):** `LQT1, KCNQ1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: 30–35% — Genes: KCNQ1 — Main Type of Variants: LOF — Current Affected: IKs — Noncardiac Phenotype: SNHL (AR), seizures — JLNS (AR), SQTS, AF", "img": null}, {"id": "fc_029_02", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LQT2**?", "a": "**Causative Gene(s):** `LQT2, KCNH2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: 25–30% — Genes: KCNH2 — Main Type of Variants: LOF — Current Affected: IKr — Noncardiac Phenotype: Seizures — SQTS, BrS, AF", "img": null}, {"id": "fc_029_03", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LQT3**?", "a": "**Causative Gene(s):** `LQT3, SCN5A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: 5–10% — Gene Curation: Definitive genes — Genes: SCN5A — Main Type of Variants: GOF — Current Affected: INa — Noncardiac Phenotype: Multiple (including seizures) — BrS, SQTS, CPVT, ERS, AF, AFL, ARVC/D, HCM, DCM, LVNC, SVT, AVB, SND, PCCD, WPW", "img": null}, {"id": "fc_029_04", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LQT17 (TKOS)**?", "a": "**Causative Gene(s):** `LQT17` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance Model: AR — Frequency: <1% — Gene Curation: with atypical characteristics — Genes: TRDN — Main Type of Variants: LOF — Current Affected: ICa — Noncardiac Phenotype: Muscle weakness — CPVT", "img": null}, {"id": "fc_029_05", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LQT5**?", "a": "**Causative Gene(s):** `LQT5, KCNE1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: <1% — Gene Curation: Genes with — Genes: KCNE1 — Main Type of Variants: LOF — Current Affected: IKs — Noncardiac Phenotype: SNHL (AR) — JLNS (AR)", "img": null}, {"id": "fc_029_06", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LQT8**?", "a": "**Causative Gene(s):** `LQT8, CACNA1C` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: <1% — Gene Curation: moderate or limited evidence, associated with — Genes: CACNA1C — Main Type of Variants: GOF — Current Affected: ICa — Noncardiac Phenotype: Dysmorphic and neurodevelopmental features — TS, SQTS, BrS, ERS, HCM, AF, SND, CND", "img": null}, {"id": "fc_029_07", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **multiorgan syndromes**?", "a": "**Causative Gene(s):** `LQT7, KCNJ2, IK1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: <1% — Genes: KCNJ2 — Main Type of Variants: LOF — Current Affected: IK1 — Noncardiac Phenotype: Muscle weakness, dysmorphic features, DD, seizures — ATS, SOTS, AF, CPVT, DCM", "img": null}, {"id": "fc_029_08", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LQTS**?", "a": "**Causative Gene(s):** `ANK2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: <1% each — Gene Curation: Other genes — Genes: ANK2 — Main Type of Variants: LOF — Current Affected: Many — Noncardiac Phenotype: Seizures — CPVT, BrS, CND AF, SND AF", "img": null}, {"id": "fc_029_09", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BrS1**?", "a": "**Causative Gene(s):** `SCN5A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance Model: AD — Frequency: 20–30% — Gene Curation: Definitive gene — Genes: SCN5A — Main Type of Variants: LOF — Current Affected: INa — Noncardiac Phenotype: Multiple (including seizures) — BrS, SQTS, CPVT, ERS, AF, AFL, ARVC, HCM, DCM, LVNC, SVT, AVB, SND, PCCD, WPW", "img": null}, {"id": "fc_029_10", "ch": 29, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CPVT1**?", "a": "**Causative Gene(s):** `CPVT1, RYR2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritanc Model: AD — e Frequency: 55–60% — Gene Curation: Definitive genes — Genes: RYR2 — Main Type of Variants: GOF — Current Affected: ICa — LQTS, HCM, LVNC, CRDS", "img": null}, {"id": "fc_029_11", "ch": 29, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`LQT1`** are associated with which clinical phenotype and molecular mechanism in **Genetic Basis**?", "a": "Forty to 55% of LQTS are caused by loss-of-function variants in KCNQ1 (LQT1) and 30–45% by loss-of-function variants in KCNH2 (LQT2).", "img": null}, {"id": "fc_029_12", "ch": 29, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCN5A`** are associated with which clinical phenotype and molecular mechanism in **Genetic Basis**?", "a": "Approximately 5–10% of LQTS cases are due to gain-of-function variants in SCN5A (LQT3).", "img": null}, {"id": "fc_029_13", "ch": 29, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`LQT2`** are associated with which clinical phenotype and molecular mechanism in **Genetic Basis of Arrhythmogenesis in LQTS**?", "a": "In LQT2 and LQT3, this effect is less noticeable; these patients are more likely to have clinical events at rest.", "img": null}, {"id": "fc_029_14", "ch": 29, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RYR2`** are associated with which clinical phenotype and molecular mechanism in **Genes Associated With LQTS**?", "a": "Proteins of the sarcoplasmic reticulum that are involved in calcium handling (encoded by CASQ2, RYR2, CALM1, CALM2, CALM3, and TRDN ) are also shown.", "img": null}, {"id": "fc_029_15", "ch": 29, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ANK2`** are associated with which clinical phenotype and molecular mechanism in **Genes Associated With LQTS**?", "a": "Other proteins that can be abnormal in inherited cardiac arrhythmias are encoded by ANK2 and TECRL .", "img": null}, {"id": "fc_029_16", "ch": 29, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`LQT8`** are associated with which clinical phenotype and molecular mechanism in **Genotype-Phenotype Inherited. Arrhythmogenic. Syndromes Correlation—cont’d**?", "a": "Timothy syndrome (LQT8) is caused by variants in CACNA1C .", "img": null}, {"id": "fc_029_17", "ch": 29, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Long QT Syndrome**, how is **sudden cardiac death (SCD)** defined and characterized?", "a": "sudden cardiac death (SCD) and resuscitated sudden cardiac arrest (SCA) in those with structurally normal hearts.", "img": null}, {"id": "fc_029_18", "ch": 29, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Basis**, how is **Romano-Ward syndrome** defined and characterized?", "a": "Romano-Ward syndrome but is generally referred to as LQTS (Table 29.", "img": null}, {"id": "fc_029_19", "ch": 29, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genotype-Phenotype Inherited. Arrhythmogenic. Syndromes Correlation—cont’d**, how is **calmodulin** defined and characterized?", "a": "calmodulin (calcium sensing signal transducing protein) genes such as CALM1-3 (LQT14-16) cause an atypical LQTS mainly manifest by severe presentation in infancy, with extremely long QT interval, 2:1 atrioventricular block (Fig.", "img": null}, {"id": "fc_029_20", "ch": 29, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genotype-Phenotype Inherited. Arrhythmogenic. Syndromes Correlation—cont’d**, how is **Timothy syndrome** defined and characterized?", "a": "Timothy syndrome (LQT8) is caused by variants in CACNA1C .", "img": null}, {"id": "fc_029_21", "ch": 29, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **History**, how is **Swimming** defined and characterized?", "a": "Swimming is a notable activity shown to trigger events in LQT1.", "img": null}, {"id": "fc_029_22", "ch": 29, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Basis**, how is **Typical CPVT** defined and characterized?", "a": "Typical CPVT includes those clinical syndromes caused by AD variants in RYR2 and AR variants in CASQ2 .", "img": null}, {"id": "fc_029_23", "ch": 29, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 29.1):", "a": "The cardiac myocyte action potential is shown as well as the depolarizing/hyperpolarizing currents, associated channels, and genes.", "img": "fig_p0656_01.jpg"}, {"id": "fc_029_24", "ch": 29, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 29.2):", "a": "Genes and proteins involved in the pathogenesis of inherited cardiac arrhythmias. The figure shows the transmembrane ionic channels that are responsible for the potassium (IKs, IK1, and IKr), calcium (ICa), and sodium (INa) currents that contribute to the cardiac action potential. Proteins of the sarcoplasmic reticulum that are involved in calcium handling (encoded by CASQ2, RYR2, CALM1, CALM2, CALM3, and TRDN ) are also shown. Other proteins that can be abnormal in inherited cardiac arrhythmias are encoded by ANK2 and TECRL . The genes that encode all these proteins or their subunits are colored according to the disease with which they have been associated. BrS, Brugada syndrome; CPVT, catecholaminergic polymorphic ventricular tachycardia; LQTS, long QT syndrome; SQTS, short QT syndrome.", "img": "fig_p0657_02.jpg"}, {"id": "fc_029_25", "ch": 29, "part": "IV", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 29.3):", "a": "Cardiac action potential disorders. Illustrated are the key ion currents (white circles) along the ventricular cardiomyocyte’s action potential that are associated with potentially lethal cardiac arrhythmia disorders. Disorders resulting in gain-of-function variants are shown in green rectangles and those with loss-offunction pathogenic variants shown in blue rectangles. For example, while gain-of-function variants in the SCN5A encoding cardiac sodium channel responsible for INa lead to LQTS, loss-of-function SCN5A variants result in BrS, CCD, and SSS. AF, Atrial fibrillation; ATS, Andersen-Tawil syndrome; BrS, Brugada syndrome; CCD, cardiac conduction disease; LQTS, long QT syndrome; MEPPC, multifocal ectopic Purkinje-related premature contractions; SSS, sick sinus syndrome; SQTS, short QT syndrome; TS, Timothy syndrome.", "img": "fig_p0657_04.jpg"}, {"id": "fc_029_26", "ch": 29, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genoty pe-Phenoty pe Inherited. A rrhythmogenic. Syndromes C orrelation**, what are the distinguishing features of **LQT1**?", "a": "**Inheritance Model**: AD; **Frequency**: 30–35%; **Genes**: KCNQ1; **Main Type of Variants**: LOF; **Current Affected**: IKs; **Noncardiac Phenotype**: SNHL (AR), seizures; **Phenotypic Overlap (Both LOF/GOF Variants)**: JLNS (AR), SQTS, AF", "img": null}, {"id": "fc_029_27", "ch": 29, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genoty pe-Phenoty pe Inherited. A rrhythmogenic. Syndromes C orrelation**, what are the distinguishing features of **LQT2**?", "a": "**Inheritance Model**: AD; **Frequency**: 25–30%; **Genes**: KCNH2; **Main Type of Variants**: LOF; **Current Affected**: IKr; **Noncardiac Phenotype**: Seizures; **Phenotypic Overlap (Both LOF/GOF Variants)**: SQTS, BrS, AF", "img": null}, {"id": "fc_029_28", "ch": 29, "part": "IV", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### 29.1 #### Genotype-Phenotype Inherited. Arrhythmogenic. Syndromes Correlation—cont’d**, what are the distinguishing features of **CPVT1**?", "a": "**Inheritanc Model**: AD; **e Frequency**: 55–60%; **Gene Curation**: Definitive genes; **Genes**: RYR2; **Main Type of Variants**: GOF; **Current Affected**: ICa; **Phenotypic Overlap (Both LOF/GOF Variants)**: LQTS, HCM, LVNC, CRDS", "img": null}, {"id": "fc_030_01", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Capillary malformationarteriovenous malformation (CM-AVM) Parkes-Weber syndrome (PWS)**?", "a": "**Causative Gene(s):** `RASA1, EPHB4` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** + + + — Inheritance: AD — Gene Variant(s): RASA1 EPHB4 — Type of Gene Variant: Loss-of- function — Key Clinical Features: Small, round, oval pink to red<1 cm to 3 cm diameter macules, often with white halo or with arterial flow on Doppler US. AVMs or AVFs in skin, muscle, bone, spine, brain, and soft tissues. Multifocal, mostly face and l", "img": null}, {"id": "fc_030_02", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hereditary hemorrhagic telangiectasia (HHT)**?", "a": "**Causative Gene(s):** `HHT1, HHT2, ACVRL1, ALK1, HHT5, GDF2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** + + + — Inheritance: AD — Gene Variant(s): HHT1: ENG HHT2: ACVRL1, ALK1 HHT5: GDF2 — Type of Gene Variant: Loss-of- function — Key Clinical Features: Multiple AVMs; Co-occurring telangiectasias; age-dependent features, commonly presents with epistaxis and cutaneous or mucosal CMs that rupture and bleed — TGF-β/BMP9/10/ALK signaling. Two T", "img": null}, {"id": "fc_030_03", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Juvenile polyposis with HHT**?", "a": "**Causative Gene(s):** `SMAD4, BMP9, ALK` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** + + + — Inheritance: AD — Type of Gene Variant: Loss-of- function — Key Clinical Features: Vascular dysplasia with AVMs and intestinal polyps — BMP9/10/ALK signaling SMAD4 tumor suppressor protein with role in TGF-βsignaling", "img": null}, {"id": "fc_030_04", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Cerebral capillary malformations; familial cerebral cavernomas (CCM)**?", "a": "**Causative Gene(s):** `CCM1, KRIT1, CCM2, CCM3, PDCD10` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** + + + — Inheritance: AD — Gene Variant(s): CCM1: KRIT1 CCM2: Malcavernin CCM3: PDCD10 — Type of Gene Variant: Loss-of- function — Key Clinical Features: Caverns (enlarged, clustered capillaries) without normal brain parenchyma Hyperkeratotic capillary-venous malformations in skin — RAS/RAF/MEK/ERK signaling. b-integrinsignaling (possible)", "img": null}, {"id": "fc_030_05", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Capillary malformation (port wine stain) and Sturge-Weber syndrome**?", "a": "**Causative Gene(s):** `GNAQ` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** + + − — Inheritance: Sporadic — Type of Gene Variant: Somatic activating — Key Clinical Features: Facial port-wine stains, intracranial vascular malformations (capillary-venous), leptomeningeal angiomatosis, glaucoma, buphthalmos, neurological impairment, seizures, ID, migraines — RAS/RAF/MEK/ERK signaling", "img": null}, {"id": "fc_030_06", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Capillary malformation (port wine stain) and phakomatosis pigmentovascularis type II or limb overgrowth**?", "a": "**Causative Gene(s):** `GNA11, GNAQ, GNA14, PIK3CA, RASA1, PI3K` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** + − − — Inheritance: Sporadic — Gene Variant(s): GNA11 GNAQ GNA14 PIK3CA, RASA1 GNA11 — Type of Gene Variant: Somatic — Key Clinical Features: Isolated and syndromic CMs — PI3K/AKT/mTOR & RAS/RAF/ MEK/ERK signaling", "img": null}, {"id": "fc_030_07", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Reticulated CM Cutis marmorata telangiectasia congenita (CMTC)**?", "a": "**Causative Gene(s):** `GNA11` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** + − − + − − — Inheritance: Sporadic — Type of Gene Variant: Somatic — Key Clinical Features: Telangiectasias with vascular pattern (red-purple), prominent veins; atrophic, ulcerated areas. May have associated limb hypoplasia or additional vascular malformations — RAS/RAF/MEK/ERK signaling", "img": null}, {"id": "fc_030_08", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PTEN-Hamartoma- Tumor syndrome (PHTS)**?", "a": "**Causative Gene(s):** `PTEN, PI3K` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** + + + — Inheritance: Sporadic & AD — Type of Gene Variant: Somatic & germline loss-of- function — Key Clinical Features: AD: Cowden and Bannayan-Riley-Ruvalcaba syndrome Somatic/Mosaic: Segmental OG, lipomatosis, AVMs, epidermal nevus (SOLAMEN) syndrome — PI3K/AKT/mTOR signaling.", "img": null}, {"id": "fc_030_09", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Mosaic KRAS-mosaic RASopathy Brain AVMs Extracranial AVM**?", "a": "**Causative Gene(s):** `KRAS, BRAF, MAP2K1, HRAS, NRAS, FGFR1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** + − + — Inheritance: Sporadic — Gene Variant(s): KRAS KRAS KRAS, BRAF, MAP2K1 HRAS, NRAS, FGFR1 — Type of Gene Variant: Somatic activating — Key Clinical Features: Capillary malformation, other vascular malformations, epidermal nevi, hyperpigmented lesions, segmental overgrowth of limbs (hemihypertrophy), epilepsy, multifocal lytic bone l", "img": null}, {"id": "fc_030_10", "ch": 30, "part": "IV", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PIK3CA-Related Overgrowth Spectrum (PROS)**?", "a": "**Causative Gene(s):** `PIK3CA, PI3K` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** + + + Lymphatic, combined — Inheritance: Sporadic — Type of Gene Variant: Somatic activating — Key Clinical Features: Spectrum of features, including variable vascular malformations(capillary, venous, lymphatic, mixed, arteriovenous)with segmental overgrowth, abnormal adipose tissue, lipomatous masses, epidermal nevi, skeletal and spine (", "img": null}, {"id": "fc_030_11", "ch": 30, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`EPHB4`** are associated with which clinical phenotype and molecular mechanism in **Vascular and Lymphatic Malformations**?", "a": "The major pathways include angiopoietin/TIE2, PI3K/AKT/ mTOR, EPHB4/RAS/MEK/ERK, TGFβ, and GNAQ/ GNA11/GNA14 signaling (Fig. 30.1 and Table 30.2).", "img": null}, {"id": "fc_030_12", "ch": 30, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PIK3CA`** are associated with which clinical phenotype and molecular mechanism in **Provisionally Unclassified**?", "a": "This patient has a confirmed somatic PIK3CA pathogenic variant.", "img": null}, {"id": "fc_030_13", "ch": 30, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GNA11`** are associated with which clinical phenotype and molecular mechanism in **Provisionally Unclassified**?", "a": "Reticulated PWS may be associated with GNA11 pathogenic variants especially if there is concomitant presence of a nevus anemicus .", "img": null}, {"id": "fc_030_14", "ch": 30, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TEK`** are associated with which clinical phenotype and molecular mechanism in **Molecular Pathogenesis**?", "a": "Most VMs are isolated lesions caused by somatic TIE / TEK pathogenic variants or somatic PIK3CA pathogenic variants.", "img": null}, {"id": "fc_030_15", "ch": 30, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TIE2`** are associated with which clinical phenotype and molecular mechanism in **Management and Treatment**?", "a": "For those in whom sclerotherapy is not an option, or if sclerotherapy is insufficient for treatment of the VM, medical therapy with sirolimus, alpelisib (if a PIK3CA pathogenic variant is identified), or direct TIE2 inhibitors can be considered.", "img": null}, {"id": "fc_030_16", "ch": 30, "part": "IV", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GLA`** are associated with which clinical phenotype and molecular mechanism in **Clinical Features and Natural History**?", "a": "Yellow arrows indicate GLA pathology (chylothorax and diffuse cystic lesions).", "img": null}, {"id": "fc_030_17", "ch": 30, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Transthoracic contrast echocardiography (bubble study)**?", "a": "**Therapy / Intervention:** • Transcatheter embolotherapy in all adults and in children with AVMs that are large or associated with hypoxemia • Antibiotic prophylaxis for procedures with risk of bacteremia, precautions to avoid air bubbles during i\n\n**Clinical Context:** Indication(s): Definite or suspected HHT — Purpose of Study: DetectpulmonaryAVMs, which lead to right-to-left shunting (15–50% of HHT patients) — • Transcatheter embolotherapy in all adults and in children with AVMs that", "img": null}, {"id": "fc_030_18", "ch": 30, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Brain MRI with and without contrast**?", "a": "**Therapy / Intervention:** • Referral to a center with neurovascular expertise for consideration of invasive testing and treatment\n\n**Clinical Context:** Indication(s): Definite or suspected HHT — Purpose of Study: DetectcerebralAVMs and other vascular malformations (~25% of HHT patients) — • Referral to a center with neurovascular expertise for consideration of invasive", "img": null}, {"id": "fc_030_19", "ch": 30, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Annual hemoglobin and hematocrit testing**?", "a": "**Therapy / Intervention:** • Esophagogastroduodenoscopy if anemia disproportionate to epistaxis • Iron supplementation • Treatment considerations for GI bleeding include endoscopic argon plasma coagulation, antifibrinolytics, and bevacizumab\n\n**Clinical Context:** Indication(s): Adult HHT patients and children with recurrent bleeding and/or symptoms of anemia — Purpose of Study: Detect substantial bleeding related togastrointestinal (GI) AVMs (−25% of HHT patients; less common bef", "img": null}, {"id": "fc_030_20", "ch": 30, "part": "IV", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Doppler ultrasonography, multiphase contrast CT, or contrast MRI of liver**?", "a": "**Therapy / Intervention:** • Additional testing and treatment directed by findings and symptoms; liver biopsy should be avoided\n\n**Clinical Context:** Indication(s): (1) Adults with definite or suspected HHT (2) HHT patients with signs/ symptoms of heart failure or hepatobiliary disease — Purpose of Study: DetecthepaticAVMs (present in 30–80% but symptomatic in<10% of", "img": null}, {"id": "fc_030_21", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Vascular and Lymphatic Malformations**, how is **Vascular tumors** defined and characterized?", "a": "Vascular tumors , most commonly infantile hemangiomas, are lesions that have proliferative growth of endothelial cells and pericytes, and are divided into benign, locally aggressive, or borderline, and malignant.", "img": null}, {"id": "fc_030_22", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Vascular and Lymphatic Malformations**, how is **Vascular malformations** defined and characterized?", "a": "Vascular malformations are localized defects of vascular morphogenesis during embryogenesis, composed of dysplastic vascular channels.", "img": null}, {"id": "fc_030_23", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Provisionally Unclassified**, how is **BeckwithWiedemann syndrome** defined and characterized?", "a": "BeckwithWiedemann syndrome among other diagnoses; referral to genetics in atypical cases can be considered.", "img": null}, {"id": "fc_030_24", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Provisionally Unclassified**, how is **Sturge-Weber syndrome (SWS)** defined and characterized?", "a": "Sturge-Weber syndrome (SWS) , a noninherited syndrome caused by a somatic pathogenic variant in GNAQ in the skin, eye, and/or brain that can also result in glaucoma, seizures, and developmental disability.", "img": null}, {"id": "fc_030_25", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Provisionally Unclassified**, how is **cutis marmorata telangiectatica congenita (CMTC)** defined and characterized?", "a": "cutis marmorata telangiectatica congenita (CMTC) , but unlike CMTC there is no atrophy or ulceration within the anomaly.", "img": null}, {"id": "fc_030_26", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features and Natural History**, how is **glomangiomas** defined and characterized?", "a": "glomangiomas ) are benign, simple vascular malformations that develop from neuromyoarterial glomus bodies.", "img": null}, {"id": "fc_030_27", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Differential Diagnosis**, how is **Hyperkeratotic cutaneous capillary venous malformation** defined and characterized?", "a": "Hyperkeratotic cutaneous capillary venous malformation caused by KRIT1 pathogenic variants are clinically similar to VVMs but individuals with KRIT1 pathogenic variants may have cerebral cavernous malformations.", "img": null}, {"id": "fc_030_28", "ch": 30, "part": "IV", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Molecular Pathogenesis**, how is **Parkes-Weber syndrome** defined and characterized?", "a": "Parkes-Weber syndrome which features extremity overgrowth with a geographic PWS and an underlying AVM.", "img": null}, {"id": "fc_031_01", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **COL7A1**?", "a": "**Causative Gene(s):** `COL7A1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Immune: Epithelial cell organization — Colitis, strictures — Affecting both the skin and involved mucosal surfaces such as oral, esophageal, colonic, anal, urogenital, and ocular", "img": null}, {"id": "fc_031_02", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **UC like colitis, Kindler syndrome**?", "a": "**Causative Gene(s):** `FERMT1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Skin abnormalities, such as skin blistering, skin atrophy, photosensitivity, pigmentation defects, and increased risk of squamous cell carcinoma", "img": null}, {"id": "fc_031_03", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GUCY2C**?", "a": "**Causative Gene(s):** `GUCY2C` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Immune: Epithelial cell intrinsic — CD like inflammation and small bowel obstruction — Neonatal meconium ileus, congenital sodium diarrhea", "img": null}, {"id": "fc_031_04", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SLC9A3**?", "a": "**Causative Gene(s):** `SLC9A3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Immune: function — Small bowel enteritis — Polyhydramnios; watery secretory diarrhea and abdominal distension soon after birth", "img": null}, {"id": "fc_031_05", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **STXBP3and STXBP2**?", "a": "**Causative Gene(s):** `STXBP2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Infantile-onset colitis like IBD — Medically refractory IBD Sensorineural deafness, bleeding disorders, hypogammaglobulinemia, renal tubular disorders", "img": null}, {"id": "fc_031_06", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Lynch syndrome—a hereditary non-polyposis colon cancer syndrome Congenital tufting enteropathy**?", "a": "**Causative Gene(s):** `EPCAM` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Immune: Epithelial cell apoptosis and necroptosis — Small bowel enteritis and colitis", "img": null}, {"id": "fc_031_07", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **TTC7A**?", "a": "**Causative Gene(s):** `TTC7A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Colitis characterized by neutrophils and eosinophils — Multiple intestinal atresias; copious secretory bloody diarrhea shortly after birth", "img": null}, {"id": "fc_031_08", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Angiopathic thrombosis, intestinal lymphangiectasia, and PLE (CHAPLE) syndrome**?", "a": "**Causative Gene(s):** `CD55` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Immune: Complement activation — Small bowel ulcerations and diarrhea", "img": null}, {"id": "fc_031_09", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ADAM17**?", "a": "**Causative Gene(s):** `ADAM17` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Immune: Epithelial cell signaling — Chronic diarrhea with chronic inflammatory changes — Erythroderma, hair abnormalities (alopecia, short, wiry or disorganized hair), recurrent severe infections and sepsis", "img": null}, {"id": "fc_031_10", "ch": 31, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SKIV2Land TTC37**?", "a": "**Causative Gene(s):** `TTC37` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Immune: Control of RNA degradation product — Perianal disease and oral ulcerations — Trichohepatoenteric syndrome", "img": null}, {"id": "fc_031_11", "ch": 31, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FOXP3`** are associated with which clinical phenotype and molecular mechanism in **Immunology Evaluation**?", "a": "Targeted flow cytometry can be performed for Forkhead box protein 3 (FOXP3).", "img": null}, {"id": "fc_031_12", "ch": 31, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IKBKG`** are associated with which clinical phenotype and molecular mechanism in **Epithelial Barrier Defects**?", "a": "IKBKG is a gene that when disrupted effects nuclear factor kappa B (NF-kB) transcription factors leading to ectodermal dysplasia and antibody deficiencies.", "img": null}, {"id": "fc_031_13", "ch": 31, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`COL7A1`** are associated with which clinical phenotype and molecular mechanism in **Epithelial Barrier Defects**?", "a": "COL7A1 encodes for collagen VII; pathogenic variants lead to an autoimmune response and deficiency in anchoring fibrils.", "img": null}, {"id": "fc_031_14", "ch": 31, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FERMT1`** are associated with which clinical phenotype and molecular mechanism in **Epithelial Barrier Defects**?", "a": "FERMT1 disruptions effect phosphoprotein and focal adhesion adaptor component kindling-1 leading to an inflammatory response in keratinocytes.", "img": null}, {"id": "fc_031_15", "ch": 31, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GUCY2C`** are associated with which clinical phenotype and molecular mechanism in **Epithelial Barrier Defects**?", "a": "Deficiencies in the two genes, guanylate cyclase 2C (GUCY2C) and solute carrier 9A3 (SLC9A3) , are linked to congenital sodium diarrhea (CSD) and also to the development of an IBD phenotype.", "img": null}, {"id": "fc_031_16", "ch": 31, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MVK`** are associated with which clinical phenotype and molecular mechanism in **Hyper-and Autoinflammatory Defects**?", "a": "Mevalonate kinase deficiency (MVK) can have a spectrum of clinical disease and severity.", "img": null}, {"id": "fc_031_17", "ch": 31, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Vedolizumab**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Vedolizumab is an anti-α4β7 integrin monoclonal antibody that reduces T cell migration into colonic tissue.", "img": null}, {"id": "fc_031_18", "ch": 31, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Janus Kinase Inhibitors**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Patients with JAK and STAT pathogenic variants are candidates for therapy using ruxolitinib (JAK 1/2 inhibitor), tofacitinib (JAK 1/3 inhibitor) and upadicitinib (JAK 1 inhibitor).", "img": null}, {"id": "fc_031_19", "ch": 31, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **IL-1 Receptor Antagonists**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** The two available inhibitors include anakinra and canakinumab.", "img": null}, {"id": "fc_031_20", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Terminology, Definition, and Evaluation of VEO-IBD**, how is **Very early onset inflammatory bowel disease (VEO-IBD)** defined and characterized?", "a": "Very early onset inflammatory bowel disease (VEO-IBD) is a descriptive term arbitrarily assigned to a subgroup of pediatric IBD with onset <6 years of age.", "img": null}, {"id": "fc_031_21", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Terminology, Definition, and Evaluation of VEO-IBD**, how is **Pediatric IBD** defined and characterized?", "a": "Pediatric IBD patients age ≥6 years are believed to have the common form of IBD and share the same etiology and clinical presentation with adult onset IBD.", "img": null}, {"id": "fc_031_22", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Terminology, Definition, and Evaluation of VEO-IBD**, how is **infantile** defined and characterized?", "a": "infantile inflammatory bowel disease with onset <2 years of age and neonatal onset inflammatory bowel disease with onset <28 days of age.", "img": null}, {"id": "fc_031_23", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Imaging**, how is **Severe combined immunodeficiency (SCID)** defined and characterized?", "a": "Severe combined immunodeficiency (SCID) presents with epithelial cell apoptosis, and eosinophilic or neutrophilic infiltrates with villous atrophy.", "img": null}, {"id": "fc_031_24", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Imaging**, how is **Chronic granulomatous disease (CGD)** defined and characterized?", "a": "Chronic granulomatous disease (CGD) has a prevalence of noncaseating granulomas without significant surrounding inflammation, eosinophils, or pigmented macrophages.", "img": null}, {"id": "fc_031_25", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Imaging**, how is **IPEX syndrome** defined and characterized?", "a": "IPEX syndrome has villous blunting and chronic inflammation within the lamina propria.", "img": null}, {"id": "fc_031_26", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Imaging**, how is **Hermansky-Pudlak syndrome** defined and characterized?", "a": "Hermansky-Pudlak syndrome can have pigmented macrophages and granulomas.", "img": null}, {"id": "fc_031_27", "ch": 31, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hyper-and Autoinflammatory Defects**, how is **Mevalonate kinase deficiency (MVK)** defined and characterized?", "a": "Mevalonate kinase deficiency (MVK) can have a spectrum of clinical disease and severity.", "img": null}, {"id": "fc_031_28", "ch": 31, "part": "V", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 31.1):", "a": "Schematic overview over monogenic defects involved in early-onset inflammatory bowel disease with or without accompanying susceptibility to infections. Figure conceptualized by Artem Kalinichenko (Boztug lab).", "img": "fig_p0712_01.jpg"}, {"id": "fc_032_01", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Type IV Waardenburg syndrome**?", "a": "**Causative Gene(s):** `SOX10` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: Autosomal dominant — Phenotype: Peripheral neuropathy with hypomyelination, sensorineural deafness and pseudo-obstruction — Age of Onset: Neonatal period", "img": null}, {"id": "fc_032_02", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Congenital myopathy and gastrointestinal pseudo-obstruction**?", "a": "**Causative Gene(s):** `POLG1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** POLG1(DNApolymerase gamma) — Inheritance: Autosomal recessive — Phenotype: Associated with mitochondrial depletion and deletions. Severe hypotonia and generalized muscle weakness, severe abdominal distension and hypoactive bowel — Age of Onset: Neonatal period", "img": null}, {"id": "fc_032_03", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Chronic idiopathic intestinal pseudo-obstruction (CIIPX)**?", "a": "**Causative Gene(s):** `FLNA` · **Inheritance:** XLR\n\n**Clinical & Molecular Profile:** FLNA(filamin A) — Inheritance: X-linked recessive — Phenotype: Abnormal filamin A leads to cytoskeletal abnormalities and potentially disrupts enteric-neuron structure and function. Seizures and progressive abdominal distension and obstruction — Age of Onset: Neonatal period", "img": null}, {"id": "fc_032_04", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hydrocephalus with stenosis of the aqueduct of Sylvius (HSAS) and congenital idiopathic intestinal pseudo-obst**?", "a": "**Causative Gene(s):** `L1CAM` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** L1CAM(L1 cell adhesion molecule) — Inheritance: Autosomal recessive — Phenotype: Defect in the differentiation of the interstitial cells of Cajal leading to progressive distension and intermittent episodes of obstruction — Age of Onset: Neonatal period", "img": null}, {"id": "fc_032_05", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Familial visceral myopathy; megacystis-microcolonintestinal hypoperistalsis syndrome**?", "a": "**Causative Gene(s):** `ACTG2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** ACTG2 (enteric smooth muscle actin– gamma 2) — Inheritance: Autosomal dominant, sporadic — Phenotype: Altered ACTG2 protein in the muscularis propria leads to impaired contractility — Age of Onset: Neonatal to third decade in life", "img": null}, {"id": "fc_032_06", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Megacystis-microcolonintestinal hypoperistalsis syndrome**?", "a": "**Causative Gene(s):** `MYH11` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** MYH11(myosin heavy chain 11) — Inheritance: Autosomal recessive — Phenotype: Abnormal MYH11 in smooth muscle myosin leads to impaired contractility — Age of Onset: Neonatal to third decade in life", "img": null}, {"id": "fc_032_07", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Multiple endocrine neoplasia type 2B**?", "a": "**Causative Gene(s):** `RET` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** RET protoonco gene (receptor tyrosine kinase) — Inheritance: Autosomal dominant — Phenotype: Gain-of-function variant associated with intestinal ganglioneuromas leading to increased cell number in the myenteric plexus and dysmotility — Age of Onset: Infancy to third decade of life", "img": null}, {"id": "fc_032_08", "ch": 32, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Mungan syndrome**?", "a": "**Causative Gene(s):** `RAD21` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: Autosomal recessive — Phenotype: Pseudo-obstruction, megaduodenum, long segment Barrett esophagus, and cardiac abnormalities — Age of Onset: First to second decade of life", "img": null}, {"id": "fc_032_09", "ch": 32, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MYH11`** are associated with which clinical phenotype and molecular mechanism in **Etiology**?", "a": "Five genes (ACTG2, LMOD1, MYH11, MYLK, MYL9) have been linked to this syndrome.", "img": null}, {"id": "fc_032_10", "ch": 32, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ACTG2`** are associated with which clinical phenotype and molecular mechanism in **Etiology**?", "a": "ACTG2 is the most commonly described gene with pathogenic variants.", "img": null}, {"id": "fc_032_11", "ch": 32, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SGOL1`** are associated with which clinical phenotype and molecular mechanism in **Primary Pediatric Intestinal Pseudo-Obstruction With Identified Genetic Pathogenic Variants—cont’d**?", "a": "Chronic atrial and intestinal dysrhythmia (CAID) syndrome is caused by the homozygous pathogenic variants of SGOL1 and is characterized by pacemaker failure in both the heart and gut leading to cardiac arrhythmias and chronic intestinal pseudo-obstruction.", "img": null}, {"id": "fc_032_12", "ch": 32, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`POLG`** are associated with which clinical phenotype and molecular mechanism in **Primary Pediatric Intestinal Pseudo-Obstruction With Identified Genetic Pathogenic Variants—cont’d**?", "a": "PIPO has also been reported in association with other mitochondrial disorders such as Alpers disease (POLG) and mitochondrial encephalopathy, lactic acidosis, and strokelike episodes syndrome (MELAS) .", "img": null}, {"id": "fc_032_13", "ch": 32, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NOTCH2NLC`** are associated with which clinical phenotype and molecular mechanism in **Miscellaneous**?", "a": "Longread sequencing has identified GGC repeat expansions in NOTCH2NLC to be associated with neuronal intranuclear inclusion disease.", "img": null}, {"id": "fc_032_14", "ch": 32, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`LCT`** are associated with which clinical phenotype and molecular mechanism in **Nutrition**?", "a": "Medium-chain triglycerides (MCT) are associated with a faster GI transit time in neonates and may be better tolerated than long-chain triglycerides (LCT) in PIPO.", "img": null}, {"id": "fc_032_15", "ch": 32, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **5HT-4 Agonists**?", "a": "**Therapy / Intervention:** 5HT-4 Agonists\n\n**Clinical Context:**", "img": null}, {"id": "fc_032_16", "ch": 32, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Cisapride**?", "a": "**Therapy / Intervention:** Cisapride\n\n**Clinical Context:** Dosage: 0.2–0.3 mg/kg/dose 3–4 times a day, 30 min prior to a meal — Mechanism: 5HT4 agonist with acetylcholine release in the gut. 5HT3 antagonist — Side Effect: Nausea Vomiting Diarrhea Constipation Abdominal cramps He", "img": null}, {"id": "fc_032_17", "ch": 32, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Prucalopride**?", "a": "**Therapy / Intervention:** Prucalopride\n\n**Clinical Context:** Dosage: 0.02–0.04 mg/kg/day max 2 mg daily — Mechanism: 5HT4 agonist with acetylcholine release in the gut — Side Effect: Nausea Vomiting Diarrhea Abdominal pain Headache Mild tachycardia", "img": null}, {"id": "fc_032_18", "ch": 32, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Cholinergics**?", "a": "**Therapy / Intervention:** Cholinergics\n\n**Clinical Context:**", "img": null}, {"id": "fc_032_19", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Etiology**, how is **Mitochondrial myopathies** defined and characterized?", "a": "Mitochondrial myopathies can also present with features of intestinal pseudo-obstruction.", "img": null}, {"id": "fc_032_20", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Primary Pediatric Intestinal Pseudo-Obstruction With Identified Genetic Pathogenic Variants—cont’d**, how is **Neurocristopathies** defined and characterized?", "a": "Neurocristopathies are disorders associated with defects of neural crest cell development.", "img": null}, {"id": "fc_032_21", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Primary Pediatric Intestinal Pseudo-Obstruction With Identified Genetic Pathogenic Variants—cont’d**, how is **Hirschsprung disease (HD)** defined and characterized?", "a": "Hirschsprung disease (HD) is a form of neurocristopathy characterized by absence of ganglion cells in the submucosal and myenteric plexuses over a variable length of the distal part of the gut leading to signs of intestinal obstruction.", "img": null}, {"id": "fc_032_22", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Primary Pediatric Intestinal Pseudo-Obstruction With Identified Genetic Pathogenic Variants—cont’d**, how is **hypoganglionosis** defined and characterized?", "a": "hypoganglionosis , along with HD-like involvement of the colon.", "img": null}, {"id": "fc_032_23", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Primary Pediatric Intestinal Pseudo-Obstruction With Identified Genetic Pathogenic Variants—cont’d**, how is **Alpers disease** defined and characterized?", "a": "Alpers disease (POLG) and mitochondrial encephalopathy, lactic acidosis, and strokelike episodes syndrome (MELAS) .", "img": null}, {"id": "fc_032_24", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Miscellaneous**, how is **Neuronal intranuclear inclusion disease** defined and characterized?", "a": "Neuronal intranuclear inclusion disease is a rare neurodegenerative disorder that can affect the central, peripheral, and/or autonomic nervous system.", "img": null}, {"id": "fc_032_25", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Miscellaneous**, how is **Diffuse intestinal ganglioneuromatosis** defined and characterized?", "a": "Diffuse intestinal ganglioneuromatosis is characterized by diffusely distributed transmural hamartomatous lesions which are composed of benign ganglion cells.", "img": null}, {"id": "fc_032_26", "ch": 32, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Miscellaneous**, how is **Intestinal myenteric hypoganglionosis** defined and characterized?", "a": "Intestinal myenteric hypoganglionosis presents with severe and persistent neonatal intestinal pseudo-obstruction.", "img": null}, {"id": "fc_032_27", "ch": 32, "part": "V", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 32.1):", "a": "Schematic representation of the enteric nervous system and connections between the neurons in the submucosal and myenteric plexus. The submucosal plexus is mainly responsible for regulating bowel secretions and blood supply. The myenteric plexus, which is located between the circular and longitudinal smooth muscle layers, regulates the bowel motor function. The interstitial cells of Cajal act as the pacemaker cells for the intestinal myocytes. The gastrointestinal tract also receives innervation from the autonomic nervous system (not shown).", "img": "fig_p0733_02.jpg"}, {"id": "fc_032_28", "ch": 32, "part": "V", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 32.2):", "a": "Synoptic view of the chronic intestinal pseudo-obstruction (CIPO) spectrum. (A and B) The most severe pediatric cases with antenatal (in utero) evidence of multivisceral dilation, often gut (B) and urinary system, commonly associated with an extremely poor prognosis. (C and D) CIPO phenotype with rapid progression to intestinal dilation (± ureter/bladder) and failure, often occurring as a result of an anamnestically reported gastroenteritis. Massive bowel dilation (C) and associated histopathology (D; corresponds to white squared area in C) revealed an intense inflammatory (mainly lymphocytic) neuropathy (hence, myenteric ganglionitis). Alkaline phosphatase anti-alkaline phosphatase immunohistochemical technique using specific anti-CD8 monoclonal antibodies was used to identify a subset of T lymphocytes. (E and G) Examples of another phenotype of the syndrome that may be seen in patients who have more insidious mild and nonspecific symptoms progressing to a classic CIPO over time. (E) Markedly distended abdomen of a 32-year-old man who presented with subocclusive episodes after years of unspecific (dyspeptic-like/irritable bowel syndrome–like) symptoms. Note the evident airfluid levels detectable in upright position in anteroposterior (F) and laterolateral (G) plain abdominal radiographs. (B–G from Di Nardo G, Di Lorenzo C, Lauro A, et al. Chronic intestinal pseudo-obstruction in children and adults: diagnosis and therapeutic options. _Neurogastroenterol Mot", "img": "fig_p0737_02.jpg"}, {"id": "fc_033_01", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hartnup disorder**?", "a": "**Causative Gene(s):** `SLC6A19` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Malabsorbed Substrate(s): Neutral amino acids (tryptophan, leucine, methionine, phenylalanine, tyrosine, valine, ?histidine, ?lysine) — Decreased intestinal absorption of free neutral amino acids i — Clinical Features: Most patients are asymptomatic; some patients have photosensitive skin rash, intermittent ataxi", "img": null}, {"id": "fc_033_02", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Cystinuria (types A, B, AB)**?", "a": "**Causative Gene(s):** `SLC3A1, SLC7A9` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Causative Gene: Type A: SLC3A1 Type B: SLC7A9 — Mode of Inheritance: AR (type A) and incomplete AR (type B) — Malabsorbed Substrate(s): Cystine and/or dibasic amino acids (lysine, ornithine, arginine) — Decreased intestinal absorption of specific free amino acids owing to a defective amino acid transporter at the brush border membrane Typ", "img": null}, {"id": "fc_033_03", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Lysinuric protein intolerance**?", "a": "**Causative Gene(s):** `SLC7A7` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Malabsorbed Substrate(s): Dibasic amino acids (lysine, ornithine, arginine) — Defect of the basolateral transporter (y+LAT-1) for dibasic amino acids (also malabsorption of di- and oligopeptides) — Clinical Features: Sparse hair, hyperammonemia, nausea, vomiting, diarrhea, protein malnutrition, failure to thrive,", "img": null}, {"id": "fc_033_04", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Iminoglycinuria**?", "a": "**Causative Gene(s):** `SLC6A20, SLC6A19, SLC36A2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Causative Gene: SLC6A20 SLC6A19 SLC36A2 — Mode of Inheritance: AR — Malabsorbed Substrate(s): l-Proline — Impaired intestinal absorption of l-proline in a subgroup of subjects — Clinical Features: Aminoaciduria; benign disorder", "img": null}, {"id": "fc_033_05", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Lowe oculocerebral syndrome**?", "a": "**Causative Gene(s):** `OCRL1` · **Inheritance:** XR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: XR — Malabsorbed Substrate(s): Lysine, arginine — Impaired intestinal lysine and arginine absorption — Clinical Features: Aminoaciduria, intellectual disability, cataracts, rickets, choreoathetosis, renal disease", "img": null}, {"id": "fc_033_06", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Congenital lactase deficiency**?", "a": "**Causative Gene(s):** `LCT` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Malabsorbed Substrate(s): Lactose — Permanent very low lactase activity — Clinical Features: Diarrhea, bloating, and dehydration in the first days of life", "img": null}, {"id": "fc_033_07", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Sucrase-isomaltase deficiency**?", "a": "**Causative Gene(s):** `SI` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Malabsorbed Substrate(s): Sucrose, starch — Sucrase activity is absent; isomaltase activity is absent or reduced; reduced maltase activity — Clinical Features: Osmotic diarrhea after starch or sucrose ingestion; failure to thrive", "img": null}, {"id": "fc_033_08", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Glucose-galactose malabsorption**?", "a": "**Causative Gene(s):** `SLC5A1, SGLT1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Malabsorbed Substrate(s): Glucose, galactose — Defect of the brush border sodium-glucose co-transporter (SGLT1) — Clinical Features: Neonatal onset of osmotic diarrhea, dehydration, intermittent or constant glycosuria", "img": null}, {"id": "fc_033_09", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Chylomicron retention disease (Anderson disease)**?", "a": "**Causative Gene(s):** `SAR1B` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Malabsorbed Substrate(s): Fat — Defective chylomicron formation and accumulation in the enterocyte — Clinical Features: Steatorrhea, failure to thrive, absence of chylomicrons and reduced LDL levels in the blood; neurological symptoms in some patients", "img": null}, {"id": "fc_033_10", "ch": 33, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Transcobalamin II deficiency**?", "a": "**Causative Gene(s):** `TCN2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Mode of Inheritance: AR — Malabsorbed Substrate(s): Cobalamin (vitamin B12) — Defective transport of cobalamin out of enterocytes into the portal blood owing to absence or malfunction of transcobalamin II — Clinical Features: Vomiting, diarrhea, failure to thrive, anemia, immunodeficiency, neurological symptoms", "img": null}, {"id": "fc_033_11", "ch": 33, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SGLT1`** are associated with which clinical phenotype and molecular mechanism in **Carbohydrate Malabsorption Disorders**?", "a": "The active transport of glucose and galactose absorption is achieved by the sodium-dependent glucose co-transporter (SGLT1), while fructose is transported by facilitated diffusion (GLUT5 transporter) from the intestinal lumen into the enterocytes.", "img": null}, {"id": "fc_033_12", "ch": 33, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SI`** are associated with which clinical phenotype and molecular mechanism in **Sucrase-Isomaltase Deficiency**?", "a": "The sucrase-isomaltase (SI) gene, mapped to chromosome 3q26.1, codes for sucrase-isomaltase, a heterodimeric protein with two subunits, sucrase and isomaltase.", "img": null}, {"id": "fc_033_13", "ch": 33, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MTTP`** are associated with which clinical phenotype and molecular mechanism in **Fat Malabsorption**?", "a": "Microsomal triglyceride transfer protein (MTTP) shuttles TG, CE, and PL to the structural Apo B-48 to promote chylomicron (CM) assembly.", "img": null}, {"id": "fc_033_14", "ch": 33, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`DGAT1`** are associated with which clinical phenotype and molecular mechanism in **DGAT1 Defects**?", "a": "DGAT1 encodes the DGAT1 protein, a microsomal enzyme with abundant expression in the small intestine.", "img": null}, {"id": "fc_033_15", "ch": 33, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PRRS1`** are associated with which clinical phenotype and molecular mechanism in **Congenital Enterokinase Deficiency and Congenital Trypsinogen Deficiency**?", "a": "Congenital trypsinogen deficiency is related to a pathogenic variant of PRRS1 on chromosome 7q35 inducing an absence of trypsinogenic activity.", "img": null}, {"id": "fc_033_16", "ch": 33, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SLC7A7`** are associated with which clinical phenotype and molecular mechanism in **Lysinuric Protein Intolerance**?", "a": "Lysinuric protein intolerance is caused by a pathogenic variant of SLC7A7 on chromosome 14q11 which has a role in the hydrolysis of exoand endopeptidases and amino acid basolateral transport.", "img": null}, {"id": "fc_033_17", "ch": 33, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Sucrase-Isomaltase Deficiency**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Enzyme replacement therapy with sacrosidase may be instituted, allowing for a return to close-to-normal intestinal activity.", "img": null}, {"id": "fc_033_18", "ch": 33, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Severe Combined Immunodeficiency**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** The condition is fatal, usually within the first year or two of life, unless infants receive immune-restoring treatments, such as stem cell transplants, gene therapy, or enzyme therapy.", "img": null}, {"id": "fc_033_19", "ch": 33, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Chronic Granulomatous Disease (CGD)**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Hematopoietic stem cell transplantation from an HLA-identical donor can be curative for CGD, and gene therapy may be an option in the future.", "img": null}, {"id": "fc_033_20", "ch": 33, "part": "V", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Treatment**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Intestinal resection or anastomosis of abnormal lymphatics to venous channels may be beneficial for selected patients or use of octreotide.", "img": null}, {"id": "fc_033_21", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Rare Inborn Defects Causing Malabsorption**, how is **absorption** defined and characterized?", "a": "absorption involves the entry of the nutrient into the enterocyte at the apical pole and its secretion at the basolateral pole into the systemic circulation.", "img": null}, {"id": "fc_033_22", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Fat Malabsorption**, how is **pancreas** defined and characterized?", "a": "pancreas and delivered through the exocrine acinar cells together with an alkaline mixture composed of water and bicarbonate, to maintain the ideal pH for enzyme activity.", "img": null}, {"id": "fc_033_23", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Fat Malabsorption**, how is **Bile salts** defined and characterized?", "a": "Bile salts , released from gallbladder stores, assist in breaking down large fat globules into small droplets, forming micelles and solubilizing the lipids allowing enzymes to get to emulsified lipid droplets.", "img": null}, {"id": "fc_033_24", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Genetic Conditions Affecting Lipid Digestion and Malabsorption**, how is **Niemann-Pick C1-Like 1 (NPC1L1)** defined and characterized?", "a": "Niemann-Pick C1-Like 1 (NPC1L1) mediates CHOL trafficking from the apical microvillus membrane to the ER.", "img": null}, {"id": "fc_033_25", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Genetic Conditions Affecting Lipid Digestion and Malabsorption**, how is **Intestinal SR-BI** defined and characterized?", "a": "Intestinal SR-BI is understood to be more involved in postprandial TG handling than in CHOL uptake and is a critical regulator of CM transport.", "img": null}, {"id": "fc_033_26", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Genetic Conditions Affecting Lipid Digestion and Malabsorption**, how is **Angiopoietin-like Protein 4 (ANGPTL4)** defined and characterized?", "a": "Angiopoietin-like Protein 4 (ANGPTL4) and ANGPTL3 inhibit lipoprotein lipase (LPL) activity through unfolding and destabilization, leading to its degradation.", "img": null}, {"id": "fc_033_27", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Protein Malabsorption**, how is **enteropeptidase** defined and characterized?", "a": "enteropeptidase (formerly called enterokinase), a jejunal brush-border enzyme that is released by the action of bile salts.", "img": null}, {"id": "fc_033_28", "ch": 33, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Protein Malabsorption**, how is **aminopeptidases** defined and characterized?", "a": "aminopeptidases located on the brush-border membranes to free amino acids and di- and tripeptides.", "img": null}, {"id": "fc_034_01", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Digestive tract**?", "a": "**Causative Gene(s):** `FIC1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** • Cystic fibrosis (meconium ileus, exocrine pancreatic insufficiency) • FIC1 deficiency (diarrhea, exocrine pancreatic insufficiency) • Myosin Vb deficiency (congenital diarrhea) • Unc45A deficiency (congenital diarrhea) • Wolman disease (diarrhea, abdominal distension) • BASD (diarrhea, steatorrhea) — SeeTable 34.4 SeeTable 34.4 SeeTable", "img": null}, {"id": "fc_034_02", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Kidney**?", "a": "**Causative Gene(s):** `DCDC2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** • ARC syndrome (proximal tubulopathy) • Peroxisomal disease (renal cysts) • 3β-HSD deficiency (renal cysts) • DCDC2 deficiency (renal cysts) • HNF1βdeficiency (renal cysts, tubulopathy) — SeeTable 34.4 SeeTable 34.4 SeeTable 34.4 SeeTable 34.4 SeeTable 34.4", "img": null}, {"id": "fc_034_03", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Metabolic diseases**?", "a": "**Causative Gene(s):** `POLG, MPV17, NPC1, NPC2, SCYL1, RINT1` · **Inheritance:** mtDNA\n\n**Clinical & Molecular Profile:** • Tyrosinemia type I(FAH) • Galactosemia(GALT) • Mitochondrial disorders including MDS(DGUOK, POLG, MPV17, TWINK, TRMU) • Niemann-Pick type C(NPC1, NPC2) • Adenosine kinase deficiency(ADK) • Recurrent liver failure syndrome (NBAS, SCYL1, RINT1) • Citrin deficiency(SLC25A13) • Transaldolase deficiency(TALDO1) • Glycogen storage disease typ", "img": null}, {"id": "fc_034_04", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hepatocellular cholestasis**?", "a": "**Causative Gene(s):** `ABCB11` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** • Familial cholestasis (especially NR1H4, ABCB11) • BASD (especiallyAKR1D1)", "img": null}, {"id": "fc_034_05", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Intrahepatic (47.5%)**?", "a": "**Causative Gene(s):** `CCDC115` · **Inheritance:** mtDNA\n\n**Clinical & Molecular Profile:** Genetic cholestasis(Table 34.4) •α1-antitrypsin deficiency • Alagille syndrome • Progressive familial intrahepatic cholestasis • Cystic fibrosis • BASD, including peroxisomal defects. Genetic metabolic disorders: • Citrin deficiency • Lysosomal storage diseases (Niemann-Pick type C, Gaucher disease, Wolman disease, acid sphingomyelinase d", "img": null}, {"id": "fc_034_06", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **3β-hydroxy-Δ-C27-steroid oxidoreductase deficiency** (#607764)?", "a": "**Causative Gene(s):** `HSD3B7` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** γGT: N — Gene (MIM Phenotype): HSD3B7 (#607764) — Inheritance: AR — Main Features: Fat malabsorption, FSV deficiency, no pruritus, low sBA, atypical bile acids in urine", "img": null}, {"id": "fc_034_07", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Δ-3-oxosteroid-5β- reductase deficiency** (#604741)?", "a": "**Causative Gene(s):** `AKR1D1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** γGT: N — Gene (MIM Phenotype): AKR1D1 (#604741) — Inheritance: AR — Main Features: Liver failure, Fat malabsorption, FSV deficiency, no pruritus, low sBA, atypical bile acids in urine", "img": null}, {"id": "fc_034_08", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Oxysterol 7α-hydroxylase deficiency** (#603711)?", "a": "**Causative Gene(s):** `CYP7B1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** γGT: N — Gene (MIM Phenotype): CYP7B1 (#603711) — Inheritance: AR — Main Features: Early liver failure, low sBA, atypical bile acids in urine", "img": null}, {"id": "fc_034_09", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Sterol 27-hydroxylase deficiency (CTX)** (#606530)?", "a": "**Causative Gene(s):** `CYP27A1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** γGT: N — Gene (MIM Phenotype): CYP27A1 (#606530) — Inheritance: AR — Main Features: TNC, low sBA, increased plasma cholestanol, neurocognitive involvement/cataract later in life, atypical bile alcohols in urine", "img": null}, {"id": "fc_034_10", "ch": 34, "part": "V", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Bile acid-CoA amino acid N-acyltransferase deficiency** (#602938)?", "a": "**Etiology:** Genomic / Rare Syndrome · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** γGT: N — Gene (MIM Phenotype): BAAT (#602938) — Inheritance: AR — Main Features: Fat malabsorption, FSV deficiency, atypical bile acids in urine", "img": null}, {"id": "fc_034_11", "ch": 34, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MDR3`** are associated with which clinical phenotype and molecular mechanism in **Diagnostic Approach to Neonatal and Infantile Cholestasis**?", "a": "Immunohistochemical studies using a panel of antibodies against CK7/19, CD68, BSEP, MDR3, TJP2, MYO5B, among others, may contribute to establish a diagnosis.", "img": null}, {"id": "fc_034_12", "ch": 34, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CFC1`** are associated with which clinical phenotype and molecular mechanism in **Anatomical Classification of Neonatal and Infantile Cholestasis**?", "a": "Pathogenic variants in CFC1 are noted in some patients with BASM.", "img": null}, {"id": "fc_034_13", "ch": 34, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KIF12`** are associated with which clinical phenotype and molecular mechanism in **Most Frequent Genetic Causes of Neonatal and Infantile Cholestasis**?", "a": "Several proteins are involved in the expression of BSEP, such as the nuclear receptor FXR, or its trafficking, such as Myosin Vb, VIPAS39/VPS33B, VPS50, UNC45A, and KIF12.", "img": null}, {"id": "fc_034_14", "ch": 34, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ZFYVE19`** are associated with which clinical phenotype and molecular mechanism in **Most Frequent Genetic Causes of Neonatal and Infantile Cholestasis**?", "a": "Finally, transporters, such as CFTR, and primary cilia associated proteins, such as DCDC2 and ZFYVE19, are also important for cholangiocyte function.", "img": null}, {"id": "fc_034_15", "ch": 34, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FIC1`** are associated with which clinical phenotype and molecular mechanism in **Genetic Hepatocellular Cholestasis**?", "a": "Familial intrahepatic cholestasis protein 1 (FIC1) deficiency is due to pathogenic variation(s) in ATP8B1 , encoding an aminophospholipid flippase expressed in most tissues including liver, intestine, pancreas, and cochlea.", "img": null}, {"id": "fc_034_16", "ch": 34, "part": "V", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ABCB4`** are associated with which clinical phenotype and molecular mechanism in **Genetic Hepatocellular Cholestasis**?", "a": "Multidrug resistance protein 3 (MDR3) deficiency is due to variations in ABCB4 , encoding a phosphatidylcholine (PC) floppase (Table 34.4 and Fig. 34.3).", "img": null}, {"id": "fc_034_17", "ch": 34, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnostic Approach to Neonatal and Infantile Cholestasis**, how is **Alpha1-antitrypsin (A1AT) deficiency** defined and characterized?", "a": "Alpha1-antitrypsin (A1AT) deficiency , Alagille syndrome (ALGS) and to a lesser extent cystic fibrosis (CF) should be promptly investigated (Fig.", "img": null}, {"id": "fc_034_18", "ch": 34, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnostic Approach to Neonatal and Infantile Cholestasis**, how is **familial hemophagocytic lymphohistiocytosis** defined and characterized?", "a": "familial hemophagocytic lymphohistiocytosis and severe hemolytic conditions such as Rh incompatibility or severe glucose-6-phosphate dehydrogenase deficiency may also manifest as NIC with splenomegaly.", "img": null}, {"id": "fc_034_19", "ch": 34, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnostic Approach to Neonatal and Infantile Cholestasis**, how is **intrahepatic cholestasis of pregnancy (ICP)** defined and characterized?", "a": "intrahepatic cholestasis of pregnancy (ICP) and/or of biliary lithiasis, especially low phospholipid associated cholelithiasis syndrome (LPAC) , or personal medical history of prematurity, anoxia, and/or prolonged parenteral nutrition.", "img": null}, {"id": "fc_034_20", "ch": 34, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Therapeutic Management**, how is **bile acid synthesis disorders (BASD)** defined and characterized?", "a": "bile acid synthesis disorders (BASD) , cortisol deficiency/panhypopituitarism, and infections, which may be treated with primary bile acids, hydrocortisone, and antibiotics, respectively.", "img": null}, {"id": "fc_034_21", "ch": 34, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Anatomical Classification of Neonatal and Infantile Cholestasis**, how is **polysplenia syndrome** defined and characterized?", "a": "polysplenia syndrome (polysplenia, preduodenal portal vein, azygos continuation of the vena cava, and abdominal and/or thoracic laterality defects, including median liver or abdominal situs inversus), referred to as biliary atresia with splenic malformation syndrome (BASM) .", "img": null}, {"id": "fc_034_22", "ch": 34, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Genetic Hepatocellular Cholestasis**, how is **microvillus inclusion disease (MVID)** defined and characterized?", "a": "microvillus inclusion disease (MVID) and normal gGT cholestasis (Table 34.", "img": null}, {"id": "fc_034_23", "ch": 34, "part": "V", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Genetic Hepatocellular Cholestasis**, how is **oto-osteo-hepato-enteric syndrome** defined and characterized?", "a": "oto-osteo-hepato-enteric syndrome , manifests as chronic normal γGT cholestasis associated with a MVID-like enteropathy and may mimic myosin Vb deficiency.", "img": null}, {"id": "fc_034_24", "ch": 34, "part": "V", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 34.1):", "a": "Global diagnosis approach of cholestasis of the newborn and young infant: initial evaluation. A1AT, Alpha1-antitrypsin; CPSS, congenital portosystemic shunt; GALD, gestational alloimmune liver disease; HLH, hemophagocytic lymphohistiocytosis; MD, mitochondrial disease; US, ultrasound.", "img": "fig_p0770_01.jpg"}, {"id": "fc_034_25", "ch": 34, "part": "V", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 34.2):", "a": "Neonatal and infantile cholestasis diagnostic approach in patients with normally colored stools or with normal cholangiography. A1AT, Alpha1-antitrypsin; CPSS, congenital portosystemic shunt; gGT , γ-glutamyl transferase; IHC, immunohistochemistry; MDR3, multidrug resistance protein 3; MRI, magnetic resonance imaging; MS, mass spectrometry; NC, neonatal cholestasis; NSC, neonatal sclerosing cholangitis.", "img": "fig_p0771_02.jpg"}, {"id": "fc_034_26", "ch": 34, "part": "V", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Extrahep i atic Features Suggestive of Specific Diagnosis in Presence i of Neonatal and Infantile Cholestasis**, what are the distinguishing features of **Facial dysmorphia**?", "a": "**Diseases (Evocative Clinical Symptoms)**: • Alagille syndrome • Smith-Lemli-Opitz syndrome • Peroxisomal disease • Transaldolase deficiency • Adenosine kinase deficiency • ARC syndrome; **Suggestive Biochemical and Imaging Findings**: SeeTable 34.4 Plasma 7-dehydrocholesterol SeeTable 34.4 Urinary polyols Highly elevated plasma methionine SeeTable 34.4", "img": null}, {"id": "fc_034_27", "ch": 34, "part": "V", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Extrahep i atic Features Suggestive of Specific Diagnosis in Presence i of Neonatal and Infantile Cholestasis**, what are the distinguishing features of **Heart**?", "a": "**Diseases (Evocative Clinical Symptoms)**: • Alagille syndrome (pulmonary artery stenosis and other congenital heart defects) • Smith-Lemli-Opitz syndrome (atrioventricular shunt, patent ductus arteriosus) • Transaldolase deficiency (atrioseptal defects) • CPSS (congenital heart defects, laterality defect); **Suggestive Biochemical and Imaging Findings**: SeeTable 34.4 Plasma 7-dehydrocholesterol Urinary polyols Doppler ultrasound", "img": null}, {"id": "fc_034_28", "ch": 34, "part": "V", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Extrahep i atic Features Suggestive of Specific Diagnosis in Presence i of Neonatal and Infantile Cholestasis**, what are the distinguishing features of **Central nervous system**?", "a": "**Diseases (Evocative Clinical Symptoms)**: • Peroxisomal disease (hypotonia, blindness, deafness) • Mitochondrial disorder (hypotonia, nystagmus) • ARC syndrome (arthrogryposis) • Smith-Lemli-Opitz syndrome (microcephaly) • Panhypopituitarism/PSIS (central nervous system and midline malformations); **Suggestive Biochemical and Imaging Findings**: SeeTable 34.4 L/P ratio, MRI (lactate spectroscopy) SeeTable 34.4 Plasma 7-dehydrocholesterol Hormonal testing, brain MRI", "img": null}, {"id": "fc_035_01", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NPHS1**?", "a": "**Causative Gene(s):** `NPHS1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: Nephrin — yndromes Ca: AR — tegorized A: 19q13.1 — CNS, SRNS (NPHS1)", "img": null}, {"id": "fc_035_02", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NPHS2**?", "a": "**Causative Gene(s):** `NPHS2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: Podocin — yndromes Ca: AR — tegorized A: 1q25–q31 — CNS, SRNS (NPHS2)", "img": null}, {"id": "fc_035_03", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PLCE1**?", "a": "**Causative Gene(s):** `PLCE1, NPHS3` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: Phospholipase C,ε1 — yndromes Ca: AR — tegorized A: 10q23 — DMS, SRNS (NPHS3)", "img": null}, {"id": "fc_035_04", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CD2AP**?", "a": "**Causative Gene(s):** `CD2AP, FSGS3` · **Inheritance:** AD / AR\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: CD2-associated protein — yndromes Ca: AD/AR — tegorized A: 6p12.3 — SRNS (FSGS3)", "img": null}, {"id": "fc_035_05", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FAT1**?", "a": "**Causative Gene(s):** `FAT1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** yndromes Ca: AR — tegorized A: 4q35.2 — NS, ciliopathy", "img": null}, {"id": "fc_035_06", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ACTN4**?", "a": "**Causative Gene(s):** `ACTN4, FSGS1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: α-Actinin-4 — yndromes Ca: AD — tegorized A: 19q13 — Late-onset SRNS (FSGS1)", "img": null}, {"id": "fc_035_07", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SRNS (FSGS5), Charcot-Marie-Tooth disease with glomerulopathy**?", "a": "**Causative Gene(s):** `INF2, FSGS5` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: Inverted formin-2 — yndromes Ca: AD", "img": null}, {"id": "fc_035_08", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Macrothrombocytopenia with sensorineural deafness, Epstein syndrome, Sebastian syndrome, Fechtner syndrome**?", "a": "**Causative Gene(s):** `MYH9` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: Myosin, heavy chain 9 — yndromes Ca: AD — tegorized A: 22q12. 3–13.1", "img": null}, {"id": "fc_035_09", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **MYO1E**?", "a": "**Causative Gene(s):** `MYO1E, FSGS6` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: Myosin IE — yndromes Ca: AR — tegorized A: 15q22.2 — Childhood-onset SRNS (FSGS6)", "img": null}, {"id": "fc_035_10", "ch": 35, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ARHGDIA**?", "a": "**Causative Gene(s):** `NPHS8` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** etic Causes of Nephrotic S: Rho GDP-dissociation inhibitor (GDI) a1 — yndromes Ca: AR — tegorized A: 17q25.3 — Childhood-onset SRNS (NPHS8), seizures, cortical blindness", "img": null}, {"id": "fc_035_11", "ch": 35, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`LAMB2`** are associated with which clinical phenotype and molecular mechanism in **Pierson Syndrome**?", "a": "Pierson syndrome (MIM #609049) is a rare autosomal recessive disorder caused by variants in LAMB2 , located on chromosome 3p21.31 and consisting of 32 exons.", "img": null}, {"id": "fc_035_12", "ch": 35, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PLCE1`** are associated with which clinical phenotype and molecular mechanism in **Phospholipase C Epsilon 1**?", "a": "Biallelic pathogenic variants in the phospholipase C epsilon 1 (PLCE1) gene cause an autosomal recessive form of earlyonset nephrotic syndrome.", "img": null}, {"id": "fc_035_13", "ch": 35, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PMM2`** are associated with which clinical phenotype and molecular mechanism in **Galloway-Mowat Syndrome**?", "a": "Pathogenic variants in several other genes, including WDR4 , NUP133 , NUP107 , OSGEP , LAGE3 , TP53RK , TPRKB , CON7 , PRDM15 , and PMM2 may also cause Galloway-Mowat syndrome.", "img": null}, {"id": "fc_035_14", "ch": 35, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TP53RK`** are associated with which clinical phenotype and molecular mechanism in **Galloway-Mowat Syndrome**?", "a": "Recessive variants in the genes encoding the four subunits of the KEOPS complex ( OSGEP , TP53RK , TPRKB , and LAGE3 ), which plays an important role in the brain and renal development, have also been identified in 37 affected individuals from 32 families.", "img": null}, {"id": "fc_035_15", "ch": 35, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`COQ6`** are associated with which clinical phenotype and molecular mechanism in **Mitochondrial Disorders**?", "a": "Defects of five nuclear genes (COQ2, PDSS2, COQ6, COQ8B, PDSS1) have been reported to cause early-onset nephrotic syndrome.", "img": null}, {"id": "fc_035_16", "ch": 35, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ITGB4`** are associated with which clinical phenotype and molecular mechanism in **Herlitz Junctional Epidermolysis Bullosa**?", "a": "Variants of several genes involved in the biosynthesis of collagens, integrins, or laminins have been reported, some of them in association with a nephrotic syndrome and FSGS: ITGB4 , ITGA4 , ITGA3 , LAMB3 , and CD151 .", "img": null}, {"id": "fc_035_17", "ch": 35, "part": "VI", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Fluid Management and Nutrition**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** In the case of symptomatic hypovolemia, intravenous albumin is the treatment of choice.", "img": null}, {"id": "fc_035_18", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Wilms Tumor Suppressor Gene Variants**, how is **Denys-Drash syndrome** defined and characterized?", "a": "Denys-Drash syndrome (DDS), Frasier , and WAGR (Wilms tumor, aniridia, genitourinary defects, mental retardation) syndromes , which typically manifest during childhood.", "img": null}, {"id": "fc_035_19", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Presentation**, how is **Neonatal-onset DDS** defined and characterized?", "a": "Neonatal-onset DDS is defined as nephrotic syndrome diagnosed before 1 month of age in patients with DDS.", "img": null}, {"id": "fc_035_20", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Presentation**, how is **Diffuse mesangial sclerosis** defined and characterized?", "a": "Diffuse mesangial sclerosis is a hallmark feature of DDS; the clinical course of nephropathy mirrors that of isolated diffuse mesangial sclerosis.", "img": null}, {"id": "fc_035_21", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **ocular abnormality** defined and characterized?", "a": "ocular abnormality is microcoria, characterized by fixed, extremely small pupils.", "img": null}, {"id": "fc_035_22", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Mitochondrial Disorders**, how is **coenzyme Q10 (ubiquinone) deficiency** defined and characterized?", "a": "coenzyme Q10 (ubiquinone) deficiency due to genetic variants affecting the biosynthesis of coenzyme Q10, a mobile electron carrier and antioxidant.", "img": null}, {"id": "fc_035_23", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Antiproteinuric Agents**, how is **Captopril** defined and characterized?", "a": "Captopril is considered the least harmful RAAS inhibitor for small children due to its short half-life, which allows for safer dose titration and makes it the preferred initial choice.", "img": null}, {"id": "fc_035_24", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Antiproteinuric Agents**, how is **indomethacin** defined and characterized?", "a": "indomethacin , reduce kidney perfusion and intraglomerular pressure by suppressing renin production, although their efficacy is not well established.", "img": null}, {"id": "fc_035_25", "ch": 35, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diuretics**, how is **amiloride** defined and characterized?", "a": "amiloride , as a blocker of ENaC, is preferable to other potassium-sparing diuretic, such as spironolactone.", "img": null}, {"id": "fc_035_26", "ch": 35, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 35.1):", "a": "Electron microscopy shows podocytes in normal and CNS (Human). (A) Scanning electron micrograph showing fenestrated endothelial cells lying on glomerular basement membrane (GBM). Podocytes enwrapping the capillaries from outside. (B) Transmission electron micrograph shows multiple podocyte cell bodies and interdigitating foot processes (original magnification ×4400). (C) Transmission electron micrograph shows normal foot processes and slit diaphragm (arrows) located foot processes (original magnification ×24,500). (D) The micrograph shows normal slit diaphragm between foot processes, composed mainly of nephrin protein. (E) Electron microscopy of nephrin gene pathogenic variant (NPHS1) kidney, podocyte foot processes wide and absent slit diaphragm between foot processes are seen due to absence of nephrin protein (original magnification ×37,200). CNS, Congenital nephrotic syndrome; E, endothelial cell; FP, foot processes; GBM, glomerular basement membrane; M, mesangial cell; P, podocyte cell body; RBCs, red blood cells; SD, slit diaphragm.", "img": "fig_p0790_10.jpg"}, {"id": "fc_035_27", "ch": 35, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 35.2):", "a": "Opinion-based management algorithm for CNS. At presentation with congenital nephrotic syndrome (CNS), a clinical and biological assessment including screening for congenital infections and genetic analysis is recommended. Initial treatment should be based on the results of these assessments. Patients should be managed at diagnosis by a specialized pediatric nephrology team. Blood volume should be assessed and symptomatic treatments instituted to maintain blood volume and prevent complications. Follow-up must be managed by a multidisciplinary team. Nephrectomy can be considered for children with persistent, severe CNS despite optimal management. Stable children can be managed on an outpatient basis with spacing or even stopping of albumin infusions. All children should be referred promptly to a kidney transplant team. Bilateral nephrectomy is recommended at the time of kidney failure (chronic kidney disease (CKD) G5) if nephrotic syndrome persists and/or if the patient has a WT1 pathogenic variant. *Preventive measures: prophylaxis for thrombosis, infection, and anemia, adequate nutrition, and growth hormone substitution. CVL, Central venous line; RAS, renin–angiotensin system. (From Boyer O, Schaefer F, Haffner D, et al. Manageme", "img": "fig_p0799_02.jpg"}, {"id": "fc_035_28", "ch": 35, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **TABLE Gen etic Causes of Nephrotic S yndromes Ca tegorized A ccording to the Location of Abnormal Proteins in**, what are the distinguishing features of **35.2 Pod**?", "a": "**etic Causes of Nephrotic S**: ocytes", "img": null}, {"id": "fc_036_01", "ch": 36, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BS I (ABS, HPES)**?", "a": "**Causative Gene(s):** `SLC12A1, NKCC2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Gene Product: NKCC2 — Inheritance: AR — Features: Polyhydramnios, prematurity, hypokalemic hypochloremic alkalosis, nephrocalcinosis, with or without concentrating defect", "img": null}, {"id": "fc_036_02", "ch": 36, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BS II (ABS with transient hyperkalemia and acidosis, HPES)**?", "a": "**Causative Gene(s):** `KCNJ1, ROMK1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Gene Product: ROMK1 — Inheritance: AR — Features: Polyhydramnios, prematurity, transient hyperkalemia and acidosis, then hypokalemic hypochloremic alkalosis, nephrocalcinosis, with or without concentrating defect", "img": null}, {"id": "fc_036_03", "ch": 36, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BS III (CBS)**?", "a": "**Causative Gene(s):** `CLCNKB` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Gene Product: ClC-Kb — Inheritance: AR; many sporadic — Features: Variable age at presentation with severity corresponding to type of gene pathogenic variant; hypokalemic hypochloremic alkalosis", "img": null}, {"id": "fc_036_04", "ch": 36, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BS IVa and BS IVb (ABS or HPES with sensorineural deafness)**?", "a": "**Causative Gene(s):** `BSND, CLCNKB` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** BSND CLCNKA, CLCNKB — Gene Product: Bartter ClC-Ka and ClC-Kb — Inheritance: AR — Features: Polyhydramnios, prematurity, hypokalemic hypochloremic alkalosis, sensorineural deafness, with or without concentrating defect", "img": null}, {"id": "fc_036_05", "ch": 36, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BS V (transient ABS)**?", "a": "**Causative Gene(s):** `MAGED2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene Product: MAGED2 — Inheritance: XR — Features: Severe polyhydramnios, hypokalemic hypochloremic alkalosis with symptoms resolving within the first few months of life", "img": null}, {"id": "fc_036_06", "ch": 36, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **EAST syndrome (SeSAME)**?", "a": "**Causative Gene(s):** `KCNJ10` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Kir4.1 — Gene Product: KCNJ10 — Inheritance: AR — Features: Epilepsy, ataxia, sensorineural deafness, hypokalemic hypochloremic alkalosis", "img": null}, {"id": "fc_036_07", "ch": 36, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CLDN10pathogenic variants**?", "a": "**Causative Gene(s):** `CLDN10` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Gene Product: Claudin-10 — Inheritance: AR — Features: Hypokalemic metabolic alkalosis with hypocalciuria but normal to elevated magnesium", "img": null}, {"id": "fc_036_08", "ch": 36, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SLC12A1`** are associated with which clinical phenotype and molecular mechanism in **Bartter Disease Type 1**?", "a": "Patients with neonatal Bartter syndrome have variants in SLC12A1 located on chromosome 15q15-21 encoding the bumetanideand furosemide-sensitive Na-K-2Cl co-transporter (BSC1 or NKCC2) (Bartter type 1) (Fig. 36.3).", "img": null}, {"id": "fc_036_09", "ch": 36, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NKCC2`** are associated with which clinical phenotype and molecular mechanism in **Bartter Disease Type 1**?", "a": "NKCC2 is a 121 kDa membrane protein comprising 12 transmembrane domains that form a transport pathway by dimerization of two homologous domains.", "img": null}, {"id": "fc_036_10", "ch": 36, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CLCNKB`** are associated with which clinical phenotype and molecular mechanism in **Bartter Disease Type 2**?", "a": "Cl leaves the cell thanks to the activity of the ClC-Ka and ClCKb chloride channels (variants in CLCNKB encoding the ClC-Kb channel cause Bartter disease type 3).", "img": null}, {"id": "fc_036_11", "ch": 36, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MAGED2`** are associated with which clinical phenotype and molecular mechanism in **Bartter Disease Type 2**?", "a": "Variants in the MAGED2 gene encoding melanoma-associated antigen D2 (MAGE-D2) cause transient antenatal Bartter syndrome (Bartter disease type 5).", "img": null}, {"id": "fc_036_12", "ch": 36, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CLDN10`** are associated with which clinical phenotype and molecular mechanism in **Bartter Disease Type 2**?", "a": "Variants in CLDN10 encoding claudin-10 cause HELIX syndrome (Hypohidrosis-Electrolyte imbalanceLacrimal gland dysfunction-Ichthyosis-Xerostomia syndrome).", "img": null}, {"id": "fc_036_13", "ch": 36, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KCNJ1`** are associated with which clinical phenotype and molecular mechanism in **Bartter Disease Type 2**?", "a": "Inactivating variants in KCNJ1 include missense and nonsense changes as well as frameshifts and deletions.", "img": null}, {"id": "fc_036_14", "ch": 36, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Manifestations**, how is **neonatal variant** defined and characterized?", "a": "neonatal variant is characterized by marked polyhydramnios from 22 to 24 weeks of gestation secondary to intrauterine polyuria, which may necessitate repeated amniocentesis to prevent premature delivery.", "img": null}, {"id": "fc_036_15", "ch": 36, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Manifestations**, how is **classic variant** defined and characterized?", "a": "classic variant , a history of maternal polyhydramnios and preterm birth may also be present.", "img": null}, {"id": "fc_036_16", "ch": 36, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Manifestations**, how is **lengthening of the corrected QT interval** defined and characterized?", "a": "lengthening of the corrected QT interval , with the possibility of developing potentially fatal ventricular arrhythmias secondary to prolonged hypomagnesemia and hypokalemia.", "img": null}, {"id": "fc_036_17", "ch": 36, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Manifestations**, how is **rhabdomyolysis** defined and characterized?", "a": "rhabdomyolysis have also been described in cases of severe hypokalemia, with the possibility of secondary acute renal damage.", "img": null}, {"id": "fc_036_18", "ch": 36, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Differential Diagnosis**, how is **HELIX syndrome** defined and characterized?", "a": "HELIX syndrome (CLDN10) is caused by a deficiency of claudin-10b, a protein located in the tight junctions of the loop of Henle cells and involved in paracellular sodium absorption.", "img": null}, {"id": "fc_036_19", "ch": 36, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis and Differential Diagnosis**, how is **RRAGD tubulopathy** defined and characterized?", "a": "RRAGD tubulopathy (RRAGD) is caused by activating variants of mTOR encoding a small Rag GTPase with probable action in the loop of Henle, due to the usual association with renal calcium loss.", "img": null}, {"id": "fc_036_20", "ch": 36, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 36.1):", "a": "Diagnostic yield and disease reclassification. Patients are initially classified based on the clinical suspicion raised by referring physicians (left node). The clinical diagnosis was reframed during preWES consultation (middle node). All the patients underwent genetic testing with WES that allowed us to confirm or reclassify the clinical diagnosis (right node). BS, Bartter syndrome; GS, Gitelman syndrome; Negative, patients without pathogenic variants; Other, genetic diagnosis outside BS and GS.", "img": "fig_p0809_05.jpg"}, {"id": "fc_036_21", "ch": 36, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 36.2):", "a": "Significant aspects of the pathophysiology of Bartter syndrome (see text).", "img": "fig_p0811_02.jpg"}, {"id": "fc_036_22", "ch": 36, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Types of Bartter Syndrome, Gitelman Syndrome, and Related Conditions**, what are the distinguishing features of **BS I (ABS, HPES)**?", "a": "**Gene**: SLC12A1; **Gene Product**: NKCC2; **Inheritance**: AR; **Features**: Polyhydramnios, prematurity, hypokalemic hypochloremic alkalosis, nephrocalcinosis, with or without concentrating defect", "img": null}, {"id": "fc_036_23", "ch": 36, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Types of Bartter Syndrome, Gitelman Syndrome, and Related Conditions**, what are the distinguishing features of **BS II (ABS with transient hyperkalemia and acidosis, HPES)**?", "a": "**Gene**: KCNJ1; **Gene Product**: ROMK1; **Inheritance**: AR; **Features**: Polyhydramnios, prematurity, transient hyperkalemia and acidosis, then hypokalemic hypochloremic alkalosis, nephrocalcinosis, with or without concentrating defect", "img": null}, {"id": "fc_036_24", "ch": 36, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Featur Variant es That Dist Age of Onset inguish Bar Serum K tter and Git Serum Cl elman Syndr Serum Mg ome Variants Serum Renin, Aldosteron**, what are the distinguishing features of **BS II**?", "a": "**AN**: AN; **Low**: High, then low; **Low**: Low; **Normal**: Normal; **High, high**: High, high; **High**: High; **—**: Transient hyperkalemia", "img": null}, {"id": "fc_036_25", "ch": 36, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Featur Variant es That Dist Age of Onset inguish Bar Serum K tter and Git Serum Cl elman Syndr Serum Mg ome Variants Serum Renin, Aldosteron**, what are the distinguishing features of **BS III**?", "a": "**AN**: N, C, A; **Low**: Low; **Low**: Very low; **Normal**: Normal; **High, high**: High, high; **High**: Low, normal, or high", "img": null}, {"id": "fc_036_26", "ch": 36, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Featur Variant es That Dist Age of Onset inguish Bar Serum K tter and Git Serum Cl elman Syndr Serum Mg ome Variants Serum Renin, Aldosteron**, what are the distinguishing features of **BS IVa, IVb**?", "a": "**AN**: AN; **Low**: Low; **Low**: Low; **Normal**: Normal; **High, high**: High, high; **High**: Normal or high; **—**: Sensorineural deafness", "img": null}, {"id": "fc_036_27", "ch": 36, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Features Variant That Dist Age of Onset inguish Bar Serum K tter and Git Serum Cl elman Syndr Serum Mg ome Variants–Serum Renin, Aldosterone**, what are the distinguishing features of **Hypocalcemic hypercalciuria**?", "a": "**Low**: Low; **Low**: Low; **Normal**: Normal; **High, high**: High, high; **—**: High; **Transient features**: Family history, hypocalcemia, suppressed PTH", "img": null}, {"id": "fc_036_28", "ch": 36, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Features Variant That Dist Age of Onset inguish Bar Serum K tter and Git Serum Cl elman Syndr Serum Mg ome Variants–Serum Renin, Aldosterone**, what are the distinguishing features of **EAST syndrome**?", "a": "**Low**: Low; **Low**: Low; **Normal**: Low; **High, high**: High, high; **—**: Low; **Transient features**: Epilepsy, ataxia, sensorineural deafness", "img": null}, {"id": "fc_037_01", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Liddle syndrome**?", "a": "**Causative Gene(s):** `SCNN1A, SCNN1B, SCNN1C` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Causative: SCNN1A SCNN1B SCNN1C — Inheritance: AD — Low — Low — Low to normal — Low to normal — ENaC antagonist", "img": null}, {"id": "fc_037_02", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Gordon syndrome**?", "a": "**Causative Gene(s):** `WNK1, WNK2, CUL3, KLHL3` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Causative: WNK1 WNK2 CUL3 KLHL3 — Inheritance: AD AD AD AD and AR — Low — Low to normal — Low to normal — High; rarely will be normal — Thiazide", "img": null}, {"id": "fc_037_03", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Syndrome of apparent mineralocorticoid excess**?", "a": "**Causative Gene(s):** `HSD11B2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Causative: HSD11B2 — Inheritance: AR — Low — Low — – — Markedly low — MRA — Diagnosis can be confirmed by sequencing of the HSD11B2 gene.", "img": null}, {"id": "fc_037_04", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Congenital adrenal hyperplasia**?", "a": "**Causative Gene(s):** `CYP11B1, CYP17A1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Causative: CYP11B1 CYP17A1 — Inheritance: AR — Low — Low — – — Variable; low in CYP17A1 — MRA", "img": null}, {"id": "fc_037_05", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Familial hyperaldosteronism type 1 (glucocorticoidremediable aldosteronism)**?", "a": "**Causative Gene(s):** `CYB11B1, CYP11B2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Causative: CYB11B1/ CYP11B2 chimeric fusion product — Inheritance: AD — Low — High — High — Mildly low to normal — Low-dose steroids+/− MRA or ENaC antagonist", "img": null}, {"id": "fc_037_06", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Familial hyperaldosteronism type 2**?", "a": "**Causative Gene(s):** `CLCN2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Causative: CLCN2 — Inheritance: AD — Low — High — High — Markedly low — MRA — Familial hyperaldosteronism type 2 is an autosomal dominant form of primary hyperaldosteronism.", "img": null}, {"id": "fc_037_07", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Familial hyperaldosteronism type 3**?", "a": "**Causative Gene(s):** `KCNJ5` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Causative: KCNJ5 — Inheritance: AD — Low — High — High — Markedly low — MRA and adrenalectomy in severe cases", "img": null}, {"id": "fc_037_08", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Familial hyperaldosteronism type 4**?", "a": "**Causative Gene(s):** `CACNA1H` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Causative: CACNA1H — Inheritance: AD — Low — High — High — Markedly low — MRA — Familial hyperaldosteronism type 4 is an autosomal dominant form of primary hyperaldosteronism caused by pathogenic gain of function variants in CACNA1H , a gene abundantly expressed in the adrenal zona glomerulosa that encodes the ɑ-subunit of a T-type calciu", "img": null}, {"id": "fc_037_09", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Neurofibromatosis type 1**?", "a": "**Causative Gene(s):** `NF1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Café-au-lait-spots, axillary, or inguinal freckling — Mechanism: Renal artery stenosis, pheochromocytoma", "img": null}, {"id": "fc_037_10", "ch": 37, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Tuberous sclerosis complex**?", "a": "**Causative Gene(s):** `TSC2, TSC1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Hypomelanotic macules, facial angiofibroma, shagreen patch — Mechanism: Progressive renal failure — TSC2 > TSC1", "img": null}, {"id": "fc_037_11", "ch": 37, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SCNN1A`** are associated with which clinical phenotype and molecular mechanism in **Liddle Syndrome**?", "a": "ENaC is made up of three homologous subunits, α, β, and γ, encoded by SCNN1A , SCNN1B , and SCNN1G , respectively.", "img": null}, {"id": "fc_037_12", "ch": 37, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KLHL3`** are associated with which clinical phenotype and molecular mechanism in **Physical Findings Suggesting a Monogenic Disorder in a Child With Hypertension—cont’d**?", "a": "Gordon syndrome is caused by pathogenic variants in one of 4 different genes, WNK1 , WNK4 , CUL3 , and KLHL3 .", "img": null}, {"id": "fc_037_13", "ch": 37, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`WNK4`** are associated with which clinical phenotype and molecular mechanism in **Physical Findings Suggesting a Monogenic Disorder in a Child With Hypertension—cont’d**?", "a": "The protein product of WNK1 inhibits the activity of WNK4. on the apical side of tubular epithelial cells.", "img": null}, {"id": "fc_037_14", "ch": 37, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`WNK1`** are associated with which clinical phenotype and molecular mechanism in **Physical Findings Suggesting a Monogenic Disorder in a Child With Hypertension—cont’d**?", "a": "Typically, patients with Gordon syndrome caused by WNK1 variants can have normal blood pressure into late adulthood.", "img": null}, {"id": "fc_037_15", "ch": 37, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`HSD11B2`** are associated with which clinical phenotype and molecular mechanism in **Syndrome of Apparent Mineralocorticoid Excess**?", "a": "Diagnosis can be confirmed by sequencing of the HSD11B2 gene.", "img": null}, {"id": "fc_037_16", "ch": 37, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CYP11B1`** are associated with which clinical phenotype and molecular mechanism in **Glucocorticoid-Remediable Aldosteronism**?", "a": "The genes that encode 11β-hydroxylase (CYP11B1) and aldosterone synthase (CYP11B2) are both located on chromosome 8 within proximity of each other.", "img": null}, {"id": "fc_037_17", "ch": 37, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Etiologies of Hypertension YOSUKE MIYASHITA, JOSEPH T. FLYNN**, how is **Primary hypertension** defined and characterized?", "a": "Primary hypertension does not have an identifiable etiology, and although genetic factors may play a role, it is largely attributable to body habitus, family history, and lifestyle factors.", "img": null}, {"id": "fc_037_18", "ch": 37, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Etiologies of Hypertension YOSUKE MIYASHITA, JOSEPH T. FLYNN**, how is **secondary hypertension** defined and characterized?", "a": "secondary hypertension has an identifiable etiology, with kidney disease and renovascular disease being the most common causes in the pediatric age range.", "img": null}, {"id": "fc_037_19", "ch": 37, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Gordon Syndrome**, how is **familial hyperkalemia and hypertension syndrome** defined and characterized?", "a": "familial hyperkalemia and hypertension syndrome , is a form of low-renin, low-aldosterone monogenic hypertension that presents with hyperkalemia , in contrast to the low or normal levels of serum potassium seen in patients with most of other forms of monogenic hypertension.", "img": null}, {"id": "fc_037_20", "ch": 37, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Syndrome of Apparent Mineralocorticoid Excess**, how is **Type 1 AME** defined and characterized?", "a": "Type 1 AME is more severe due to complete absence of 11βHSD2 activity and typically presents early in life with hypertension, low plasma renin and aldosterone levels, hypokalemia, metabolic alkalosis, and an elevated urinary cortisol:cortisone ratio.", "img": null}, {"id": "fc_037_21", "ch": 37, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Syndrome of Apparent Mineralocorticoid Excess**, how is **Type 2 AME** defined and characterized?", "a": "Type 2 AME is milder due to varying degrees of residual 11βHSD2 enzyme activity and presents later in life with lower-grade hypertension than in type 1 AME; electrolyte abnormalities are rare or absent.", "img": null}, {"id": "fc_037_22", "ch": 37, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Glucocorticoid-Remediable Aldosteronism**, how is **familial hyperaldosteronism type 1** defined and characterized?", "a": "familial hyperaldosteronism type 1 , aldosterone synthase hyperactivity, and glucocorticoid suppressible hyperaldosteronism.", "img": null}, {"id": "fc_037_23", "ch": 37, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 37.1):", "a": "An overview of monogenic hypertension disorders categorized by salient biochemical and genetic features. APA, Aldosterone-producing adenoma; CAH, congenital adrenal hyperplasia; FH, familial hyperaldosteronism; GRA, glucocorticoid remediable aldosteronism; MEN, multiple endocrine neoplasia; PASNA, primary aldosteronism with seizures and neurological abnormalities; PHA, pseudohypoaldosteronism.", "img": "fig_p0833_02.jpg"}, {"id": "fc_037_24", "ch": 37, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 37.2):", "a": "Molecular basis of Liddle syndrome. The epithelial sodium channel (ENaC) regulates sodium reabsorption in the distal tubules of the kidney. (A) ENaC, the renal outer medullary potassium channel (ROMK) and the sodium-potassium ATPase work in concert to maintain hydroelectrolytic balance in renal distal tubule epithelial cells. (B) pathogenic variants in Liddle syndrome result in either increased ENaC density on the apical membrane of the renal distal tubule epithelial cells or an increased propensity for channel opening, resulting in increased inward sodium current and altered flow of potassium, chloride, hydrogen ion, and bicarbonate (red arrows) . Pathophysiology of Liddle syndrome. AE1, Anion exchanger 1; ATPase, pump; Ca2þ, calcium; Cl , chloride; ENaC, epithelial sodium channel; Hþ, hydrogen ion; HCO3 , bicarbonate; Kþ, potassium; MR, mineralocorticoid receptor; Naþ, sodium; ROMK, renal outer medullary potassium.", "img": "fig_p0834_06.jpg"}, {"id": "fc_037_25", "ch": 37, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic Char With Low Pla acteristics, B sma Renin A iochemical Fe ctivity atures, and Treatment for Mono genic Hyperten sion Disorders**, what are the distinguishing features of **Condition**?", "a": "**Inheritance**: Genes; Pattern; PRA; Aldosterone; ARR; Potassium; Treatment", "img": null}, {"id": "fc_037_26", "ch": 37, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic Char With Low Pla acteristics, B sma Renin A iochemical Fe ctivity atures, and Treatment for Mono genic Hyperten sion Disorders**, what are the distinguishing features of **Liddle syndrome**?", "a": "**Inheritance**: SCNN1A SCNN1B SCNN1C; AD; Low; Low; Low to normal; Low to normal; ENaC antagonist", "img": null}, {"id": "fc_037_27", "ch": 37, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic Char With Low Pla acteristics, B sma Renin A iochemical Fe ctivity atures, and Treatment for Mono genic Hyperten sion Disorders**, what are the distinguishing features of **Gordon syndrome**?", "a": "**Inheritance**: WNK1 WNK2 CUL3 KLHL3; AD AD AD AD and AR; Low; Low to normal; Low to normal; High; rarely will be normal; Thiazide", "img": null}, {"id": "fc_037_28", "ch": 37, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Physical Findings Suggesting a Monogenic Disorder in a Child With Hypertension**, what are the distinguishing features of **Café-au-lait-spots, axillary, or inguinal freckling**?", "a": "**Genetic Syndrome**: Neurofibromatosis type 1; **Mechanism**: Renal artery stenosis, pheochromocytoma; **Genetic Abnormality Involved**: NF1", "img": null}, {"id": "fc_038_01", "ch": 38, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Interpretation of thePLASMICscore: 0–4: low risk for severe deficiency; 5: intermediate risk; 6–7: high risk.**?", "a": "**Causative Gene(s):** `ADAMTS13` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Points: ADAMTS13 — TTP is caused by a deficiency of the von Willebrand factor (VWF)-cleaving protease ADAMTS13, which can be either congenital or acquired.", "img": null}, {"id": "fc_038_02", "ch": 38, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Complementrelated genes**?", "a": "**Causative Gene(s):** `CFH` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormality: Heterozygous and (rarely) homozygous variants clustering (50%) in the last 2 exons — Main Effect: Impaired cell-surface complement regulation — Frequency: 20–30%", "img": null}, {"id": "fc_038_03", "ch": 38, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Complementunrelated genes**?", "a": "**Causative Gene(s):** `DGKE` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormality: Homozygous or compound heterozygous variants — Main Effect: Upregulation of prothrombotic factors, decreased VEGF signaling and apoptosis — Frequency: Infantile cases", "img": null}, {"id": "fc_038_04", "ch": 38, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **−332T (c.−332C>T, rs3753394)**?", "a": "**Causative Gene(s):** `CFH` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Effect: Lower FH levels — However, only a fraction of CFH variants identified in aHUS affect the N-terminal regulatory domain or other domains.", "img": null}, {"id": "fc_038_05", "ch": 38, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **469T (c.469C>T, p.H157Y, rs425757)**?", "a": "**Causative Gene(s):** `CFHR1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Effect: Competition with FH at — These events are favored by the presence in the CFH locus of 5 genes (CFHR1, CFHR2, CFHR3, CFHR4, CFHR5) that are homologous to CFH gene, but encode for five factor H-related proteins (FHR1, FHR2, FHR3, FHR4, FHR5) without complement regulatory properties.", "img": null}, {"id": "fc_038_06", "ch": 38, "part": "VI", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **−652A (c.−652A>G, rs2796267)**?", "a": "**Causative Gene(s):** `CD46` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** MCP/CD46 — Effect: Lower transcriptional — MCP/CD46 gene abnormalities account for 8 to 10% C-aHUS cases.", "img": null}, {"id": "fc_038_07", "ch": 38, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ADAMTS13`** are associated with which clinical phenotype and molecular mechanism in **Genetic Etiologies of Hemolytic Uremic Syndrome**?", "a": "TTP is caused by a deficiency of the von Willebrand factor (VWF)-cleaving protease ADAMTS13, which can be either congenital or acquired.", "img": null}, {"id": "fc_038_08", "ch": 38, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`DGKE`** are associated with which clinical phenotype and molecular mechanism in **Epidemiology**?", "a": "Information about the epidemiology of DGKE -associated aHUS varies, perhaps by region.", "img": null}, {"id": "fc_038_09", "ch": 38, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`G6PD`** are associated with which clinical phenotype and molecular mechanism in **Epidemiology**?", "a": "Cases of atypical HUS associated with Denys-Drash syndrome , primary hyperoxaluria type II , G6PD-deficiency , and the syndrome associated with TREX1 have been reported anecdotally.", "img": null}, {"id": "fc_038_10", "ch": 38, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`C3`** are associated with which clinical phenotype and molecular mechanism in **Complement-Mediated aHUS (C-aHUS)**?", "a": "The alternative pathway (AP) is continuously activated in plasma by low-grade hydrolysis of C3.", "img": null}, {"id": "fc_038_11", "ch": 38, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CFH`** are associated with which clinical phenotype and molecular mechanism in **Complement Factor H**?", "a": "However, only a fraction of CFH variants identified in aHUS affect the N-terminal regulatory domain or other domains.", "img": null}, {"id": "fc_038_12", "ch": 38, "part": "VI", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CFHR1`** are associated with which clinical phenotype and molecular mechanism in **Complement Factor H**?", "a": "These events are favored by the presence in the CFH locus of 5 genes (CFHR1, CFHR2, CFHR3, CFHR4, CFHR5) that are homologous to CFH gene, but encode for five factor H-related proteins (FHR1, FHR2, FHR3, FHR4, FHR5) without complement regulatory properties.", "img": null}, {"id": "fc_038_13", "ch": 38, "part": "VI", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Genotype-Phenotype Correlations**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Thirty to 60% of patients with complement gene pathogenic variants relapse after eculizumab discontinuation, whereas recurrence occurs in less than 10% of patients without identified pathogenic variants.", "img": null}, {"id": "fc_038_14", "ch": 38, "part": "VI", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Denys–Drash Syndrome-Associated aHUS**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** All progressed to end-stage renal disease despite treatment with plasma exchange, eculizumab, or both.", "img": null}, {"id": "fc_038_15", "ch": 38, "part": "VI", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Inverted Formin 2-Mediated Renal Disease**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Pathogenic variants in INF2 in association with known aHUS risk haplotypes have been described in two families with either aHUS or posttransplant TMA, who did not respond to terminal complement-blockade with eculizumab (Table 38.3).", "img": null}, {"id": "fc_038_16", "ch": 38, "part": "VI", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Glucose-6-Phosphate Dehydrogenase (G6PD)Deficiency and Suspected aHUS**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** A child with clinical presentation suggestive of aHUS without any known secondary or genetic cause and nonresponsive to eculizumab was subsequently diagnosed with G6PD-deficiency (Table 38.3).", "img": null}, {"id": "fc_038_17", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Etiologies of Hemolytic Uremic Syndrome**, how is **thrombotic microangiopathies (TMA)** defined and characterized?", "a": "thrombotic microangiopathies (TMA) and is described as an acute syndrome defined by a clinical triad of thrombocytopenia, nonimmune microangiopathic hemolytic anemia, and acute kidney failure.", "img": null}, {"id": "fc_038_18", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Etiologies of Hemolytic Uremic Syndrome**, how is **Pregnancy-associated HUS** defined and characterized?", "a": "Pregnancy-associated HUS typically illustrates this challenge for classification, in that pathogenic variants of the complement genes are found with the same prevalence (40–60%) as in C-aHUS.", "img": null}, {"id": "fc_038_19", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Epidemiology**, how is **cobalamin (cbl)-metabolism** defined and characterized?", "a": "cobalamin (cbl)-metabolism , neonatal screening programs have revealed a notably higher occurrence of the cblC-type than formerly estimated, ranging from 1:37,000 to 1:100,000.", "img": null}, {"id": "fc_038_20", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Laboratory Evaluation for Suspected HUS**, how is **Thrombocytopenia** defined and characterized?", "a": "Thrombocytopenia (or thrombocytes within normal range, but with a reduction of 30% compared to usual values).", "img": null}, {"id": "fc_038_21", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Laboratory Evaluation for Suspected HUS**, how is **Acute kidney injury** defined and characterized?", "a": "Acute kidney injury is always present, by definition, usually with microhematuria and sometimes proteinuria.", "img": null}, {"id": "fc_038_22", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Laboratory Evaluation for Suspected HUS**, how is **congenital** defined and characterized?", "a": "congenital (due to homozygosity or compound heterozygosity for pathogenic variants in ADAMTS13 ), or acquired , with the development of anti-ADAMTS13 inhibitory antibodies.", "img": null}, {"id": "fc_038_23", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Complement Factor H**, how is **Anti-FH inhibitory antibodies** defined and characterized?", "a": "Anti-FH inhibitory antibodies have been reported in 5 to 10% of all patients and ~25 to 50% of pediatric cases.", "img": null}, {"id": "fc_038_24", "ch": 38, "part": "VI", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Inverted Formin 2-Mediated Renal Disease**, how is **focal segmental glomerulosclerosis** defined and characterized?", "a": "focal segmental glomerulosclerosis , in association with Charcot-Marie-Tooth disease in 25% of the cases.", "img": null}, {"id": "fc_038_25", "ch": 38, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 38.1):", "a": "Differential diagnostic algorithm in thrombotic microangiopathies. Ab, Antibodies; aHUS,", "img": "fig_p0847_02.jpg"}, {"id": "fc_038_26", "ch": 38, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 38.2):", "a": "Peripheral blood smear stained with hematoxylin and eosin (100× magnification) demonstrating fragmentation of red blood cells (schistocytes) associated with the thrombotic microangiopathy syndromes.", "img": "vfig_p0846_01.jpg"}, {"id": "fc_038_27", "ch": 38, "part": "VI", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 38.3):", "a": "Kidney biopsies of patients with aHUS. (A) A 2-year-old female patient carrying a pathogenic variant in DGKE , who presented with acute kidney injury, hemolysis, normal platelet count, and nephrotic syndrome. Biopsy demonstrates both arteriolar (*) and capillary (arrow) thrombi as well as diffuse glomerular mesangiolysis and basal membrane duplication. Stain: Acid Fuchsin Orange G. (Courtesy from Dr. H. Chehade and Dr. S. Rotman, Lausanne University Hospital, Switzerland.) (B) A 36-year-old male patient with recurrent aHUS associated to a heterozygous pathogenic variant in the complement factor H gene. Biopsy demonstrates extensive capillary thrombosis with an aspect of glomerular paralysis, with capillary loops containing abundant erythrocytes, karyorrhexis with cellular debris in capillary lumina, and severe mesangiolysis. Stain: periodic acid–Schiff stain.", "img": "fig_p0849_14.jpg"}, {"id": "fc_038_28", "ch": 38, "part": "VI", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gene Ab normalities Associated With aHUS**, what are the distinguishing features of **Complementrelated genes**?", "a": "**Abnormality**: CFH; **Main Effect**: Heterozygous and (rarely) homozygous variants clustering (50%) in the last 2 exons; **Frequency**: Impaired cell-surface complement regulation; 20–30%", "img": null}, {"id": "fc_039_01", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Genetic abnormality**?", "a": "**Causative Gene(s):** `AIRE, FOXP3, CLTA4, LRBA, STAT1, IL2RA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** APS-1: AIRE — IPEX: FOXP3 — CTLA4: CLTA4 — Monogenic APS LRBA: LRBA — ITCH: ITCH — STATI: STAT1 — STAT5b: STAT5b — CD25: IL2RA", "img": null}, {"id": "fc_039_02", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Polyglandular Syndrome**?", "a": "**Causative Gene(s):** `CTLA4, LRBA, CD25` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** APS-1 — IPEX — CTLA4 — LRBA — ITCH — STATI — STAT5b — CD25 — Autoimmune polyglandular syndromes are rare disorders characterized by immune-mediated dysfunction of both endocrine and nonendocrine tissues due to loss of immunologic tolerance , the state in which the immune system distinguishes self-antigens from non-self-antigens and preven", "img": null}, {"id": "fc_039_03", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CMC representing the main clinical phenotype (“CMC disease”)**?", "a": "**Causative Gene(s):** `IL17F, JNK1, MAPK8, TRAF3, TRAF3IP2, ACT1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Features: • Autosomal dominant due to variants in IL-17F(IL17F)or Jun N-terminal kinase 1 (JNK1;MAPK8); autosomal recessive due to variants in IL-17 receptor A or (IL17RAorIL17RC) and TRAF3- interacting protein 2(TRAF3IP2; ACT1) • Oral candidiasis usually begins by age 6 months to 2 years • Cutaneous and ungual candidiasis common • No ass", "img": null}, {"id": "fc_039_04", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CMC associated with other immunodeficiency disorders**?", "a": "**Causative Gene(s):** `STAT3, DOCK8` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Features: • Hyper-IgE syndromes due to STAT3 and DOCK8 deficiencies • Severe combined immunodeficiency • DiGeorge syndrome • Interleukin-12 receptor β1 and interleukin-12B (p40) deficiencies • Autosomal dominant hypohidrotic ectodermal dysplasia with immunodeficiency (NFKBIAvariants) • Keratitis–ichthyosis–deafness (KID) syndrome", "img": null}, {"id": "fc_039_05", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CD25 expression**?", "a": "**Causative Gene(s):** `CD25` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** IPEX: Normal — CD25: Absent — STAT5B: Normal or low — STAT1: Normal — ITCH: Not tested", "img": null}, {"id": "fc_039_06", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CD4CD45RO**?", "a": "**Causative Gene(s):** `CD4CD45RO` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** IPEX: Elevated — CD25: Elevated — STAT5B: Elevated — STAT1: Normal or high — ITCH: Not tested", "img": null}, {"id": "fc_039_07", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FOXP3 expression**?", "a": "**Causative Gene(s):** `FOXP3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** IPEX: Absent or normal — CD25: Normal or low — STAT5B: Normal or low — STAT1: Normal — ITCH: Not tested", "img": null}, {"id": "fc_039_08", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Poor T cell proliferation, CMV disease**?", "a": "**Causative Gene(s):** `IL2RA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** IL-2 Signaling IL2RA", "img": null}, {"id": "fc_039_09", "ch": 39, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Lymphadenopathy, splenomegaly, cytopenias,↓IgG**?", "a": "**Causative Gene(s):** `NFKB1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** NFκB Signaling NFKB1", "img": null}, {"id": "fc_039_10", "ch": 39, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`AIRE`** are associated with which clinical phenotype and molecular mechanism in **Immunologic Tolerance and Autoimmunity**?", "a": "The ability of the mTECs to express a wide variety of self-antigens is mediated by AIRE , a transcriptional regulator located at chromosomal locus 21q22.3.", "img": null}, {"id": "fc_039_11", "ch": 39, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`APC`** are associated with which clinical phenotype and molecular mechanism in **Immunologic Tolerance and Autoimmunity**?", "a": "APC, Antigen presenting cell. (From Nambam B, Haller MJ, Winter WE, Schatz D.", "img": null}, {"id": "fc_039_12", "ch": 39, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FOXP3`** are associated with which clinical phenotype and molecular mechanism in **Immunologic Tolerance and Autoimmunity**?", "a": "Tregs originating from the thymus are termed central or natural Tregs and carry surface CD4+CD25+ and the intracellular forkhead transcription factor (FOXP3+).", "img": null}, {"id": "fc_039_13", "ch": 39, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CYP1A2`** are associated with which clinical phenotype and molecular mechanism in **Monogenic Autoimmune Polyglandular Syndromes**?", "a": "Autoantibodies to liver/kidney microsome type 1 (LKM1) are commonly associated with the autoimmune hepatitis, likely directed at hepatic antigens CYP2A6, CYP1A1, CYP1A2, and CYP2B6.", "img": null}, {"id": "fc_039_14", "ch": 39, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TTC37`** are associated with which clinical phenotype and molecular mechanism in **IPEX**?", "a": "Genes associated with IPEX-like syndrome include CD25 , CTLA4 , LRBA , STAT1 , STAT3 , STAT5B , ITCH , TTC7A , and TTC37 .", "img": null}, {"id": "fc_039_15", "ch": 39, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CTLA4`** are associated with which clinical phenotype and molecular mechanism in **Nongenetic Causes of Polyglandular Autoimmunity**?", "a": "These medications are typically directed against immune checkpoint targets such as CTLA4, PD1, and PDL1.", "img": null}, {"id": "fc_039_16", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **Autoimmune polyglandular syndrome 1 (APS-1)** defined and characterized?", "a": "Autoimmune polyglandular syndrome 1 (APS-1) , also referred to as autoimmune polyendocrinopathy candidiasisectodermal dystrophy (APECED) , is a monogenic disorder caused by pathogenic variants in AIRE .", "img": null}, {"id": "fc_039_17", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **Autoimmune hypoparathyroidism** defined and characterized?", "a": "Autoimmune hypoparathyroidism is usually seen after the onset of mucocutaneous candidiasis.", "img": null}, {"id": "fc_039_18", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **Autoimmune primary adrenal insufficiency** defined and characterized?", "a": "Autoimmune primary adrenal insufficiency usually manifests later in life than mucocutaneous candidiasis and hypoparathyroidism.", "img": null}, {"id": "fc_039_19", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **Autoimmune gonadal failure** defined and characterized?", "a": "Autoimmune gonadal failure is seen in up to 60% of females by 30 years of age; approximately 25% of males are affected.", "img": null}, {"id": "fc_039_20", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **Ectodermal dystrophy** defined and characterized?", "a": "Ectodermal dystrophy consisting of tooth enamel hypoplasia, keratitis, nail dystrophy, and calcification of the tympanic membrane is the most frequent, occurring in over 75% of affected individuals.", "img": null}, {"id": "fc_039_21", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **Alopecia areata** defined and characterized?", "a": "Alopecia areata occurs in nearly 30% of affected individuals, often appears before puberty, and consists of total loss of scalp hair (i.", "img": null}, {"id": "fc_039_22", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **atrophic gastritis** defined and characterized?", "a": "atrophic gastritis occurs in up to 30% of individuals with APS-1.", "img": null}, {"id": "fc_039_23", "ch": 39, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Monogenic Autoimmune Polyglandular Syndromes**, how is **autoimmune hepatitis** defined and characterized?", "a": "autoimmune hepatitis is the leading cause of death; liver function should be monitored regularly.", "img": null}, {"id": "fc_039_24", "ch": 39, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 39.1):", "a": "Whereas the binding of PD-L1 on an APC to PD-1 (pictured) downregulates activated T cells (CD4 T cells in this drawing; top half of the figure), interference in PD-1:PD-L1 signaling via a therapeutic monoclonal antibody to PD-1 (as pictured) or via a therapeutic monoclonal antibody to PD-L1 will maintain T cell activation (bottom half of the figure). Indeed, therapeutic anti-PD-1 and anti-PD-L1 monoclonal antibodies have produced remarkable beneficial results in the treatment of some cancers. APC, Antigen presenting cell.", "img": "fig_p0864_02.jpg"}, {"id": "fc_039_25", "ch": 39, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 39.2):", "a": "Oral candidiasis in a patient with chronic mucocutaneous candidiasis and type 1 diabetes.", "img": "fig_p0870_01.jpg"}, {"id": "fc_039_26", "ch": 39, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 39.3):", "a": "Chronic paronychia. All 20 nails were discolored and hyperplastic in this 8-year-old male with chronic mucocutaneous candidiasis. The chronic paronychia and nail dystrophy resolved on long-term treatment with oral ketoconazole.", "img": "fig_p0870_03.jpg"}, {"id": "fc_039_27", "ch": 39, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 39.4):", "a": "Incidence of disease development by age in patients with autoimmune polyendocrine syndrome type I (APS-I).", "img": "fig_p0870_05.jpg"}, {"id": "fc_039_28", "ch": 39, "part": "VII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Classification Characteristic Manifestations**, what are the distinguishing features of **PAS type 1**?", "a": "**Characteristic Manifestations**: Chronic candidiasis, hypoparathyroidism, Addison disease (at least two present)", "img": null}, {"id": "fc_040_01", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ataxia-telangiectasia**?", "a": "**Causative Gene(s):** `ATM` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Leukemia, Hodgkin lymphoma, non-Hodgkin lymphoma — Other Clinical Features: Cerebellar ataxia, oculomotor apraxia, choreoathetosis, telangiectasia of conjunctivae, immune deficiency", "img": null}, {"id": "fc_040_02", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Beckwith-Wiedemann syndrome**?", "a": "**Causative Gene(s):** `CDKN1C, LIT1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Genetic Locus: 11p15: epigenetics and genomic alterations; CDKN1C, LIT1 — Inheritance: Imprinting, AD — Wilms tumor, hepatoblastoma, neuroblastoma, rhabdomyosarcoma — Other Clinical Features: Macrosomia, macroglossia, visceromegaly, omphalocele, renal abnormalities, neonatal hypoglycemia, hemihypertrophy", "img": null}, {"id": "fc_040_03", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Carney complex**?", "a": "**Causative Gene(s):** `PRKAR1A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Schwannoma, testicular Sertoli tumor, thyroid adenoma, myxoma (cardiac, skin, others) — Other Clinical Features: Blue nevi, lentigines, hypercortisolism caused by PPNAD", "img": null}, {"id": "fc_040_04", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Constitutional mismatch DNA repair deficiency syndrome**?", "a": "**Causative Gene(s):** `MLH1, MSH2, MSH6, PMS2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Genetic Locus: MLH1, MSH2, MSH6, PMS2(biallelic) — Inheritance: AR — CNS tumors, hematological, Lynch syndrome associated cancers, sarcoma, embryonal tumor, pilomatricoma — Other Clinical Features: Hyper/hypopigmentation", "img": null}, {"id": "fc_040_05", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Costello syndrome**?", "a": "**Causative Gene(s):** `HRAS` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Rhabdomyosarcoma, neuroblastoma, transitional cell bladder cancer, papillomas — Other Clinical Features: DD, hypermobility, characteristic facial features, arrhythmia, CHD, large birth weight, FTT", "img": null}, {"id": "fc_040_06", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Diamond-Blackfan anemia**?", "a": "**Causative Gene(s):** `RPL5, RPL11, RPS19, RPS10, RPS26, RPL15` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Genetic Locus: RPL5, RPL11, RPS19, RPS10, RPS26, RPL15, RPL26, RPL35A, RPS7, RPS24, RPS17, GATA1 — Inheritance: AD — Osteosarcoma, AML, MDS — Other Clinical Features: Red cell aplasia, cleft lip/palate, malformed or absent thumbs, microcephaly, distinctive facial features, cataracts, glaucoma, hypospadias, short stature", "img": null}, {"id": "fc_040_07", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **DICER1 syndrome**?", "a": "**Causative Gene(s):** `DICER1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Multinodular goiter, thyroid cancer, pleuropulmonary blastoma, cystic nephroma, ovarian sex cord-stromal tumor, pituitary blastoma, pineal blastoma, ocular medulloepithelioma, nasal chondromesenchymal hamartoma, Wilms tumor — Other Clinical Features: Goiter, cystic nephroma", "img": null}, {"id": "fc_040_08", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Denys-Drash syndrome**?", "a": "**Causative Gene(s):** `WT1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Wilms tumor — Other Clinical Features: Diffuse glomerulosclerosis, gonadal dysgenesis, infertility", "img": null}, {"id": "fc_040_09", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Dyskeratosis congenita**?", "a": "**Causative Gene(s):** `CTC1, DKC1, TERC, TERT, TINF2, WRAP53` · **Inheritance:** XLR\n\n**Clinical & Molecular Profile:** Genetic Locus: CTC1, DKC1, TERC, TERT, TINF2, WRAP53 (TCAB1), NHP2, NOP10, RTEL1, ACD — Inheritance: XLR — MDS, AML, SCC of head/neck/anogenital region — Other Clinical Features: BMF, pulmonary fibrosis, dysplastic nails, lacy reticular skin pigmentation, leukoplakia", "img": null}, {"id": "fc_040_10", "ch": 40, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Familial adenomatous polyposis**?", "a": "**Causative Gene(s):** `APC` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Polyposis, CRC, small bowel cancer, stomach cancer, pancreatic cancer, thyroid cancer, CNS tumors, hepatoblastoma, juvenile nasopharyngeal angiofibroma, desmoid tumors, osteomas, endodermal cysts — Other Clinical Features: Dental abnormalities, CHRPE", "img": null}, {"id": "fc_040_11", "ch": 40, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RET`** are associated with which clinical phenotype and molecular mechanism in **Susceptibility Genes and Inheritance Patterns**?", "a": "A classic example is an activating alteration in the onco gene RET that causes multiple endocrine neoplasia disease.", "img": null}, {"id": "fc_040_12", "ch": 40, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SH2D1A`** are associated with which clinical phenotype and molecular mechanism in **Susceptibility Genes and Inheritance Patterns**?", "a": "Duncan disease, also known as X-linked lymphoproliferative syndrome (XLP), is due to alterations in SH2D1A and manifests with severe mononucleosis after Epstein-Barr infections and ultimately develop lymphomas in affected males.", "img": null}, {"id": "fc_040_13", "ch": 40, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SDHAF2`** are associated with which clinical phenotype and molecular mechanism in **Hereditary Pheochromocytoma-Paraganglioma**?", "a": "Hereditary pheochromocytoma-paraganglioma arises from pathogenic germline variants in several genes ( SDHA, SDHB, SDHC, SDHD, SDHAF2, TMEM127, MAX, and probably other rare genes like SLC25A11 , DNMT3A, and DLST ).", "img": null}, {"id": "fc_040_14", "ch": 40, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NF1`** are associated with which clinical phenotype and molecular mechanism in **Hereditary Pheochromocytoma-Paraganglioma**?", "a": "Depending on related genes involved, the secretory pattern would be different: metanephrines and normetanephrines in RET , NF1 , and other kinase-related genes; while VHL and SDHx genes related tumors secrete normetanephrine.", "img": null}, {"id": "fc_040_15", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Cancer Predisposition Syndromes in Children**, how is **cancer predisposition syndrome (CPS)** defined and characterized?", "a": "cancer predisposition syndrome (CPS) , although they essentially refer to the same concept.", "img": null}, {"id": "fc_040_16", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **MEN2A—Sipple Syndrome**, how is **Pheochromocytoma (PHEO)** defined and characterized?", "a": "Pheochromocytoma (PHEO) is the second most common endocrine cancer in pediatric patients with MEN2.", "img": null}, {"id": "fc_040_17", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **MEN2A—Sipple Syndrome**, how is **Hypercalcemia associated with PHPT** defined and characterized?", "a": "Hypercalcemia associated with PHPT is observed in 10–30% of adults; it is uncommon in children under the age of 20–25 years.", "img": null}, {"id": "fc_040_18", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **MEN2A—Sipple Syndrome**, how is **Cutaneous lichen amyloidosis** defined and characterized?", "a": "Cutaneous lichen amyloidosis , a dermatological condition associated with the 634 codon variant may occur in some patients.", "img": null}, {"id": "fc_040_19", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **MEN2A—Sipple Syndrome**, how is **Hirschsprung disease (HD)** defined and characterized?", "a": "Hirschsprung disease (HD) is associated with pathogenic variants in RET (most common) and other genes (EDNRB, EDN3) .", "img": null}, {"id": "fc_040_20", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **MEN2A—Sipple Syndrome**, how is **Familiar medullary thyroid cancer (FMTC)** defined and characterized?", "a": "Familiar medullary thyroid cancer (FMTC) has been classified as a variant of MEN2A, which requires at least two generations affected by RET germline variants or two members affected within the same generation.", "img": null}, {"id": "fc_040_21", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **MEN2B**, how is **ganglioneuromatosis** defined and characterized?", "a": "ganglioneuromatosis or mucosal neuromas , one of the earlier and specific features; other unspecific features include marfanoid habitus, pectus excavatum, scoliosis, inability to produce tears (85% of patients), constipation, and diarrhea.", "img": null}, {"id": "fc_040_22", "ch": 40, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **MEN1—Wermer Syndrome**, how is **Hyperparathyroidism (PHPT)** defined and characterized?", "a": "Hyperparathyroidism (PHPT) related to adenoma or hyperplasia of the parathyroid, is the most common endocrinopathy.", "img": null}, {"id": "fc_040_23", "ch": 40, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 40.1):", "a": "Tumors associated with cancer predisposition syndromes in children and adolescents. This figure is not a complete list of pediatric tumors and cancer predisposition syndromes. CNS, Central nervous system; DTPS, DICER1-related tumor predisposition syndrome; FAP, familial adenomatous polyposis; FIPA, familial isolated pituitary adenoma; JGCT, juvenile granulosa cell tumor; MEN, multiple endocrine neoplasia; NETs, neuroendocrine tumors; NF1, neurofibromatosis type I; PTEN, hamartoma multiple syndrome; RMS, rhabdomyosarcoma; SDHs, succinate dehydrogenase syndromes; VHL, Von Hippel-Lindau syndrome. (Created in BioRender. Hoenicka J [2025] [https://biorender.com/t1jmgzb]; Modified by editors.)", "img": "fig_p0893_02.jpg"}, {"id": "fc_040_24", "ch": 40, "part": "VII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Syndrome Genetic Locus Inheritance Primary Associated Tumors/Cancers (Pediatric and Adult) Other Clinical Features**, what are the distinguishing features of **Ataxia-telangiectasia**?", "a": "**Genetic Locus**: ATM; **Inheritance**: AR; **Primary Associated Tumors/Cancers (Pediatric and Adult)**: Leukemia, Hodgkin lymphoma, non-Hodgkin lymphoma; **Other Clinical Features**: Cerebellar ataxia, oculomotor apraxia, choreoathetosis, telangiectasia of conjunctivae, immune deficiency", "img": null}, {"id": "fc_040_25", "ch": 40, "part": "VII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Syndrome Genetic Locus Inheritance Primary Associated Tumors/Cancers (Pediatric and Adult) Other Clinical Features**, what are the distinguishing features of **Bazex-Dupré-Christol**?", "a": "**Genetic Locus**: Mapped toXq24-q27; **Inheritance**: XLD; **Primary Associated Tumors/Cancers (Pediatric and Adult)**: SCC; **Other Clinical Features**: Basal cell nevi, hypotrichosis, hypohidrosis, milia, atrophoderma follicularis", "img": null}, {"id": "fc_040_26", "ch": 40, "part": "VII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Syndrome Genetic Locus Inheritance Primary Associated Tumors/Cancers (Pediatric and Adult) Other Clinical Features**, what are the distinguishing features of **Beckwith-Wiedemann syndrome**?", "a": "**Genetic Locus**: 11p15: epigenetics and genomic alterations; CDKN1C, LIT1; **Inheritance**: Imprinting, AD; **Primary Associated Tumors/Cancers (Pediatric and Adult)**: Wilms tumor, hepatoblastoma, neuroblastoma, rhabdomyosarcoma; **Other Clinical Features**: Macrosomia, macroglossia, visceromegaly, omphalocele, renal abnormalities, neonatal hypoglycemia, hemihypertrophy", "img": null}, {"id": "fc_040_27", "ch": 40, "part": "VII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Syndrome Genetic Locus Inheritance Primary Associated Tumors/Cancers (Pediatric and Adult) Other Clinical Features**, what are the distinguishing features of **Down syndrome**?", "a": "**Genetic Locus**: Trisomy 21; **Inheritance**: Chromosomal; **Primary Associated Tumors/Cancers (Pediatric and Adult)**: Leukemia; **Other Clinical Features**: Characteristic facial features, DD, CHD, hypotonia, hypothyroidism, vision and hearing impairment", "img": null}, {"id": "fc_040_28", "ch": 40, "part": "VII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Syndrome Genetic Locus Inheritance Primary Associated Tumors/Cancers (Pediatric and Adult) Other Clinical Features**, what are the distinguishing features of **Denys-Drash syndrome**?", "a": "**Genetic Locus**: WT1; **Inheritance**: AD; **Primary Associated Tumors/Cancers (Pediatric and Adult)**: Wilms tumor; **Other Clinical Features**: Diffuse glomerulosclerosis, gonadal dysgenesis, infertility", "img": null}, {"id": "fc_041_01", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Kallman Syndrome**?", "a": "**Causative Gene(s):** `ANOS1` · **Inheritance:** XLR\n\n**Clinical & Molecular Profile:** Clinical Presentation: Classically anosmia. May have spectrum of intact sense of smell. — Genes: KAL-1/ANOS1 — Inheritance: X-linked recessive", "img": null}, {"id": "fc_041_02", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Adrenal hypoplasia congenita**?", "a": "**Causative Gene(s):** `NROB1` · **Inheritance:** XLR\n\n**Clinical & Molecular Profile:** Clinical Presentation: Males only, salt wasting adrenal crisis infancy, +/−under virilization, and potential for abnormal function of GnRH/LH/FSH producing cells — Genes: NROB1 — Inheritance: X-linked recessive", "img": null}, {"id": "fc_041_03", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Prohormone convertase 1 deficiency (PC1)**?", "a": "**Causative Gene(s):** `PC1, PCSK1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Clinical Presentation: Infancy, resistant diarrhea, obesity. Potential hypothyroidism, hypocortisolism, post prandial hypoglycemia, AVP deficiency, growth hormone deficiency — Genes: PCSK1 — Inheritance: AR", "img": null}, {"id": "fc_041_04", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CHARGE syndrome**?", "a": "**Causative Gene(s):** `CHD7` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Clinical Presentation: Coloboma, heart defects, choanal atresia, growth restriction, ear abnormalities — Genes: CHD7 — Inheritance: AD", "img": null}, {"id": "fc_041_05", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Optic nerve hypoplasia**?", "a": "**Causative Gene(s):** `HESX1, SOX2, SOX3, OTX2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Presentation: Wide phenotype: vision impairment, intellectual disability, hypothyroidism, hypocortisolism, AVP deficiency, growth hormone deficiency — Genes: Majority do not have pathogenic variant. HESX1, SOX2, SOX3, OTX2,orPROKR2(not exhaustive) — Inheritance: De novo", "img": null}, {"id": "fc_041_06", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hartsfield syndrome**?", "a": "**Causative Gene(s):** `FGFR1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Clinical Presentation: Seizures, ectrodactyly, cleft lip/palate holoprosencephaly, potential hypothyroidism, hypocortisolism, AVP deficiency, growth hormone deficiency — Genes: FGFR1 — Inheritance: AR or AD", "img": null}, {"id": "fc_041_07", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Börjeson-Forssman- Lejmann syndrome**?", "a": "**Causative Gene(s):** `PHF6` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Clinical Presentation: Intellectual disability, obesity, seizures, cryptorchidism — Genes: PHF6 — Inheritance: XL recessive", "img": null}, {"id": "fc_041_08", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Gaucher disease**?", "a": "**Causative Gene(s):** `GBA` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Clinical Presentation: (variable) Hepatosplenomegaly, anemia, thrombocytopenia — Genes: (Newborn screen USA) GBA — Inheritance: AR", "img": null}, {"id": "fc_041_09", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Sertoli cell only syndrome**?", "a": "**Causative Gene(s):** `CDY1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Presentation: Asymptomatic, infertile — Genes: Undefined Microdeletion of Y chromosome,CDY1, DAZ", "img": null}, {"id": "fc_041_10", "ch": 41, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Aromatase deficiency**?", "a": "**Causative Gene(s):** `CYP19A1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Clinical Presentation: Ambiguous genitalia or virilization during puberty in 46,XX Tall, delayed bone age, eunuchoid proportions in 46,XY — Genes: CYP19A1 — Inheritance: AR", "img": null}, {"id": "fc_041_11", "ch": 41, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GNAS1`** are associated with which clinical phenotype and molecular mechanism in **Gonadotropin Dependent Precocious Puberty**?", "a": "Another example is McCune-Albright syndrome in which constitutive activity of the LH receptor (GIPP), due to a somatic activating variant of the GNAS1 gene that encodes for the cAMP G-alpha subunit of the LH receptor, causes production of gonadal sex steroids that leads to the premature activation of the HPG axis and subsequent GDPP.", "img": null}, {"id": "fc_041_12", "ch": 41, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MKRN3`** are associated with which clinical phenotype and molecular mechanism in **Gonadotropin Dependent Precocious Puberty**?", "a": "An example of a gene with an indirect effect on GnRH production is the inhibitory role of Makorin ring finger protein 3 (MKRN3).", "img": null}, {"id": "fc_041_13", "ch": 41, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`DLK1`** are associated with which clinical phenotype and molecular mechanism in **Gonadotropin Dependent Precocious Puberty**?", "a": "A paternally inherited variant in DLK1 (another imprinted gene) is seen in small subset of females with GDPP and is thought to be related to dysregulation of hypothalamic GnRH producing neurons.", "img": null}, {"id": "fc_041_14", "ch": 41, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IGSF10`** are associated with which clinical phenotype and molecular mechanism in **Constitutional Delay of Growth and Puberty**?", "a": "An example of a genetic determinant is loss of function variants in the immunoglobulin superfamily member 10 (IGSF10) gene.", "img": null}, {"id": "fc_041_15", "ch": 41, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ANOS1`** are associated with which clinical phenotype and molecular mechanism in **Hypogonadotropic Hypogonadism**?", "a": "A family history of HypoH, male infertility, or anosmia also raises clinical suspicion as Kallman syndrome is a monogenic cause of HypoH associated with anosmia or hyposmia most commonly due to X-linked inheritance of KAL-1 (also known as ANOS1 ) pathogenic variant.", "img": null}, {"id": "fc_041_16", "ch": 41, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CHD7`** are associated with which clinical phenotype and molecular mechanism in **Hypogonadotropic Hypogonadism**?", "a": "Certain diagnoses are associated with HypoH including CHARGE syndrome often due to CHD7 variants.", "img": null}, {"id": "fc_041_17", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Pubertal Axis: Hypothalamic-PituitaryGonadal Axis Activity**, how is **mini-puberty** defined and characterized?", "a": "mini-puberty of infancy, this early pubertal-like HPG activity is thought to help prime the gonads and genitalia for later development in adolescence.", "img": null}, {"id": "fc_041_18", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Pubertal Axis: Hypothalamic-PituitaryGonadal Axis Activity**, how is **thelarche** defined and characterized?", "a": "thelarche , between the ages of 8 to 13 years of age, with the mean age of 10.", "img": null}, {"id": "fc_041_19", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Pubertal Axis: Hypothalamic-PituitaryGonadal Axis Activity**, how is **menarche** defined and characterized?", "a": "menarche , occurs within 2–3 years of thelarche or initial breast development.", "img": null}, {"id": "fc_041_20", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Assessment of Pubertal Development**, how is **bone age** defined and characterized?", "a": "bone age (or skeletal age), as determined by the level of growth plate and general skeletal development more closely corresponds to pubertal timing and sex steroid exposure than the chronological age.", "img": null}, {"id": "fc_041_21", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Early Pubertal Development**, how is **Variations of pubertal development** defined and characterized?", "a": "Variations of pubertal development , in which slow or nonprogressive sexual development occurs without evidence of other pubertal changes.", "img": null}, {"id": "fc_041_22", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Early Pubertal Development**, how is **Gonadotropin dependent precocious puberty** defined and characterized?", "a": "Gonadotropin dependent precocious puberty (GDPP), in which gonadal sex steroid production is occurring and dependent on pituitary gonadotropin release (e.", "img": null}, {"id": "fc_041_23", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Early Pubertal Development**, how is **Gonadotropin independent precocious puberty** defined and characterized?", "a": "Gonadotropin independent precocious puberty (GIPP), in which gonadal and/or adrenal sex steroid production is present, and independent of LH and FSH.", "img": null}, {"id": "fc_041_24", "ch": 41, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Premature Adrenarche**, how is **Growth acceleration** defined and characterized?", "a": "Growth acceleration is typically observed in more progressive etiologies of precocious puberty including GDPP or GIPP.", "img": null}, {"id": "fc_041_25", "ch": 41, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 41.1):", "a": "Normal hypothalamic-pituitary-gonadal axis. FSH, Folliclestimulating hormone; GnRH, gonadotropin-releasing hormone; LH, luteinizing hormone.", "img": "fig_p0908_07.jpg"}, {"id": "fc_041_26", "ch": 41, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 41.3):", "a": "Two-year-old twin sisters with idiopathic isolated premature thelarche manifested by isolated breast development to Tanner stage 3. (Peter M. Wolfgram and Bethany Auble. Nelson Pediatric SymptomBased Diagnosis , 55, 1047-1066.e1.)", "img": "fig_p0916_09.jpg"}, {"id": "fc_041_27", "ch": 41, "part": "VII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 41.4):", "a": "Flowchart for diagnosing sexual precocity in phenotypic female. CNS, Central nervous system; GnRH, gonadotropin-releasing hormone; LH, luteinizing hormone; LHRH, luteinizing hormone-releasing hormone; MRI, magnetic resonance imaging; T 4, thyroxine; TSH, thyrotropin. (Ferri’s Clinical Advisor 2024, 1136.e10-1136.e16.)", "img": "fig_p0918_01.jpg"}, {"id": "fc_041_28", "ch": 41, "part": "VII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Genetic Causes of Delayed Puberty**, what are the distinguishing features of **Hypogonadotropic Hy**?", "a": "**Clinical Presentation**: pogonadism", "img": null}, {"id": "fc_042_01", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Glucosuria • Progressive glucose intolerance then diabetes in late adolescence or early adulthood**?", "a": "**Causative Gene(s):** `HNF1A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Location (Chromosome,: 12q24.31 — • Pathogenic variant in HNF1A transcription factor • Beta cell dysfunction — • Glucosuria • Progressive glucose intolerance then diabetes in late adolescence or early adulthood — • Low dose sulfonylureas • GLP-1 receptor agonists — 600496", "img": null}, {"id": "fc_042_02", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Dyslipidemia • Diabetes • Hyperinsulinemic hypoglycemia early in life**?", "a": "**Causative Gene(s):** `HNF4A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Location (Chromosome,: 20q12 — • Pathogenic variant in HNF4A transcription factor • Defective glucosestimulated insulin secretion — • Dyslipidemia • Diabetes • Hyperinsulinemic hypoglycemia early in life — • Low dose sulfonylureas • GLP-1 receptor agonists — 125850", "img": null}, {"id": "fc_042_03", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Also known as “Renal Cysts and Diabetes Syndrome (RCAD)” • Pancreatic exocrine insufficiency (may be subclinic**?", "a": "**Causative Gene(s):** `HNF1B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Location (Chromosome,: 17q12 — • Pathogenic variant in HNF1B transcription factor • Dysfunctional embryonic development of pancreas and genitourinary system — • Also known as “Renal Cysts and Diabetes Syndrome (RCAD)” • Pancreatic exocrine insufficiency (may be subclinical) • Renal cysts, small kidneys, renal hypoplasia, or absent kidney,", "img": null}, {"id": "fc_042_04", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ABCC8**?", "a": "**Causative Gene(s):** `ABCC8, SUR1, SGLT2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Location (Chromosome,: 11p15.5 — • Defective SUR1 subunit on K-ATP channel in pancreatic beta cells • Impaired insulin secretion — • Various phenotypes • Neurological symptoms are associated — • Sulfonylurea (glyburide) • SGLT2 inhibitors, GLP-1 receptor agonists — 125853", "img": null}, {"id": "fc_042_05", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **KCNJ11**?", "a": "**Causative Gene(s):** `KCNJ11` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Location (Chromosome,: 11p15.1 — • Defective Kir6.2 subunit on K-ATP channel in pancreatic beta cells • Impaired insulin secretion — • Multiple phenotypes — • Sulfonylurea (glyburide) — 616329", "img": null}, {"id": "fc_042_06", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **APPL1**?", "a": "**Causative Gene(s):** `APPL1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Location (Chromosome,: 3p14.3 — • Pathogenic variant in APPL1 protein • Dysregulated insulin secretion • Reduced beta cell survival — • Low-carbohydrate diet • Oral hypoglycemic agents • Insulin — 616511", "img": null}, {"id": "fc_042_07", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PDX1**?", "a": "**Causative Gene(s):** `PDX1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Location (Chromosome,: 13q12.2 — • Beta cell dysfunction • Defective insulin secretion — • Variable age of onset — • Low-carbohydrate diet • Oral hypoglycemic agents • Insulin — 606392", "img": null}, {"id": "fc_042_08", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **6q24**?", "a": "**Causative Gene(s):** `PLAGL1` · **Inheritance:** Imprinting / UPD\n\n**Clinical & Molecular Profile:** PLAGL1/HYMAI — Inheritance: Variable (imprinting) — Other Clinical Features: TNDM±macroglossia±umbilical hernia", "img": null}, {"id": "fc_042_09", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **6p22.1**?", "a": "**Causative Gene(s):** `ZFP57` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Inheritance: Recessive — Other Clinical Features: TNDM (multiple hypomethylation syndrome)±macroglossia ±developmental delay±umbilical defects±congenital heart disease", "img": null}, {"id": "fc_042_10", "ch": 42, "part": "VII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **13q12.1**?", "a": "**Causative Gene(s):** `PDX1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Inheritance: Recessive — Other Clinical Features: PNDM+pancreatic agenesis (steatorrhea)", "img": null}, {"id": "fc_042_11", "ch": 42, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GCK`** are associated with which clinical phenotype and molecular mechanism in **Maturity Onset Diabetes of the Young**?", "a": "Most authorities recommend classifying MODY types based on genetic etiology rather than arbitrary numbering (e.g., GCK-MODY was previously known as MODY2) (Table 42.1).", "img": null}, {"id": "fc_042_12", "ch": 42, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`HNF1A`** are associated with which clinical phenotype and molecular mechanism in **GCK-MODY**?", "a": "A decreased high-sensitivity C-reactive protein can also distinguish HNF1A-MODY from type 2 diabetes (but is not seen with HNF4A-MODY).", "img": null}, {"id": "fc_042_13", "ch": 42, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`INS`** are associated with which clinical phenotype and molecular mechanism in **HNF1A-MODY**?", "a": "HNF1A is part of a family of transcription factors which regulate the expression of genes in pancreatic beta-cells and other tissues, including insulin (INS), glucose transporter (GLUT), and sodium/glucose cotransporter 2 (SGLT2).", "img": null}, {"id": "fc_042_14", "ch": 42, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ABCC8`** are associated with which clinical phenotype and molecular mechanism in **K-ATP Channel Defects**?", "a": "ABCC8-MODY is caused by activating variants (usually heterozygous and missense) in the ATP-binding cassette transporter subfamily C member 8 (ABCC8) gene on chromosome 11p15.5.", "img": null}, {"id": "fc_042_15", "ch": 42, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SUR1`** are associated with which clinical phenotype and molecular mechanism in **K-ATP Channel Defects**?", "a": "This gene encodes the sulfonylurea receptor 1 (SUR1) subunit of the K-ATP channel in the pancreatic beta cell membrane.", "img": null}, {"id": "fc_042_16", "ch": 42, "part": "VII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KCNJ11`** are associated with which clinical phenotype and molecular mechanism in **K-ATP Channel Defects**?", "a": "KCNJ11-MODY is caused by activating variants (usually heterozygous and missense) in KCNJ11 on chromosome 11p15.1.", "img": null}, {"id": "fc_042_17", "ch": 42, "part": "VII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **21q22.3**?", "a": "**Therapy / Intervention:** • Insulin • Antifungal • Glucocorticoid and mineralocorticoid replacement • Calcium and Vitamin D supplementation\n\n**Clinical Context:** Presentation: Autoimmune polyendocrinopathy syndrome type 1 • Mucocutaneous candidiasis • Hypoparathyroidism • Addison disease — Treatment: • Insulin • Antifungal • Glucocorticoid and mineralocorticoid replacement • Calc", "img": null}, {"id": "fc_042_18", "ch": 42, "part": "VII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **2q33.2**?", "a": "**Therapy / Intervention:** • CTLA-4 fusion proteins • Hematopoietic stem cell transplant\n\n**Clinical Context:** Presentation: Immune dysregulation with autoimmunity, immunodeficiency, and lymphoproliferation • Lymphoproliferative disease • Enteropathy • Cytopenias • Thyroiditis • Diabetes — Treatment: • CTLA-4 fusion proteins • He", "img": null}, {"id": "fc_042_19", "ch": 42, "part": "VII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Xp11.23**?", "a": "**Therapy / Intervention:** • Hematopoietic stem cell transplant\n\n**Clinical Context:** Presentation: IPEX syndrome • Protein losing enteropathy • Neonatal diabetes • Severe skin rashes • Only in males — Treatment: • Hematopoietic stem cell transplant", "img": null}, {"id": "fc_042_20", "ch": 42, "part": "VII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **10p15.1**?", "a": "**Therapy / Intervention:** • Sirolimus • Hematopoietic stem cell transplant\n\n**Clinical Context:** Presentation: Immunodeficiency 41 with lymphoproliferation and autoimmunity • Severe enteropathy leading to malabsorption • Chromic and recurring CMV infection • Diabetes • Hypothyroidism • Dermatological conditions — Tr", "img": null}, {"id": "fc_042_21", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Maturity Onset Diabetes of the Young**, how is **metabolic syndrome** defined and characterized?", "a": "metabolic syndrome (obesity, acanthosis nigricans, elevated triglycerides, and low HDL cholesterol, as well as elevated blood pressure levels).", "img": null}, {"id": "fc_042_22", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HNF1A-MODY**, how is **pancreas** defined and characterized?", "a": "pancreas , HNF1B helps with differentiation of the pancreatic cells to ductal, acinar, and endocrine cells.", "img": null}, {"id": "fc_042_23", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HNF1A-MODY**, how is **kidney** defined and characterized?", "a": "kidney , HNF1B directs the growth of the metanephric mesenchyme, the collecting ducts, renal pelvis, and ureters; patients commonly present with renal cysts, but can also present with small, hyperechogenic kidneys, renal hypoplasia, or an absent kidney.", "img": null}, {"id": "fc_042_24", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **HNF1A-MODY**, how is **Hypomagnesemia** defined and characterized?", "a": "Hypomagnesemia is a common feature resulting from renal magnesium wasting, as well as hyperuricemia.", "img": null}, {"id": "fc_042_25", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **K-ATP Channel Defects**, how is **ABCC8-MODY** defined and characterized?", "a": "ABCC8-MODY is caused by activating variants (usually heterozygous and missense) in the ATP-binding cassette transporter subfamily C member 8 (ABCC8) gene on chromosome 11p15.", "img": null}, {"id": "fc_042_26", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **K-ATP Channel Defects**, how is **KCNJ11-MODY** defined and characterized?", "a": "KCNJ11-MODY is caused by activating variants (usually heterozygous and missense) in KCNJ11 on chromosome 11p15.", "img": null}, {"id": "fc_042_27", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Rare Subtypes**, how is **INS-MODY** defined and characterized?", "a": "INS-MODY results from pathogenic variants (usually heterozygous) in the insulin (INS) gene that encodes for preproinsulin, the precursor of insulin.", "img": null}, {"id": "fc_042_28", "ch": 42, "part": "VII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Rare Subtypes**, how is **CEL-MODY** defined and characterized?", "a": "CEL-MODY is caused by pathogenic variants in the carboxyl-ester lipase (CEL) gene; only certain variants in the VNTR appear to be causative and lead to misfolding of the CEL enzyme.", "img": null}, {"id": "fc_043_01", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Autosomal dominant cystinuria Glucose transporter 1 deficiency Autosomal dominant GTP cyclohydrolase I deficie**?", "a": "**Causative Gene(s):** `PRKAG2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: Autosomal dominant — The protein kinase AMP-activated non-catalytic subunit gamma 2 (PRKAG2) cardiac syndrome is an autosomal dominant glycogen storage disorder resulting from pathogenic variants in PRKAG2 .", "img": null}, {"id": "fc_043_02", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Propionic acidemia (PA)**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Primary Biomarker: C3", "img": null}, {"id": "fc_043_03", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Methylmalonic acidemia (methylmalonyl-CoA mutase) (MMA-Mut)**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Primary Biomarker: C3", "img": null}, {"id": "fc_043_04", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Methylmalonic acidemia (cobalamin defects: A,B) (MMA-Cbl)**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Primary Biomarker: C3", "img": null}, {"id": "fc_043_05", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Isovaleric acidemia (IVA)**?", "a": "**Causative Gene(s):** `C5` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Primary Biomarker: C5", "img": null}, {"id": "fc_043_06", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Holocarboxylase synthetase deficiency* (multiple carboxylase deficiency) (MCD)**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Primary Biomarker: C5OH, C3", "img": null}, {"id": "fc_043_07", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **β-Ketothiolase deficiency (BKT)**?", "a": "**Causative Gene(s):** `C5` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Primary Biomarker: C5:1, C5OH", "img": null}, {"id": "fc_043_08", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Glutaric acidemia type I (GA-I)**?", "a": "**Causative Gene(s):** `C5` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Primary Biomarker: C5 DC", "img": null}, {"id": "fc_043_09", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Methylmalonic acidemia with homocystinuria (Cbl C, D)**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Biomarker: C3", "img": null}, {"id": "fc_043_10", "ch": 43, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Malonic acidemia (MAL)**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Biomarker: C3 DC", "img": null}, {"id": "fc_043_11", "ch": 43, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PRKAG2`** are associated with which clinical phenotype and molecular mechanism in **Classification**?", "a": "BPAN, Beta-propeller protein-associated neurodegeneration; CHILD, congenital hemidysplasia with ichthyosiform erythroderma and limb defects; PRKAG2, protein kinase AMP-activated non-catalytic subunit gamma 2.", "img": null}, {"id": "fc_043_12", "ch": 43, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATP7A`** are associated with which clinical phenotype and molecular mechanism in **Abnormal Development Associated With Dysmorphic Features and/or Congenital Malformations**?", "a": "Occipital horn syndrome is also due to pathogenic variants in ATP7A but presents with a connective tissue phenotype (bruised skin, hyperextensible joints, diverticula, skeletal abnormalities).", "img": null}, {"id": "fc_043_13", "ch": 43, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`BCS1L`** are associated with which clinical phenotype and molecular mechanism in **Liver Failure**?", "a": "Some mitochondrial hepatopathies, such as BCS1L -related disorders, may have features of iron overload mimicking neonatal hemochromatosis, the nonheritable constellation of gestational alloimmune hepatitis-induced liver injury with associated extrahepatic siderosis.", "img": null}, {"id": "fc_043_14", "ch": 43, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TFR2`** are associated with which clinical phenotype and molecular mechanism in **Liver Failure**?", "a": "This group of disorders include hemochromatosis associated with HFE , HJV , HAMP , and TFR2 ; ferroportin-associated iron overload; BMP6 -associated iron overload; and aceruloplasminemia.", "img": null}, {"id": "fc_043_15", "ch": 43, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Management**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Management of IMDs generally involves a combination of dietary modification, supplementation with vitamins or cofactors, medications, enzyme replacement therapy, or occasionally liver or bone marrow transplant.", "img": null}, {"id": "fc_043_16", "ch": 43, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Disorders of Carbohydrate Metabolism**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Treatment with enzyme replacement therapy is available.", "img": null}, {"id": "fc_043_17", "ch": 43, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Cardiomyopathy**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Enzyme replacement therapy is available to slow disease progression.", "img": null}, {"id": "fc_043_18", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Classification**, how is **Small molecule disorders** defined and characterized?", "a": "Small molecule disorders are IMDs affecting the intermediary metabolism of ammonia, ketones, amino acids, organic acids, and fatty acids.", "img": null}, {"id": "fc_043_19", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Classification**, how is **Large molecule disorders** defined and characterized?", "a": "Large molecule disorders are IMDs affecting the synthesis or degradation of complex molecules.", "img": null}, {"id": "fc_043_20", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Classification**, how is **Disorders of energy metabolism** defined and characterized?", "a": "Disorders of energy metabolism are IMDs impairing mitochondrial functioning, either directly or secondarily.", "img": null}, {"id": "fc_043_21", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Classification**, how is **miscellaneous category** defined and characterized?", "a": "miscellaneous category encompasses many IMDs that cannot be classified into the aforementioned categories, including disorders involving the metabolism of carbohydrates, vitamins, minerals, heavy metals, heme (e.", "img": null}, {"id": "fc_043_22", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Laboratory Evaluation**, how is **metabolomic analysis** defined and characterized?", "a": "metabolomic analysis can be an essential tool in the evaluation of a patient with a suspected metabolic disorder, particularly when genetic studies are nondiagnostic.", "img": null}, {"id": "fc_043_23", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Laboratory Evaluation**, how is **Newborn screening protocols** defined and characterized?", "a": "Newborn screening protocols to evaluate for IMDs have been adopted in the United States and many other countries.", "img": null}, {"id": "fc_043_24", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Technical**, how is **Neuroimaging** defined and characterized?", "a": "Neuroimaging with brain MRI in the undifferentiated patient with acute encephalopathy may reveal findings suggestive of a specific IMD or category of IMDs and is also important in excluding potential alternate etiologies (Fig.", "img": null}, {"id": "fc_043_25", "ch": 43, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Abnormal Development Associated With Dysmorphic Features and/or Congenital Malformations**, how is **Smith-Lemli-Opitz syndrome (SLO)** defined and characterized?", "a": "Smith-Lemli-Opitz syndrome (SLO) is the prototypical disorder of cholesterol biosynthesis and results from abnormal activity of 7-dehydrocholesterol reductase, the enzyme that catalyzes the conversion of 7-dehydrocholesterol to cholesterol.", "img": null}, {"id": "fc_043_26", "ch": 43, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 43.1):", "a": "Sunburst chart depicting the hierarchical nature of the International Classification of Inherited Metabolic Disorders. The size of each section of the chart is directly proportional to the number of disorders in that group. For an interactive version of the chart incorporating a zoom function, please refer to www.icimd.org.", "img": "fig_p0954_01.jpg"}, {"id": "fc_043_27", "ch": 43, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 43.2):", "a": "Initial clinical approach to a full-term newborn infant with a suspected genetic metabolic disorder. This schema is a guide to elucidate some of the metabolic disorders in newborn infants. Although some exceptions to this schema exist, it is appropriate for most cases affected by disorders or intermediate metabolism. CNS, Central nervous system; GI, gastrointestinal; HCO 3 , bicarbonate.", "img": "fig_p0964_01.jpg"}, {"id": "fc_043_28", "ch": 43, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 43.3):", "a": "Chart of imaging findings in selected metabolic disorders. Single asterisk denotes patients with inborn errors of metabolism (IEM) with macrocephaly. Double asterisk denotes patients with IEM and enhancement. 18q–syndrome, 18q deletion syndrome; CST, corticospinal tract; HABC, hypomyelination with atrophy of basal ganglia and cerebellum; MELAS, mitochondrial encephalopathy, lactic acidosis, and strokelike episodes; MLC, megalencephalic leukoencephalopathy with subcortical cysts; MLD, metachromatic leukodystrophy; MSUD, maple syrup urine disease; PMD, Pelizaeus-Merzbacher disease; PMLD, Pelizaeus-Merzbacher-like disease; PVL, periventricular leukoencephalopathy, WM, white matter; X-ALD, X-linked adrenoleukodystrophy.", "img": "fig_p0967_02.jpg"}, {"id": "fc_044_01", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BH4 deficiencies**?", "a": "**Causative Gene(s):** `BH4, GCH1, SPR` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Without hyperphenylalaninemia 1. Autosomal dominant GTP cyclohydrolase deficiency (Dopa-responsive dystonia, Segawa disease, AD-GTPCH) 2. Sepiapterin reductase deficiency (SR) — Associated Genes: GCH1 SPR", "img": null}, {"id": "fc_044_02", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Monoamine synthesis defects**?", "a": "**Causative Gene(s):** `TH, DDC` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 1. Aromatic L-amino acid decarboxylase deficiency (AADC) 2. Tyrosine hydroxylase deficiency (TH) — Associated Genes: DDC TH", "img": null}, {"id": "fc_044_03", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Monoamine transport defects**?", "a": "**Causative Gene(s):** `VMAT2, SLC6A3, SLC18A2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 1. Dopamine transporter deficiency (DAT) 2. Vesicular monoamine transporter 2 deficiency (VMAT2) — Associated Genes: SLC6A3 SLC18A2", "img": null}, {"id": "fc_044_04", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Chaperone-associated defect**?", "a": "**Causative Gene(s):** `DNAJC12` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** 1. DNAJC12 deficiency — Associated Genes: DNAJC12 — DNAJC12 deficiency a very rare autosomal recessive condition that causes elevation of Phe and low levels of dopamine and serotonin.", "img": null}, {"id": "fc_044_05", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Disorders of Glycine metabolism**?", "a": "**Causative Gene(s):** `LIPT2, BOLA3, GLRX5, IBA57, NFU1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 1. Glycine encephalopathy or Nonketotic hyperglycinemia (NKH) 2. Lipoate deficiency (Glycine cleavage system cofactor deficiency) — Associated Genes: AMT, GLDC, GCSH LIAS, LIPT2, BOLA3, GLRX5, IBA57, NFU1", "img": null}, {"id": "fc_044_06", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Disorders of Serine metabolism**?", "a": "**Causative Gene(s):** `PSAT1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 1. Serine biosynthetic enzyme defects (PGDH, PSAT, PSPH) — Associated Genes: PHGDH, PSAT1, PSPH", "img": null}, {"id": "fc_044_07", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Disorders of GABA metabolism**?", "a": "**Causative Gene(s):** `ALDH5A1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** 1. GABA Transaminase deficiency 2. Succinic semialdehyde dehydrogenase deficiency (SSADH) — Associated Genes: ABAT ALDH5A1", "img": null}, {"id": "fc_044_08", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AD-GCH1**?", "a": "**Causative Gene(s):** `GCH1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** AD GCH1 — Clinical Features: Parkinsonism, dystonia, motor delay, diurnal fluctuation, truncal hypotonia, hypertonia of extremities, tremors, and hypokinetic/rigid syndrome", "img": null}, {"id": "fc_044_09", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AR-GCH1**?", "a": "**Causative Gene(s):** `GCH1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** AR GCH1 — Clinical Features: Truncal hypotonia, parkinsonism, feeding/swallowing difficulties, dystonia, excessive sweating, temperature instability, intellectual disability, motor delay, choreoathetosis, drooling, oculogyric crises, ptosis, and seizures", "img": null}, {"id": "fc_044_10", "ch": 44, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PCD deficiency**?", "a": "**Causative Gene(s):** `PCBD1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: No severe neurological symptoms and transient and benign hyperphenylalaninemia", "img": null}, {"id": "fc_044_11", "ch": 44, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`BH4`** are associated with which clinical phenotype and molecular mechanism in **Genetic Disorders of Neurotransmitters**?", "a": "This group includes also defects in the metabolism of tetrahydrobiopterin (BH4), a cofactor for biogenic amine synthesis.", "img": null}, {"id": "fc_044_12", "ch": 44, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GCH1`** are associated with which clinical phenotype and molecular mechanism in **Etiology**?", "a": "Autosomal dominant GTP cyclohydrolase deficiency (GTPCH), also known as autosomal dominant doparesponsive dystonia (DRD) or Segawa disease , is caused by heterozygous pathogenic variants in GCH1 .", "img": null}, {"id": "fc_044_13", "ch": 44, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SPR`** are associated with which clinical phenotype and molecular mechanism in **Etiology**?", "a": "It is an autosomal recessive condition, caused by pathogenic variants in SPR .", "img": null}, {"id": "fc_044_14", "ch": 44, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PCBD1`** are associated with which clinical phenotype and molecular mechanism in **Etiology**?", "a": "It is an autosomal recessive disorder caused by pathogenic variants in PCBD1 .", "img": null}, {"id": "fc_044_15", "ch": 44, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`DDC`** are associated with which clinical phenotype and molecular mechanism in **Etiology**?", "a": "It is an autosomal recessive condition, caused by biallelic pathogenic variants in DDC .", "img": null}, {"id": "fc_044_16", "ch": 44, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TH`** are associated with which clinical phenotype and molecular mechanism in **Diagnosis**?", "a": "Molecular genetic diagnosis shows biallelic pathogenic variants in TH .", "img": null}, {"id": "fc_044_17", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Disorders of Neurotransmitters**, how is **Electrical synapses** defined and characterized?", "a": "Electrical synapses facilitate direct ionic communication through ion channels, which permit bidirectional flow of current between neurons.", "img": null}, {"id": "fc_044_18", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Disorders of Neurotransmitters**, how is **Chemical transmission** defined and characterized?", "a": "Chemical transmission occurs when one neuron’s signal is sent through chemical messengers called neurotransmitters.", "img": null}, {"id": "fc_044_19", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Etiology**, how is **doparesponsive dystonia** defined and characterized?", "a": "doparesponsive dystonia (DRD) or Segawa disease , is caused by heterozygous pathogenic variants in GCH1 .", "img": null}, {"id": "fc_044_20", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Amino Acid Neurotransmitter Disorders**, how is **L-forms** defined and characterized?", "a": "L-forms are used as building blocks for proteins (proteinogenic) and the D-forms are neurotransmitters and neuromodulators.", "img": null}, {"id": "fc_044_21", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Amino Acid Neurotransmitter Disorders**, how is **neurological** defined and characterized?", "a": "neurological symptoms: global developmental delay, intractable epilepsy, encephalopathy, or microcephaly.", "img": null}, {"id": "fc_044_22", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Etiology**, how is **nonketotic hyperglycinemia** defined and characterized?", "a": "nonketotic hyperglycinemia , NKH) is caused by defects in the glycine cleavage system (GCS), which is composed of four proteins: P, H, T and L proteins (Fig.", "img": null}, {"id": "fc_044_23", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Manifestations**, how is **infantile form** defined and characterized?", "a": "infantile form may have normal early development followed by the onset of seizures and variable developmental delay and cognitive impairment.", "img": null}, {"id": "fc_044_24", "ch": 44, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Manifestations**, how is **late onset form** defined and characterized?", "a": "late onset form may present with episodic movement disorder triggered by febrile illness, and mild intellectual disability or behavioral disturbances.", "img": null}, {"id": "fc_044_25", "ch": 44, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 44.1):", "a": "Simplified schematic illustration of chemical neurotransmission. Neurotransmitters (NT) are synthesized (1) in the presynaptic neuron, transported into the synaptic vesicle (2), and stored in the synaptic vesicle (3) until a depolarization signal triggers release of the NT (4). Once enough NT accumulates in the synaptic cleft, postsynaptic receptors (R) are activated (5), triggering a number of postsynaptic neuron modifications (6) (depolarization, long term synaptic plasticity, intracellular signal transduction). NT reuptake (7) occurs through membrane bound NT transporters into the presynaptic neuron, where it will be either degraded/ catabolized (8) or re-utilized by storage in the synaptic vesicle (9).", "img": "fig_p1002_01.jpg"}, {"id": "fc_044_26", "ch": 44, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 44.2):", "a": "Pathways of neurotransmitter and biopterin synthesis, degradation, and recycling. 5-HIAA, 5-hydroxyindoleacetic acid; 5-HIAL, 5hydroxyindoleacetaldehyde; BH4, tetrahydrobiopterin; DHPR, dihydropterine reductase; DOPAC, 3,4-dihydroxyphenylacetic acid; DOPAL, 3,4dihydroxyphenylacetaldehyde; DTDS, dopamine transport deficiency syndrome; GTP, guanosine-5′-triphosphate; HVA, homovanillic acid; MOPG, methoxylhydroxyphenylglycol; PLP, pyridoxal5′-phosphate; PTP, 6-pyruvoyltetrahydropterin; qBH2, quinonoid dihydrobiopterin; VLA, vanillyllactic acid; VMA, vanillylmandelic acid; VMAT 2, vesicular monoamine transporter.", "img": "fig_p1003_02.jpg"}, {"id": "fc_044_27", "ch": 44, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 44.3):", "a": "Glycine cleavage pathway. Glycine degradation occurs via four (H, T, P, L) proteins. H protein interacts with the three other proteins acting as a shuttle for intermediary products in glycine decarboxylation. Excess glycine is degraded into CO2, NH3, and 5,10-methylene-tetrahydrofolate.", "img": "fig_p1004_05.jpg"}, {"id": "fc_044_28", "ch": 44, "part": "VIII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Classification of Genetic Neurotransmitter Disorders**, what are the distinguishing features of **BH4 deficiencies**?", "a": "**Associated Genes**: Without hyperphenylalaninemia 1. Autosomal dominant GTP cyclohydrolase deficiency (Dopa-responsive dystonia, Segawa disease, AD-GTPCH) 2. Sepiapterin reductase deficiency (SR); GCH1 SPR", "img": null}, {"id": "fc_045_01", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Metabolic coma (without**?", "a": "**Causative Gene(s):** `HCO3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Laboratory Studies: Acidosis (metabolic; pH<7.20*, HCO3 <10 mmol, Pco2 — Other Features: With ketosis — Organic acidurias, MSUD MCD*, PC, RCD — Differential Diagnosis: Diabetes Intoxication Encephalitis", "img": null}, {"id": "fc_045_02", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **focal neuroloical**?", "a": "**Causative Gene(s):** `MCT1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Laboratory Studies: <25 mm) — Ketolysis defects, MCT1", "img": null}, {"id": "fc_045_03", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Neurological coma (with focal signs**?", "a": "**Causative Gene(s):** `OTC` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Laboratory Studies: Biological signs are very variable, can be absent or — Other Features: Cerebral edema — MSUD, OTC — Differential Diagnosis: Cerebral tumor Migraine Encephalitis", "img": null}, {"id": "fc_045_04", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **seizures, or intracranial hypertension)**?", "a": "**Causative Gene(s):** `OTC` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Laboratory Studies: moderate; see “Metabolic coma” — Other Features: Hemiplegia (hemianopsia) — MSUD, OTC, MMA, PA, PGK — Differential Diagnosis: Moyamoya syndrome", "img": null}, {"id": "fc_045_05", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Propionic Acidemia**?", "a": "**Causative Gene(s):** `PCCB` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Propionic acidemia (PA) is an autosomal recessive disorder of propionyl-CoA metabolism that results in the accumulation of toxic compounds due to defects in propionyl-CoA carboxylase (Fig. 45.2), encoded by the genes PCCA and PCCB .", "img": null}, {"id": "fc_045_06", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Methylmalonic Acidemia**?", "a": "**Causative Gene(s):** `MMUT` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** MMA is autosomal recessive, caused by pathogenic variants in one of several genes, MMUT, MMAA, MMAB, MCEE, and MMADHC .", "img": null}, {"id": "fc_045_07", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Isovaleric Acidemia**?", "a": "**Causative Gene(s):** `IVD` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Isovaleric acidemia (IVA) is an autosomal recessive disorder resulting from a defect in leucine metabolism, specifically a deficiency of isovaleryl-CoA dehydrogenase, encoded by the gene IVD , which converts isovaleryl-CoA to methylcrotonyl-CoA (Fig. 45.2).", "img": null}, {"id": "fc_045_08", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Glutaric Aciduria Type I**?", "a": "**Causative Gene(s):** `GCDH` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Glutaric aciduria type I (GA1) is an autosomal recessive disorder involving a defect in lysine metabolism, specifically decreased activity of glutaryl-CoA dehydrogenase, encoded by GCDH .", "img": null}, {"id": "fc_045_09", "ch": 45, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Urea Cycle Disorders**?", "a": "**Causative Gene(s):** `OTC` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** CPS1, n-acetylglutamate synthase, and OTC are all mitochondrially located (proximal UCDs).", "img": null}, {"id": "fc_045_10", "ch": 45, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PCCB`** are associated with which clinical phenotype and molecular mechanism in **Propionic Acidemia**?", "a": "Propionic acidemia (PA) is an autosomal recessive disorder of propionyl-CoA metabolism that results in the accumulation of toxic compounds due to defects in propionyl-CoA carboxylase (Fig. 45.2), encoded by the genes PCCA and PCCB .", "img": null}, {"id": "fc_045_11", "ch": 45, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CPS1`** are associated with which clinical phenotype and molecular mechanism in **Propionic Acidemia**?", "a": "Hyperammonemia is due to inhibition by various toxic metabolites on carbamoyl phosphate synthetase I (CPS1), a urea cycle enzyme; hyperammonemia is commonly found prior to treatment.", "img": null}, {"id": "fc_045_12", "ch": 45, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MMUT`** are associated with which clinical phenotype and molecular mechanism in **Methylmalonic Acidemia**?", "a": "MMA is autosomal recessive, caused by pathogenic variants in one of several genes, MMUT, MMAA, MMAB, MCEE, and MMADHC .", "img": null}, {"id": "fc_045_13", "ch": 45, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IVD`** are associated with which clinical phenotype and molecular mechanism in **Isovaleric Acidemia**?", "a": "Isovaleric acidemia (IVA) is an autosomal recessive disorder resulting from a defect in leucine metabolism, specifically a deficiency of isovaleryl-CoA dehydrogenase, encoded by the gene IVD , which converts isovaleryl-CoA to methylcrotonyl-CoA (Fig. 45.2).", "img": null}, {"id": "fc_045_14", "ch": 45, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GCDH`** are associated with which clinical phenotype and molecular mechanism in **Glutaric Aciduria Type I**?", "a": "Glutaric aciduria type I (GA1) is an autosomal recessive disorder involving a defect in lysine metabolism, specifically decreased activity of glutaryl-CoA dehydrogenase, encoded by GCDH .", "img": null}, {"id": "fc_045_15", "ch": 45, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`OTC`** are associated with which clinical phenotype and molecular mechanism in **Urea Cycle Disorders**?", "a": "CPS1, n-acetylglutamate synthase, and OTC are all mitochondrially located (proximal UCDs).", "img": null}, {"id": "fc_045_16", "ch": 45, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Phenylalanine Hydroxylase Deficiency**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** A minority of patients are responsive to sapropterin, a synthetic form of the cofactor for phenylalanine hydroxylase.", "img": null}, {"id": "fc_045_17", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Metabolic Crisis With Inborn Errors of Metabolism**, how is **metabolic crisis** defined and characterized?", "a": "metabolic crisis is the result of insufficiently functioning, or completely nonfunctioning, enzymes that lead to a deficiency of metabolites necessary for cellular function and to an accumulation of toxic metabolites that further perturb metabolism.", "img": null}, {"id": "fc_045_18", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Metabolic Crisis With Inborn Errors of Metabolism**, how is **catabolic stressors** defined and characterized?", "a": "catabolic stressors include: the onset of overnight fasting in infancy (or fasting for other reasons in later child/adulthood), illness, surgery, after ingestion of certain medications (i.", "img": null}, {"id": "fc_045_19", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Methylmalonic Acidemia**, how is **cobalamin/ vitamin B12** defined and characterized?", "a": "cobalamin/ vitamin B12 , the cofactor for methylmalonyl mutase, which involves MMAA, MMAB, and MMADHC; and combined they account for less than 40% of all patients with MMA.", "img": null}, {"id": "fc_045_20", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Carbamoyl Phosphate Synthetase I**, how is **orotic acid** defined and characterized?", "a": "orotic acid , which is found variably elevated in the UCD other than to CPS1.", "img": null}, {"id": "fc_045_21", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ornithine Transcarbamylase Deficiency**, how is **Males** defined and characterized?", "a": "Males are hemizygous and usually present in the neonatal or infancy period.", "img": null}, {"id": "fc_045_22", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ornithine Transcarbamylase Deficiency**, how is **Females** defined and characterized?", "a": "Females are typically heterozygous and may present at any age, usually secondary to a catabolic stressor; severity predictions are nearly impossible due to random X-inactivation.", "img": null}, {"id": "fc_045_23", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Argininosuccinate Lyase Deficiency**, how is **trichorrhexis nodosa** defined and characterized?", "a": "trichorrhexis nodosa , which is due to arginine deficient hair follicles and is pathognomonic.", "img": null}, {"id": "fc_045_24", "ch": 45, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Lysinuric Protein Intolerance**, how is **Hemophagocytic lymphohistiocytosis (HLH)** defined and characterized?", "a": "Hemophagocytic lymphohistiocytosis (HLH) , or a presentation with a subset of HLH features, is a common and severe complication of disease (Chapter 59).", "img": null}, {"id": "fc_045_25", "ch": 45, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 45.1):", "a": "Flow diagram describing the interpretation of basic, widely available laboratory findings in the setting of a metabolic emergency. The presence of symptoms of acute intoxication should prompt obtaining these labs. Findings should prompt further investigation using specialty biochemical labs to aid in the diagnosis of the inborn error of metabolism. Variable based on age and/or severity.", "img": "fig_p1016_01.jpg"}, {"id": "fc_045_26", "ch": 45, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 45.2):", "a": "Branched chain amino acid metabolism. Some reactions are not shown. Odd-chain fatty acids (i.e., propionate), threonine, and methionine also are catabolized to propionyl-CoA via alternate pathways. Branched chain amino transferase (blue box) has not been officially attributed to disease. Enzymes in red boxes are related to disease. Branched chain alpha-ketoacid dehydrogenase is a shared enzyme that metabolizes the three essential branched chain amino acids, leucine, isoleucine, and valine. Leucine is further metabolized via a pathway involving the enzyme responsible for IVA, isovaleryl-CoA dehydrogenase. Isoleucine and valine have a shared catabolic pathway involving the enzymes related to PA, propionyl-CoA carboxylase and MMA, methylmalonyl-CoA epimerase and mutase.", "img": "fig_p1020_07.jpg"}, {"id": "fc_045_27", "ch": 45, "part": "VIII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clinical Presentation Laboratory Studies Other Features Most Frequent Diagnosis (Disorder/Enzyme Deficiency) Differentia**, what are the distinguishing features of **Metabolic coma (without**?", "a": "**Laboratory Studies**: Acidosis (metabolic; pH<7.20*, HCO3 <10 mmol, Pco2; **Other Features**: With ketosis; **Most Frequent Diagnosis (Disorder/Enzyme Deficiency)**: Organic acidurias, MSUD MCD*, PC, RCD; **Differential Diagnosis**: Diabetes Intoxication Encephalitis", "img": null}, {"id": "fc_045_28", "ch": 45, "part": "VIII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Clinical Presentation Laboratory Studies Other Features Most Frequent Diagnosis (Disorder/Enzyme Deficiency) Differentia**, what are the distinguishing features of **focal neuroloical**?", "a": "**Laboratory Studies**: <25 mm); **Most Frequent Diagnosis (Disorder/Enzyme Deficiency)**: Ketolysis defects, MCT1", "img": null}, {"id": "fc_046_01", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Fabry med Manfy (manfy54@yahoo.com) For personal use only. No other uses**?", "a": "**Causative Gene(s):** `GLA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Deficient Enzyme: α-galactosidase A — Main Storage Material: Ceramide trihexoside — Estimated Incidence: 1:40,000– 120,000* — Severity: Mild/ intermediate — Clinical Symptoms: Acroparesthesia, gastroenteritis, nephropathy, cerebrovascular disease/stroke, corneal opacities, left ventricular hypertrophy, cardiomyopathy and arrhythmia, renal", "img": null}, {"id": "fc_046_02", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Type I versity of Southern Califor ut permission. Copyright ©**?", "a": "**Causative Gene(s):** `GBA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Deficient Enzyme: Glucocerebrosidase — Main Storage Material: Glucosy lceramide — Estimated Incidence: 1:30,000 — Severity: Mild/ intermediate — Clinical Symptoms: Type I: hepatosplenomegaly, thrombocytopenia, pancytopenia, bone disease, osteopenia, degenerative arthritis, and increased risk of myeloma — CNS. Affected: No — Age of Onset:", "img": null}, {"id": "fc_046_03", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Krabbe**?", "a": "**Causative Gene(s):** `GALC` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** GALC — i: Galactocerebrosidase — Main Storage: Galactosylceramide and galactosylsphingosine — Estimated: 1:100,000 — Severe — Clinical: Infantile: irritability, hypotonia, spasticity, feeding difficulties and psychomotor regression. Juvenile:variable onset and progression from childhood to adulthood, muscle weakness, vision loss and intel", "img": null}, {"id": "fc_046_04", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Late-infantile MLD**?", "a": "**Causative Gene(s):** `ARSA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** ARSA — i: Arylsulfatase A — Main Storage: Sulfatide — Estimated: 1:40,000– 160,000 (50% cases) — Severe — Clinical: Ataxia, weakness, loss of speech and cherry-red macula, cognitive decline — CNS.: Yes — Age of: 3 years — Life: <5 years — Approved: HSCT/ HSC-GT Europe", "img": null}, {"id": "fc_046_05", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Niemann-Pick Type A**?", "a": "**Causative Gene(s):** `SMPD1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** SMPD1 — i: Sphingomyelinase — Main Storage: Sphingomyelin — Estimated: 1:100,000 — Severe — Clinical: Hepatosplenomegaly, failure to thrive, psychomotor regression, interstitial lung disease, and cherry-red macula — CNS.: Yes — Age of: Early infancy — Life: 2–3 years — Approved: ERT", "img": null}, {"id": "fc_046_06", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Niemann-Pick Type B**?", "a": "**Causative Gene(s):** `SMPD1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** SMPD1 — Severe– intermediate — Clinical: Juvenile: hepatosplenomegaly, recurrent pulmonary infections, thrombocytopenia, short stature, and neurological impairment — CNS.: No — Age of: Childhood– adolescence — Life: Childhood– adulthood — Approved: ERT", "img": null}, {"id": "fc_046_07", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GM 1-gangliosidosis types I, II, & III**?", "a": "**Causative Gene(s):** `GM1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** GLBI — Deficient Enzyme: β-Galactosidase — Main Storage Material: GM1 gangliosides, KS, glycolipids, and oligosaccharides — Estimated Incidence: 1:100,000 — Severity: Severe — Clinical Symptoms: Type I:seizures, hypotonia, developmental decline at 6 months, cherry-red macula and severe motor decline Type II:speech regress, ataxia, progres", "img": null}, {"id": "fc_046_08", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GM2 gangliosidosis, Tay-Sachs**?", "a": "**Causative Gene(s):** `HEXA, GM2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Deficient Enzyme: Hexosaminidase A — Main Storage Material: GM2 gangliosides, glycosphingolipids, and oligosaccharides — Estimated Incidence: 1:320,000 — Severity: Severe — Clinical Symptoms: Infantile: hypotonia, developmental regression before 1 year, macrocephaly, seizures, and cherry-red macula. Juvenile: progressive developmental reg", "img": null}, {"id": "fc_046_09", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GM2 gangliosidosis. Sandhoff**?", "a": "**Causative Gene(s):** `GM2, HEXB` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** HEXB — i: Hexosaminidase B — Main Storage: GM2 gangliosides, glycosphingolipids, and oligosaccharides — Estimated: 1:130,000 — Severe — Clinical: Infantile:hypotonia, developmental regression<1 year, macrocephaly, seizures, and cherryred macula. Juvenile:progressive developmental regression early childhood, cerebellar ataxia, dysarthria,", "img": null}, {"id": "fc_046_10", "ch": 46, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **MPS I Hurler**?", "a": "**Causative Gene(s):** `IDUA` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** IDUA — i: Alpha-L iduronidase — Main Storage: HS/DS — Estimated: 1:100,000 — Severe (57% of cases) — Clinical: Coarse facial features, hepatosplenomegaly, hernias, corneal clouding, frequent otitis media, cognitive decline (except attenuated forms), and dysostosis multiplex — CNS.: Yes — Age of: 6–12 months — Life: 1–12 years — Approved:", "img": null}, {"id": "fc_046_11", "ch": 46, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GM2`** are associated with which clinical phenotype and molecular mechanism in **Skin Manifestations**?", "a": "Dermal melanocytosis is a known clinical sign in MPS disorders, GM1 gangliosidosis, GM2 gangliosidosis, and Niemann-Pick disease A/B.", "img": null}, {"id": "fc_046_12", "ch": 46, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GAA`** are associated with which clinical phenotype and molecular mechanism in **Valvular Heart Disease**?", "a": "Gaucher disease has a predominantly cardiac form referred to as type 3c that is caused by a homozygous variant p.Asp448His (Asp409His) in GAA ; affected patients often experience relentless progressive calcification of heart valves and the aorta.", "img": null}, {"id": "fc_046_13", "ch": 46, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Fabry med Manfy (manfy54@yahoo.com) For personal use only. No other uses**?", "a": "**Therapy / Intervention:** ERT/SRT\n\n**Clinical Context:** Deficient Enzyme: α-galactosidase A — Main Storage Material: Ceramide trihexoside — Estimated Incidence: 1:40,000– 120,000* — Severity: Mild/ intermediate — Clinical Symptoms: Acroparesthesia, gastroenteritis, nephropath", "img": null}, {"id": "fc_046_14", "ch": 46, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Type I versity of Southern Califor ut permission. Copyright ©**?", "a": "**Therapy / Intervention:** ERT/SRT\n\n**Clinical Context:** Deficient Enzyme: Glucocerebrosidase — Main Storage Material: Glucosy lceramide — Estimated Incidence: 1:30,000 — Severity: Mild/ intermediate — Clinical Symptoms: Type I: hepatosplenomegaly, thrombocytopenia, pancytopen", "img": null}, {"id": "fc_046_15", "ch": 46, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Type II nia from ClinicalKey.com b 2026. Elsevier Inc. All righ**?", "a": "**Therapy / Intervention:** ERT (little impact on neurological disease)\n\n**Clinical Context:** Estimated Incidence: ~1:200,000 — Severity: Severe — Clinical Symptoms: Type II:limited psychomotor development, bulbar signs including stridor and swallowing difficulty, lung disease, hypertonic posturing, spasticity, e", "img": null}, {"id": "fc_046_16", "ch": 46, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Type Ill y Elsevier on ts reserved.**?", "a": "**Therapy / Intervention:** ERT (little impact on neurological disease)\n\n**Clinical Context:** Estimated Incidence: ~1:200,000 — Severity: Intermediate/ severe — Clinical Symptoms: Type III:oculomotor apraxia, supranuclear gaze palsy, epilepsy. Perinatal lethal from: hepatosplenomegaly, pancytopenia, skin abnormal", "img": null}, {"id": "fc_046_17", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Differentiating Features of Storage Diseases**, how is **Pompe disease** defined and characterized?", "a": "Pompe disease arises from a deficiency of a lysosomal enzyme leading to the lysosomal storage of glycogen and is classified as GSD type II.", "img": null}, {"id": "fc_046_18", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Retina**, how is **macular cherry red spot** defined and characterized?", "a": "macular cherry red spot , which results from the deposition of storage material around the macula.", "img": null}, {"id": "fc_046_19", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Extraocular Movements**, how is **Horizontal saccade palsy** defined and characterized?", "a": "Horizontal saccade palsy is a characteristic finding in the chronic form of neuronopathic Gaucher disease (Gaucher disease type III), whereas vertical saccade deficiency/vertical supranuclear gaze palsy is observed in patients with Niemann-Pick C (NPC) disease.", "img": null}, {"id": "fc_046_20", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Skin Manifestations**, how is **collodion baby** defined and characterized?", "a": "collodion baby phenotype, which includes ectropia and eclabium.", "img": null}, {"id": "fc_046_21", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Skin Manifestations**, how is **Dermal melanocytosis** defined and characterized?", "a": "Dermal melanocytosis is a known clinical sign in MPS disorders, GM1 gangliosidosis, GM2 gangliosidosis, and Niemann-Pick disease A/B.", "img": null}, {"id": "fc_046_22", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Skin Manifestations**, how is **Hypopigmented nodularity** defined and characterized?", "a": "Hypopigmented nodularity on the skin of the back is an early sign, considered highly specific for MPS II, although similar findings have been reported in MPS I.", "img": null}, {"id": "fc_046_23", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Skin Manifestations**, how is **Marked skin thickening** defined and characterized?", "a": "Marked skin thickening is frequently observed in patients with MPS.", "img": null}, {"id": "fc_046_24", "ch": 46, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Skin Manifestations**, how is **Vascular** defined and characterized?", "a": "Vascular skin manifestations are observed in a subset of LSDs, most notably in Fabry disease.", "img": null}, {"id": "fc_046_25", "ch": 46, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 46.1):", "a": "A six-year-old female with Hurler syndrome. Note course facies", "img": "fig_p1052_01.jpg"}, {"id": "fc_046_26", "ch": 46, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 46.2):", "a": "Collodion membrane in one-day-old infant", "img": "fig_p1053_02.jpg"}, {"id": "fc_046_27", "ch": 46, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 46.3):", "a": "Congenital dermal melanocytosis. A diffuse pigmentation in a normal child. When widespread, dermal melanocytosis may be associated with lysosomal storage disease.", "img": "fig_p1053_04.jpg"}, {"id": "fc_046_28", "ch": 46, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 46.4):", "a": "Angiokeratomas of Fabry disease. Multiple dark red to red–brown macules and papules located on the lower trunk.", "img": "fig_p1053_13.jpg"}, {"id": "fc_047_01", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ALG10 alpha-1,2-glucosyltransferase deficiency**?", "a": "**Causative Gene(s):** `ALG10` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene-CDG: ALG10-CDG", "img": null}, {"id": "fc_047_02", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Subunit STT3A (OST complex) deficiency**?", "a": "**Causative Gene(s):** `STT3A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Gene-CDG: STT3A-CDG(ar) — Some CDG (e.g., DHDDS-, ALG8-, ALG9-, STT3A-, and COG4-CDG) can be inherited in both an autosomal recessive and an autosomal dominant manner, albeit with different phenotypes.", "img": null}, {"id": "fc_047_03", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Subunit STT3B (OST complex) deficiency**?", "a": "**Causative Gene(s):** `STT3B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene-CDG: STT3B-CDG — There are two alternative STT3 proteins, STT3A, which catalyzes the co-translational glycosylation of the vast majority of proteins, and STT3B, which mediates post-translational glycosylation of a specific subset of proteins that elude STT3A.", "img": null}, {"id": "fc_047_04", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SEC63 homolog, protein translocation regulator deficiency**?", "a": "**Causative Gene(s):** `SEC63` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene-CDG: SEC63-CDG", "img": null}, {"id": "fc_047_05", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Translocon associated protein complex subunit SSR3 deficiency**?", "a": "**Causative Gene(s):** `SSR3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene-CDG: SSR3-CDG", "img": null}, {"id": "fc_047_06", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Lysosomal enzyme trafficking factor TMEM251 deficiency**?", "a": "**Causative Gene(s):** `TMEM251` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene-CDG: LYSET-CDG", "img": null}, {"id": "fc_047_07", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **3′Repair exonuclease 1 deficiency (AG1) deficiency**?", "a": "**Causative Gene(s):** `AG1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene-CDG: TREX1-CDG", "img": null}, {"id": "fc_047_08", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Brain**?", "a": "**Causative Gene(s):** `PMM2, DPAGT1, ALG12, MAN1B1, POMT1, POMT2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: Cerebellar hypoplasia — Gene Associated With CDG: PMM2, DPAGT1, ALG12, MAN1B1, B4GALT1, POMT1, POMT2, POMGNT1, POMGNT2, B3GALNT2, POMK, CRPPA, FKTN, FKRP, RXYLT1, B4GAT1, LARGE1, GMPPB, PIGG, GPAA1, DPM2, ATP6V0A2, ATP6V1A, ATP6V1E1", "img": null}, {"id": "fc_047_09", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Epilepsy**?", "a": "**Causative Gene(s):** `ALG13, ALG2, MGAT2, SLC35A2, NGLY1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: Infantile spasms — Gene Associated With CDG: ALG13, ALG2, MGAT2, DOLK, SLC35A2, NGLY1", "img": null}, {"id": "fc_047_10", "ch": 47, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hearing**?", "a": "**Causative Gene(s):** `ALG12, HS6ST1, SLC35A2, PGM3, COG5, ALG11` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Clinical Features: Sensorineural hearing impairment — Gene Associated With CDG: ALG12, MOGS, HS6ST1, SLC35A2, PGM3, GMPPA, COG5, ALG11, PMM2, RFT1, ALG3, CHST14, DSE, SLC26A2, PIGL, PIGT", "img": null}, {"id": "fc_047_11", "ch": 47, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`C2`** are associated with which clinical phenotype and molecular mechanism in **Understanding Glycosylation Pathways**?", "a": "A third, less common type of protein glycosylation, called C-mannosylation, refers to the formation of an unusual C-C bond between a mannose residue and the C2 atom of tryptophan.", "img": null}, {"id": "fc_047_12", "ch": 47, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`COG4`** are associated with which clinical phenotype and molecular mechanism in **When Glycosylation Goes Wrong**?", "a": "Some CDG (e.g., DHDDS-, ALG8-, ALG9-, STT3A-, and COG4-CDG) can be inherited in both an autosomal recessive and an autosomal dominant manner, albeit with different phenotypes.", "img": null}, {"id": "fc_047_13", "ch": 47, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PMM2`** are associated with which clinical phenotype and molecular mechanism in **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**?", "a": "PMM2-CDG is the most prevalent disorder of N-glycosylation with over 1,000 patients identified worldwide.", "img": null}, {"id": "fc_047_14", "ch": 47, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ALG8`** are associated with which clinical phenotype and molecular mechanism in **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**?", "a": "Severe protein-losing enteropathy in normally developing children is often associated with pathogenic variants in MPI or ALG8 .", "img": null}, {"id": "fc_047_15", "ch": 47, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SLC35A1`** are associated with which clinical phenotype and molecular mechanism in **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**?", "a": "SLC35A1- and COG6-CDG have been associated with thrombocytopenia, whereas a Bombay blood group accompanied by hyperleukocytosis is the hallmark of SLC35C1-CDG.", "img": null}, {"id": "fc_047_16", "ch": 47, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATP6AP1`** are associated with which clinical phenotype and molecular mechanism in **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**?", "a": "Metabolic cutis laxa is associated with neurological symptoms in ATP6V0A2CDG and ATP6V1E1-CDG, while ATP6V1A-CDG, ATP6AP1-, and ATP6AP2-CDG also show severe hypercholesterolemia, and the latter two might also present with immunodeficiency.", "img": null}, {"id": "fc_047_17", "ch": 47, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **CAD Deficiency Clinical characteristics: Early infantile epilepsy encephalopathy, dyserythropoietic **?", "a": "**Therapy / Intervention:** Therapy: Uridine: 100 mg/kg/day (divided into 4 doses) Mechanism: Provides uridine for UMP synthesis, thereby bypassing the metabolic block in thede novosynthesis pathway\n\n**Clinical Context:** Therapy: Uridine: 100 mg/kg/day (divided into 4 doses) Mechanism: Provides uridine for UMP synthesis, thereby bypassing the metabolic block in thede novosynthesis pathway — Efficacy: Seizure cessation, resolves anemia, i", "img": null}, {"id": "fc_047_18", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **O-Linked Protein Glycosylation**, how is **O-mannosylation** defined and characterized?", "a": "O-mannosylation has been described for a limited number of client proteins expressed mainly in the nervous system and muscle tissue.", "img": null}, {"id": "fc_047_19", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **O-Linked Protein Glycosylation**, how is **domain-specific glycosylation** defined and characterized?", "a": "domain-specific glycosylation is initiated in the ER, while further extension and modification of the glycan occurs in the Golgi.", "img": null}, {"id": "fc_047_20", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**, how is **PMM2-CDG** defined and characterized?", "a": "PMM2-CDG is the most prevalent disorder of N-glycosylation with over 1,000 patients identified worldwide.", "img": null}, {"id": "fc_047_21", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**, how is **N-glycosylation** defined and characterized?", "a": "N-glycosylation and those involving multiple glycosylation pathways , some of these CDG present clinically recognizable features.", "img": null}, {"id": "fc_047_22", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**, how is **proteoglycan synthesis** defined and characterized?", "a": "proteoglycan synthesis is critical for the function of the extracellular matrix (ECM), genetic defects are mainly associated with skeletal abnormalities, joint laxity, and short stature.", "img": null}, {"id": "fc_047_23", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**, how is **GPI-anchor** defined and characterized?", "a": "GPI-anchor deficiency has variable clinical consequences, including hypotonia, developmental delay, epilepsy, visual impairment, hearing loss, cerebral and cerebellar atrophy, and congenital malformations.", "img": null}, {"id": "fc_047_24", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Disorders of Glycosylation: Nomenclature and Classification (Partial List)—cont'd**, how is **glycosphingolipid synthesis** defined and characterized?", "a": "glycosphingolipid synthesis have been described to date, all presenting mainly a neurological phenotype ranging from intellectual disability to severe epilepsy and hereditary spastic paraparesis.", "img": null}, {"id": "fc_047_25", "ch": 47, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis of Glycosylation Disorders**, how is **O-mannosylation** defined and characterized?", "a": "O-mannosylation , α-dystroglycan can be examined by immunohistochemical staining of a muscle biopsy.", "img": null}, {"id": "fc_047_26", "ch": 47, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 47.1):", "a": "Biosynthesis of the activated sugar donors UPD-GlcNAc, GDP-Man, Dol-P-Man, Dol-P-Glc, UDP-Glc, UDP-Gal, and CMP-Sia. ALG5, Dolichyl-phosphate beta-glucosyltransferase; DPM1/2/3, dolicholphosphate mannosyltransferase subunit 1/2/3; GALE, UDP-galactose 4-epimerase; GALK1, galactokinase 1; GDP, guanosine diphosphate; GFPT-1, glutamine-fructose-6-phosphate transaminase 1; GMPPA, GDP-mannose pyrophosphorylase; GNE, bifunctional UDP-N-acetylglucosamine 2-epimerase/ N-acetylmannosamine kinase; MPI, mannose-6 phosphate isomerase; NANS, N-acetylneuraminate synthase; PGM3, phosphoglucomutase 3; PMM2, phosphomannomutase 2; UDP, uridine diphosphate.", "img": "fig_p1070_01.jpg"}, {"id": "fc_047_27", "ch": 47, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 47.2):", "a": "Schematic representation of the major classes of mammalian glycoconjugates. EGF, Epidermal growth factor; GPI-anchor, glycosylphosphatidylinositol anchor; Ser, serine residue; S/T, serine or threonine residues; Trp, tryptophan residue; TSR, thrombospondin type-1 repeats.", "img": "fig_p1071_02.jpg"}, {"id": "fc_047_28", "ch": 47, "part": "VIII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Congenital Dis i orders of Glycosylation: Nomenclature and Classification (Partial List)**, what are the distinguishing features of **Disorders of Monosac PMM2-CDG**?", "a": "**Name**: charide Synthesis and Interconversion Phosphomannomutase 2 deficiency", "img": null}, {"id": "fc_048_01", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Alpers-Huttenlocher syndrome**?", "a": "**Causative Gene(s):** `POLG, FARS2, NARS2, PARS2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: Triad of intractable seizures, developmental regression+/−liver failure — Gene(s): POLG rarelyCARS2, FARS2, NARS2, PARS2, TWNK — Inheritance: AR", "img": null}, {"id": "fc_048_02", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Bjornstad syndrome**?", "a": "**Causative Gene(s):** `BCS1L` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: Congenital SNHL, pili torti — Inheritance: AR — BCS1L , encoding a protein responsible for the incorporation of the Rieske iron-sulfur protein into the nascent complex III holoenzyme, is the complex III assembly factor most frequently linked to disease.", "img": null}, {"id": "fc_048_03", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CoQ10biosynthesis defects**?", "a": "**Causative Gene(s):** `COQ2, COQ4, COQ7, COQ9, PDSS1, COQ8A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: 3 main phenotypes: Complex multisystem disease Ataxia+/−seizures Steroid resistant nephrotic syndrome — Gene(s): COQ2, COQ4, COQ7, COQ9, PDSS1 COQ8A COQ2, COQ6, COQ8B, PDSS — Inheritance: 2 AR", "img": null}, {"id": "fc_048_04", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **DCMA**?", "a": "**Causative Gene(s):** `DNAJC19` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: DCMwithataxia — Inheritance: AR", "img": null}, {"id": "fc_048_05", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Ethylmalonic encephalopathy**?", "a": "**Causative Gene(s):** `ETHE1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: Encephalopathy, acrocyanosis, petechiae, diarrhea, ethylmalonic aciduria — Inheritance: AR", "img": null}, {"id": "fc_048_06", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Friedreich ataxia**?", "a": "**Causative Gene(s):** `FXN` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: Progressive ataxia, muscle weakness, dysarthria, sensory neuropathy, HCM — Inheritance: AR", "img": null}, {"id": "fc_048_07", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **GRACILE**?", "a": "**Causative Gene(s):** `BCS1L` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: Growthretardation,aminoaciduria,cholestasis,iron overload,LA andearly death — Inheritance: AR", "img": null}, {"id": "fc_048_08", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HUPRA**?", "a": "**Causative Gene(s):** `SARS2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: Hyperuricemia,pulmonary hypertension,renal failure, alkalosis — Inheritance: AR", "img": null}, {"id": "fc_048_09", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **MDDS**?", "a": "**Causative Gene(s):** `MPV17, POLG` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: MitochondrialDNAdepletion syndrome—3 main phenotypes: Hepatocerebral — Gene(s): DGUOK, MPV17, POLG, TWNK — Inheritance: AR", "img": null}, {"id": "fc_048_10", "ch": 48, "part": "VIII", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **MEGDEL**?", "a": "**Causative Gene(s):** `SERAC1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Canonical Clinical Features: 3MGA,deafness,encephalopathy, andLeigh-like disease — Inheritance: AR", "img": null}, {"id": "fc_048_11", "ch": 48, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`OPA1`** are associated with which clinical phenotype and molecular mechanism in **Optic neuropathy: Leber hereditary optic neuropathy**?", "a": "Dominant optic atrophy or Kjer’s disease , is caused by dominant variants of the OPA1 mitochondrial fusion protein and is the most common genetic optic atrophy.", "img": null}, {"id": "fc_048_12", "ch": 48, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`BCS1L`** are associated with which clinical phenotype and molecular mechanism in **Disorders of Oxidative Phosphorylation**?", "a": "BCS1L , encoding a protein responsible for the incorporation of the Rieske iron-sulfur protein into the nascent complex III holoenzyme, is the complex III assembly factor most frequently linked to disease.", "img": null}, {"id": "fc_048_13", "ch": 48, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CHCHD10`** are associated with which clinical phenotype and molecular mechanism in **Disorders of Mitochondrial Lipid Biosynthesis and Membrane Stability**?", "a": "Dominant variants in two proteins associated with the MICOS, CHCHD2 and CHCHD10, may cause Parkinson disease, frontotemporal dementia, or amyotrophic lateral sclerosis.", "img": null}, {"id": "fc_048_14", "ch": 48, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SPG7`** are associated with which clinical phenotype and molecular mechanism in **Disorders of Protein Quality Control**?", "a": "Other proteins involved in mitochondrial quality control (including AFG3L2, HSPD1, and SPG7) are associated with spastic paraplegia and ataxia syndromes.", "img": null}, {"id": "fc_048_15", "ch": 48, "part": "VIII", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ETHE1`** are associated with which clinical phenotype and molecular mechanism in **Metabolic Investigations**?", "a": "Ethylmalonic aciduria is present in patients with ethylmalonic encephalopathy caused by ETHE1 deficiency.", "img": null}, {"id": "fc_048_16", "ch": 48, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Genetics of Primary Mitochondrial Disorders**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Another promising approach to treatment of LHON is that of allotopic gene therapy, which has undergone phase III clinical trials examining the therapeutic response in those affected for less than 6 months (RESCUE) and those visually impaired for between 6 and 12 months (REVERSE);", "img": null}, {"id": "fc_048_17", "ch": 48, "part": "VIII", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Emerging Therapies**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Genetic therapies can be divided into those that target the mtDNA, and gene therapy for nuclear DNA encoded PMDs.", "img": null}, {"id": "fc_048_18", "ch": 48, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetics of Primary Mitochondrial Diseases**, how is **Primary mitochondrial diseases (PMD)** defined and characterized?", "a": "Primary mitochondrial diseases (PMD) are defined as genetic disorders affecting mitochondrial function, structure, or dynamics, and are estimated to affect at least 1 in 4,300 people.", "img": null}, {"id": "fc_048_19", "ch": 48, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetics of Primary Mitochondrial Diseases**, how is **heteroplasmy** defined and characterized?", "a": "heteroplasmy , whereas homoplasmy refers to the situation where all copies of mtDNA are identical.", "img": null}, {"id": "fc_048_20", "ch": 48, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Optic neuropathy: Leber hereditary optic neuropathy**, how is **hypertrophic** defined and characterized?", "a": "hypertrophic , with deep trabeculation of the myocardial wall that may extend to noncompaction and may be dilated in end-stage disease.", "img": null}, {"id": "fc_048_21", "ch": 48, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Disease Spectrum Associated With m.3243A > G**, how is **intestinal pseudoobstruction** defined and characterized?", "a": "intestinal pseudoobstruction , which usually requires conservative management rather than surgical intervention and is a significant contributor to the mortality of these stroke-like events.", "img": null}, {"id": "fc_048_22", "ch": 48, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **The Disease Spectrum Associated With m.3243A > G**, how is **progressive external ophthalmoplegia (PEO)** defined and characterized?", "a": "progressive external ophthalmoplegia (PEO) is a recognized manifestation of disease associated with m.", "img": null}, {"id": "fc_048_23", "ch": 48, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Myoclonic Epilepsy With Ragged Red Fibers**, how is **maternally inherited Leigh syndrome (MILS)** defined and characterized?", "a": "maternally inherited Leigh syndrome (MILS) rather than MERRF, or more typically in late childhood or early adult life.", "img": null}, {"id": "fc_048_24", "ch": 48, "part": "VIII", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Disorders of Oxidative Phosphorylation**, how is **Leigh syndrome** defined and characterized?", "a": "Leigh syndrome or leukoencephalopathies , variably associated with cardiomyopathy .", "img": null}, {"id": "fc_048_25", "ch": 48, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 48.1):", "a": "Oxidative phosphorylation. Schematic representation of the process of oxidative phosphorylation which occurs on the inner mitochondrial membrane. Electrons donated from the tricarboxylic acid cycle enter the mitochondrial respiratory chain at complex I, through the oxidation of nicotinamide adenine dinucleotide (NADH), and at complex II through oxidation of succinate and reduction of ubiquinone to ubiquinol. A third entry point for electrons derived from fatty acid oxidation occurs via the electron transfer flavoprotein. Through a series of electrochemical reactions electrons are exchanged or shuttled via CoQ10 (ubiquinone/ubiquinol) through the complexes until they reach complex IV, where oxygen acts as the ultimate electron acceptor. As electrons move through the mitochondrial respiratory chain, electrical neutrality is maintained by the extrusion of protons at complexes I, III, and IV forming a potential electrochemical gradient across the inner mitochondrial membrane, which is then dissipated through complex V, driving the condensation of inorganic phosphate (Pi) with adenosine dinucleotide (ADP) to form adenosine triphosphate (ATP), the energy currency of the cell.", "img": "fig_p1092_02.jpg"}, {"id": "fc_048_26", "ch": 48, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 48.2):", "a": "Mitochondrial DNA. A schematic representation of mitochondrial DNA (mtDNA), a double stranded loop of approximately 16.5 kb in size, comprising light (L) and heavy (H) strands, encoding 13 proteins (red, blue, green, and orange), 22 tRNAs (white), and 2 ribosomal RNAs (yellow). The displacement or D-loop (cyan) is a triple-stranded noncoding region essential for the replication and transcription of mtDNA. The D-loop houses the both the light strand (PL) and heavy strand (PH) promoters, as well as the origin of heavy strand replication (OH).", "img": "fig_p1093_02.jpg"}, {"id": "fc_048_27", "ch": 48, "part": "VIII", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 48.3):", "a": "Germline mtDNA heteroplasmy segregation. Normal mitochondria with functional mtDNAs are blue. Defective mitochondria with abnormal mtDNAs are brown. Oocytes bear hundreds of thousands of mtDNAs. After fertilization of a heteroplasmic oocyte, nDNA replication and cell division form a blastocyst, but the mtDNAs do not replicate and are randomly distributed into daughter cells. Some inner-cell-mass cells become primordial germ cells (PGCs), which form the oocytes in the female embryos. Each PGC receives only a few functional mtDNA elements, thus generating a broad distribution of PGC mtDNA heteroplasmy levels. The PGCs replicate and increase their mtDNAs and form proto-oocytes. After hormonal stimulation, multiple oocytes mature toward ovulation. Those proto-oocytes and/or embryos with the most robust mitochondria outcompete those with deficient mitochondria and survive. If all of a woman’s PGCs receive a high proportion of mutant mtDNAs, no normal proto-oocytes or embryos are available to outcompete the mutant, and multiple affected offspring result. (Modified from Wallace DC. Mitochondrial genetic medicine. Nat Genet . 2018;50:164201649 [Fig. 1A, p. 1643].)", "img": "fig_p1094_01.jpg"}, {"id": "fc_048_28", "ch": 48, "part": "VIII", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **##### 48.1 #### Mitochondrial Clinical Syndromes**, what are the distinguishing features of **Alpers-Huttenlocher syndrome**?", "a": "**Canonical Clinical Features**: Triad of intractable seizures, developmental regression+/−liver failure; **Gene(s)**: POLG rarelyCARS2, FARS2, NARS2, PARS2, TWNK; **Inheritance**: AR", "img": null}, {"id": "fc_049_01", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HS-1**?", "a": "**Causative Gene(s):** `SPTB` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormal Protein: β-Spectrin — Gene/Chromosome: SPTB/14q23-q24.1 — Frequency: 40–50% — Anemia RBC Morphology: Slight to moderate Spherocytes+acanthocytes", "img": null}, {"id": "fc_049_02", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HS-2**?", "a": "**Causative Gene(s):** `ANK1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormal Protein: Ankyrin — Gene/Chromosome: ANK1/8p11.2 — Frequency: 20–30% — Anemia RBC Morphology: Slight to moderate Spherocytes", "img": null}, {"id": "fc_049_03", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HS-3**?", "a": "**Causative Gene(s):** `SLC4A1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormal Protein: Band 3 — Gene/Chromosome: SLC4A1/17q21 — Frequency: 15–20% — Anemia RBC Morphology: Slight to moderate Spherocytes+pincered cells", "img": null}, {"id": "fc_049_04", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HS-4**?", "a": "**Causative Gene(s):** `SPTA1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormal Protein: α-Spectrin — Gene/Chromosome: SPTA1/1q22-q23 — Frequency: 5–7% — Anemia RBC Morphology: Severe Spherocytes+microspherocytes+ schistocytes", "img": null}, {"id": "fc_049_05", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **HS-5**?", "a": "**Causative Gene(s):** `EPB42` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Abnormal Protein: Protein 4.2 — Gene/Chromosome: EPB42/15q15-q21 — Frequency: <5% — Anemia RBC Morphology: Moderate Spherocytes+ovalocytes", "img": null}, {"id": "fc_049_06", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hereditary Spherocytosis**?", "a": "**Causative Gene(s):** `SPTA1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** The most severe form of HS is a compound heterozygous condition wherein a pathogenic SPTA1 variant coexists in trans with the null polymorphic α-LEPRA (Low Expression, Prague) allele, which allows for residual expression of small amounts of normal α-spectrin sufficient to avoid the lethality associa", "img": null}, {"id": "fc_049_07", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hereditary Elliptocytosis**?", "a": "**Causative Gene(s):** `SPTA1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** The most frequently affected proteins are α- spectrin (SPTA1) in up to 65% of cases, β-spectrin (SPTB) in up to 30% of cases, and protein 4.1 (EPB41) in up to 5%.", "img": null}, {"id": "fc_049_08", "ch": 49, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**?", "a": "**Causative Gene(s):** `PIEZO1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Dehydrated hereditary stomatocytosis 1 (DHS1) is the more prevalent form and is caused by pathogenic variants in PIEZO1 , which encodes a mechanosensitive protein (Piezo1) that is part of stretch-activated cation channels.", "img": null}, {"id": "fc_049_09", "ch": 49, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SPTA1`** are associated with which clinical phenotype and molecular mechanism in **Hereditary Spherocytosis**?", "a": "The most severe form of HS is a compound heterozygous condition wherein a pathogenic SPTA1 variant coexists in trans with the null polymorphic α-LEPRA (Low Expression, Prague) allele, which allows for residual expression of small amounts of normal α-spectrin sufficient to avoid the lethality associated with complete absence of α-spectrin.", "img": null}, {"id": "fc_049_10", "ch": 49, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PIEZO1`** are associated with which clinical phenotype and molecular mechanism in **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**?", "a": "Dehydrated hereditary stomatocytosis 1 (DHS1) is the more prevalent form and is caused by pathogenic variants in PIEZO1 , which encodes a mechanosensitive protein (Piezo1) that is part of stretch-activated cation channels.", "img": null}, {"id": "fc_049_11", "ch": 49, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`KCNN4`** are associated with which clinical phenotype and molecular mechanism in **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**?", "a": "Dehydrated hereditary stomatocytosis 2 (DHS2) is caused by pathogenic variants in KCNN4 , which encodes the Gardos channel, a widely expressed Ca -dependent K channel that mediates K conductance in RBCs.", "img": null}, {"id": "fc_049_12", "ch": 49, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SLC4A1`** are associated with which clinical phenotype and molecular mechanism in **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**?", "a": "SLC4A1 encodes a segment of band 3 involved in anion exchange and the regulation of cation leak.", "img": null}, {"id": "fc_049_13", "ch": 49, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SLC2A1`** are associated with which clinical phenotype and molecular mechanism in **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**?", "a": "SLC2A1 encodes the GLUT1 glucose transporter, which also binds stomatin, an integral membrane protein.", "img": null}, {"id": "fc_049_14", "ch": 49, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`G6PD`** are associated with which clinical phenotype and molecular mechanism in **Erythroenzymopathies**?", "a": "Erythroenzymopathies, or defects in RBC enzymes (other than G6PD) are rare diseases leading to NIHA.", "img": null}, {"id": "fc_049_15", "ch": 49, "part": "IX", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Structural Hemoglobinopathies**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** HU is currently the treatment of choice in children and young patients, where it is recommended from shortly after birth to prevent recurrent VOCs.", "img": null}, {"id": "fc_049_16", "ch": 49, "part": "IX", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Thalassemia Syndromes**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Hematopoietic stem cell transplantation (HSCT) and gene therapy are the only curative treatment for thalassemia though HSCT is reserved for the more severe cases with neonatal onset, or when regular blood transfusions are problematic or ineffective.", "img": null}, {"id": "fc_049_17", "ch": 49, "part": "IX", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **NIHA Due to Infections**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Artesunate has replaced quinine as the recommended first-line treatment for severe malaria; patients should be monitored for drug-induced hemolysis for at least 4 weeks following treatment.", "img": null}, {"id": "fc_049_18", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Nonimmune Hemolytic Anemias**, how is **Nonimmune hemolytic anemias (NIHAs)** defined and characterized?", "a": "Nonimmune hemolytic anemias (NIHAs) are a heterogeneous group of rare diseases that primarily affect the integrity of the red blood cell (RBC), but that can also affect hematopoiesis.", "img": null}, {"id": "fc_049_19", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Membranopathies**, how is **hereditary elliptocytosis (HE)** defined and characterized?", "a": "hereditary elliptocytosis (HE) , due to failure of horizontal interactions; and (3) hereditary stomatocytosis , due to altered permeability of the RBC membrane that leads to either an increase or decrease in cellular hydration and volume, with a resultant change in shape (Table 49.", "img": null}, {"id": "fc_049_20", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Spherocytosis**, how is **Hereditary spherocytosis (HS)** defined and characterized?", "a": "Hereditary spherocytosis (HS) is the most common RBC membrane disorder.", "img": null}, {"id": "fc_049_21", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Elliptocytosis**, how is **hereditary pyropoikilocytosis (HPP)** defined and characterized?", "a": "hereditary pyropoikilocytosis (HPP) occurs when a pathogenic HE variant exists in trans (i.", "img": null}, {"id": "fc_049_22", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**, how is **Dehydrated hereditary stomatocytosis 1 (DHS1)** defined and characterized?", "a": "Dehydrated hereditary stomatocytosis 1 (DHS1) is the more prevalent form and is caused by pathogenic variants in PIEZO1 , which encodes a mechanosensitive protein (Piezo1) that is part of stretch-activated cation channels.", "img": null}, {"id": "fc_049_23", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**, how is **Dehydrated hereditary stomatocytosis 2 (DHS2)** defined and characterized?", "a": "Dehydrated hereditary stomatocytosis 2 (DHS2) is caused by pathogenic variants in KCNN4 , which encodes the Gardos channel, a widely expressed Ca -dependent K channel that mediates K conductance in RBCs.", "img": null}, {"id": "fc_049_24", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**, how is **Southeast Asian ovalocytosis (SAO)** defined and characterized?", "a": "Southeast Asian ovalocytosis (SAO) is caused by a unique deletion of 27 nucleotides in SLC4A1 that affects band 3 and results in ovalocytes or ovalo-stomatocytes (Fig.", "img": null}, {"id": "fc_049_25", "ch": 49, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Hereditary Stomatocytosis (Abnormal RBC Membrane Permeability Syndromes)**, how is **GLUT1 deficiency** defined and characterized?", "a": "GLUT1 deficiency , a condition termed stomatin-deficient cryohydrocytosis .", "img": null}, {"id": "fc_049_26", "ch": 49, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 49.1):", "a": "Red blood cell (RBC) shape and sizes. Structure of RBC membrane skeleton.", "img": "fig_p1114_01.jpg"}, {"id": "fc_049_27", "ch": 49, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 49.2):", "a": "May-Grünwald Giemsa-stained blood smear of a patient with hereditary spherocytosis. Top: two spherocytes (arrows) ; Bottom: pincer cell (arrow) .", "img": "fig_p1115_06.jpg"}, {"id": "fc_049_28", "ch": 49, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 49.3):", "a": "Sodium dodecyl sulfate polyacrylamide gel electrophoresis (SDS-PAGE) of membrane", "img": "fig_p1116_10.jpg"}, {"id": "fc_050_01", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Type 2 (F-HLH 2)**?", "a": "**Causative Gene(s):** `PRF1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): PRF1(perforin) — HLH-Related Dysfunction: Cytolytic pore formation", "img": null}, {"id": "fc_050_02", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Type 3 (F-HLH 3)**?", "a": "**Causative Gene(s):** `UNC13D` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): UNC13D(Unc-13 homolog D) — HLH-Related Dysfunction: Cytolytic vesicle priming — Unique Clinical Features: Increased incidence of CNS disease", "img": null}, {"id": "fc_050_03", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Type 4 (F-HLH 4)**?", "a": "**Causative Gene(s):** `STX11` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): STX11(Syntaxin 11) — HLH-Related Dysfunction: Cytolytic vesicle fusion — Unique Clinical Features: Mild, recurrent HLH, colitis", "img": null}, {"id": "fc_050_04", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Type 5 (F-HLH 5)**?", "a": "**Causative Gene(s):** `STXBP2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): STXBP2(Syntaxin binding protein 2) — HLH-Related Dysfunction: Cytolytic vesicle fusion — Unique Clinical Features: Colitis; hypogammaglobulinemia, and sensorineural hearing loss", "img": null}, {"id": "fc_050_05", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Hermansky-Pudlak syndrome type 2**?", "a": "**Causative Gene(s):** `AP3B1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): AP3B1(Adaptor Related Protein Complex 3 Subunit Beta 1) — HLH-Related Dysfunction: Cytolytic vesicle trafficking — Unique Clinical Features: Partial albinism; immunodeficiency, bleeding tendency, and platelet storage pool deficiency", "img": null}, {"id": "fc_050_06", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Griscelli syndrome type 2**?", "a": "**Causative Gene(s):** `RAB27A` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): RAB27A(Rab-27A protein) — HLH-Related Dysfunction: Cytolytic vesicle docking — Unique Clinical Features: Partial albinism and silvery gray hair", "img": null}, {"id": "fc_050_07", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **X-linked lymphoproliferative disorder type 1 (XLP1)**?", "a": "**Causative Gene(s):** `SH2D1A, SH2, XLP1` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): SH2D1A(SH2 Domain Containing 1A) — HLH-Related Dysfunction: Defective killing of EBV-infected B cells — Unique Clinical Features: Severe HLH; Hypogammaglobulinemia, and lymphoma", "img": null}, {"id": "fc_050_08", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **X-linked lymphoproliferative disorder type 2 (XLP2)**?", "a": "**Causative Gene(s):** `XIAP, XLP2` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): XIAP(X-linked inhibitor of apoptosis protein) — HLH-Related Dysfunction: Increased inhibition of apoptosis in EBV-infected cells (gain of function) — Unique Clinical Features: Mild, recurrent HLH (may be triggered by non-EBV viruses)", "img": null}, {"id": "fc_050_09", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **IL-2-inducible T cell kinase deficiency**?", "a": "**Causative Gene(s):** `IL2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Locus (Protein): ITK(IL2 inducible T cell kinase) — HLH-Related Dysfunction: Impaired proliferation of EBV-specific T cells — Unique Clinical Features: Hodgkin lymphoma", "img": null}, {"id": "fc_050_10", "ch": 50, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CD27 deficiency**?", "a": "**Causative Gene(s):** `CD27` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** HLH-Related Dysfunction: Impaired proliferation of EBV-specific T cells — Unique Clinical Features: Combined immunodeficiency", "img": null}, {"id": "fc_050_11", "ch": 50, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`BRAF`** are associated with which clinical phenotype and molecular mechanism in **Langerhans Cell Histiocytosis**?", "a": "Mitogen-activated protein kinase (MAPK) pathway gene alterations are present in more than 85% of cases of LCH (most commonly BRAF -V600E pathogenic variants), and activation of this pathway appears to be a primary inducer of lymphoproliferation, suggestive of a neoplastic process.", "img": null}, {"id": "fc_050_12", "ch": 50, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STXBP2`** are associated with which clinical phenotype and molecular mechanism in **50.3 Histopathology of IgG4-Related Disease (IgG4-RD)**?", "a": "There are multiple genetic causes of HLH including pathogenic variants in PRF1, UNC13D, STX11, STXBP2, and NLRC4 .", "img": null}, {"id": "fc_050_13", "ch": 50, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`XLP1`** are associated with which clinical phenotype and molecular mechanism in **X-Linked Lymphoproliferative Diseases**?", "a": "Type 1 (XLP1) is a primary immunodeficiency associated with an inability to clear infection with EBV.", "img": null}, {"id": "fc_050_14", "ch": 50, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`SH2D1A`** are associated with which clinical phenotype and molecular mechanism in **X-Linked Lymphoproliferative Diseases**?", "a": "SH2D1A encodes the Signaling Lymphocytic Activation Molecule (SLAM)-associated protein (SAP).", "img": null}, {"id": "fc_050_15", "ch": 50, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NOD2`** are associated with which clinical phenotype and molecular mechanism in **X-Linked Lymphoproliferative Diseases**?", "a": "XIAP is an anti-apoptotic factor that also is required for NOD1/NOD2 signaling.", "img": null}, {"id": "fc_050_16", "ch": 50, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FAS`** are associated with which clinical phenotype and molecular mechanism in **Autoimmune Lymphoproliferative Syndrome (ALPS)**?", "a": "Autoimmune lymphoproliferative syndrome (ALPS) is an inherited lymphoproliferative disorder resulting from heterozygous variants in the FAS receptor signaling pathway.", "img": null}, {"id": "fc_050_17", "ch": 50, "part": "IX", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Treatment**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Other options include the cytotoxic T-lymphocyte antigen-4 fusion protein abatacept, and the anti-IL-4 receptor monoclonal antibody dupilumab.", "img": null}, {"id": "fc_050_18", "ch": 50, "part": "IX", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Diagnosis**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** The recombinant IL-1 receptor antagonist anakinra is effective in patients with MAS secondary to sJIA and other rheumatic diseases.", "img": null}, {"id": "fc_050_19", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **Solitary LCH** defined and characterized?", "a": "Solitary LCH usually presents with indolent onset in older children or adults with isolated bone lesions (eosinophilic granuloma) .", "img": null}, {"id": "fc_050_20", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Clinical Features**, how is **multisystem form** defined and characterized?", "a": "multisystem form often occurs in patients under 1 year of age and is usually more aggressive.", "img": null}, {"id": "fc_050_21", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis**, how is **Birbeck granules** defined and characterized?", "a": "Birbeck granules , cytoplasmic structures that are shaped like a tennis racket.", "img": null}, {"id": "fc_050_22", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnosis**, how is **progressive transformation of germinal center-like** defined and characterized?", "a": "progressive transformation of germinal center-like (scattered larger follicles with plasma cells), and inflammatory pseudotumor-like (node partially effaced by fibro-inflammatory infiltrate and storiform fibrosis).", "img": null}, {"id": "fc_050_23", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **50.3 Histopathology of IgG4-Related Disease (IgG4-RD)**, how is **Systemic juvenile idiopathic arthritis (sJIA)** defined and characterized?", "a": "Systemic juvenile idiopathic arthritis (sJIA) is the most common rheumatic disease associated with MAS.", "img": null}, {"id": "fc_050_24", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **X-Linked Lymphoproliferative Diseases**, how is **Type 1 (XLP1)** defined and characterized?", "a": "Type 1 (XLP1) is a primary immunodeficiency associated with an inability to clear infection with EBV.", "img": null}, {"id": "fc_050_25", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **X-Linked Lymphoproliferative Diseases**, how is **XLP type 2** defined and characterized?", "a": "XLP type 2 is recognized as X-linked inhibitor of apoptosis (XIAP) deficiency.", "img": null}, {"id": "fc_050_26", "ch": 50, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Treatment**, how is **multicentric Castleman disease (POEMS-MCD)** defined and characterized?", "a": "multicentric Castleman disease (POEMS-MCD) , both of which result from pathological plasma cells.", "img": null}, {"id": "fc_050_27", "ch": 50, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 50.1):", "a": "Overlaps in the pathogenesis of lymphoproliferation in IEI, infections, and malignancies. EBV, Epstein-Barr virus; HLH, hemophagocytic lymphohistiocytosis. (The Etiologic Landscape of Lymphoproliferation in Childhood: Proposal for a Diagnostic Approach Exploring from Infections to Inborn Errors of Immunity and Metabolic Diseases, © 2024 Costagliola et al, taken from Therapeutics and Clinical Risk Management, © 2024 Dove Medical Press Limited, reprinted by permission of Informa UK Limited, trading Taylor & Francis Group https://www.tandfonline.com. This is an Open Access article distributed under the terms of the Creative Commons Attribution – Non Commercial [unported, v3.0] License [http://creativecommons.org/ licenses/by-nc/3.0/] which permits non-commercial re-use, distribution, and reproduction in any medium, provided the original work is properly cited, and is not altered, transformed, or built upon in any way.)", "img": "fig_p1136_01.jpg"}, {"id": "fc_050_28", "ch": 50, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 50.2):", "a": "First-level approach to patients presenting with lymphoproliferation. CMV, Cytomegalovirus; CRP, C-reactive protein; CT, computed tomography; EBV, Epstein-Barr virus; ESR, erythrocyte sedimentation rate; GAS, group A Streptococcus , HLH, hemophagocytic lymphohistiocytosis; IGRA, interferon-gamma release assay; NTM, nontuberculous mycobacteria; PET, positron emission tomography; TST, tuberculin skin test; US, ultrasound. Notes: This algorithm identifies the patients with a clinical picture suggestive for infection (green boxes) and malignancy (red boxes) and those with a less defined clinical picture (yellow boxes) . The diagnostic approach for patients with suspected infection or malignancy is provided, evidencing that first-level analysis and US imaging are mandatory in patients with high risk of malignancy. On the other hand, when infection is suspected, the choice about performing laboratory and imaging investigations relies on the individual situation. Patients without a clearly defined diagnosis should be periodically reassesses and eventually undergo further investigations. There is no uniform consensus regarding the need to perform prolonged antibiotic treatment in NTM lymphadenitis, and some authors suggest to perform only clinical observation. *PET and CT can be performed also before lymph nodal biopsy based on the clinical judgment. (The Etiologic Landscape of Lymphoprolifer", "img": "fig_p1137_02.jpg"}, {"id": "fc_051_01", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SAMD9/SAMD9L disorders**?", "a": "**Causative Gene(s):** `SAMD9, SAMD9L` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** y g: MIRAGE (SAMD9): MDS, infection, restriction of growth, adrenal hypoplasia, genital phenotypes, and enteropathy — y: Transient or permanent cytopenia", "img": null}, {"id": "fc_051_02", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Fanconi anemia**?", "a": "**Causative Gene(s):** `FANCA, FANCC, FANCD1, BRCA2, FANCD2, FANCG` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — FANCA, FANCC, FANCD1/BRCA2, FANCD2, FANCE, FANCF, FANCG/XRCC9, FANC1, FANCJ/BRIP1, FANCL/PHF9, FANCM, FANCN/PALB2, FANCO/RAD51C, FANCP/ SLX4, FANCQ/ERCC4, FANCR/RAD51, FANCS/BRCA1, FANCT/UBE2T, FANCU/ XRCC2, FANCV/REV7, FANCW/RFWD3 — Affected Pathways: DNA repair, homologous recombination, ribosome biogenesis(FANC1)", "img": null}, {"id": "fc_051_03", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Mixed Fanconi anemia/ xeroderma pigmentosa/ Cockayne syndrome**?", "a": "**Causative Gene(s):** `ERCC1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — ERCC1/XPF — Affected Pathways: DNA repair", "img": null}, {"id": "fc_051_04", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Shwachman-Diamond**?", "a": "**Causative Gene(s):** `SBDS, DNAJC21, EFL1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — SBDS, DNAJC21, EFL1 — Affected Pathways: Ribosome biogenesis — Shwachman-Diamond syndrome is a rare autosomal recessive HBMFS secondary to pathogenic variants in genes involved in ribosomal biogenesis that leads to defects in ribosome assembly.", "img": null}, {"id": "fc_051_05", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **syndrome**?", "a": "**Causative Gene(s):** `SRP54` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Affected Pathways: Co-translational protein modification — Shwachman-Diamond syndrome is a rare autosomal recessive HBMFS secondary to pathogenic variants in genes involved in ribosomal biogenesis that leads to defects in ribosome assembly.", "img": null}, {"id": "fc_051_06", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Dyskeratosis congenita**?", "a": "**Causative Gene(s):** `DKC1` · **Inheritance:** XLR\n\n**Clinical & Molecular Profile:** Inheritance: XLR — Affected Pathways: Telomere maintenance, ribosome biogenesis — Dyskeratosis congenita (DC) is a rare multisystemic disorder caused by abnormalities in telomere biology .", "img": null}, {"id": "fc_051_07", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SRP72-associated hereditary aplastic anemia/MDS**?", "a": "**Causative Gene(s):** `SRP72` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Affected Pathways: Co-translational protein modification", "img": null}, {"id": "fc_051_08", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **ERCC6L2-associated hereditary aplastic anemia/MDS**?", "a": "**Causative Gene(s):** `ERCC6L2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Affected Pathways: Transcription", "img": null}, {"id": "fc_051_09", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Reticular dysgenesis**?", "a": "**Causative Gene(s):** `AK2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Affected Pathways: Nucleotide metabolism", "img": null}, {"id": "fc_051_10", "ch": 51, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Cartilage-hair hypoplasia**?", "a": "**Causative Gene(s):** `POP1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — RMRP, POP1, NEPRO — Affected Pathways: rRNA and mitochondrial RNA processing", "img": null}, {"id": "fc_051_11", "ch": 51, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`GATA2`** are associated with which clinical phenotype and molecular mechanism in **Other Genetic Syndromes**?", "a": "GATA2 encodes for a hematopoietic transcription factor involved in early stages of hematopoiesis.", "img": null}, {"id": "fc_051_12", "ch": 51, "part": "IX", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Other Genetic Syndromes**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** HSCT is the treatment of choice, as well as specific therapy for infectious complications.", "img": null}, {"id": "fc_051_13", "ch": 51, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **RACHEL PHELAN**, how is **Pancytopenia** defined and characterized?", "a": "Pancytopenia refers to reductions below age-related normal levels in each of the three peripheral blood cell types: erythrocytes, leukocytes, and platelets.", "img": null}, {"id": "fc_051_14", "ch": 51, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **General Diagnostic Approach**, how is **myelodysplastic syndrome (MDS)** defined and characterized?", "a": "myelodysplastic syndrome (MDS) or acute myeloid leukemia (AML) , cytogenetics and a fluorescence in situ hybridization panel for MDS should also be performed at the time of bone marrow evaluation.", "img": null}, {"id": "fc_051_15", "ch": 51, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **General Diagnostic Approach**, how is **hematopoietic stem cell transplantation (HSCT)** defined and characterized?", "a": "hematopoietic stem cell transplantation (HSCT) or other supportive therapies, such as androgens.", "img": null}, {"id": "fc_051_16", "ch": 51, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Fanconi Anemia**, how is **VACTERL-H association** defined and characterized?", "a": "VACTERL-H association (vertebral anomalies, anal atresia, cardiac defects, tracheoesophageal fistula, esophageal atresia, renal abnormalities, limb abnormalities, and hydrocephalus) may be present.", "img": null}, {"id": "fc_051_17", "ch": 51, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnostic Approach**, how is **chromosomal breakage analysis** defined and characterized?", "a": "chromosomal breakage analysis of peripheral blood lymphocytes is initially performed.", "img": null}, {"id": "fc_051_18", "ch": 51, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 51.1):", "a": "Decision algorithm for the clinical classification of patients with bone marrow failure. (A) Unexplained cytopenia(s) leading to the suspicion of an IBMFS can include a CBC of hemoglobin of <10.5 × 10 /L, neutrophils of <1.5 × 10 /L, and/or platelets of <150 × 10 /L. (B) The first decision point implies ruling out acquired causes of BMF including hematological malignancies and nutritional, infectious agents, immune, or drug exposure. (C) If acquired causes have been ruled out, we consider an IBMFS and complete a thorough physical examination, as well as prenatal, personal, and family history. Classification of the cytopenia and physical examination should be taken into consideration to guide clinical suspicion of a specific IBMFS. (D) If multilineage cytopenia and clinical features are compatible with FA, we perform the chromosome breakage test with DEB, if available. (E) If multilineage cytopenia and clinical features are compatible with DC, we perform the leukocyte telomere length test, if available (less often FA and DC can present with unilineage cytopenias). (F) If multilineage cytopenia and clinical features are compatible with SDS, we perform diagnostic screening with serum trypsinogen or pancreatic isoamylase. (G) If there is confirmation of anemia plus reticulocytopenia and clinical features are compatible with DBA, we perform diagnostic screening with erythrocyte adenosine de", "img": "fig_p1167_02.jpg"}, {"id": "fc_051_19", "ch": 51, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 51.2):", "a": "Comparative outline of the common anomalies observed in patients with IBMFS. Features that help build the suspicion of a specific IBMFS are given. The clinical manifestations of various IBMFS exhibit overlap in certain organs and systems. This includes cytopenias, an elevated risk of hematological malignancies, and short stature, which are common features among the classical IBMFS discussed in this paper. Highlighted in yellow, patients with FA are characterized by short stature, abnormal skin pigmentation, facial features, congenital heart disease, ear malformations, genitourinary malformations, renal malformations, and thumb defects. Highlighted in orange, patients with DC exhibit the following characteristics: nail dystrophy, mucosal leukoplakia, early hair graying, reticulated skin pigmentation, pulmonary fibrosis, short stature, and eye abnormalities. Highlighted in light blue, patients with SDS present pancreatic insufficiency, skeletal dysplasia, short stature, congenital heart disease, and hepatic dysfunction. Highlighted in pink, patients with DBA present short stature, thumb defects, asymmetric scapula, fusion of cervical vertebrae, webbed neck, genitourinary malformations, and congenital heart disease. Highlighted in green, patients with TAR present short stature, hypoplastic ulnae, hypoplastic humeri, and renal malformations. Highlighted in dark blue, patients with SCN present with short stature and inflammatory bowel disease. *Increased visibil", "img": "fig_p1168_01.jpg"}, {"id": "fc_051_20", "ch": 51, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 51.5):", "a": "Features of the diagnostic triad in dyskeratosis congenita. (A, B) Dystrophic nails on hands and feet. (C, D) Lacy reticular pigmentation on neck and upper thorax. (E, F) Oral leukoplakia on tongue and buccal mucosa. (A–C and E, From Shimamura A, Alter BP. Pathophysiology and management of inherited bone marrow failure syndromes. Blood Rev . 2010;24:101-122, Fig. 8; D and F, from Savage SA, Alter BP. Dyskeratosis congenita. Hematol Oncol Clin North Am . 2009;23:215-231.)", "img": "fig_p1176_09.jpg"}, {"id": "fc_051_21", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Age Hb (g/dL)* HCT (%)* MCV (fL)* MCHC (g/dL RBC)* Reticulocytes WBCs (310/mL) Platelets (10/mL)**, what are the distinguishing features of **26–30 wk gestation**?", "a": "**Hb (g/dL)***: 13.4 (11); **HCT (%)***: 41.5 (34.9); **MCV (fL)***: 118.2 (106.7); **MCHC (g/dL RBC)***: 37.9 (30.6); **WBCs (310/mL)**: 4.4 (2.7); **Platelets (10/mL)**: 254 (180–327)", "img": null}, {"id": "fc_051_22", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Age Hb (g/dL)* HCT (%)* MCV (fL)* MCHC (g/dL RBC)* Reticulocytes WBCs (310/mL) Platelets (10/mL)**, what are the distinguishing features of **28 wk**?", "a": "**Hb (g/dL)***: 14.5; **HCT (%)***: 45; **MCV (fL)***: 120; **MCHC (g/dL RBC)***: 31.0; **Reticulocytes**: (5–10); **Platelets (10/mL)**: 275", "img": null}, {"id": "fc_051_23", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Age Hb (g/dL)* HCT (%)* MCV (fL)* MCHC (g/dL RBC)* Reticulocytes WBCs (310/mL) Platelets (10/mL)**, what are the distinguishing features of **32 wk**?", "a": "**Hb (g/dL)***: 15.0; **HCT (%)***: 47; **MCV (fL)***: 118; **MCHC (g/dL RBC)***: 32.0; **Reticulocytes**: (3–10); **Platelets (10/mL)**: 290", "img": null}, {"id": "fc_051_24", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Clinical Manifestations and Laboratory Findings in Inherited Bone Marrow Failure Syndrome**, what are the distinguishing features of **Syndrome**?", "a": "**y g**: Nonhematological Clinical Manifestations; **y**: Laboratory Findings", "img": null}, {"id": "fc_051_25", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Clinical Manifestations and Laboratory Findings in Inherited Bone Marrow Failure Syndrome**, what are the distinguishing features of **Fanconi anemia**?", "a": "**y g**: Short stature, low birth weight, microcephaly, microphthalmia, hearing loss, triangular face, micrognathia, cardiac anomalies, tracheoesophageal fistula, esophageal atresia, kidney anomalies, hypoplastic thenar eminence, clinodactyly, café-au-lait macules; **y**: Pancytopenia, macrocytosis, elevated Hb F, increased chromosome breakage in clastogenic assay", "img": null}, {"id": "fc_051_26", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Clinical Manifestations and Laboratory Findings in Inherited Bone Marrow Failure Syndrome**, what are the distinguishing features of **Dyskeratosis congenita**?", "a": "**y g**: Mucocutaneous triad (skin pigmentation, nail dysplasia, oral leukoplakia), short stature, low birth weight, failure to thrive, pulmonary fibrosis, stenosis of the esophagus, liver fibrosis; **y**: Pancytopenia, macrocytosis, elevated Hb F, very short telomeres", "img": null}, {"id": "fc_051_27", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### 51.4 #### Specific Types of Anomalies in Fanconi Anemia**, what are the distinguishing features of **Generalized hyperpigmentation on the trunk, neck, and intertriginous areas; café-au-lait macules; hypopigmented areas**?", "a": "**Eyes(20%)**: Small eyes, strabismus, epicanthal folds, short or almond-shaped palpebral fissures, hypertelorism, ptosis, slanting, cataracts, astigmatism, blindness, epiphora, nystagmus, proptosis, small iris", "img": null}, {"id": "fc_051_28", "ch": 51, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **###### 51.4 #### Specific Types of Anomalies in Fanconi Anemia**, what are the distinguishing features of **Short stature, delicate features, small size, underweight**?", "a": "**Eyes(20%)**: Deafness (usually conductive); abnormal shape; atresia; dysplasia; low set, large, or small; infections; abnormal middle ear; absent eardrum; dimples; rotated; canal stenosis", "img": null}, {"id": "fc_052_01", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **1q24.2**?", "a": "**Causative Gene(s):** `F5` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** p yp: Thrombophilia-2 due to activated protein C resistance — AD — F5 — This approach with multiple genetic information has been confirmed and improved by another group including 9 genetic variants: FV Leiden (rs6025), F5 rs118203906, F5 rs11820395, PT20210A variant, blood group A1, F12 rs1801020, F13 rs5985, SERPINC1 rs121909548, and SER", "img": null}, {"id": "fc_052_02", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **1q25.1**?", "a": "**Causative Gene(s):** `SERPINC1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** p yp: Thrombophilia-7 due to antithrombin III deficiency — AD, AR — SERPINC1 — The classic thrombophilia genes ( SERPINC1 for antithrombin, PROC for protein C, and PROS1 for protein S) harbor hundreds of private variants (present in only a few families each), which confer a high VTE risk for heterozygous carriers.", "img": null}, {"id": "fc_052_03", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **2q14.3**?", "a": "**Causative Gene(s):** `PROC` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** p yp: Thrombophilia-3 due to protein C deficiency, autosomal recessive — AR — PROC — The classic thrombophilia genes ( SERPINC1 for antithrombin, PROC for protein C, and PROS1 for protein S) harbor hundreds of private variants (present in only a few families each), which confer a high VTE risk for heterozygous carriers.", "img": null}, {"id": "fc_052_04", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **3q11.1**?", "a": "**Causative Gene(s):** `PROS1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** p yp: Thrombophilia-5 due to protein S deficiency, autosomal recessive — AR — PROS1 — The genetic analysis of PS is complex due to the presence of two homologous genes encoding the protein: PROS1 (responsible for most Type I and Type II deficiencies) and the pseudo gene PROSP .", "img": null}, {"id": "fc_052_05", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **8p12**?", "a": "**Causative Gene(s):** `THPH9` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** p yp: ?Thrombophilia-9 due to decreased release of tissue plasminogen — THPH9", "img": null}, {"id": "fc_052_06", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **10q25.3**?", "a": "**Causative Gene(s):** `HABP2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** p yp: {Venous thromboembolism, susceptibility to} — AD — HABP2", "img": null}, {"id": "fc_052_07", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **11p11.2**?", "a": "**Causative Gene(s):** `F2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** p yp: Thrombophilia-1 due to thrombin defect — AD — F2", "img": null}, {"id": "fc_052_08", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **20p11.21**?", "a": "**Causative Gene(s):** `THBD` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** p yp: Thrombophilia-12 due to thrombomodulin defect — AD — THBD", "img": null}, {"id": "fc_052_09", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **22q11.21**?", "a": "**Causative Gene(s):** `HCF2` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** p yp: Thrombophilia-10 due to heparin cofactor II deficiency — AD — HCF2", "img": null}, {"id": "fc_052_10", "ch": 52, "part": "IX", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **10.0**?", "a": "**Causative Gene(s):** `SERPINC1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Gene or Genetic Variant: SERPINC1(Antithrombin) — Commentary: Over 130 private variants associated with antithrombin deficiency", "img": null}, {"id": "fc_052_11", "ch": 52, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`APC`** are associated with which clinical phenotype and molecular mechanism in **Protein C Deficiency**?", "a": "Activated PC (APC) exerts its anticoagulant function by inactivating factors Va and VIIIa.", "img": null}, {"id": "fc_052_12", "ch": 52, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PROS1`** are associated with which clinical phenotype and molecular mechanism in **Protein S Deficiency**?", "a": "The genetic analysis of PS is complex due to the presence of two homologous genes encoding the protein: PROS1 (responsible for most Type I and Type II deficiencies) and the pseudo gene PROSP .", "img": null}, {"id": "fc_052_13", "ch": 52, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PROC`** are associated with which clinical phenotype and molecular mechanism in **Other Genetic Variants Implicated in Hereditary Thrombophilia**?", "a": "The classic thrombophilia genes ( SERPINC1 for antithrombin, PROC for protein C, and PROS1 for protein S) harbor hundreds of private variants (present in only a few families each), which confer a high VTE risk for heterozygous carriers.", "img": null}, {"id": "fc_052_14", "ch": 52, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PT20210A`** are associated with which clinical phenotype and molecular mechanism in **Concept of the Individual Risk Profile**?", "a": "In contrast, another study proposed adding two classical genetic factors, FV Leiden and PT20210A variant, to other clinical variables.", "img": null}, {"id": "fc_052_15", "ch": 52, "part": "IX", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`F5`** are associated with which clinical phenotype and molecular mechanism in **Concept of the Individual Risk Profile**?", "a": "This approach with multiple genetic information has been confirmed and improved by another group including 9 genetic variants: FV Leiden (rs6025), F5 rs118203906, F5 rs11820395, PT20210A variant, blood group A1, F12 rs1801020, F13 rs5985, SERPINC1 rs121909548, and SERPIN10 rs2232698.", "img": null}, {"id": "fc_052_16", "ch": 52, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Thrombophilia: OMIM Phenotypic Series**, how is **Transient congenital AT deficiency** defined and characterized?", "a": "Transient congenital AT deficiency is associated with specific genetic alterations that may temporarily lower functional AT levels under external circumstances (e.", "img": null}, {"id": "fc_052_17", "ch": 52, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Protein C Deficiency**, how is **Type I** defined and characterized?", "a": "Type I (quantitative) from Type II (qualitative) deficiencies.", "img": null}, {"id": "fc_052_18", "ch": 52, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Genetic Variants Implicated in Hereditary Thrombophilia**, how is **C46T in the** defined and characterized?", "a": "C46T in the FXII Gene: This variant is linked to VTE risk.", "img": null}, {"id": "fc_052_19", "ch": 52, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Genetic Variants Implicated in Hereditary Thrombophilia**, how is **Epigenetic biomarkers** defined and characterized?", "a": "Epigenetic biomarkers may be associated with VTE including circulating microRNAs in the blood.", "img": null}, {"id": "fc_052_20", "ch": 52, "part": "IX", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Case Example**, how is **May-Thurner syndrome** defined and characterized?", "a": "May-Thurner syndrome is an anatomic predisposition to left sided ileo-femoral venous thrombosis.", "img": null}, {"id": "fc_052_21", "ch": 52, "part": "IX", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 52.1):", "a": "May-Thurner syndrome. Right common iliac artery compressing the left common ileac vein (arrow) .", "img": "fig_p1193_17.jpg"}, {"id": "fc_052_22", "ch": 52, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Condition General Population Patients With First VTE Episode Annual VTE Risk in Asymptomatic Individuals**, what are the distinguishing features of **No known defect**?", "a": "**General Population**: 85%; **Patients With First VTE Episode**: 65%; **Annual VTE Risk in Asymptomatic Individuals**: 0,01%", "img": null}, {"id": "fc_052_23", "ch": 52, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Condition General Population Patients With First VTE Episode Annual VTE Risk in Asymptomatic Individuals**, what are the distinguishing features of **Antithrombin deficiency**?", "a": "**General Population**: 0.01%; **Patients With First VTE Episode**: 0.5–2%; **Annual VTE Risk in Asymptomatic Individuals**: 1.7%", "img": null}, {"id": "fc_052_24", "ch": 52, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Condition General Population Patients With First VTE Episode Annual VTE Risk in Asymptomatic Individuals**, what are the distinguishing features of **Protein C deficiency**?", "a": "**General Population**: 0.2–0.5%; **Patients With First VTE Episode**: 2–3%; **Annual VTE Risk in Asymptomatic Individuals**: 0.7%", "img": null}, {"id": "fc_052_25", "ch": 52, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Thrombophilia: OMIM Phenotypic Series**, what are the distinguishing features of **Location**?", "a": "**p yp**: Phenotype; Inheritance; Gene/Locus", "img": null}, {"id": "fc_052_26", "ch": 52, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Thrombophilia: OMIM Phenotypic Series**, what are the distinguishing features of **1p36.22**?", "a": "**p yp**: {Thromboembolism, susceptibility to}; AD; MTHFR", "img": null}, {"id": "fc_052_27", "ch": 52, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **#### Thrombophilia: OMIM Phenotypic Series**, what are the distinguishing features of **1q24.2**?", "a": "**p yp**: Thrombophilia-2 due to activated protein C resistance; AD; F5", "img": null}, {"id": "fc_052_28", "ch": 52, "part": "IX", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gene or Genetic Variant RR Commentary**, what are the distinguishing features of **SERPINC1(Antithrombin)**?", "a": "**RR**: 10.0; **Commentary**: Over 130 private variants associated with antithrombin deficiency", "img": null}, {"id": "fc_053_01", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Herpes simplex encephalitis**?", "a": "**Causative Gene(s):** `TBK1, TLR3, TRAF3, UNC93B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** TBK1, TLR3, TRAF3, TRIF, UNC93B — Innate immune cells recognize the virus using several classes of pattern recognition receptors including Toll-like receptors (e.g., TLR3, TLR7, TLR8, TLR9), RIG-I-like receptors (e.g., RIG-I and MDA5), C-type lectin receptors, and NOD-like receptors (e.g., NLRP3).", "img": null}, {"id": "fc_053_02", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Cutaneous herpes simplex**?", "a": "**Causative Gene(s):** `DOCK8, GATA2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Severe T-cell defects,DOCK8, GATA2, WAS", "img": null}, {"id": "fc_053_03", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **EBV—chronic**?", "a": "**Causative Gene(s):** `CD21, CD27, CORO1A, MAGT1, CXCR4` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** CD21, CD27, CORO1A, ITK, MAGT1, PRKCD, CXCR4 — These genetic defects include pathogenic variants in SH2D1A, ITK, MAGT1, CTPS1, CD27, CD70, CORO1A , and RASGRP1 .", "img": null}, {"id": "fc_053_04", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **EBV—HLH**?", "a": "**Causative Gene(s):** `AP3B1, LYST1, PRF1, RAB27A, SH2D1A, STX11` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** AP3B1, LYST1, PRF1, RAB27A, SH2D1A, STX11, UNC13D, XIAP — These genetic defects include pathogenic variants in SH2D1A, ITK, MAGT1, CTPS1, CD27, CD70, CORO1A , and RASGRP1 .", "img": null}, {"id": "fc_053_05", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Papilloma virus**?", "a": "**Causative Gene(s):** `CD4, ATM, CD40L, EVER1, EVER2, DOCK8` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Idiopathic CD4 lymphopenia,ATM, CD40L, EVER1, EVER2, DOCK8, GATA2, IKBKG, MST1, RORH, STK4, CXCR4", "img": null}, {"id": "fc_053_06", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Candida**?", "a": "**Causative Gene(s):** `AIRE, CARD9, IL17F, IL17RA, STAT1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** AIRE, CARD9, IL17F, IL17RA, STAT1 — Mendelian susceptibility to mycobacterial diseases (MSMD) are IEIs characterized by a selective predisposition to intracellular infectious agents, particularly mycobacteria and other microorganisms such as Salmonella sp., or mucocutaneous and fungal infections ( Candida spp., Paracoccidioides spp., and", "img": null}, {"id": "fc_053_07", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Aspergillus**?", "a": "**Causative Gene(s):** `CD4, CYBA, CYBB, DOCK8, GATA2, ITGB2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Idiopathic CD4 lymphopenia,CYBA, CYBB, DOCK8, GATA2, ITGB2, NCF1, NCF2, NCF4, STAT3 — Infection with Aspergillus nidulans or A. phellinus (Inonotus) species is almost pathognomonic for CGD, whereas A. mucorales or A. fusarium are uncommon causes of disease in the absence of concomitant iatrogenic immunosuppression.", "img": null}, {"id": "fc_053_08", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pseudomonas**?", "a": "**Causative Gene(s):** `IRAK4, ITGB2, MYD88, BTK, CD40LG` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Congenital neutropenia,IRAK4, ITGB2, MYD88, BTK(neutropenia),CD40LG(neutropenia) — TLRs located on the cell membrane have the primary function of recognizing mycobacterial components, internalizing the bacteria through phagocytosis, and activating the NF-κB pathway via MyD88 and IRAK4.", "img": null}, {"id": "fc_053_09", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Salmonella**?", "a": "**Causative Gene(s):** `CYBB, IFNGR1, IFNGR2, IL12B, IL12RB1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** CYBB, IFNGR1, IFNGR2, IL12B, IL12RB1 — Mendelian susceptibility to mycobacterial diseases (MSMD) are IEIs characterized by a selective predisposition to intracellular infectious agents, particularly mycobacteria and other microorganisms such as Salmonella sp., or mucocutaneous and fungal infections ( Candida spp., Paracoccidioides spp., a", "img": null}, {"id": "fc_053_10", "ch": 53, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Serratia**?", "a": "**Causative Gene(s):** `CYBA, CYBB, NCF1, NCF2, NCF4` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** CYBA, CYBB, NCF1, NCF2, NCF4", "img": null}, {"id": "fc_053_11", "ch": 53, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`C2`** are associated with which clinical phenotype and molecular mechanism in **Encapsulated Bacteria**?", "a": "The early components of complement (i.e., C1q, C2, C4, and C3) are the first activated by antibody and result in covalent binding of C3 to the bacterial capsule and enhanced phagocytosis.", "img": null}, {"id": "fc_053_12", "ch": 53, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IRAK4`** are associated with which clinical phenotype and molecular mechanism in **Fungus**?", "a": "TLRs located on the cell membrane have the primary function of recognizing mycobacterial components, internalizing the bacteria through phagocytosis, and activating the NF-κB pathway via MyD88 and IRAK4.", "img": null}, {"id": "fc_053_13", "ch": 53, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NOD2`** are associated with which clinical phenotype and molecular mechanism in **Fungus**?", "a": "NOD2 recognition leads to the activation of the NF-κB pathway through the RIP2 adaptor molecule and also leads to inflammasome activation, a process resulting in increased transcription of inflammatory cytokines such as IL-1β, IL-18.", "img": null}, {"id": "fc_053_14", "ch": 53, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CD4`** are associated with which clinical phenotype and molecular mechanism in **Fungus**?", "a": "Infected macrophage can present antigen to T cells and secrete IL-12 and IL-23, cytokines that stimulating the differentiation of naïve CD4+ T lymphocytes into Th1-profile that produces IFN-γ and express the CD40 ligand (CD40L).", "img": null}, {"id": "fc_053_15", "ch": 53, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CARD9`** are associated with which clinical phenotype and molecular mechanism in **Candida—Invasive Disease**?", "a": "CARD9 is a signaling protein important in receptors known to detect fungus, such as Dectin-1 and mannose binding protein.", "img": null}, {"id": "fc_053_16", "ch": 53, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TLR3`** are associated with which clinical phenotype and molecular mechanism in **Viruses**?", "a": "Innate immune cells recognize the virus using several classes of pattern recognition receptors including Toll-like receptors (e.g., TLR3, TLR7, TLR8, TLR9), RIG-I-like receptors (e.g., RIG-I and MDA5), C-type lectin receptors, and NOD-like receptors (e.g., NLRP3).", "img": null}, {"id": "fc_053_17", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Immune/Inflammatory Disorders**, how is **Inborn errors of immunity (IEI)** defined and characterized?", "a": "Inborn errors of immunity (IEI) , often referred to as primary immunodeficiencies (PIDs) , constitute a heterogeneous group of rare genetic disorders that result in a compromised or dysfunctional immune system.", "img": null}, {"id": "fc_053_18", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Immune/Inflammatory Disorders**, how is **combined immunodeficiency (SCID)** defined and characterized?", "a": "combined immunodeficiency (SCID) , lead to a wide range of severe and opportunistic infections, including viral, bacterial, and fungal, due to the profound dysfunction in multiple arms of the immune system.", "img": null}, {"id": "fc_053_19", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Bacteria**, how is **innate immune system** defined and characterized?", "a": "innate immune system is the first line of defense against bacterial invaders and provides immediate but nonspecific protection (Chapters 55 and 60).", "img": null}, {"id": "fc_053_20", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Bacteria**, how is **adaptive immune system** defined and characterized?", "a": "adaptive immune system provides a highly specific and long-lasting defense against bacteria.", "img": null}, {"id": "fc_053_21", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Encapsulated Bacteria**, how is **Common variable immunodeficiency (CVID)** defined and characterized?", "a": "Common variable immunodeficiency (CVID) is characterized by late-onset IEI with low levels of immunoglobulins, particularly IgG and IgA, leading to recurrent susceptibility to pneumonia and sinusitis with encapsulated bacteria.", "img": null}, {"id": "fc_053_22", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Encapsulated Bacteria**, how is **X-linked agammaglobulinemia (XLA)** defined and characterized?", "a": "X-linked agammaglobulinemia (XLA) is characterized by a deficiency of B cells and antibodies with increased vulnerability to encapsulated bacteria.", "img": null}, {"id": "fc_053_23", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Encapsulated Bacteria**, how is **Specific antibody deficiency** defined and characterized?", "a": "Specific antibody deficiency is characterized by impaired antibody production to the polysaccharide capsule of the bacteria but with normal total immunoglobulin levels, leading to susceptibility to Streptococcus pneumoniae and other encapsulated bacteria.", "img": null}, {"id": "fc_053_24", "ch": 53, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Encapsulated Bacteria**, how is **C2 deficiency** defined and characterized?", "a": "C2 deficiency is the most common complement disorder and can result in susceptibility to encapsulated bacteria, in particular _S.", "img": null}, {"id": "fc_053_25", "ch": 53, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 53.1):", "a": "Immunodeficiencies affecting cellular and humoral immunity. (A) Severe combined immunodeficiencies defined by T cell lymphopenia.", "img": "fig_p1200_02.jpg"}, {"id": "fc_053_26", "ch": 53, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 53.2):", "a": "(A–C) CID with associated or syndromic features. Ab, Antibody; AD, autosomal dominant inheritance; AD DN, autosomal dominant inheritance with dominant negative effect; ANA, antinuclear antibodies; ANCA, antineutrophil cytoplasm antibodies; AR, autosomal recessive inheritance; Bc, B cells; BCG, Bacillus Calmette-Guerin; BCR, B cell receptor; CD, cluster of differentiation; CID, combined immunodeficiency of T and B cells; CMV, cytomegalovirus; CNS, central nervous system; def, deficiency; DNA, deoxyribonucleic acid; EBV, Epstein-Barr virus; EDA, anhidrotic ectodermal dysplasia; GOF, gain-offunction; HIES, hyper IgE syndrome; FILS, facial dysmorphism, immunodeficiency, livedo and short stature; ID, immunodeficiency; Ig, immunoglobulins; IL-6, interleukin-6; IUGR, intrauterine growth retardation; LOF, loss-of-function; MCC, mucocutaneous candidiasis; Nl, normal; NK, natural killer; PHA, phytohemagglutinin; PPS, polysaccharides; RTE, recent thymic emigrant; SCBMS, seizures, cortical blindness, and microcephaly syndrome; SCID, severe combined immunodeficiency; sd, syndrome; Tc, T cells; TCR, T cell receptor; TREC, T cell receptor excision circle; XL, X-linked inheritance. (From Bousfiha A, Moundir A, Tangye SG, et al. The 2002 update of IUIS phenotypical classification for human inborn errors of immunity. _J C", "img": "fig_p1202_02.jpg"}, {"id": "fc_053_27", "ch": 53, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **### Sentinel Infections and Related Genes**, what are the distinguishing features of **Herpes simplex encephalitis**?", "a": "**Recognized Gene Defects and Well-Characterized Syndromes**: TBK1, TLR3, TRAF3, TRIF, UNC93B", "img": null}, {"id": "fc_053_28", "ch": 53, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **### Sentinel Infections and Related Genes**, what are the distinguishing features of **Cutaneous herpes simplex**?", "a": "**Recognized Gene Defects and Well-Characterized Syndromes**: Severe T-cell defects,DOCK8, GATA2, WAS", "img": null}, {"id": "fc_054_01", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **IL2RG**?", "a": "**Causative Gene(s):** `IL2RG` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** ~30% — Most common (42%) — SCID Subtype: Common — Although most commonly associated with hypomorphic variants in RAG1/2 , other defects including DCLRE1C, LIG4, RMRP, ZAP70, IL2RG, IL7R , CD3D , and ADA have all been associated with Omenn syndrome (Table 54.5).", "img": null}, {"id": "fc_054_02", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **RAG1**?", "a": "**Causative Gene(s):** `RAG1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** ~17% — Common — SCID Subtype: Most common (26%) — Most common (79%) — The recombination-activating genes RAG1 and RAG2 encode proteins that are critical for initiating V(D)J recombination.", "img": null}, {"id": "fc_054_03", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **IL7R**?", "a": "**Causative Gene(s):** `IL7R` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** ~7% — Common — Very rare — Interleukin-7 receptor-α (IL-7Rα) deficiency is an autosomal recessive disorder caused by variants in the IL-7Rα chain (encoded by IL7R ).", "img": null}, {"id": "fc_054_04", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **DCLRE1C**?", "a": "**Causative Gene(s):** `DCLRE1C` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** ~7% — Common — SCID Subtype: Rare — Although most commonly associated with hypomorphic variants in RAG1/2 , other defects including DCLRE1C, LIG4, RMRP, ZAP70, IL2RG, IL7R , CD3D , and ADA have all been associated with Omenn syndrome (Table 54.5).", "img": null}, {"id": "fc_054_05", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **JAK3**?", "a": "**Causative Gene(s):** `JAK3` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** ~5% — Common — SCID Subtype: Unusual — Janus kinase-3 (JAK3) deficiency is an autosomal recessive disorder whose presentation closely resembles that of IL-2Rγc deficiency with loss of T and NK cells, but preservation of B cell development.", "img": null}, {"id": "fc_054_06", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **RAG2**?", "a": "**Causative Gene(s):** `RAG2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** ~4% — Unusual — SCID Subtype: Common — Common — The recombination-activating genes RAG1 and RAG2 encode proteins that are critical for initiating V(D)J recombination.", "img": null}, {"id": "fc_054_07", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CD3D**?", "a": "**Causative Gene(s):** `CD3D` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** <2% — Unusual — SCID Subtype: Rare — Although most commonly associated with hypomorphic variants in RAG1/2 , other defects including DCLRE1C, LIG4, RMRP, ZAP70, IL2RG, IL7R , CD3D , and ADA have all been associated with Omenn syndrome (Table 54.5).", "img": null}, {"id": "fc_054_08", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **LIG4**?", "a": "**Causative Gene(s):** `LIG4` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** <1% — SCID Subtype: Rare — Although most commonly associated with hypomorphic variants in RAG1/2 , other defects including DCLRE1C, LIG4, RMRP, ZAP70, IL2RG, IL7R , CD3D , and ADA have all been associated with Omenn syndrome (Table 54.5).", "img": null}, {"id": "fc_054_09", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NHEJ1**?", "a": "**Causative Gene(s):** `NHEJ1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** <1% — SCID Subtype: Rare — Cernunnos, encoded by NHEJ1 , is an essential component of the non-homologous end joining (NHEJ) pathway and forms a complex with DNA ligase II and XRCC4 to repair double strand brakes.", "img": null}, {"id": "fc_054_10", "ch": 54, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BCL11B**?", "a": "**Causative Gene(s):** `BCL11B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** <1% — SCID Subtype: Very rare", "img": null}, {"id": "fc_054_11", "ch": 54, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FOXN1`** are associated with which clinical phenotype and molecular mechanism in **FOXN1 Deficiency**?", "a": "The Forkhead box protein N1 (FOXN1) transcription factor has a critical role in the development of skin and thymic epithelial cells.", "img": null}, {"id": "fc_054_12", "ch": 54, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RAG2`** are associated with which clinical phenotype and molecular mechanism in **RAG1/2 Deficiency**?", "a": "The recombination-activating genes RAG1 and RAG2 encode proteins that are critical for initiating V(D)J recombination.", "img": null}, {"id": "fc_054_13", "ch": 54, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RAG1`** are associated with which clinical phenotype and molecular mechanism in **RAG1/2 Deficiency**?", "a": "Hypomorphic variants in RAG1/2 can be associated with Omenn syndrome .", "img": null}, {"id": "fc_054_14", "ch": 54, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`LIG4`** are associated with which clinical phenotype and molecular mechanism in **RAG1/2 Deficiency**?", "a": "Although most commonly associated with hypomorphic variants in RAG1/2 , other defects including DCLRE1C, LIG4, RMRP, ZAP70, IL2RG, IL7R , CD3D , and ADA have all been associated with Omenn syndrome (Table 54.5).", "img": null}, {"id": "fc_054_15", "ch": 54, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`DCLRE1C`** are associated with which clinical phenotype and molecular mechanism in **Artemis Deficiency**?", "a": "The endonuclease Artemis is encoded by the DNA CrossLink Repair 1C (DCLRE1C) gene and is an essential part of the V(D)J recombination and non-homologous endjoining (NHEJ) pathway in which diverse antigen receptors are formed.", "img": null}, {"id": "fc_054_16", "ch": 54, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`AK2`** are associated with which clinical phenotype and molecular mechanism in **AK2 Deficiency (Reticular Dysgenesis)**?", "a": "Mitochondrial adenylate kinase-2 (AK2) regulates mitochondrial ATP production and is needed for hematopoietic stem cell differentiation and proliferation.", "img": null}, {"id": "fc_054_17", "ch": 54, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **CARD11**?", "a": "**Therapy / Intervention:** Supportive\n\n**Clinical Context:** Inheritance: AD — Abnormal signaling upstream of NFκB pathway — Features: Severe atopy; autoimmunity; infections — Treatment: Supportive", "img": null}, {"id": "fc_054_18", "ch": 54, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **MHC Class I deficiency**?", "a": "**Therapy / Intervention:** Supportive\n\n**Clinical Context:** Inheritance: AR — Impaired expression of HLA Class I molecules — Features: Respiratory infections; skin granulomatous lesions — Treatment: Supportive", "img": null}, {"id": "fc_054_19", "ch": 54, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **MHC Class II deficiency**?", "a": "**Therapy / Intervention:** Supportive\n\n**Clinical Context:** Inheritance: AR — Absence of HLA Class II molecules — Features: Recurrent infections; gastrointestinal manifestations; hepatic abnormalities — Treatment: Supportive", "img": null}, {"id": "fc_054_20", "ch": 54, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Ataxia telangiectasia**?", "a": "**Therapy / Intervention:** Supportive\n\n**Clinical Context:** Inheritance: AR — Impaired DNA repair and cell cycle regulation — Features: Cerebellar ataxia; telangiectases; predisposition to malignancy; radiosensitivity — Treatment: Supportive", "img": null}, {"id": "fc_054_21", "ch": 54, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **TTC7A Deficiency (MIA Syndrome)**, how is **multiple intestinal atresia (MIA) syndrome** defined and characterized?", "a": "multiple intestinal atresia (MIA) syndrome , is an autosomal recessive condition that causes multiple obstructions in the bowel, intestinal inflammation, and diarrhea.", "img": null}, {"id": "fc_054_22", "ch": 54, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Combined Immunodeficiency With EBVLymphoproliferation**, how is **X-linked lymphoproliferative syndromes** defined and characterized?", "a": "X-linked lymphoproliferative syndromes , XLP-1 and XLP-2, result from variants in SH2DIA and BIRC4 , respectively, and occur in an X-linked manner.", "img": null}, {"id": "fc_054_23", "ch": 54, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Moesin Deficiency**, how is **X-linked moesin-associated immune deficiency (XMAID)** defined and characterized?", "a": "X-linked moesin-associated immune deficiency (XMAID) , this condition is caused by pathogenic variants in the cytoskeletal protein moesin and is transmitted in an X-linked manner.", "img": null}, {"id": "fc_054_24", "ch": 54, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Ataxia-Telangiectasia**, how is **Nijmegen breakage syndrome** defined and characterized?", "a": "Nijmegen breakage syndrome , resembling AT, stems from biallelic variants in NBN , impacting cell division and DNA repair.", "img": null}, {"id": "fc_054_25", "ch": 54, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Cartilage Hair Hypoplasia**, how is **metaphyseal chondrodysplasia** defined and characterized?", "a": "metaphyseal chondrodysplasia , is an autosomal recessive syndrome initially observed in the Amish and later in the Finnish population.", "img": null}, {"id": "fc_054_26", "ch": 54, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Cartilage Hair Hypoplasia**, how is **Omenn syndrome** defined and characterized?", "a": "Omenn syndrome (T B SCID), while others display heterogenous levels of T cell deficiency.", "img": null}, {"id": "fc_054_27", "ch": 54, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Schimke Immuno-Osseous Dysplasia (SIOD)**, how is **spondyloepiphyseal dysplasia** defined and characterized?", "a": "spondyloepiphyseal dysplasia , progressive renal failure, and moderate cellular immunodeficiency.", "img": null}, {"id": "fc_054_28", "ch": 54, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 54.1):", "a": "Profound T cell deficiency arising from impaired maturation of T lineage cells in the thymus. Lymphoid progenitor cells from the bone marrow enter the thymus where they undergo differentiation and maturation into functional T cells. Naïve thymocytes ( DN , double negative cells) undergo T cell receptor rearrangement, namely β-chain rearrangement and pairing of the β-chain with the pre-TCRα chain, giving rise to cells expressing both CD4 and CD8 ( DP , double positive cells). After positive and negative selection in the cortex, thymocytes downregulate the expression of either CD4 or CD8, resulting in single positive cells. These cells are exported from the thymus to the blood and secondary lymphatic organs, where they encounter antigens and exert their biological functions. Various defects in this process can cause profound T cell deficiencies. Blocked lines indicate specific stages impaired by known genetic abnormalities. Some defects may also interfere with maturation of B and natural killer (NK) cells. ADA, Adenosine deaminase deficiency; DN, double negative; γc, gamma common chain of the interleukin (IL) 2 receptor; IL2R α, alpha chain of the IL2 receptor; IL7R α, alpha chain of the IL7 receptor; JAK3, Janus activated kinase 3; MHC, major histocompatibility complex; PNP, purine nucleoside phosphorylase; RAG, recombination activating genes; ZAP-70, zeta chain associated protein kinase 70.", "img": "fig_p1226_01.jpg"}, {"id": "fc_055_01", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Severe congenital**?", "a": "**Causative Gene(s):** `ELANE, GFI1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Genes: ELANE GFI1 — Pattern of: AD — (MSMD): 19 Genes — Neutropenia can be isolated or syndromic (with an extrahematopoietic involvement) and is caused by a number of genes (ELANE, GFI1, G6PC3, VPS45, HAX1, G6PT1, WAS, LAMTOR2, TAZ, VPS13B, USB1, JAGN1, CLPB, CSF3R, SMARCD2, CEBPE, SBDS, DNAJC21, EFL1, HYOU1, SRP54, CXCR2) .", "img": null}, {"id": "fc_055_02", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **neutropenia**?", "a": "**Causative Gene(s):** `VPS45, IL12RB1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Genes: , G6PC3, VPS45 — Pattern of: AR — IL-12 and IL-23 receptor β1 chain deficiency — Genes: IL12RB1 — Pattern of: AR", "img": null}, {"id": "fc_055_03", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Kostmann disease**?", "a": "**Causative Gene(s):** `HAX1, IL12B` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Genes: HAX1 — Pattern of: AR — i IL-12p40 (IL-12 and IL-23) i — Genes: IL12B — Pattern of: AR", "img": null}, {"id": "fc_055_04", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **type 1b**?", "a": "**Causative Gene(s):** `IL12RB2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** IL-12Rβ2 deficiency i — Genes: IL12RB2 — Pattern of: AR — Genetic dissection of MSMD has identified deleterious variants in 22 genes, including 19 autosomal ( IFNGR1, IFNGR2, IFNG, STAT1, JAK1, IRF8, IRF1, SPPL2A, TYK2, IL12B, IL12RB1, IL12RB2, IL23R, TBX21, RORC, ZNFX1, CCR2, ISG15, and USP18 ) and three X-linked ( CYBB, NEMO, and MCTS1", "img": null}, {"id": "fc_055_05", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **X-linked neutropenia P14/LAMTOR2 deficiency**?", "a": "**Causative Gene(s):** `LAMTOR2, IL23R, IFNGR1` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Genes: WAS LAMTOR2 — Pattern of: XL AR — IL-23R deficiency IFN-γreceptor 1 deficiency — Genes: IL23R IFNGR1 — Pattern of: AR AR, AD", "img": null}, {"id": "fc_055_06", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **i Barth syndrome**?", "a": "**Causative Gene(s):** `IFNGR2` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Genes: TAZ — Pattern of: XL — i IFN-receptor 2 deficiency i — Genes: IFNGR2 — Pattern of: AR, AD", "img": null}, {"id": "fc_055_07", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **type II)**?", "a": "**Causative Gene(s):** `CYBB` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Macrophage gp91 phox i — Genes: CYBB — Pattern of: XL — Genetic dissection of MSMD has identified deleterious variants in 22 genes, including 19 autosomal ( IFNGR1, IFNGR2, IFNG, STAT1, JAK1, IRF8, IRF1, SPPL2A, TYK2, IL12B, IL12RB1, IL12RB2, IL23R, TBX21, RORC, ZNFX1, CCR2, ISG15, and USP18 ) and three X-linked ( CYBB, NEMO, and MCTS1 )", "img": null}, {"id": "fc_055_08", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Cohen syndrome**?", "a": "**Causative Gene(s):** `VPS13B` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Genes: VPS13B — Pattern of: AR — deficiency — Neutropenia can be isolated or syndromic (with an extrahematopoietic involvement) and is caused by a number of genes (ELANE, GFI1, G6PC3, VPS45, HAX1, G6PT1, WAS, LAMTOR2, TAZ, VPS13B, USB1, JAGN1, CLPB, CSF3R, SMARCD2, CEBPE, SBDS, DNAJC21, EFL1, HYOU1, SRP54, CXCR2) .", "img": null}, {"id": "fc_055_09", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Clericuzio syndrome**?", "a": "**Causative Gene(s):** `USB1, IKBKG` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Genes: USB1 — Pattern of: AR — i IKBKG (NEMO) i — Genes: IKBKG — Pattern of: XL — Neutropenia can be isolated or syndromic (with an extrahematopoietic involvement) and is caused by a number of genes (ELANE, GFI1, G6PC3, VPS45, HAX1, G6PT1, WAS, LAMTOR2, TAZ, VPS13B, USB1, JAGN1, CLPB, CSF3R, SMARCD2, CEBPE, SBDS, DNAJC21, EFL1, HYOU1, SRP", "img": null}, {"id": "fc_055_10", "ch": 55, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **neutropenia) i**?", "a": "**Causative Gene(s):** `SPPL2A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** SPPL2a deficiency i — Genes: SPPL2A — Pattern of: AR — Genetic dissection of MSMD has identified deleterious variants in 22 genes, including 19 autosomal ( IFNGR1, IFNGR2, IFNG, STAT1, JAK1, IRF8, IRF1, SPPL2A, TYK2, IL12B, IL12RB1, IL12RB2, IL23R, TBX21, RORC, ZNFX1, CCR2, ISG15, and USP18 ) and three X-linked ( CYBB, NEMO, and MCTS1 ) (", "img": null}, {"id": "fc_055_11", "ch": 55, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TLR3`** are associated with which clinical phenotype and molecular mechanism in **Infections and SARS-CoV-2**?", "a": "TLR1/2/4/5/6/10 are surface receptors which sense extracellular components of the microorganisms and TLR3/7/8/9 are intracellular and sense DNA or RNA from microorganisms.", "img": null}, {"id": "fc_055_12", "ch": 55, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TRAF3`** are associated with which clinical phenotype and molecular mechanism in **Herpes Simplex Virus Encephalitis (HSE) Due to Deficiencies of the TLR3 Pathway**?", "a": "Human defects in several components of Toll-like receptor 3 (TLR3) signaling pathway and the IFN α/β receptor 1 (IFNAR1) pathway ( TLR3, TRIF, TRAF3, TBK1, IRF3, UNC93B1, IFNAR1, TYK2, STAT1, STAT2, DBR1, SNORA31, ATG4A , and MAP1LC3B2 ; Table 55.1 and Table 55.5) are known genetic causes predisposing to HSE.", "img": null}, {"id": "fc_055_13", "ch": 55, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`EVER1`** are associated with which clinical phenotype and molecular mechanism in **Genetic Etiologies of Papillomaviruses (HPV) Infections in Humans**?", "a": "Rare variants in four genes have been linked to EV ( TMC6, TMC8, encoding for EVER1 and EVER2 proteins, respectively, CIB1 and CD28 , Table 55.1 and Table 55.5), all with AR pattern of inheritance.", "img": null}, {"id": "fc_055_14", "ch": 55, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IFIH1`** are associated with which clinical phenotype and molecular mechanism in **Other Intrinsic and Innate Immune Deficiencies Predisposing to Systemic Viral Infections**?", "a": "In these cases, and when a T and NK cell deficiencies are ruled out, patients have been identified with deleterious variants in IFIH1, STAT1 LOF, IFNAR2, POLR3A, POLR3C, POLR3F, IRF7, IRF9, IL18BP, ZNFX1, TLR7, FCGR3A, CD28, NOS2 (Table 55.1 and Table 55.5).", "img": null}, {"id": "fc_055_15", "ch": 55, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CYBB`** are associated with which clinical phenotype and molecular mechanism in **Defects in Type 2 Interferon Immunity: Mendelian Susceptibility in Mycobacterial Disease (MSMD)**?", "a": "Genetic dissection of MSMD has identified deleterious variants in 22 genes, including 19 autosomal ( IFNGR1, IFNGR2, IFNG, STAT1, JAK1, IRF8, IRF1, SPPL2A, TYK2, IL12B, IL12RB1, IL12RB2, IL23R, TBX21, RORC, ZNFX1, CCR2, ISG15, and USP18 ) and three X-linked ( CYBB, NEMO, and MCTS1 ) (Fig. 55.1 and Table 55.4).", "img": null}, {"id": "fc_055_16", "ch": 55, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ISG15`** are associated with which clinical phenotype and molecular mechanism in **Defects in Type 2 Interferon Immunity: Mendelian Susceptibility in Mycobacterial Disease (MSMD)**?", "a": "Some of these cause syndromic MSMD with susceptible to both mycobacterial as well as a border range of pathogens (i.e., STAT1) or cerebral calcifications (i.e., ISG15 deficiency).", "img": null}, {"id": "fc_055_17", "ch": 55, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Early onset disseminated NTM or BCG**?", "a": "**Therapy / Intervention:** Antimycobacterials; HSCT\n\n**Clinical Context:** Complete IFN-gR1 or IFN-gR2 deficiency — Gene/Inheritance: IFNGR1orIFNGR2/AR — Treatment: Antimycobacterials; HSCT", "img": null}, {"id": "fc_055_18", "ch": 55, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **NTM or BCG osteomyelitis, disseminatedSalmonella, disseminated endemic mycoses**?", "a": "**Therapy / Intervention:** Antimycobacterials; adjuvant IFN-γ\n\n**Clinical Context:** Autosomal dominant IFN-gR1 or IFN-gR2 deficiency — Gene/Inheritance: IFNGR1orIFNGR2/AD — Treatment: Antimycobacterials; adjuvant IFN-γ", "img": null}, {"id": "fc_055_19", "ch": 55, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Disseminated NTM, BCG,Salmonella Mucocutaneous candidiasis Variable penetration**?", "a": "**Therapy / Intervention:** Antimycobacterials; consider IFN-γwith careful monitoring\n\n**Clinical Context:** IL-12RB1 deficiency — Gene/Inheritance: IL12RB1/AR — Treatment: Antimycobacterials; consider IFN-γwith careful monitoring", "img": null}, {"id": "fc_055_20", "ch": 55, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Disseminated NTM, BCG,Salmonella Variable penetration**?", "a": "**Therapy / Intervention:** Antimycobacterials; consider IFN-γwith careful monitoring\n\n**Clinical Context:** IL-12p40 deficiency — Gene/Inheritance: IL12B/AR — Treatment: Antimycobacterials; consider IFN-γwith careful monitoring", "img": null}, {"id": "fc_055_21", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Intrinsic and Innate Deficiencies With Susceptibility to Bacteria**, how is **Isolated congenital asplenia** defined and characterized?", "a": "Isolated congenital asplenia (ICA) caused by pathogenic variants in RPSA or HMOX predisposes individuals to life-threatening invasive infections early in childhood, caused by encapsulated bacteria, typically _S.", "img": null}, {"id": "fc_055_22", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Etiologies of Papillomaviruses (HPV) Infections in Humans**, how is **Epidermodysplasia verruciformis (EV)** defined and characterized?", "a": "Epidermodysplasia verruciformis (EV) is a rare genodermatosis presenting with persistent, disseminated, flat warts and pityriasis versicolor-like skin lesions induced by human β-papillomaviruses (β-HPVs).", "img": null}, {"id": "fc_055_23", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Genetic Etiologies of Papillomaviruses (HPV) Infections in Humans**, how is **Juvenile recurrent respiratory papillomatosis** defined and characterized?", "a": "Juvenile recurrent respiratory papillomatosis , driven by some α-HPVs, was shown to be due to biallelic gainof-function (GOF) in NLRP1, suggesting an important role of cell intrinsic immunity against HPVs other than β-HPVs (α, γ, μ and ν).", "img": null}, {"id": "fc_055_24", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Defects in Type 2 Interferon Immunity: Mendelian Susceptibility in Mycobacterial Disease (MSMD)**, how is **Macrophage activation syndrome** defined and characterized?", "a": "Macrophage activation syndrome may occur in rare cases, probably due to uncontrolled mycobacterial infection.", "img": null}, {"id": "fc_055_25", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Defects in Th17 and CARD9 Signaling: Susceptibility to Fungi**, how is **Chronic Mucotaneous Candidiasis (CMC)** defined and characterized?", "a": "Chronic Mucotaneous Candidiasis (CMC) is characterized by persistent or recurrent infections of the skin (intertrigo, angular cheilitis), nails (onychomycosis) and mucous membranes (oral, esophageal, genital) caused by _Candida (C.", "img": null}, {"id": "fc_055_26", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Defects in Th17 and CARD9 Signaling: Susceptibility to Fungi**, how is **Autoimmune polyglandular syndrome-1** defined and characterized?", "a": "Autoimmune polyglandular syndrome-1 is caused by pathogenic variants of the AIRE gene resulting in impaired T-cell tolerance, with 88% of patients developing CMC (Chapter 39).", "img": null}, {"id": "fc_055_27", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnostic Studies**, how is **dihydrorhodamine (DHR) test** defined and characterized?", "a": "dihydrorhodamine (DHR) test is used to evaluate phagocyte respiratory oxidative burst in the context of bacterial and/or fungal infections when CGD is considered.", "img": null}, {"id": "fc_055_28", "ch": 55, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Diagnostic Studies**, how is **Shedding of CD62L** defined and characterized?", "a": "Shedding of CD62L is used as a screening tool when IRAK4/MyD88 deficiencies are suspected.", "img": null}, {"id": "fc_056_01", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AD-HIES**?", "a": "**Causative Gene(s):** `STAT3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD, less commonly sporadic — Clinical Features: • Cold abscesses • Recurrent sinopulmonary infections • Mucocutaneous candidiasis • Coarse facies • Minimal trauma fractures • Scoliosis • Joint hyperextensibility • Retained primary teeth • Coronary artery tortuosity or dilation • Lymphoma — Lab Abnormalities: • High IgE (>2,00", "img": null}, {"id": "fc_056_02", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Lymphoproliferation (e.g., lymphadenopathy, splenomegaly) • Growth failure • Autoimmune enteropathy • Various **?", "a": "**Causative Gene(s):** `STAT3, STAT3GOF` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Clinical Features: • Lymphoproliferation (e.g., lymphadenopathy, splenomegaly) • Growth failure • Autoimmune enteropathy • Various autoimmune endocrinopathies (e.g., diabetes mellitus, thyroiditis) • Hepatitis • Pulmonary disease • Juvenile-onset arthritis • Dermatitis — Lab Abnormalities: • Cytopenias common •+/−Hemolyt", "img": null}, {"id": "fc_056_03", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **STAT1 GOF**?", "a": "**Causative Gene(s):** `STAT1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Clinical Features: • Chronic candidal infections • Bacterial infections • Autoimmune conditions • Cerebral aneurysms •+/−Disseminated viral and/or fungal infections •+/−Dermatitis — Lab Abnormalities: • Cytopenias common", "img": null}, {"id": "fc_056_04", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **STAT6 GOF**?", "a": "**Causative Gene(s):** `STAT6` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Clinical Features: • Multiple food, drug, and environmental allergies • Recurrent anaphylaxis • Asthma • Allergic eosinophilic gastroenteritis and eosinophilic esophagitis • Lymphoproliferation • Coarse facies • Minimal trauma fractures • Joint hyperextensibility • Vascular anomalies — Lab Abnormalities: • High IgE • Eos", "img": null}, {"id": "fc_056_05", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **DOCK8 deficiency**?", "a": "**Causative Gene(s):** `DOCK8` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Clinical Features: • Severe mucocutaneous viral infections • Mucocutaneous candidiasis • Atopic features (asthma, allergies) • Squamous cell carcinoma • Lymphoma — Lab Abnormalities: • High IgE • Eosinophilia •+/−Decreased IgM", "img": null}, {"id": "fc_056_06", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **IPEX**?", "a": "**Causative Gene(s):** `FOXP3` · **Inheritance:** XLR\n\n**Clinical & Molecular Profile:** Inheritance: XLR — Clinical Features: • Severe diarrhea (autoimmune enteropathy) • Various autoimmune endocrinopathies (e.g., diabetes mellitus, thyroiditis) • Food allergies — Lab Abnormalities: • High IgE • Eosinophilia • Various autoantibodies", "img": null}, {"id": "fc_056_07", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CD25 Deficiency**?", "a": "**Causative Gene(s):** `IL2RA, CD25` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Clinical Features: • Severe diarrhea (autoimmune enteropathy) • Autoimmune disease — Lab Abnormalities: • Normal or mildly elevated IgE • Various autoantibodies", "img": null}, {"id": "fc_056_08", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Netherton syndrome**?", "a": "**Causative Gene(s):** `SPINK5` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Clinical Features: • Hair shaft abnormalities • Erythroderma • Ichthyosis linearis circumflexa • Food allergies • Recurrent gastroenteritis • Neonatal hypernatremic dehydration • Upper and lower respiratory infections — Lab Abnormalities: • High IgE • Eosinophilia", "img": null}, {"id": "fc_056_09", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PGM3 deficiency**?", "a": "**Causative Gene(s):** `PGM3` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Clinical Features: • Neurological abnormalities • Leukocytoclastic vasculitis • Atopic features (asthma, allergies) • Sinopulmonary infections • Mucocutaneous viral infections — Lab Abnormalities: • High IgE • Eosinophilia", "img": null}, {"id": "fc_056_10", "ch": 56, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FCAS**?", "a": "**Causative Gene(s):** `NLRP3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Gene (Protein): NLRP3 (cryopyrin) — Inheritance: AD — Attack Length: Brief; Minutes– 3 d — Timing of Onset: Neonatal or infantile — Cutaneous Features: • Cold-induced urticaria — • Arthralgia • Conjunctivitis • Headache", "img": null}, {"id": "fc_056_11", "ch": 56, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`WAS`** are associated with which clinical phenotype and molecular mechanism in **Syndrome**?", "a": "HIES, Hyper IgE syndrome; IPEX, immune dysregulation, polyendocrinopathy, enteropathy, X-linked; SCID, severe combined immunodeficiency; WAS, Wiskott Aldrich syndrome.", "img": null}, {"id": "fc_056_12", "ch": 56, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STAT3`** are associated with which clinical phenotype and molecular mechanism in **Syndrome**?", "a": "Most cases of ADHIES are due to dominant negative pathogenic variants in the signal transducer and activator of transcription 3 (STAT3) gene, leading to loss of function and failure of Th17 cell differentiation and reduced IL-17 and IL-22 production.", "img": null}, {"id": "fc_056_13", "ch": 56, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STAT1`** are associated with which clinical phenotype and molecular mechanism in **STAT1 Gain of Function Disease**?", "a": "STAT1 facilitates type 1 and type 2 interferon (IFN)mediated gene transcription.", "img": null}, {"id": "fc_056_14", "ch": 56, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`RAG1`** are associated with which clinical phenotype and molecular mechanism in **STAT1 Gain of Function Disease**?", "a": "These features usually occur with hypomorphic variants in genes causing SCID (e.g., RAG1 ) resulting in the generation of some T cells that tend to be autoreactive.", "img": null}, {"id": "fc_056_15", "ch": 56, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STAT6`** are associated with which clinical phenotype and molecular mechanism in **STAT6 Gain of Function Disease**?", "a": "STAT6 is a transcription factor important in allergic immune responses activated in response to IL-4 and IL-13.", "img": null}, {"id": "fc_056_16", "ch": 56, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IL2RG`** are associated with which clinical phenotype and molecular mechanism in **Severe Combined Immunodeficiency**?", "a": "The most common subtype of SCID is an X-linked recessive form (X-SCID) accounting for ~29% of cases, caused by IL2RG pathogenic variants with loss of T and NK cell development.", "img": null}, {"id": "fc_056_17", "ch": 56, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **STAT1 Gain of Function Disease**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Depending upon the subtype, treatments for SCID can include hematopoietic stem cell transplant, enzyme replacement therapy, or gene therapy.", "img": null}, {"id": "fc_056_18", "ch": 56, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **STAT6 Gain of Function Disease**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Successful treatment of STAT6 GOF disease has been reported with dupilumab, ruxolitinib, and tofacitinib.", "img": null}, {"id": "fc_056_19", "ch": 56, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Cryopyrin-Associated Periodic Syndromes**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** The treatment of CAPS is focused on reducing IL-1β activity using medications like anakinra (IL-1 receptor antagonist), rilonacept (IL-1 trap), and canakinumab (IL-1β monoclonal antibody).", "img": null}, {"id": "fc_056_20", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Disorders Presenting With Eczematous Dermatitis**, how is **Atopic dermatitis** defined and characterized?", "a": "Atopic dermatitis is the most common eczematous eruption of childhood, affecting approximately 15 to 20% of children in the United States.", "img": null}, {"id": "fc_056_21", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Syndrome**, how is **Chronic mucocutaneous candidiasis** defined and characterized?", "a": "Chronic mucocutaneous candidiasis and recurrent sinopulmonary infections are also commonly seen.", "img": null}, {"id": "fc_056_22", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **STAT1 Gain of Function Disease**, how is **IPEX-like syndrome** defined and characterized?", "a": "IPEX-like syndrome , with mild to severe dermatitis reported.", "img": null}, {"id": "fc_056_23", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Severe Combined Immunodeficiency**, how is **Omenn syndrome** defined and characterized?", "a": "Omenn syndrome is an autosomal recessive variant of SCID typically caused by deficiency of RAG proteins; it has also been reported in other genetic causes of SCID such as ADA deficiency.", "img": null}, {"id": "fc_056_24", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **DOCK8 Deficiency**, how is **hyper-IgE syndrome** defined and characterized?", "a": "hyper-IgE syndrome is due to pathogenic variants in the dedicator of cytokinesis 8 gene (DOCK8) and is called DOCK8 deficiency.", "img": null}, {"id": "fc_056_25", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **CD25 Deficiency**, how is **IPEX-like** defined and characterized?", "a": "IPEX-like disorder due to a functional defect in Treg cells.", "img": null}, {"id": "fc_056_26", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Netherton Syndrome**, how is **Ichthyosis linearis circumflexa** defined and characterized?", "a": "Ichthyosis linearis circumflexa is characterized by migratory, polycyclic, scaly erythematous plaques with a characteristic peripheral double-edged scale which usually responds poorly to topical steroids (Fig.", "img": null}, {"id": "fc_056_27", "ch": 56, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Phosphoglucomutase 3 Deficiency**, how is **disorder of glycosylation** defined and characterized?", "a": "disorder of glycosylation which leads to multiple immune defects (Chapter 47).", "img": null}, {"id": "fc_056_28", "ch": 56, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 56.1):", "a": "Distribution patterns of atopic dermatitis (AD) and regional variants. *May be the only manifestation of AD in adults. Not to be confused with nummular eczema occurring outside the setting of AD. (From McAleer MA, Irvine AD. Atopic dermatitis. In Bolognia JL, Schaffer JV, Cerroni L, (eds). Dermatology. 5th ed. Philadelphia: Elsevier; 2025 [Fig. 12.3, p. 214].)", "img": "fig_p1268_03.jpg"}, {"id": "fc_057_01", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Presence of aconfirmatory NLRP3 genotype*and at least oneamong the following: • Urticarial rash • Red eye (con**?", "a": "**Causative Gene(s):** `NLRP3, MEFV, MVK` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** FMF: Presence ofconfirmatory MEFV genotype*andat least one among the following: • Duration of episodes 1–3 days • Arthritis • Chest pain • Abdominal pain — TRAPS: Presence of confirmatory TNFRSF1Agenotype*and at least one among the following: • Duration of episodes≥7 days • Myalgia • Migratory rash • Periorbital oedema • Relatives affecte", "img": null}, {"id": "fc_057_02", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Presence ofnot confirmatory NLRP3 genotypeand at least twoamong the following: • Urticarial rash • Red eye (co**?", "a": "**Causative Gene(s):** `NLRP3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** FMF: Presence of notconfirmatory MEFVgenotypeand at least two among the following: • Duration of episodes 1–3 days • Arthritis • Chest pain • Abdominal pain — TRAPS: Presence of a not confirmatory TNFRSF1Agenotypeand at least twoamong the following: • Duration of episodes≥7 days • Myalgia • Migratory rash • Periorbital oedema • Relatives", "img": null}, {"id": "fc_057_03", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **l itions**?", "a": "**Causative Gene(s):** `PSTPIP1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Hz/Hc — PSTPIP1 — AD — Rash, FTT, hepatosplenomegaly, neutropenia — Targeted: IL-1, TNF", "img": null}, {"id": "fc_057_04", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **l mily cond**?", "a": "**Causative Gene(s):** `WDR1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** PFIT — WDR1 — AR — Fever, infection, oral inflammation, perianal ulceration — Targeted: IL-18", "img": null}, {"id": "fc_057_05", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **l IL-1 fa**?", "a": "**Causative Gene(s):** `NLRP3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Cryopyrin activation — FCAS — NLRP3 — AD — Cold urticaria, extremity pain, conjunctivitis, fever — Targeted: IL-1", "img": null}, {"id": "fc_057_06", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **l and other**?", "a": "**Causative Gene(s):** `NLRP3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** MWS — NLRP3 — AD — Urticarial rash, extremity pain, hearing loss, conjunctivitis, fever — Targeted: IL-1", "img": null}, {"id": "fc_057_07", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **lpathies**?", "a": "**Causative Gene(s):** `NLRP3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** NOMID — NLRP3 — AD — CNS inflammation, urticaria, knee arthropathy, fever — Targeted: IL-1", "img": null}, {"id": "fc_057_08", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **lasomo**?", "a": "**Causative Gene(s):** `LPIN2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Majeed’s — LPIN2 — AR — Osteomyelitis, fevers, rash, dyserythropoietic anemia — Targeted: IL-1", "img": null}, {"id": "fc_057_09", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **nflamm**?", "a": "**Causative Gene(s):** `NLRC4` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** NLRC4 activation — AIFEC — NLRC4 — AD — Enterocolitis, rash, arthritis, fever — Targeted: IL-1, IL-18", "img": null}, {"id": "fc_057_10", "ch": 57, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **pathies**?", "a": "**Causative Gene(s):** `IFIH1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Nucleic acid sensing — SMS — IFIH1, DDX58a — AD — Calcification of aorta/cardiac valves, osteopenia, acroosteolysis, dental anomalies — Targeted: JAK?", "img": null}, {"id": "fc_057_11", "ch": 57, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NLRP3`** are associated with which clinical phenotype and molecular mechanism in **IL-1 Related Autoinflammatory Diseases and Inflammasomopathies**?", "a": "NLRP3 inflammasomes are formed by priming and activation signaling.", "img": null}, {"id": "fc_057_12", "ch": 57, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MEFV`** are associated with which clinical phenotype and molecular mechanism in **Familial Mediterranean Fever**?", "a": "There is evidence that MEFV variants associated with FMF could have a selective advantage in survival from the bubonic plague.", "img": null}, {"id": "fc_057_13", "ch": 57, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`PSTPIP1`** are associated with which clinical phenotype and molecular mechanism in **Pyogenic Arthritis With Pyoderma Gangrenosum and Acne (PAPA) Syndrome**?", "a": "PAPA syndrome caused by genetic variants in PSTPIP1 (prolineserine-threonine phosphatase interacting protein-1) gene, also known as CD2-binding protein 1 (CD2BP1).", "img": null}, {"id": "fc_057_14", "ch": 57, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NLRP12`** are associated with which clinical phenotype and molecular mechanism in **NLRP12-Associated Autoinflammatory Disease/Guadeloupe Variant Periodic Fever Syndrome (FCAS2)**?", "a": "Recurrent fevers associated with NLRP12 variants involving twins from Guadeloupe who experienced symptoms such as arthralgia, periodic fever, and cold-induced urticaria and was named the Guadeloupe Variant Periodic Fever Syndrome, also known as FCAS2 (Familial Cold Autoinflammatory Syndrome 2).", "img": null}, {"id": "fc_057_15", "ch": 57, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`NLRC4`** are associated with which clinical phenotype and molecular mechanism in **Autoinflammation With Infantile Enterocolitis (AIFEC)/NLRC4-AID**?", "a": "Heterozygous gain-of-function variants in NLRC4 (NODlike family caspase activation and recruitment domaincontaining protein-4) result in a syndrome of HLH/MAS, severe intestinal inflammation, skin rash, and fever.", "img": null}, {"id": "fc_057_16", "ch": 57, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MVK`** are associated with which clinical phenotype and molecular mechanism in **Mevalonate Kinase Deficiency/ Hyperimmunoglobulinemia D and Periodic Fever Syndrome**?", "a": "The enzyme mevalonate kinase (MVK) is widely expressed throughout the body and has a crucial role in a key step of the biosynthetic pathway for both cholesterol and nonsterol isoprenes.", "img": null}, {"id": "fc_057_17", "ch": 57, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **COPA**?", "a": "**Therapy / Intervention:** IL-17? JAK?\n\n**Clinical Context:** g l Mechanism: Golgi-ER transport — l Inheritance: AD — Clinical Presentation: Arthritis, ILD, diffuse alveolar hemorrhage, autoantibodies — Targeted Therapy: IL-17? JAK?", "img": null}, {"id": "fc_057_18", "ch": 57, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **VEO-IBD**?", "a": "**Therapy / Intervention:** HSCT, IL-1?\n\n**Clinical Context:** g l Mechanism: Cytokine dysregulation — ly Gene: IL-10, IL10RA, IL10RB — l Inheritance: AR — Clinical Presentation: Early-onset colitis, FTT — Targeted Therapy: HSCT, IL-1?", "img": null}, {"id": "fc_057_19", "ch": 57, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **CDC42 deficiency**?", "a": "**Therapy / Intervention:** , IL-1\n\n**Clinical Context:** g l Mechanism: Actin polymerization — l Inheritance: AR — Clinical Presentation: Neurodevelopmental defects, facial dysmorphism cytopenias recurrent infection, fever, rash — Targeted Therapy: , IL-1", "img": null}, {"id": "fc_057_20", "ch": 57, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Familial Mediterranean Fever**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Anakinra treatment is effective and safe in colchicine-resistant FMF patients in one randomized–controlled study.", "img": null}, {"id": "fc_057_21", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Familial Mediterranean Fever**, how is **Colchicine** defined and characterized?", "a": "Colchicine is the standard therapy for individuals with FMF.", "img": null}, {"id": "fc_057_22", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Familial Mediterranean Fever**, how is **Anakinra treatment** defined and characterized?", "a": "Anakinra treatment is effective and safe in colchicine-resistant FMF patients in one randomized–controlled study.", "img": null}, {"id": "fc_057_23", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Cryopyrin-Associated Periodic Syndromes (CAPS)**, how is **NLRP3-associated autoinflammatory diseases** defined and characterized?", "a": "NLRP3-associated autoinflammatory diseases to refer to the broader spectrum of conditions within CAPS.", "img": null}, {"id": "fc_057_24", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Cryopyrin-Associated Periodic Syndromes (CAPS)**, how is **NOMID** defined and characterized?", "a": "NOMID (or chronic infantile neurological cutaneous articular [CINCA] syndrome) presents with fever, urticaria, overgrowth of the long bones’ epiphyses, and chronic aseptic meningitis.", "img": null}, {"id": "fc_057_25", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Cryopyrin-Associated Periodic Syndromes (CAPS)**, how is **anti-IL-1 treatment** defined and characterized?", "a": "anti-IL-1 treatment is recommended for the whole CAPS spectrum.", "img": null}, {"id": "fc_057_26", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Autoinflammation With Infantile Enterocolitis (AIFEC)/NLRC4-AID**, how is **A severe phenotype (NLRC4-AID phenotype 1)** defined and characterized?", "a": "A severe phenotype (NLRC4-AID phenotype 1) with neonatal onset and a high mortality rate (40%), presenting with high fevers, macrophage activation syndrome (MAS), severe enterocolitis, and a nonspecific skin eruption.", "img": null}, {"id": "fc_057_27", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Autoinflammation With Infantile Enterocolitis (AIFEC)/NLRC4-AID**, how is **A mild phenotype (NLRC4-AID phenotype 2)** defined and characterized?", "a": "A mild phenotype (NLRC4-AID phenotype 2) with onset in childhood, a cutaneous tropism with urticaria and erythematous nodules, arthromyalgia, and conjunctivitis.", "img": null}, {"id": "fc_057_28", "ch": 57, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Mevalonate Kinase Deficiency/ Hyperimmunoglobulinemia D and Periodic Fever Syndrome**, how is **Mevalonic aciduria** defined and characterized?", "a": "Mevalonic aciduria is characterized by a range of clinical symptoms, including recurrent fever, intellectual disability, developmental abnormalities, and early death.", "img": null}, {"id": "fc_058_01", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AGS, FCL, SLE**?", "a": "**Causative Gene(s):** `TREX1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AR, AD (DN) — Protein Function: DNase", "img": null}, {"id": "fc_058_02", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AGS, SP**?", "a": "**Causative Gene(s):** `RNASEH2B` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AR — Protein Function: RNase", "img": null}, {"id": "fc_058_03", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AGS, FCL, cerebral vasculopathy**?", "a": "**Causative Gene(s):** `SAMHD1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AR — Protein Function: Regulation of dNTP", "img": null}, {"id": "fc_058_04", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AGS, BSN, SP**?", "a": "**Causative Gene(s):** `ADAR1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AR, AD (DN) — Protein Function: RNA editing", "img": null}, {"id": "fc_058_05", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **AGS, SMS, SP**?", "a": "**Causative Gene(s):** `IFIH1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): GOF — Inheritance: AD — Protein Function: dsRNA sensor — Children with typical features of AGS or SPENCD may fulfill the diagnostic criteria for SLE; heterozygous variants in TREX1, IFIH1, or ACP5 may be associated with adult onset SLE, without the other associated features.", "img": null}, {"id": "fc_058_06", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Neonatal anemia, arthropathy, glomerulonephritis, and liver disease**?", "a": "**Causative Gene(s):** `DNASE2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AR — Protein Function: DNase", "img": null}, {"id": "fc_058_07", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **X-linked reticulate pigmentary disorder**?", "a": "**Causative Gene(s):** `POLA1` · **Inheritance:** XLR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: XLR — Protein Function: DNA polymerase", "img": null}, {"id": "fc_058_08", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **NDD, systemic sclerosis, SP**?", "a": "**Causative Gene(s):** `ATAD3A` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AD (DN) — Protein Function: Multiple — DNA; or (ii) mitochondrial integrity, perturbed by variant of the ATPase family AAA domain-containing protein 3A (ATAD3A) gene, thought to lead to cytosolic leakage of mitochondrial DNA.", "img": null}, {"id": "fc_058_09", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Infantile encephalopathy (mitochondrial disease), BSN**?", "a": "**Causative Gene(s):** `PNPT1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AR — Protein Function: Polynucleotide phosphorylase", "img": null}, {"id": "fc_058_10", "ch": 58, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SPENCD, SLE**?", "a": "**Causative Gene(s):** `ACP5` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Variant Mechanism (GOF/LOF): LOF — Inheritance: AR — Protein Function: Phosphatase — Secondary to autosomal recessive variants in the acid phosphatase 5, tartrate resistant (ACP5) gene, this condition was originally thought to be a skeletal dysplasia, with enchondromas and platyspondyly, causing progressive short stature.", "img": null}, {"id": "fc_058_11", "ch": 58, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`JAK1`** are associated with which clinical phenotype and molecular mechanism in **Type I Interferonopathies**?", "a": "This primarily involves the receptor-associated kinases JAK1 and tyrosine kinase 2 (TYK2), which activate a heterotrimeric complex of STAT1, STAT2, and IRF9, known as interferon stimulated gene factor 3 (ISGF3), via phosphorylation of tyrosine residues on STAT1 and STAT2.", "img": null}, {"id": "fc_058_12", "ch": 58, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STAT1`** are associated with which clinical phenotype and molecular mechanism in **Type I Interferonopathies**?", "a": "A minor complex comprising tyrosine phosphorylated STAT1 homodimers also participates in IFNAR signaling.", "img": null}, {"id": "fc_058_13", "ch": 58, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IFIH1`** are associated with which clinical phenotype and molecular mechanism in **Defective Nucleic Acid Homeostasis**?", "a": "Indeed, most variants associated with AicardiGoutières syndrome (AGS) confer defects in nucleic acid homeostasis (an exception is variants of the interferon induced with helicase C domain 1 [IFIH1] gene, encoding the RNA sensor MDA5).", "img": null}, {"id": "fc_058_14", "ch": 58, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`ATAD3A`** are associated with which clinical phenotype and molecular mechanism in **Defective Nucleic Acid Homeostasis**?", "a": "DNA; or (ii) mitochondrial integrity, perturbed by variant of the ATPase family AAA domain-containing protein 3A (ATAD3A) gene, thought to lead to cytosolic leakage of mitochondrial DNA.", "img": null}, {"id": "fc_058_15", "ch": 58, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STING1`** are associated with which clinical phenotype and molecular mechanism in **Constitutive Pattern Recognition Receptor (PRR) Signaling**?", "a": "Similarly, GOF STING1 variants lead to constitutive ligand-independent translocation of STING to the Golgi apparatus from the endoplasmic reticulum (ER), resulting in downstream activation of TBK1/IKKε.", "img": null}, {"id": "fc_058_16", "ch": 58, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STAT2`** are associated with which clinical phenotype and molecular mechanism in **Exaggerated IFNAR Signaling**?", "a": "This feedback loop also depends on an interaction between USP18 and STAT2, that is in turn compromised by homozygous missense variants in STAT2 , producing a recessively inherited disease that in many respects phenocopies USP18 deficiency.", "img": null}, {"id": "fc_058_17", "ch": 58, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **USP18 and ISG15 Deficiency, STAT2 - Associated Type I Interferonopathy**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Treatment responses to JAK inhibition have been variable, with evidence of suppression of the ISG signature without obvious impact on neuropathology although dosage may be a factor, as control of disease with high-dose ruxolitinib has been reported in a case of USP18 deficiency.", "img": null}, {"id": "fc_058_18", "ch": 58, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Clinical Management**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Because of the association with excessive IFN-I activity, therapeutic blockade of IFN-I signaling, primarily with JAK inhibitors (JAKi, mainly ruxolitinib, baricitinib and tofacitinib), is a cornerstone of treatment.", "img": null}, {"id": "fc_058_19", "ch": 58, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Aicardi-Goutières Syndrome (AGS)**, how is **Moyamoya** defined and characterized?", "a": "Moyamoya and/or cerebral aneurysms may be present, either with or without other features of AGS; individuals with SAMHD1 variant are at risk of cerebrovascular events.", "img": null}, {"id": "fc_058_20", "ch": 58, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Singleton-Merten Syndrome (SMS)**, how is **Treatment** defined and characterized?", "a": "Treatment for the disorders described above is generally oriented to the particular phenotype, focusing on management of vasculopathy and neurological disability and monitoring for end-organ disease (e.", "img": null}, {"id": "fc_058_21", "ch": 58, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **STING-Associated Vasculopathy of Infancy (SAVI) and COPA Syndrome**, how is **COPA syndrome** defined and characterized?", "a": "COPA syndrome , due to heterozygous dominant negative variants in COPA , albeit clinical nonpenetrance has been estimated in approximately 30% of variant carriers.", "img": null}, {"id": "fc_058_22", "ch": 58, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **USP18 and ISG15 Deficiency, STAT2 - Associated Type I Interferonopathy**, how is **Mendelian susceptibility to mycobacterial disease (MSMD)** defined and characterized?", "a": "Mendelian susceptibility to mycobacterial disease (MSMD) , in which patients exhibit susceptibility to weakly pathogenic nontuberculous mycobacteria, which is thought to involve a separate function of secreted ISG15 in mycobacterial immunity.", "img": null}, {"id": "fc_058_23", "ch": 58, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 58.1):", "a": "Schematic representation of genetic mechanisms and clinical manifestations in main interferonopathies.", "img": "fig_p1305_02.jpg"}, {"id": "fc_058_24", "ch": 58, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 58.2):", "a": "Characteristic clinical phenotypes of interferonopathies. Chilblain lesions typical of monogenic type I interferonopathies, seen most frequently on the toes, fingers (A), ears (B), and nose. The lesions are generally worse in the cold months. (C) Representative brain CT scan of intracranial calcifications seen in a patient with Aicardi-Goutières syndrome due to TREX1 homozygous pathogenic variants. (D) Chest CT scan of a SAVI patient (performed at the age of 12.5 years) showing evidence of interstitial lung disease (interlobular septal thickening, intralobular lines, cystic lesions, and some ground-glass lesions) and fibrosis (honeycombing). (Modified from Melki I, Fremond ML. Type I interferonopathies: from a novel concept to targeted therapeutics. Curr Rheum Reports . 2020;22:32, Fig. 1.)", "img": "fig_p1308_01.jpg"}, {"id": "fc_058_25", "ch": 58, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 58.3):", "a": "Schematic representation of various pathways affected in genetic interferonopathies. Purple rectangles indicate variant proteins in type I interferonopathies. Numbered yellow circles indicate the common mechanistic defect. 1. Loss-of-function pathogenic variants of genes that encode enzymes responsible for DNA or DNA-RNA hybrid molecule degradation. 2. Pathogenic variants that lead to constitutive activation or reduction of activation threshold of intracytosolic nucleic acid sensors. 3. Gain-of-function pathogenic variants of positive IFN signaling regulators; 4. Loss-offunction pathogenic variants of negative IFN signaling regulators; and 5. Proteasomal dysfunctional leading to the unfolded protein response and downstream IFN pathway activation. ADAR, RNA adenosine deaminase; ERGIC, endothelial reticulum–Golgi intermediate compartment; IFIH1, IFN-induced helicase C domain-containing protein 1; IFNAR, interferon-α receptor; IRF3, interferon regulatory factor 3; IRF7, interferon regulatory factor 7; IRF9, interferon regulatory factor 9; ISG15, interferon-stimulated gene 15; ISGF3, the transcriptional activator induced by interferon-α; ISRE, interferon-sensitive response element; JAK1, Janus kinase 1; MAVS, mitochondrial antiviral-signaling protein; NTPs, nucleoside triphosphates; P, phosphorylation; RIG-I, retinoic acid-inducible gene I; RNASEH2, ribonuclease H domain 2; SAMHD1, SAM domain and HD domain deoxynucl", "img": "fig_p1309_02.jpg"}, {"id": "fc_058_26", "ch": 58, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 58.4):", "a": "Clinical manifestations of stimulator of interferon genes (STING)–associated vasculopathy with onset in infancy (SAVI). (A) Typical facial distribution of telangiectatic lesions on the nose and cheeks with atrophy and scarring of the skin with loss of deep tissue of the nose. (B) Violaceous, scaling, atrophic plaques on both hands and progressive autoamputations of several fingers. (C) Hilar lymphadenopathy and bilateral interstitial infiltrates on high-resolution computed tomography (CT) image. (D) Ulcerated lesions on the pinna of the ear with scales and crusts.", "img": "fig_p1312_01.jpg"}, {"id": "fc_058_27", "ch": 58, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gene Variant Mechanism (GOF/LOF) Inheritance Protein Function Phenotype(s)**, what are the distinguishing features of **TREX1**?", "a": "**Variant Mechanism (GOF/LOF)**: LOF; **Inheritance**: AR, AD (DN); **Protein Function**: DNase; **Phenotype(s)**: AGS, FCL, SLE", "img": null}, {"id": "fc_058_28", "ch": 58, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gene Variant Mechanism (GOF/LOF) Inheritance Protein Function Phenotype(s)**, what are the distinguishing features of **RNASEH2A**?", "a": "**Variant Mechanism (GOF/LOF)**: LOF; **Inheritance**: AR; **Protein Function**: RNase; **Phenotype(s)**: AGS", "img": null}, {"id": "fc_059_01", "ch": 59, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **FOXP3**?", "a": "**Causative Gene(s):** `FOXP3, CD25, IL2RB, AIRE` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Protein — IL2RA: CD25 — IL2RB: IL2RB — STAT5B: STAT5b — AIRE: AIRE — There are only a few proteins that are available for clinical testing such as FOXP3 or LRBA.", "img": null}, {"id": "fc_059_02", "ch": 59, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **CTLA4**?", "a": "**Causative Gene(s):** `CTLA4, LRBA, PD1` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Protein — LRBA: LRBA — PCDC1: PD1 — Pathogenic variants in CTLA4 result in a disease called CTLA4 haploinsufficiency (CHAI) , an autosomal dominant disorder.", "img": null}, {"id": "fc_059_03", "ch": 59, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **STAT1**?", "a": "**Causative Gene(s):** `STAT1, STAT2, STAT3, STAT6, JAK1` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Protein — STAT2: STAT2 — STAT3: STAT3 — STAT5B: STAT5b — STAT6: STAT6 — JAK1: JAK1 — Lastly it is not yet known whether gain-of-function variants in STAT1 or STAT3 ( STAT1-GOF or STAT3-GOF ) affect the responsiveness of effector cells to Treg suppression or directly affect Treg function. (From Togerson TR.", "img": null}, {"id": "fc_059_04", "ch": 59, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Diagnostic Evaluation for Disorders of Immune Regulation**?", "a": "**Causative Gene(s):** `FOXP3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** There are only a few proteins that are available for clinical testing such as FOXP3 or LRBA.", "img": null}, {"id": "fc_059_05", "ch": 59, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Defects in T Regulatory Cells (Tregs)**?", "a": "**Causative Gene(s):** `FOXP3` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** It arises from defects in the FOXP3 gene located on the X chromosome.", "img": null}, {"id": "fc_059_06", "ch": 59, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Thymic Defects Leading to Autoimmunity**?", "a": "**Causative Gene(s):** `AIRE` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Autoimmune regulator (AIRE) , a protein expressed in the thymus, is important in controlling the expression of tissue-specific antigens in thymic epithelial cells, which is important in the deletion of autoreactive T cells.", "img": null}, {"id": "fc_059_07", "ch": 59, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`FOXP3`** are associated with which clinical phenotype and molecular mechanism in **Diagnostic Evaluation for Disorders of Immune Regulation**?", "a": "There are only a few proteins that are available for clinical testing such as FOXP3 or LRBA.", "img": null}, {"id": "fc_059_08", "ch": 59, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IL2RA`** are associated with which clinical phenotype and molecular mechanism in **Defects in T Regulatory Cells (Tregs)**?", "a": "HSCT has been successful in both IL2RA and IL2RB deficiency.", "img": null}, {"id": "fc_059_09", "ch": 59, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IL10`** are associated with which clinical phenotype and molecular mechanism in **Defects in T Regulatory Cells (Tregs)**?", "a": "Variants in genes that affect CTLA-4 expression (CTLA4, LRBA, DEF6) or expression/responsiveness to IL-10 (IL10, IL10RA, IL10RB) affect these functions of Tregs.", "img": null}, {"id": "fc_059_10", "ch": 59, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`STAT1`** are associated with which clinical phenotype and molecular mechanism in **Defects in T Regulatory Cells (Tregs)**?", "a": "Lastly it is not yet known whether gain-of-function variants in STAT1 or STAT3 ( STAT1-GOF or STAT3-GOF ) affect the responsiveness of effector cells to Treg suppression or directly affect Treg function. (From Togerson TR.", "img": null}, {"id": "fc_059_11", "ch": 59, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`AIRE`** are associated with which clinical phenotype and molecular mechanism in **Thymic Defects Leading to Autoimmunity**?", "a": "Autoimmune regulator (AIRE) , a protein expressed in the thymus, is important in controlling the expression of tissue-specific antigens in thymic epithelial cells, which is important in the deletion of autoreactive T cells.", "img": null}, {"id": "fc_059_12", "ch": 59, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CTLA4`** are associated with which clinical phenotype and molecular mechanism in **Defects in Inhibitory T Cell Receptors**?", "a": "Cytotoxic T-lymphocyte-associated protein 4 (CTLA4) and programmed cell death protein 1 (PD1) are inhibitory receptors on immune cells and variants in these genes have been found in human disease.", "img": null}, {"id": "fc_059_13", "ch": 59, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Defects in T Regulatory Cells (Tregs)**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Given the lack of control on effector T cells mediated by Tregs, therapies targeting T cells, such as sirolimus and tacrolimus, can be effective in the short term.", "img": null}, {"id": "fc_059_14", "ch": 59, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Defects in Inhibitory T Cell Receptors**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Given the immune-mediated diseases with lymphoproliferation and autoimmunity, sirolimus can be effective.", "img": null}, {"id": "fc_059_15", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **very-early onset inflammatory bowel disease (VEOIBD)** defined and characterized?", "a": "very-early onset inflammatory bowel disease (VEOIBD) , have been linked to several genes in immune regulation (Chapter 31).", "img": null}, {"id": "fc_059_16", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **autoimmune cytopenias** defined and characterized?", "a": "autoimmune cytopenias , which can result in anemia, thrombocytopenia, neutropenia, or lymphopenia.", "img": null}, {"id": "fc_059_17", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **Dermatological diseases** defined and characterized?", "a": "Dermatological diseases , such as eczema and psoriasis, are also among the common organ systems affected (Chapter 56).", "img": null}, {"id": "fc_059_18", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **interstitial lung disease** defined and characterized?", "a": "interstitial lung disease , follicular bronchiolitis, or noncaseating granulomas.", "img": null}, {"id": "fc_059_19", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **Endocrine manifestations** defined and characterized?", "a": "Endocrine manifestations , such as thyroiditis, type 1 diabetes, adrenal insufficiency, and gonadal insufficiency, can also develop (Chapter 39).", "img": null}, {"id": "fc_059_20", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **musculoskeletal** defined and characterized?", "a": "musculoskeletal manifestations such as arthritis or myositis.", "img": null}, {"id": "fc_059_21", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **Renal disease** defined and characterized?", "a": "Renal disease can develop presenting with hematuria or proteinuria.", "img": null}, {"id": "fc_059_22", "ch": 59, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Overview of Disorders of Immune Regulation Clinical Features in Disorders of Immune Regulation**, how is **neurological defects** defined and characterized?", "a": "neurological defects such as encephalitis or sensorineural hearing loss.", "img": null}, {"id": "fc_059_23", "ch": 59, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 59.1):", "a": "The effect of known IPEX and IPEX-like associated gene defects on Treg (regulatory T cells) generation and function. Both AIRE and FOXP3 play important roles in the generation of Treg cells in the thymus. The expansion, maintenance, and activation of Treg cells in the periphery is known to be highly dependent on interleukin-2 (IL-2), which is required to maintain long-term expression of FOXP3. Variants in the IL-2 receptor chains ( IL2RA / IL2RB ) or in STAT5B affect this aspect of the Treg function. Treg cells mediate immune suppression via a variety of mechanisms including downregulation of antigen presenting cell co-stimulatory function by CTLA-4 and through secretion of immunoregulatory cytokines like interleukin-10 (IL-10) and transforming growth factor-β (TGF-β). Variants in genes that affect CTLA-4 expression (CTLA4, LRBA, DEF6) or expression/responsiveness to IL-10 (IL10, IL10RA, IL10RB) affect these functions of Tregs. Lastly it is not yet known whether gain-of-function variants in STAT1 or STAT3 ( STAT1-GOF or STAT3-GOF ) affect the responsiveness of effector cells to Treg suppression or directly affect Treg function.", "img": "fig_p1322_01.jpg"}, {"id": "fc_059_24", "ch": 59, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 59.2):", "a": "Clinical manifestations in the IPEX-like cohorts. (Modified from Gambineri E, Ciullini Mannurita S, Hagin D, et al. Clinical, immunological, and molecular heterogeneity of 173 patients with the phenotype of immune dysregulation, polyendocrinopathy, enteropathy, X-linked [IPEX] syndrome. Front Immunol . 2018;9:2411. Fig. 5. Also Fig. 174.2 in Nelson Textbook of Pediatrics 22/e.)", "img": "fig_p1322_03.jpg"}, {"id": "fc_059_25", "ch": 59, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gene FOXP3 IL2RA IL2RB STAT5B AIRE**, what are the distinguishing features of **Protein**?", "a": "**FOXP3**: FOXP3; **IL2RA**: CD25; **IL2RB**: IL2RB; **STAT5B**: STAT5b; **AIRE**: AIRE", "img": null}, {"id": "fc_059_26", "ch": 59, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Gene FOXP3 IL2RA IL2RB STAT5B AIRE**, what are the distinguishing features of **Onset age**?", "a": "**FOXP3**: Fetal to adolescence; **IL2RA**: Infancy; **IL2RB**: Fetal to childhood; **STAT5B**: Infancy to childhood; **AIRE**: Childhood to adulthood", "img": null}, {"id": "fc_059_27", "ch": 59, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Defects in In hibitory T Cell Receptors**, what are the distinguishing features of **Protein**?", "a": "**CTLA4**: CTLA4; **LRBA**: LRBA; **PCDC1**: PD1", "img": null}, {"id": "fc_059_28", "ch": 59, "part": "X", "cat": "Differential Diagnosis", "q": "In the differential diagnosis of **Defects in In hibitory T Cell Receptors**, what are the distinguishing features of **Onset age**?", "a": "**CTLA4**: Childhood to young adulthood; **LRBA**: Infancy to childhood; **PCDC1**: Childhood", "img": null}, {"id": "fc_060_01", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SLE, infections due to encapsulated bacteria**?", "a": "**Causative Gene(s):** `C2` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Deficiency: C1q C1r,C1s C2 C4 (total) — Inheritance: Autosomal recessive — C2 deficiency is one of the most common complement deficiencies, with an estimated prevalence of 1:20,000 in the Swedish population.", "img": null}, {"id": "fc_060_02", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Susceptibility to autoimmunity and infections**?", "a": "**Causative Gene(s):** `C4A, C4B` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Deficiency: C4A or C4B — Inheritance: Complex — Mannose-binding lectin (MBL) deficiency has a prevalence of ~5% and loss of some alleles of C4A or C4B are quite common (1:250); these disorders do not cause severe illness on their own.", "img": null}, {"id": "fc_060_03", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Pyogenic infections, Neisserial infections, Glomerulonephritis**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Deficiency: C3 — Inheritance: Autosomal recessive — However, there are gain of function variants in C3 and alternative pathway components that are inherited in an autosomal dominant manner.", "img": null}, {"id": "fc_060_04", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Neisserial infections, including meningococcal meningitis**?", "a": "**Causative Gene(s):** `C5, C6, C7, C9` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Deficiency: C5, C6, C7, C8, C9 — Inheritance: Autosomal recessive — Alternatively, C3bBb or C4b2b can bind to C3b and form the C5 convertase, which cleaves C5 into C5a and C5b.", "img": null}, {"id": "fc_060_05", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **3MC syndrome**?", "a": "**Causative Gene(s):** `MASP1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Deficiency: MASP1 — Inheritance: Autosomal recessive — This results in the activation of MBL-associated serine protease 1 (MASP1) and MASP2.", "img": null}, {"id": "fc_060_06", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Respiratory infections**?", "a": "**Causative Gene(s):** `MASP2` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Deficiency: MASP2 — This results in the activation of MBL-associated serine protease 1 (MASP1) and MASP2.", "img": null}, {"id": "fc_060_07", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **aHUS**?", "a": "**Causative Gene(s):** `CD46` · **Inheritance:** Genetic\n\n**Clinical & Molecular Profile:** Deficiency: CD46/MCP — Inheritance: Heterozygous or compound heterozygous variants", "img": null}, {"id": "fc_060_08", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PNH* CHAPLE Syndrome**?", "a": "**Causative Gene(s):** `CD55` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Deficiency: CD55/DAF — Inheritance: Autosomal recessive — Isolated CD55 deficiency is the molecular cause of a rare autosomal recessive syndrome characterized by complement hyperactivation, angiopathic thrombosis, and early-onset protein-losing enteropathy (CHAPLE syndrome) .", "img": null}, {"id": "fc_060_09", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **PNH* Chronic hemolysis and relapsing peripheral demyelinating disease, cerebral infarction**?", "a": "**Causative Gene(s):** `CD59` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Deficiency: CD59 — Inheritance: Autosomal recessive — Isolated deficiency of CD59 results in early-onset Coombs-negative hemolytic anemia and recurrent episodes of chronic inflammatory demyelinating polyradiculoneuropathy (CIDP).", "img": null}, {"id": "fc_060_10", "ch": 60, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **C3 glomerulopathy**?", "a": "**Causative Gene(s):** `C3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Deficiency: C3 gain-of-function — Inheritance: Autosomal dominant — However, there are gain of function variants in C3 and alternative pathway components that are inherited in an autosomal dominant manner.", "img": null}, {"id": "fc_060_11", "ch": 60, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CP`** are associated with which clinical phenotype and molecular mechanism in **Complement Deficiencies**?", "a": "The complement system can be initiated depending on the context by three distinct pathways: classical (CP), lectin (LP), and alternative (AP), each leading to a common terminal pathway activation and generation of the membrane attack complex .", "img": null}, {"id": "fc_060_12", "ch": 60, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`MASP1`** are associated with which clinical phenotype and molecular mechanism in **Complement Deficiencies**?", "a": "This results in the activation of MBL-associated serine protease 1 (MASP1) and MASP2.", "img": null}, {"id": "fc_060_13", "ch": 60, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`C2`** are associated with which clinical phenotype and molecular mechanism in **Complement Deficiencies**?", "a": "C2 binds to C4b and is then cleaved by C1r/C1s or MASP into C4b2b, which is a C3 convertase and able to cleave C3 into C3a and C3b (Fig. 60.1).", "img": null}, {"id": "fc_060_14", "ch": 60, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`C3`** are associated with which clinical phenotype and molecular mechanism in **Complement Deficiencies**?", "a": "The AP monitors for pathogen invasion by maintaining a low level of constitutive activation by a process known as C3 tick-over.", "img": null}, {"id": "fc_060_15", "ch": 60, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`C5`** are associated with which clinical phenotype and molecular mechanism in **Complement Deficiencies**?", "a": "Alternatively, C3bBb or C4b2b can bind to C3b and form the C5 convertase, which cleaves C5 into C5a and C5b.", "img": null}, {"id": "fc_060_16", "ch": 60, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CD59`** are associated with which clinical phenotype and molecular mechanism in **Complement Deficiencies**?", "a": "DAF, C8 binding protein, and CD59 are glycosylphosphatidylinositol (GPI)-linked proteins, and MCP is an integral membrane glycoprotein.", "img": null}, {"id": "fc_060_17", "ch": 60, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Treatment of Complement System Deficiencies**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Ravulizumab, a long-acting second-generation C5 inhibitor, is approved for intravenous administration every 8 weeks, with results comparable to eculizumab.", "img": null}, {"id": "fc_060_18", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Complement Deficiencies**, how is **classical pathway (CP)** defined and characterized?", "a": "classical pathway (CP) is triggered by binding of C1q to immunoglobulin-G (IgG) and IgM-containing immune complexes or by C-reactive protein (CRP) resulting in activation of the C1r and C1s proteases.", "img": null}, {"id": "fc_060_19", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Complement Deficiencies**, how is **lectin pathway (LP)** defined and characterized?", "a": "lectin pathway (LP) is activated by the interaction of carbohydrate binding proteins, known as lectins (mannose binding lectin [MBL], collectin-10, collectin-11, ficolin-1, ficolin-2, or ficolin-3) with carbohydrate residues on microorganism surfaces.", "img": null}, {"id": "fc_060_20", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Deficiencies of the Classical Pathway**, how is **infectious susceptibilities** defined and characterized?", "a": "infectious susceptibilities in classical pathway complement deficiencies are pyogenic encapsulated organisms (i.", "img": null}, {"id": "fc_060_21", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Deficiencies of Lectin Pathway**, how is **MBL deficiency** defined and characterized?", "a": "MBL deficiency in the general Caucasian population has been estimated to be between 5% and 10%.", "img": null}, {"id": "fc_060_22", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Deficiencies of Lectin Pathway**, how is **MASP2 deficiency** defined and characterized?", "a": "MASP2 deficiency has been associated with pyogenic infections, inflammatory lung disease, and autoimmunity.", "img": null}, {"id": "fc_060_23", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Deficiencies of Lectin Pathway**, how is **ficolin-3 deficiency** defined and characterized?", "a": "ficolin-3 deficiency manifest variable clinical symptoms, particularly infections, autoimmune disorders, and neurological complications.", "img": null}, {"id": "fc_060_24", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Deficiencies of Alternative Pathway**, how is **Factor D deficiency** defined and characterized?", "a": "Factor D deficiency , which is very rare, and properdin deficiency both result in selective impairment of the alternative pathway.", "img": null}, {"id": "fc_060_25", "ch": 60, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Deficiency of Complement Regulatory Proteins and Receptors**, how is **hereditary angioedema** defined and characterized?", "a": "hereditary angioedema characterized by repeated attacks of angioedema.", "img": null}, {"id": "fc_060_26", "ch": 60, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 60.1):", "a": "Complement system activation pathways. LPS, Lipopolysaccharide; MAC, membrane attack complex; MASP, mannose-binding lectin-associated serine protease; MBL, mannose-binding lectin. *Examples of anaphylatoxins from the complement pathways.", "img": "fig_p1332_01.jpg"}, {"id": "fc_060_27", "ch": 60, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 60.2):", "a": "Initial evaluation of potential complement pathway defects based on CH50 and AH50 levels.", "img": "fig_p1337_13.jpg"}, {"id": "fc_060_28", "ch": 60, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 60.3):", "a": "Interpretation of C3 and CD4 complement levels. (A) Normal C3 and C4 levels in the presence of recurrent infections should prompt the physician to analyze the functional integrity of the complement cascade. In this situation, an undetectable CH50 test indicates deficiency of a complement component. (B) Normal C3 but reduced C4 levels are indicative of activation of the classical pathway but without alternative pathway activation. Testing for C1INH and cryoglobulins, which typically give only a low C4, is indicated. If these two assays are negative and C4 levels are repetitively low, genetic deficiency of one or more alleles of C4 is suspected. (C) Low C3 but normal C4 levels suggest alternative pathway activation without activation of the classical pathway. This can occur nephritic factors (C3 nephritic factor or C4 nephritic factor), autoantibodies against complement regulatory proteins (i.e., Factor H and Factor I), or genetic defects in Factor, Factor I, MCP, C3, or Factor B. Poststreptococcal glomerulonephritis and IgA nephritis can also cause this pattern. (D) Simultaneous low C3 and C4 levels indicate significant complement consumption by immune complexes due to infections or autoimmune disease. ↓, Low; 1 , positive; 2, negative; aHUS, atypical hemolytic uremic syndrome; C1INH, C1 esterase inhibitor; GN, glomerulonephritis; GOF, gain of function; HUVS, hypocomplementemic urticarial vasculitis syndrome", "img": "fig_p1338_01.jpg"}, {"id": "fc_061_01", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BTK deficiency, X-linked agammaglobulinemia**?", "a": "**Causative Gene(s):** `BTK` · **Inheritance:** X-Linked\n\n**Clinical & Molecular Profile:** Inheritance: XL — Ig: All isotypes decreased in majority of patients; some patients have detectable immunoglobulins — Associated Features: Severe bacterial infections, normal numbers of pro-B cells", "img": null}, {"id": "fc_061_02", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **m heavy chain deficiency**?", "a": "**Causative Gene(s):** `IGHM` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Ig: All isotypes decreased — Associated Features: Severe bacterial infections, normal", "img": null}, {"id": "fc_061_03", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **l5 deficiency**?", "a": "**Causative Gene(s):** `IGLL1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Associated Features: numbers of pro-B cells", "img": null}, {"id": "fc_061_04", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Iga deficiency**?", "a": "**Causative Gene(s):** `CD79A` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Selective IgA deficiency is characterized by absence of IgA in the blood, while IgG and IgM remain within normal limits.", "img": null}, {"id": "fc_061_05", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **Igb deficiency**?", "a": "**Causative Gene(s):** `CD79B` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — CD79A , and CD79B result in congenital agammaglobulinemia with absent B cells.", "img": null}, {"id": "fc_061_06", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **BLNK deficiency**?", "a": "**Causative Gene(s):** `BLNK` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — B cell linker (BLNK) is also involved in B cell receptor signaling as is PIK3R1 and PIK3CD, and autosomal recessive deficiencies in these proteins similarly impair B cell development resulting in congenital agammaglobulinemia.", "img": null}, {"id": "fc_061_07", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **p110d deficiency**?", "a": "**Causative Gene(s):** `PIK3CD` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Associated Features: Severe bacterial infections; autoimmune complications (IBD)", "img": null}, {"id": "fc_061_08", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **p85 deficiency**?", "a": "**Causative Gene(s):** `PIK3R1` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Associated Features: Severe bacterial infections, cytopenias, decreased or absent pro-B cells", "img": null}, {"id": "fc_061_09", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **E47 transcription factor i**?", "a": "**Causative Gene(s):** `TCF3` · **Inheritance:** AD\n\n**Clinical & Molecular Profile:** Inheritance: AD — Associated Features: Recurrent bacterial infections — Haploinsufficiency in the transcription factors PU.1 and E47, due to genetic variants in SPI1 and TCF3 respectively, can result in agammaglobulinemia.", "img": null}, {"id": "fc_061_10", "ch": 61, "part": "X", "cat": "Syndrome & OMIM Profile", "q": "What are the genetic etiology, inheritance pattern, and hallmark clinical features of **SLC39A7 (ZIP7) deficiency**?", "a": "**Causative Gene(s):** `SLC39A7, ZIP7` · **Inheritance:** AR\n\n**Clinical & Molecular Profile:** Inheritance: AR — Associated Features: Early-onset infections, blistering dermatosis, failure to thrive, thrombocytopenia", "img": null}, {"id": "fc_061_11", "ch": 61, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`IGHM`** are associated with which clinical phenotype and molecular mechanism in **Congenital Agammaglobulinemia**?", "a": "Pathogenic gene variants of IGHM are the most common autosomal recessive etiologies of agammaglobulinemia and prevent expression of functional immunoglobulin μ heavy chain which is required for B cell development.", "img": null}, {"id": "fc_061_12", "ch": 61, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CD79B`** are associated with which clinical phenotype and molecular mechanism in **Congenital Agammaglobulinemia**?", "a": "CD79A , and CD79B result in congenital agammaglobulinemia with absent B cells.", "img": null}, {"id": "fc_061_13", "ch": 61, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`BLNK`** are associated with which clinical phenotype and molecular mechanism in **Congenital Agammaglobulinemia**?", "a": "B cell linker (BLNK) is also involved in B cell receptor signaling as is PIK3R1 and PIK3CD, and autosomal recessive deficiencies in these proteins similarly impair B cell development resulting in congenital agammaglobulinemia.", "img": null}, {"id": "fc_061_14", "ch": 61, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`TCF3`** are associated with which clinical phenotype and molecular mechanism in **Congenital Agammaglobulinemia**?", "a": "Haploinsufficiency in the transcription factors PU.1 and E47, due to genetic variants in SPI1 and TCF3 respectively, can result in agammaglobulinemia.", "img": null}, {"id": "fc_061_15", "ch": 61, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CD81`** are associated with which clinical phenotype and molecular mechanism in **Congenital Agammaglobulinemia**?", "a": "Activation leads to docking of SYK and subsequent tyrosine phosphorylation including BTK and PI3K. (B) The BCR coreceptor complex consists of the CR2 complement receptor, CD19, and CD81.", "img": null}, {"id": "fc_061_16", "ch": 61, "part": "X", "cat": "Molecular Etiology", "q": "Pathogenic variants in **`CR2`** are associated with which clinical phenotype and molecular mechanism in **Congenital Agammaglobulinemia**?", "a": "Microbial antigens that have bound the complement fragment C3d can simultaneously bind to the CR2 molecule and the BCR.", "img": null}, {"id": "fc_061_17", "ch": 61, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Common Variable Immunodeficiency (CVID) and Monogenic CVID-Like Disorders**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Therapy with abatacept (CTLA-4-Ig) has demonstrated efficacy for patients with CTLA4 or LRBA pathogenic gene variants.", "img": null}, {"id": "fc_061_18", "ch": 61, "part": "X", "cat": "Precision Therapy & Management", "q": "What is the targeted therapeutic approach or clinical management strategy for **Treatment**?", "a": "**Therapy / Intervention:** Targeted / Disease-Modifying Therapy\n\n**Clinical Context:** Treatment of CTLA-4 or LRBA deficiencies with abatacept (CTLA-4-Ig) has proven efficacious for gastrointestinal, hematopoietic, and pulmonary complications of these immune disorders.", "img": null}, {"id": "fc_061_19", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Antibody Deficiencies**, how is **Primary antibody deficiency (PAD)** defined and characterized?", "a": "Primary antibody deficiency (PAD) is a group of inherited or acquired disorders that have a primary effect of impairing the body’s ability to produce antibodies, which are proteins that play an integral part in the immune system.", "img": null}, {"id": "fc_061_20", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Antibody Deficiencies**, how is **autoimmune diseases** defined and characterized?", "a": "autoimmune diseases , such as autoimmune cytopenia, seronegative arthritis and enteropathy, as well as hematological malignancies, such as chronic lymphocytic leukemia or lymphoma.", "img": null}, {"id": "fc_061_21", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Agammaglobulinemia**, how is **X-linked agammaglobulinemia (XLA)** defined and characterized?", "a": "X-linked agammaglobulinemia (XLA) is typically characterized by absence of circulating B cells.", "img": null}, {"id": "fc_061_22", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Congenital Agammaglobulinemia**, how is **Autosomal recessive** defined and characterized?", "a": "Autosomal recessive forms of congenital agammaglobulinemia also occur and make up approximately 15% of agammaglobulinemia cases and result from pathogenic gene variants of other components of the B cell receptor signaling complex (Table 61.", "img": null}, {"id": "fc_061_23", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Common Variable Immunodeficiency (CVID) and Monogenic CVID-Like Disorders**, how is **activated PI3K delta syndrome (APDS)** defined and characterized?", "a": "activated PI3K delta syndrome (APDS) due to pathogenic gene variants in PIK3CD .", "img": null}, {"id": "fc_061_24", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Antibody Deficiencies**, how is **IgG1** defined and characterized?", "a": "IgG1 is the most abundant of the subclasses and plays a major role in providing immunity for protein-based vaccines.", "img": null}, {"id": "fc_061_25", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Antibody Deficiencies**, how is **IgG2** defined and characterized?", "a": "IgG2 is thought to play a vital role in defending against encapsulated bacteria, such as Haemophilus and Streptococcus .", "img": null}, {"id": "fc_061_26", "ch": 61, "part": "X", "cat": "Clinical & Diagnostic Concept", "q": "In the clinical evaluation of **Other Antibody Deficiencies**, how is **IgG3** defined and characterized?", "a": "IgG3 has both antiviral and antibacterial activity and is known to play a role in neutralizing toxins.", "img": null}, {"id": "fc_061_27", "ch": 61, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 61.1):", "a": "Signal transduction by the B cell receptor (A) and its coreceptor complex (B) . (A) Antigen-induced cross-linking of the BCR leads to clustering and localization in membrane lipid rafts, activation of SRC family tyrosine kinases, and tyrosine phosphorylation of the cytoplasmic domains of the Ig α/Ig β heterodimer. Activation leads to docking of SYK and subsequent tyrosine phosphorylation including BTK and PI3K. (B) The BCR coreceptor complex consists of the CR2 complement receptor, CD19, and CD81. Microbial antigens that have bound the complement fragment C3d can simultaneously bind to the CR2 molecule and the BCR. Binding triggers dual signaling cascades, which result in enhanced downstream signal transduction and B cell activation. Ig, Immunoglobulin; P, phosphate; PI3, phosphatidylinositol 3; PLC γ, phospholipase Cγ. (Modified from Abbas A, Lichtman A, Pillai S. Cellular and Molecular Immunology . 9th ed. Philadelphia: Elsevier; 2018:167-168.)", "img": "fig_p1343_02.jpg"}, {"id": "fc_061_28", "ch": 61, "part": "X", "cat": "Visual & Imaging Spotter", "q": "Identify the diagnostic sign, dysmorphic phenotype, neuroimaging pattern, or molecular pathway illustrated below (Fig. 61.2):", "a": "Suggested workflow for diagnosis of primary antibody deficiency (PAD). AGAM, Agammaglobulinemia; CVID, common variable immunodeficiency; dx, diagnosis; HIGMS, hyper-IgM syndromes; PAD, primary antibody deficiency; SAD, specific antibody deficiency; SD, standard deviation", "img": "fig_p1349_02.jpg"}];
